  for select to authenticated using (public.is_admin());

-- ---------------------------------------------------------------------------
-- Aggregate, privacy-preserving metrics for admins (counts only, no row data).
-- ---------------------------------------------------------------------------
create or replace function public.admin_usage_metrics()
returns table (
  total_users bigint,
  onboarded_users bigint,
  workouts_last_7d bigint,
  workouts_last_30d bigint,
  active_users_30d bigint,
  ai_requests_30d bigint,
  plus_subscribers bigint,
  pro_subscribers bigint
)
language plpgsql
stable
security definer
set search_path = public
as $$
begin
  if not public.is_admin() then
    raise exception 'Not authorized' using errcode = '42501';
  end if;
  return query
  select
    (select count(*) from public.profiles),
    (select count(*) from public.profiles where onboarding_completed_at is not null),
    (select count(*) from public.workout_sessions where status = 'completed' and started_at > now() - interval '7 days'),
    (select count(*) from public.workout_sessions where status = 'completed' and started_at > now() - interval '30 days'),
    (select count(distinct user_id) from public.workout_sessions where started_at > now() - interval '30 days'),
    (select count(*) from public.ai_usage_events where created_at > now() - interval '30 days'),
    (select count(*) from public.user_entitlements where plan = 'plus'),
    (select count(*) from public.user_entitlements where plan = 'pro');
end;
$$;

revoke execute on function public.admin_usage_metrics() from anon, public;
grant execute on function public.admin_usage_metrics() to authenticated;

-- ===== supabase/migrations/20261016000003_storage.sql =====
-- Storage buckets
-- avatars: private; each user can only touch objects under "<their uid>/..."
-- exercise-media: public read of licensed demonstration media; admin write.

on conflict (id) do nothing;

create policy avatars_owner_select on storage.objects
  for select to authenticated
  using (bucket_id = 'avatars' and (storage.foldername(name))[1] = (select auth.uid())::text);
create policy avatars_owner_insert on storage.objects
  for insert to authenticated
  with check (bucket_id = 'avatars' and (storage.foldername(name))[1] = (select auth.uid())::text);
create policy avatars_owner_update on storage.objects
  for update to authenticated
  using (bucket_id = 'avatars' and (storage.foldername(name))[1] = (select auth.uid())::text);
create policy avatars_owner_delete on storage.objects
  for delete to authenticated
  using (bucket_id = 'avatars' and (storage.foldername(name))[1] = (select auth.uid())::text);

create policy exercise_media_public_read on storage.objects
  for select to anon, authenticated
  using (bucket_id = 'exercise-media');
create policy exercise_media_admin_write on storage.objects
  for all to authenticated
  using (bucket_id = 'exercise-media' and public.is_admin())
  with check (bucket_id = 'exercise-media' and public.is_admin());

-- ===== supabase/migrations/20261017000001_custom_programs.sql =====
-- Custom program builder (/train/build): users can save private programs with source = 'custom'.
-- Custom programs follow the same rules as starter and AI programs: private to their owner,
-- never published, and free for the owner.

alter table public.training_programs drop constraint if exists training_programs_source_check;
alter table public.training_programs
  add constraint training_programs_source_check check (source in ('curated', 'starter', 'ai', 'custom'));

drop policy if exists training_programs_insert on public.training_programs;
create policy training_programs_insert on public.training_programs
  for insert to authenticated with check (
    (owner_id = (select auth.uid()) and is_published = false and source in ('starter', 'ai', 'custom'))
    or (owner_id is null and public.is_admin())
  );

-- Supports the per-user build rate limit (recent custom programs by owner).
create index if not exists training_programs_owner_source_created_idx
  on public.training_programs (owner_id, source, created_at desc)
  where owner_id is not null;

-- ===== supabase/migrations/20261017000002_progress_photos.sql =====
-- Progress photos (private)
-- Each photo is an object in the PRIVATE `progress-photos` bucket under "<uid>/...",
-- plus a metadata row in public.progress_photos. Only the owner can see or change
-- either. Admins get NO access to other users' photos (no is_admin() clause anywhere).

create table public.progress_photos (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users (id) on delete cascade,
  storage_path text not null unique check (char_length(storage_path) between 3 and 300),
  taken_on date not null default current_date,
  pose text not null default 'front' check (pose in ('front', 'side', 'back', 'other')),
  weight_kg numeric(5, 2) check (weight_kg between 25 and 400),
  note text check (char_length(note) <= 280),
  created_at timestamptz not null default now(),
  -- The object must live in the owner's own folder.
  check (split_part(storage_path, '/', 1) = user_id::text)
);
create index progress_photos_user_idx on public.progress_photos (user_id, taken_on desc);

alter table public.progress_photos enable row level security;

create policy progress_photos_select_own on public.progress_photos
  for select to authenticated using (user_id = (select auth.uid()));
create policy progress_photos_insert_own on public.progress_photos
  for insert to authenticated with check (user_id = (select auth.uid()));
create policy progress_photos_update_own on public.progress_photos
  for update to authenticated using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()));
create policy progress_photos_delete_own on public.progress_photos
  for delete to authenticated using (user_id = (select auth.uid()));

-- Storage bucket: private, images only, 8 MB max per object.
values ('progress-photos', 'progress-photos', false, 8388608, array['image/jpeg', 'image/png', 'image/webp'])
on conflict (id) do nothing;

create policy progress_photos_owner_select on storage.objects
  for select to authenticated
  using (bucket_id = 'progress-photos' and (storage.foldername(name))[1] = (select auth.uid())::text);
create policy progress_photos_owner_insert on storage.objects
  for insert to authenticated
  with check (bucket_id = 'progress-photos' and (storage.foldername(name))[1] = (select auth.uid())::text);
create policy progress_photos_owner_update on storage.objects
  for update to authenticated
  using (bucket_id = 'progress-photos' and (storage.foldername(name))[1] = (select auth.uid())::text);
create policy progress_photos_owner_delete on storage.objects
  for delete to authenticated
  using (bucket_id = 'progress-photos' and (storage.foldername(name))[1] = (select auth.uid())::text);

-- ===== supabase/migrations/20261017000003_challenges.sql =====
-- Narrow Gate Fitness — faith & fitness challenges ("40 Days Through the Narrow Gate").
-- Part of the optional Faith section. Rows are private to their owner (no admin access).

create table public.challenge_enrollments (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users (id) on delete cascade,
  challenge_slug text not null check (char_length(challenge_slug) between 1 and 64),
  started_on date not null,
  status text not null default 'active' check (status in ('active', 'completed', 'abandoned')),
  completed_at timestamptz,
  created_at timestamptz not null default now(),
  check (status <> 'completed' or completed_at is not null)
);
-- At most one active enrollment per user and challenge.
create unique index challenge_enrollments_one_active_idx
  on public.challenge_enrollments (user_id, challenge_slug) where status = 'active';
create index challenge_enrollments_user_idx on public.challenge_enrollments (user_id, created_at desc);

create table public.challenge_checkins (
  id uuid primary key default gen_random_uuid(),
  enrollment_id uuid not null references public.challenge_enrollments (id) on delete cascade,
  user_id uuid not null references auth.users (id) on delete cascade,
  day_number smallint not null check (day_number between 1 and 40),
  devotional_done boolean not null default false,
  workout_done boolean not null default false,
  note text check (char_length(note) <= 1000),
  checked_on date not null,
  created_at timestamptz not null default now(),
  unique (enrollment_id, day_number)
);
create index challenge_checkins_user_idx on public.challenge_checkins (user_id);

-- ---------------------------------------------------------------------------
-- Row Level Security: owner-only
-- ---------------------------------------------------------------------------
alter table public.challenge_enrollments enable row level security;
alter table public.challenge_checkins enable row level security;

create policy challenge_enrollments_select_own on public.challenge_enrollments
  for select to authenticated using (user_id = (select auth.uid()));
create policy challenge_enrollments_insert_own on public.challenge_enrollments
  for insert to authenticated with check (user_id = (select auth.uid()));
create policy challenge_enrollments_update_own on public.challenge_enrollments
  for update to authenticated using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()));
create policy challenge_enrollments_delete_own on public.challenge_enrollments
  for delete to authenticated using (user_id = (select auth.uid()));

create policy challenge_checkins_select_own on public.challenge_checkins
  for select to authenticated using (user_id = (select auth.uid()));
create policy challenge_checkins_insert_own on public.challenge_checkins
  for insert to authenticated with check (
    user_id = (select auth.uid())
    and exists (select 1 from public.challenge_enrollments e where e.id = enrollment_id and e.user_id = (select auth.uid()))
  );
create policy challenge_checkins_update_own on public.challenge_checkins
  for update to authenticated
  using (user_id = (select auth.uid()))
  with check (
    user_id = (select auth.uid())
    and exists (select 1 from public.challenge_enrollments e where e.id = enrollment_id and e.user_id = (select auth.uid()))
  );
create policy challenge_checkins_delete_own on public.challenge_checkins
  for delete to authenticated using (user_id = (select auth.uid()));

-- ===== supabase/migrations/20261017000004_food_barcode.sql =====
-- Barcode scanning: products looked up on Open Food Facts are cached per user in public.foods
-- with source 'openfoodfacts' and source_ref = the product barcode.

alter table public.foods drop constraint if exists foods_source_check;
alter table public.foods
  add constraint foods_source_check check (source in ('custom', 'usda', 'curated', 'openfoodfacts'));

-- Users may cache Open Food Facts products for themselves, like USDA foods.
drop policy if exists foods_insert_own on public.foods;
create policy foods_insert_own on public.foods
  for insert to authenticated with check (
    (owner_id = (select auth.uid()) and source in ('custom', 'usda', 'openfoodfacts'))
    or (owner_id is null and public.is_admin())
  );

-- Cached USDA / Open Food Facts foods are upserted with ON CONFLICT (owner_id, source, source_ref).
-- Postgres can't use a *partial* unique index for that, so the original index made those upserts fail
-- (error 42P10). A plain unique index behaves the same for rows without a source_ref, because
-- NULLs never conflict with each other.
drop index if exists public.foods_owner_source_ref;
create unique index foods_owner_source_ref on public.foods (owner_id, source, source_ref);

-- ===== supabase/migrations/20261017000005_sex_and_diet_type.sql =====
-- Onboarding now asks for sex (used only for calorie estimates) and a diet style.

alter table public.profiles
  add column if not exists sex text check (sex in ('male', 'female', 'unspecified'));
-- Users may update their own sex (column-level grant; role stays non-updatable).
grant update (sex) on public.profiles to authenticated;

alter table public.onboarding_answers
  add column if not exists diet_type text not null default 'balanced' check (diet_type in (
    'balanced', 'high_protein', 'low_carb', 'keto', 'mediterranean', 'paleo', 'vegetarian', 'vegan',
    'pescatarian', 'intermittent_fasting', 'carnivore', 'daniel_fast', 'dash'));

-- ===== supabase/migrations/20261017000006_supplements_and_steps.sql =====
-- Narrow Gate Fitness — supplement stack, supplement check-offs and daily steps.
-- Supplement ids refer to the built-in reference list in the app (src/data/supplements.ts).
-- All rows are private to their owner (no admin access).

create table public.supplement_stack (
  user_id uuid not null references auth.users (id) on delete cascade,
  supplement_id text not null check (char_length(supplement_id) between 1 and 64),
  added_at timestamptz not null default now(),
  primary key (user_id, supplement_id)
);

create table public.supplement_logs (
  user_id uuid not null references auth.users (id) on delete cascade,
  supplement_id text not null check (char_length(supplement_id) between 1 and 64),
  taken_on date not null,
  created_at timestamptz not null default now(),
  primary key (user_id, supplement_id, taken_on)
);
create index supplement_logs_user_day_idx on public.supplement_logs (user_id, taken_on desc);

create table public.daily_steps (
  user_id uuid not null references auth.users (id) on delete cascade,
  day date not null,
  steps integer not null check (steps between 0 and 200000),
  source text not null default 'manual' check (source in ('manual', 'apple_health', 'health_connect')),
  updated_at timestamptz not null default now(),
  primary key (user_id, day)
);
create trigger daily_steps_updated_at before update on public.daily_steps
  for each row execute function public.set_updated_at();

-- Daily step goal (users may update it; column-level grant like the other self-editable profile fields).
alter table public.profiles
  add column if not exists step_goal integer not null default 8000 check (step_goal between 1000 and 50000);
grant update (step_goal) on public.profiles to authenticated;

-- ---------------------------------------------------------------------------
-- Row Level Security: owner-only
-- ---------------------------------------------------------------------------
alter table public.supplement_stack enable row level security;
alter table public.supplement_logs enable row level security;
alter table public.daily_steps enable row level security;

create policy supplement_stack_select_own on public.supplement_stack
  for select to authenticated using (user_id = (select auth.uid()));
create policy supplement_stack_insert_own on public.supplement_stack
  for insert to authenticated with check (user_id = (select auth.uid()));
create policy supplement_stack_update_own on public.supplement_stack
  for update to authenticated using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()));
create policy supplement_stack_delete_own on public.supplement_stack
  for delete to authenticated using (user_id = (select auth.uid()));

create policy supplement_logs_select_own on public.supplement_logs
  for select to authenticated using (user_id = (select auth.uid()));
create policy supplement_logs_insert_own on public.supplement_logs
  for insert to authenticated with check (user_id = (select auth.uid()));
create policy supplement_logs_update_own on public.supplement_logs
  for update to authenticated using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()));
create policy supplement_logs_delete_own on public.supplement_logs
  for delete to authenticated using (user_id = (select auth.uid()));

create policy daily_steps_select_own on public.daily_steps
  for select to authenticated using (user_id = (select auth.uid()));
create policy daily_steps_insert_own on public.daily_steps
  for insert to authenticated with check (user_id = (select auth.uid()));
create policy daily_steps_update_own on public.daily_steps
  for update to authenticated using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()));
create policy daily_steps_delete_own on public.daily_steps
  for delete to authenticated using (user_id = (select auth.uid()));

-- ===== supabase/migrations/20261017000007_onboarding_plan.sql =====
-- Onboarding now builds a calorie budget (MyFitnessPal / MyNetDiary style) alongside the starter program:
-- goal weight, weekly pace and activity level outside workouts. session_minutes and equipment already
-- live on onboarding_answers.
--
-- onboarding_answers is covered by the owner-only RLS policies created in 20261016000002_rls_policies.sql
-- (onboarding_answers_{select,insert,update,delete}_own: user_id = auth.uid()), so the new columns are
-- private to their owner. Columns are nullable so accounts created before this migration keep working;
-- the app falls back to the stored nutrition targets when they are missing.

alter table public.onboarding_answers
  add column if not exists goal_weight_kg numeric(5, 2) check (goal_weight_kg between 25 and 400),
  add column if not exists weekly_change_kg numeric(4, 2) check (weekly_change_kg in (-1, -0.75, -0.5, -0.25, 0, 0.25, 0.5)),
  add column if not exists activity_level text check (activity_level in ('sedentary', 'light', 'active', 'very_active'));

comment on column public.onboarding_answers.goal_weight_kg is 'Optional target bodyweight in kg.';
comment on column public.onboarding_answers.weekly_change_kg is 'Chosen weekly weight change in kg (negative = lose).';
comment on column public.onboarding_answers.activity_level is 'Daily-life activity outside workouts, for the calorie budget.';

-- ===== supabase/migrations/20261019000008_food_amounts.sql =====
-- MyFitnessPal-style amounts for logged food: the exact weight eaten, the unit and quantity picked
-- ("6 oz", "1.5 cup, chopped"), a readable amount ("6 oz (170 g)"), fiber / sugar / sodium, where the
-- values came from, and the nutrition basis (per 100 g, label serving, USDA portions) so an entry can be
-- edited later. All columns are nullable: entries logged before this migration keep working and are
-- edited as "servings" of their own values.
--
-- meal_items already has owner-only RLS for select / insert / update / delete (user_id = auth.uid(),
-- and the parent meal must be the user's own); new columns are covered by those row policies.

alter table public.meal_items
  add column if not exists grams numeric(8, 1) check (grams > 0 and grams <= 20000),
  add column if not exists quantity numeric(10, 3) check (quantity > 0 and quantity <= 100000),
  add column if not exists unit_label text check (char_length(unit_label) between 1 and 100),
  add column if not exists amount_label text check (char_length(amount_label) between 1 and 160),
  add column if not exists fiber_g numeric(6, 1) check (fiber_g >= 0),
  add column if not exists sugar_g numeric(6, 1) check (sugar_g >= 0),
  add column if not exists sodium_mg numeric(9, 1) check (sodium_mg >= 0),
  add column if not exists source text check (source ~ '^(usda:[0-9]{1,10}|off:[0-9]{8,14}|food:[0-9a-f-]{36}|custom)$'),
  add column if not exists basis jsonb check (
    basis is null
    or coalesce(jsonb_typeof(basis) = 'object' and jsonb_typeof(basis -> 'per100') = 'object' and octet_length(basis::text) <= 8000, false)
  );

-- ===== supabase/migrations/20261020000009_ui_prefs.sql =====
-- Display and Faith preferences shown in Profile & Settings (SPEC §1, §12).
--   text_size      : root text scale on top of the system text size.
--   reduce_motion  : turns off page animations and celebration confetti.
--   home_scripture : show the Scripture card on Home (Faith itself is always available).
alter table public.profiles
  add column if not exists text_size text not null default 'default' check (text_size in ('default', 'large', 'xlarge')),
  add column if not exists reduce_motion boolean not null default false,
  add column if not exists home_scripture boolean not null default true;

-- Self-editable like the other profile preferences (column-level grants).
grant update (text_size, reduce_motion, home_scripture) on public.profiles to authenticated;

-- ===== supabase/migrations/20261020000010_activities.sql =====
-- Narrow Gate Fitness — runs and walks ("activities").
--
-- One row per run or walk. The row id is the stable activity id: the client generates it before
-- the first save, so a double-submitted form or a retried upload is a no-op instead of a duplicate,
-- and badges/records derived from activities can key on it.
--
-- Decisions (see docs/RUN_TRACKING_PLAN.md):
-- * distance_m may be null only for a time-only manual entry ("a 30-minute walk"). Treadmill and
--   GPS activities always have a distance. Pace is never stored: it's computed in code from
--   distance_m and moving_s, so there is one source of truth.
-- * moving_s excludes paused time and is never more than elapsed_s. Manual entries default it to
--   elapsed_s when the user doesn't know their moving time.
-- * route is only allowed for GPS activities, so manual/treadmill entries can never carry a route.
-- * Soft delete (deleted_at): reads filter it out; records and badges recalculate from the
--   remaining rows. The owner can also hard-delete (and account deletion cascades).
-- * Duplicate imports: external_id (a wearable/health-app workout id) is unique per user and
--   source, and two live GPS recordings can't start at the same instant.

create table public.activities (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users (id) on delete cascade,
  kind text not null check (kind in ('run', 'walk')),
  source text not null check (source in ('manual', 'treadmill', 'gps')),
  started_at timestamptz not null,
  timezone text not null default 'UTC' check (char_length(timezone) between 1 and 64),
  distance_m numeric(9, 2) check (distance_m is null or (distance_m >= 0 and distance_m <= 500000)),
  elapsed_s integer not null check (elapsed_s between 1 and 172800),
  moving_s integer not null check (moving_s >= 1),
  notes text check (notes is null or char_length(notes) <= 2000),
  perceived_effort smallint check (perceived_effort is null or perceived_effort between 1 and 10),
  route jsonb,
  splits jsonb check (splits is null or jsonb_typeof(splits) = 'array'),
  external_id text check (external_id is null or char_length(external_id) between 1 and 128),
  is_private boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  deleted_at timestamptz,
  constraint activities_moving_le_elapsed check (moving_s <= elapsed_s),
  constraint activities_distance_required check (distance_m is not null or source = 'manual'),
  constraint activities_route_gps_only check (route is null or source = 'gps')
);

create index activities_user_started_idx on public.activities (user_id, started_at desc) where deleted_at is null;
create unique index activities_user_source_external_uidx on public.activities (user_id, source, external_id)
  where external_id is not null;
create unique index activities_user_gps_started_uidx on public.activities (user_id, source, started_at)
  where source = 'gps' and deleted_at is null;

create trigger activities_updated_at before update on public.activities
  for each row execute function public.set_updated_at();

-- ---------------------------------------------------------------------------
-- Row Level Security: owner-only (no admin access; routes are private data)
-- ---------------------------------------------------------------------------
alter table public.activities enable row level security;

create policy activities_select_own on public.activities
  for select to authenticated using (user_id = (select auth.uid()));
create policy activities_insert_own on public.activities
  for insert to authenticated with check (user_id = (select auth.uid()));
create policy activities_update_own on public.activities
  for update to authenticated using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()));
create policy activities_delete_own on public.activities
  for delete to authenticated using (user_id = (select auth.uid()));

-- ===== supabase/migrations/20261020000011_food_favorites.sql =====
-- Food favorites (SPEC §8 "Favorites and recent foods").
--
-- A favorite points at a food by the same stable source key that meal_items.source uses:
--   usda:<fdcId>      USDA FoodData Central (bundled SR Legacy or the remote API)
--   off:<barcode>     Open Food Facts product
--   food:<uuid>       a row in public.foods (built-in common foods or the user's own saved foods)
-- Hand-entered quick adds ("custom") have no stable identity and can't be favorited.
--
-- name / detail / basis are a display snapshot so the Favorites tab renders without a lookup. When a
-- favorite is logged, nutrition is always re-read on the server from the source (logFoodAction), never
-- taken from this snapshot.
--
-- Rows are private to their owner: owner-only RLS for select / insert / update / delete, no admin
-- access, and they cascade away with the auth user on account deletion.

create table public.food_favorites (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users (id) on delete cascade,
  food_key text not null check (food_key ~ '^(usda:[0-9]{1,10}|off:[0-9]{8,14}|food:[0-9a-f-]{36})$'),
  name text not null check (char_length(name) between 1 and 160),
  detail text check (char_length(detail) <= 200),
  basis jsonb not null check (
    coalesce(jsonb_typeof(basis) = 'object' and jsonb_typeof(basis -> 'per100') = 'object' and octet_length(basis::text) <= 8000, false)
  ),
  is_estimate boolean not null default false,
  created_at timestamptz not null default now(),
  constraint food_favorites_user_key_unique unique (user_id, food_key)
);
create index food_favorites_user_created_idx on public.food_favorites (user_id, created_at desc);

alter table public.food_favorites enable row level security;

create policy food_favorites_select_own on public.food_favorites
  for select to authenticated using (user_id = (select auth.uid()));
create policy food_favorites_insert_own on public.food_favorites
  for insert to authenticated with check (user_id = (select auth.uid()));
create policy food_favorites_update_own on public.food_favorites
  for update to authenticated using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()));
create policy food_favorites_delete_own on public.food_favorites
  for delete to authenticated using (user_id = (select auth.uid()));

comment on table public.food_favorites is 'Foods a user starred for quick logging. Owner-only.';
comment on column public.food_favorites.food_key is 'Stable source key, same format as meal_items.source (usda:/off:/food:).';

-- ===== supabase/migrations/20261021000012_recipes_planner_grocery.sql =====
-- Narrow Gate Fitness — Stage 2A nutrition: recipes, meal planner, grocery list and day marks (SPEC §8).
--
-- Every table is private to its owner: owner-only RLS for select / insert / update / delete, no admin
-- access, and every row cascades away with the auth user on account deletion. Child rows (recipe
-- ingredients, plan entries, grocery items) also check that the parent row belongs to the same user.
--
-- Deletes are hard deletes, like meals and saved meals: diary entries logged from a recipe or a plan keep
-- their own snapshot of the nutrition (meal_items.basis), so deleting the recipe or plan never changes
-- what was eaten.

-- ---------------------------------------------------------------------------
-- Recipes
-- ---------------------------------------------------------------------------
create table public.recipes (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users (id) on delete cascade,
  name text not null check (char_length(name) between 1 and 120),
  servings numeric(6, 2) not null default 1 check (servings > 0 and servings <= 100),
  notes text check (char_length(notes) <= 2000),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index recipes_user_idx on public.recipes (user_id, name);
create trigger recipes_updated_at before update on public.recipes
  for each row execute function public.set_updated_at();

-- One row per ingredient. `basis` is a snapshot of the food's nutrition in the same format as
-- meal_items.basis (per 100 g / ml, label serving, USDA household portions, missing macros), taken from the
-- source on the server when the ingredient was added. `quantity` + `unit_label` are the amount picked.
create table public.recipe_ingredients (
  id uuid primary key default gen_random_uuid(),
  recipe_id uuid not null references public.recipes (id) on delete cascade,
  user_id uuid not null references auth.users (id) on delete cascade,
  position smallint not null default 0 check (position between 0 and 199),
  name text not null check (char_length(name) between 1 and 160),
  source text not null check (source ~ '^(usda:[0-9]{1,10}|off:[0-9]{8,14}|food:[0-9a-f-]{36})$'),
  quantity numeric(10, 3) not null check (quantity > 0 and quantity <= 100000),
  unit_label text not null check (char_length(unit_label) between 1 and 100),
  grams numeric(8, 1) check (grams > 0 and grams <= 20000),
  amount_label text check (char_length(amount_label) between 1 and 160),
  basis jsonb not null check (
    coalesce(jsonb_typeof(basis) = 'object' and jsonb_typeof(basis -> 'per100') = 'object' and octet_length(basis::text) <= 8000, false)
  ),
  is_estimate boolean not null default false,
  created_at timestamptz not null default now()
);
create index recipe_ingredients_recipe_idx on public.recipe_ingredients (recipe_id, position);

-- Diary entries logged from a recipe or a built-in planner recipe point back at it.
alter table public.meal_items drop constraint if exists meal_items_source_check;
alter table public.meal_items add constraint meal_items_source_check
  check (source ~ '^(usda:[0-9]{1,10}|off:[0-9]{8,14}|food:[0-9a-f-]{36}|recipe:[0-9a-f-]{36}|app:[a-z0-9-]{1,60}|custom)$');

-- ---------------------------------------------------------------------------
-- Meal planner
-- ---------------------------------------------------------------------------
create table public.meal_plan_settings (
  user_id uuid primary key references auth.users (id) on delete cascade,
  meals_per_day smallint not null default 3 check (meals_per_day between 2 and 5),
  budget text not null default 'any' check (budget in ('low', 'medium', 'any')),
  allergies text[] not null default '{}' check (cardinality(allergies) <= 20 and octet_length(array_to_string(allergies, ',')) <= 1000),
  dislikes text[] not null default '{}' check (cardinality(dislikes) <= 20 and octet_length(array_to_string(dislikes, ',')) <= 1000),
  include_app_recipes boolean not null default true,
  updated_at timestamptz not null default now()
);
create trigger meal_plan_settings_updated_at before update on public.meal_plan_settings
  for each row execute function public.set_updated_at();

-- A generated plan for a run of days. `targets` and `settings` are snapshots of what it was built for.
create table public.meal_plans (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users (id) on delete cascade,
  start_date date not null,
  days smallint not null default 7 check (days between 1 and 14),
  targets jsonb not null check (jsonb_typeof(targets) = 'object' and octet_length(targets::text) <= 2000),
  settings jsonb not null check (jsonb_typeof(settings) = 'object' and octet_length(settings::text) <= 4000),
  created_at timestamptz not null default now(),
  constraint meal_plans_user_start_unique unique (user_id, start_date)
);

-- One planned meal. Planned meals are separate from what was eaten: "Log this meal" copies it into the
-- diary (meals / meal_items) and records logged_at here.
create table public.meal_plan_entries (
  id uuid primary key default gen_random_uuid(),
  plan_id uuid not null references public.meal_plans (id) on delete cascade,
  user_id uuid not null references auth.users (id) on delete cascade,
  plan_date date not null,
  slot smallint not null check (slot between 0 and 4),
  meal_type text not null check (meal_type in ('breakfast', 'lunch', 'dinner', 'snack')),
  label text not null check (char_length(label) between 1 and 40),
  source_key text not null check (source_key ~ '^(app:[a-z0-9-]{1,60}|recipe:[0-9a-f-]{36}|meal:[0-9a-f-]{36})$'),
  name text not null check (char_length(name) between 1 and 160),
  portion numeric(4, 2) not null check (portion >= 0.25 and portion <= 4),
  -- Nutrition for ONE serving at planning time, plus whether every ingredient had data.
  per_serving jsonb not null check (jsonb_typeof(per_serving) = 'object' and octet_length(per_serving::text) <= 2000),
  -- Ingredient amounts for ONE serving, for the grocery list: [{key, name, quantity, unitLabel}].
  ingredients jsonb not null default '[]' check (jsonb_typeof(ingredients) = 'array' and octet_length(ingredients::text) <= 20000),
  logged_at timestamptz,
  created_at timestamptz not null default now(),
  constraint meal_plan_entries_slot_unique unique (plan_id, plan_date, slot)
);
create index meal_plan_entries_user_date_idx on public.meal_plan_entries (user_id, plan_date);

-- ---------------------------------------------------------------------------
-- Grocery list (one per user)
-- ---------------------------------------------------------------------------
create table public.grocery_lists (
  user_id uuid primary key references auth.users (id) on delete cascade,
  from_date date,
  to_date date,
  generated_at timestamptz,
  updated_at timestamptz not null default now(),
  check (from_date is null or to_date is null or from_date <= to_date)
);
create trigger grocery_lists_updated_at before update on public.grocery_lists
  for each row execute function public.set_updated_at();

create table public.grocery_items (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users (id) on delete cascade,
  name text not null check (char_length(name) between 1 and 160),
  quantity numeric(10, 2) check (quantity is null or (quantity > 0 and quantity <= 100000)),
  unit text check (char_length(unit) between 1 and 60),
  note text check (char_length(note) <= 300),
  origin text not null check (origin in ('plan', 'manual')),
  ingredient_key text check (char_length(ingredient_key) <= 80),
  checked boolean not null default false,
  position integer not null default 0,
  created_at timestamptz not null default now()
);
create index grocery_items_user_idx on public.grocery_items (user_id, position);

-- ---------------------------------------------------------------------------
-- Day marks: "this day is complete" or "I ate nothing" (a fast), so weekly summaries can tell a day
-- logged as zero from a day that simply wasn't logged.
-- ---------------------------------------------------------------------------
create table public.nutrition_day_marks (
  user_id uuid not null references auth.users (id) on delete cascade,
  day date not null,
  status text not null check (status in ('complete', 'fasted')),
  updated_at timestamptz not null default now(),
  primary key (user_id, day)
);
create trigger nutrition_day_marks_updated_at before update on public.nutrition_day_marks
  for each row execute function public.set_updated_at();

-- ---------------------------------------------------------------------------
-- Row Level Security: owner-only
-- ---------------------------------------------------------------------------
alter table public.recipes enable row level security;
alter table public.recipe_ingredients enable row level security;
alter table public.meal_plan_settings enable row level security;
alter table public.meal_plans enable row level security;
alter table public.meal_plan_entries enable row level security;
alter table public.grocery_lists enable row level security;
alter table public.grocery_items enable row level security;
alter table public.nutrition_day_marks enable row level security;

do $$
declare t text;
begin
  foreach t in array array['recipes', 'meal_plan_settings', 'meal_plans', 'grocery_lists', 'grocery_items', 'nutrition_day_marks'] loop
    execute format('create policy %1$s_select_own on public.%1$s for select to authenticated using (user_id = (select auth.uid()))', t);
    execute format('create policy %1$s_insert_own on public.%1$s for insert to authenticated with check (user_id = (select auth.uid()))', t);
    execute format('create policy %1$s_update_own on public.%1$s for update to authenticated using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()))', t);
    execute format('create policy %1$s_delete_own on public.%1$s for delete to authenticated using (user_id = (select auth.uid()))', t);
  end loop;
end $$;

-- Children: the row and its parent must both be the user's own.
create policy recipe_ingredients_select_own on public.recipe_ingredients
  for select to authenticated using (user_id = (select auth.uid()));
create policy recipe_ingredients_insert_own on public.recipe_ingredients
  for insert to authenticated with check (
    user_id = (select auth.uid())
    and exists (select 1 from public.recipes r where r.id = recipe_id and r.user_id = (select auth.uid()))
  );
create policy recipe_ingredients_update_own on public.recipe_ingredients
  for update to authenticated using (user_id = (select auth.uid())) with check (
    user_id = (select auth.uid())
    and exists (select 1 from public.recipes r where r.id = recipe_id and r.user_id = (select auth.uid()))
  );
create policy recipe_ingredients_delete_own on public.recipe_ingredients
  for delete to authenticated using (user_id = (select auth.uid()));

create policy meal_plan_entries_select_own on public.meal_plan_entries
  for select to authenticated using (user_id = (select auth.uid()));
create policy meal_plan_entries_insert_own on public.meal_plan_entries
  for insert to authenticated with check (
    user_id = (select auth.uid())
    and exists (select 1 from public.meal_plans p where p.id = plan_id and p.user_id = (select auth.uid()))
  );
create policy meal_plan_entries_update_own on public.meal_plan_entries
  for update to authenticated using (user_id = (select auth.uid())) with check (
    user_id = (select auth.uid())
    and exists (select 1 from public.meal_plans p where p.id = plan_id and p.user_id = (select auth.uid()))
  );
create policy meal_plan_entries_delete_own on public.meal_plan_entries
  for delete to authenticated using (user_id = (select auth.uid()));

comment on table public.recipes is 'User recipes (ingredients in recipe_ingredients). Owner-only.';
comment on table public.recipe_ingredients is 'Recipe ingredients with a nutrition basis snapshot. Owner-only.';
comment on table public.meal_plan_settings is 'Meal planner preferences: meals per day, budget, allergies, dislikes. Owner-only.';
comment on table public.meal_plans is 'Generated meal plans. Owner-only.';
comment on table public.meal_plan_entries is 'Planned meals (separate from the diary until logged). Owner-only.';
comment on table public.grocery_lists is 'The date range the grocery list was generated for. Owner-only.';
comment on table public.grocery_items is 'Grocery list lines (from the plan or added by hand). Owner-only.';
comment on table public.nutrition_day_marks is 'Days marked complete or as a fast (logged as zero). Owner-only.';

-- ===== supabase/migrations/20261021000013_training_templates.sql =====
-- Narrow Gate Fitness — Stage 2B training (SPEC §5, §6).
--
--   * training_programs.needs_specialist_review: specialist programming (show prep, meet prep, combat, active
--     aging) that a qualified coach has not reviewed yet. The app shows "Not yet reviewed by a qualified coach".
--   * profiles.rest_timer_sound / rest_timer_vibrate: optional rest-timer alerts in the workout logger.
--   * workout_templates + workout_template_exercises: saved custom workouts (order, sets, reps / time /
--     distance, rest, supersets). Private to their owner, cascade on account deletion, included in the export.

alter table public.training_programs
  add column if not exists needs_specialist_review boolean not null default false;

alter table public.profiles
  add column if not exists rest_timer_sound boolean not null default true,
  add column if not exists rest_timer_vibrate boolean not null default true;
grant update (rest_timer_sound, rest_timer_vibrate) on public.profiles to authenticated;

create table public.workout_templates (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users (id) on delete cascade,
  name text not null check (char_length(name) between 1 and 120),
  notes text check (char_length(notes) <= 2000),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index workout_templates_user_idx on public.workout_templates (user_id, updated_at desc);
create trigger workout_templates_updated_at before update on public.workout_templates
  for each row execute function public.set_updated_at();

-- One row per exercise, in order. `target` says what each set prescribes: reps, a time or a distance.
-- Exercises sharing a `superset_group` (1–20) within a template are done as a superset: one set of each in
-- turn, with rest only after the round.
create table public.workout_template_exercises (
  id uuid primary key default gen_random_uuid(),
  template_id uuid not null references public.workout_templates (id) on delete cascade,
  user_id uuid not null references auth.users (id) on delete cascade,
  exercise_id uuid not null references public.exercises (id) on delete restrict,
  position smallint not null check (position between 0 and 39),
  sets smallint not null check (sets between 1 and 20),
  target text not null default 'reps' check (target in ('reps', 'time', 'distance')),
  reps text check (char_length(reps) between 1 and 20),
  duration_seconds integer check (duration_seconds between 5 and 7200),
  distance_m numeric(8, 1) check (distance_m > 0 and distance_m <= 100000),
  rest_seconds smallint not null default 90 check (rest_seconds between 0 and 900),
  superset_group smallint check (superset_group between 1 and 20),
  notes text check (char_length(notes) <= 500),
  unique (template_id, position),
  check (
    (target = 'reps' and reps is not null)
    or (target = 'time' and duration_seconds is not null)
    or (target = 'distance' and distance_m is not null)
  )
);
create index workout_template_exercises_template_idx on public.workout_template_exercises (template_id, position);
create index workout_template_exercises_exercise_idx on public.workout_template_exercises (exercise_id);

alter table public.workout_templates enable row level security;
alter table public.workout_template_exercises enable row level security;

create policy workout_templates_select_own on public.workout_templates
  for select to authenticated using (user_id = (select auth.uid()));
create policy workout_templates_insert_own on public.workout_templates
  for insert to authenticated with check (user_id = (select auth.uid()));
create policy workout_templates_update_own on public.workout_templates
  for update to authenticated using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()));
create policy workout_templates_delete_own on public.workout_templates
  for delete to authenticated using (user_id = (select auth.uid()));

-- Children: the row and its parent template must both be the user's own.
create policy workout_template_exercises_select_own on public.workout_template_exercises
  for select to authenticated using (user_id = (select auth.uid()));
create policy workout_template_exercises_insert_own on public.workout_template_exercises
  for insert to authenticated with check (
    user_id = (select auth.uid())
    and exists (select 1 from public.workout_templates t where t.id = template_id and t.user_id = (select auth.uid()))
  );
create policy workout_template_exercises_update_own on public.workout_template_exercises
  for update to authenticated using (user_id = (select auth.uid())) with check (
    user_id = (select auth.uid())
    and exists (select 1 from public.workout_templates t where t.id = template_id and t.user_id = (select auth.uid()))
  );
create policy workout_template_exercises_delete_own on public.workout_template_exercises
  for delete to authenticated using (user_id = (select auth.uid()));

grant select, insert, update, delete on public.workout_templates, public.workout_template_exercises to authenticated;

-- ===== supabase/migrations/20261021000020_faith_calendar.sql =====
-- Narrow Gate Fitness — Stage 2C: prayer journal, daily practices, faith reminders, secondary goal and
-- training-calendar reschedules (SPEC §3, §4, §12).
--
-- Every new table is private to its owner: owner-only RLS for select / insert / update / delete, no admin
-- access, and rows cascade away with the auth user on account deletion.

-- ---------------------------------------------------------------------------
-- Prayer journal: entry type, answered prayers and the AI-coach opt-in.
-- ---------------------------------------------------------------------------
-- kind: 'reflection' (general), 'request' (a prayer request) or 'praise' (praise / thanksgiving).
-- A request can be marked answered (answered_on + optional note).
-- share_with_coach is OFF by default: the AI coach only ever sees entries the user ticked.
alter table public.faith_journal_entries
  add column kind text not null default 'reflection' check (kind in ('reflection', 'request', 'praise')),
  add column answered_on date,
  add column answered_note text check (char_length(answered_note) <= 2000),
  add column share_with_coach boolean not null default false,
  add constraint faith_journal_answered_note_needs_date check (answered_note is null or answered_on is not null);

create index faith_journal_user_kind_idx on public.faith_journal_entries (user_id, kind, entry_date desc);

-- ---------------------------------------------------------------------------
-- Daily practices reuse discipline_goals / discipline_checkins. `practice` names the preset
-- (Scripture reading, prayer, gratitude, fasting, worship, rest/Sabbath) or 'custom'.
-- ---------------------------------------------------------------------------
alter table public.discipline_goals
  add column practice text not null default 'custom'
    check (practice in ('scripture', 'prayer', 'gratitude', 'fasting', 'worship', 'rest', 'custom'));

-- One active row per preset practice (custom practices can repeat).
create unique index discipline_goals_one_preset_idx on public.discipline_goals (user_id, practice)
  where practice <> 'custom' and is_active;

-- ---------------------------------------------------------------------------
-- Faith reminders: optional, off by default (no row = off). Delivered as local notifications by the
-- iPhone / Android app; the web app only stores the settings.
-- ---------------------------------------------------------------------------
create table public.faith_reminders (
  user_id uuid not null references auth.users (id) on delete cascade,
  kind text not null check (kind in ('devotional', 'prayer', 'practices')),
  enabled boolean not null default false,
  remind_at time not null default '07:00',
  -- JavaScript weekdays: 0 = Sunday … 6 = Saturday.
  weekdays smallint[] not null default '{0,1,2,3,4,5,6}'
    check (cardinality(weekdays) <= 7 and weekdays <@ array[0, 1, 2, 3, 4, 5, 6]::smallint[]),
  updated_at timestamptz not null default now(),
  primary key (user_id, kind)
);
create trigger faith_reminders_updated_at before update on public.faith_reminders
  for each row execute function public.set_updated_at();

-- ---------------------------------------------------------------------------
-- Secondary goal (optional, onboarding).
-- ---------------------------------------------------------------------------
alter table public.onboarding_answers
  add column secondary_goal text check (secondary_goal in (
    'build_strength', 'build_muscle', 'lose_fat', 'improve_conditioning', 'athletic_performance',
    'combat_sports', 'general_health', 'mobility', 'run_5k'
  ));

-- ---------------------------------------------------------------------------
-- Training calendar: a planned program session moved to another date. Keyed by the enrolment and the
-- program day, so completed workouts (workout_sessions) are never touched by a reschedule.
-- ---------------------------------------------------------------------------
create table public.planned_session_overrides (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users (id) on delete cascade,
  user_program_id uuid not null references public.user_programs (id) on delete cascade,
  program_day_id uuid not null references public.program_days (id) on delete cascade,
  planned_date date not null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint planned_session_overrides_unique unique (user_program_id, program_day_id)
);
create index planned_session_overrides_user_idx on public.planned_session_overrides (user_id, planned_date);
create trigger planned_session_overrides_updated_at before update on public.planned_session_overrides
  for each row execute function public.set_updated_at();

-- ---------------------------------------------------------------------------
-- Row Level Security: owner-only
-- ---------------------------------------------------------------------------
alter table public.faith_reminders enable row level security;
alter table public.planned_session_overrides enable row level security;

create policy faith_reminders_select_own on public.faith_reminders
  for select to authenticated using (user_id = (select auth.uid()));
create policy faith_reminders_insert_own on public.faith_reminders
  for insert to authenticated with check (user_id = (select auth.uid()));
create policy faith_reminders_update_own on public.faith_reminders
  for update to authenticated using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()));
create policy faith_reminders_delete_own on public.faith_reminders
  for delete to authenticated using (user_id = (select auth.uid()));

-- The row and the enrolment it reschedules must both be the user's own.
create policy planned_session_overrides_select_own on public.planned_session_overrides
  for select to authenticated using (user_id = (select auth.uid()));
create policy planned_session_overrides_insert_own on public.planned_session_overrides
  for insert to authenticated with check (
    user_id = (select auth.uid())
    and exists (select 1 from public.user_programs up where up.id = user_program_id and up.user_id = (select auth.uid()))
  );
create policy planned_session_overrides_update_own on public.planned_session_overrides
  for update to authenticated using (user_id = (select auth.uid())) with check (
    user_id = (select auth.uid())
    and exists (select 1 from public.user_programs up where up.id = user_program_id and up.user_id = (select auth.uid()))
  );
create policy planned_session_overrides_delete_own on public.planned_session_overrides
  for delete to authenticated using (user_id = (select auth.uid()));

comment on table public.faith_reminders is 'Optional devotional / prayer / practice reminder settings (off by default). Owner-only.';
comment on table public.planned_session_overrides is 'Planned program sessions moved to another date on the training calendar. Owner-only.';
comment on column public.faith_journal_entries.share_with_coach is 'Off by default. Only entries with this set are ever included in the AI coach context.';

-- ===== supabase/migrations/20261022000021_memberships_stage1.sql =====
-- Narrow Gate Fitness — AI model routing (memberships stage 1).
--
-- Pro coaching runs most requests on a fast model and sends plan generation and complex coaching questions to a
-- larger model, capped at a monthly share. Each usage row now records which model served it so the cap can be
-- enforced and costs reviewed. Rows written before routing existed count as the fast tier.
-- Users still can't write their own usage rows (service role only), so the cap can't be bypassed from the client.
alter table public.ai_usage_events
  add column model text check (char_length(model) <= 100),
  add column model_tier text not null default 'fast' check (model_tier in ('fast', 'smart'));

create index ai_usage_events_user_tier_idx on public.ai_usage_events (user_id, model_tier, created_at desc);

-- AI data-sharing consent. The AI coach sends parts of the user's own data to the AI provider (Anthropic) to
-- answer. Nothing is sent until the user allows it on the coach screen; they can withdraw it any time in
-- Profile & Settings, which stops the coach until they allow it again (App Store guideline 5.1.2(i)).
alter table public.profiles add column ai_data_consent_at timestamptz;
grant update (ai_data_consent_at) on public.profiles to authenticated;

-- ===== supabase/migrations/20261022000022_legacy_plan_terms.sql =====
-- Narrow Gate Fitness — keep existing subscribers' AI allowance through the October 2026 plan change.
--
-- Before this change Plus included an AI coach allowance (60 messages a month) and Pro 400 messages and 20 plan
-- generations. Under the new plans Plus has no AI and Pro has 150 messages. So nobody who is already paying loses
-- anything unexpectedly, every Stripe subscription that exists when this migration runs keeps its previous AI
-- allowance for as long as that subscription stays on the same plan and keeps access. Subscriptions created
-- afterwards follow the new plans. If there are no existing subscriptions, nothing is inserted.
--
-- Nothing in `subscriptions` or `user_entitlements` is changed. The terms end on their own when the subscription
-- ends (cancelled and past its paid period, or expired). The owner can end them earlier with notice by setting
-- `ends_at`. The allowances below are the previous code defaults; if production overrode them with
-- PLAN_PLUS_AI_MONTHLY_LIMIT / PLAN_PRO_AI_MONTHLY_LIMIT, update these rows to match.
create table public.legacy_plan_terms (
  stripe_subscription_id text primary key references public.subscriptions (stripe_subscription_id) on delete cascade,
  user_id uuid not null references auth.users (id) on delete cascade,
  plan text not null check (plan in ('plus', 'pro')),
  ai_monthly_limit integer not null check (ai_monthly_limit >= 0),
  ai_plan_monthly_limit integer not null check (ai_plan_monthly_limit >= 0),
  ai_smart_monthly_limit integer not null check (ai_smart_monthly_limit >= 0),
  ends_at timestamptz,
  reason text not null default 'Subscribed before the October 2026 plan change' check (char_length(reason) <= 200),
  created_at timestamptz not null default now()
);
create index legacy_plan_terms_user_idx on public.legacy_plan_terms (user_id);

alter table public.legacy_plan_terms enable row level security;
-- Members can see their own kept terms (shown on Plans & billing); only the service role writes.
create policy legacy_plan_terms_select_own on public.legacy_plan_terms
  for select to authenticated using (user_id = (select auth.uid()));

-- One-time snapshot: every subscription that has, or can still regain, access when this migration runs.
-- (Run once here, not kept as a callable function, so later subscriptions can't be added to it by mistake.)
select s.stripe_subscription_id, s.user_id, s.plan,
       case s.plan when 'plus' then 60 else 400 end,
       case s.plan when 'plus' then 0 else 20 end,
       case s.plan when 'plus' then 6 else 40 end
from public.subscriptions s
where s.status in ('active', 'trialing', 'past_due', 'unpaid', 'paused')
   or (s.status = 'canceled' and s.current_period_end > now())
on conflict (stripe_subscription_id) do nothing;

-- ===== supabase/migrations/20261022000023_store_subscriptions.sql =====
-- Narrow Gate Fitness — App Store / Google Play subscriptions through RevenueCat (stage 2).
--
-- RevenueCat is the source of truth for in-app purchases. After every RevenueCat webhook (and after a purchase or
-- "Restore purchases" in the app) the server fetches the customer's current state from RevenueCat's REST API and
-- stores one row per store product here. Entitlements are then recomputed from these rows together with the
-- Stripe rows in `subscriptions`, so a member who pays on both gets the higher plan. Only the service role writes.
create table public.store_subscriptions (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users (id) on delete cascade,
  store text not null check (store in ('app_store', 'play_store', 'test_store', 'other')),
  product_id text not null check (char_length(product_id) <= 200),
  -- The plan this product grants (from the RevenueCat entitlement it unlocks). Null if it isn't attached to one.
  plan text check (plan in ('plus', 'pro')),
  period_type text check (char_length(period_type) <= 20),
  purchased_at timestamptz,
  original_purchased_at timestamptz,
  expires_at timestamptz,
  grace_period_expires_at timestamptz,
  unsubscribe_detected_at timestamptz,
  billing_issue_detected_at timestamptz,
  refunded_at timestamptz,
  is_sandbox boolean not null default false,
  ownership_type text check (char_length(ownership_type) <= 30),
  store_transaction_id text check (char_length(store_transaction_id) <= 200),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (user_id, store, product_id)
);
create index store_subscriptions_user_idx on public.store_subscriptions (user_id);
create trigger store_subscriptions_updated_at before update on public.store_subscriptions
  for each row execute function public.set_updated_at();

alter table public.store_subscriptions enable row level security;
create policy store_subscriptions_select_own on public.store_subscriptions
  for select to authenticated using (user_id = (select auth.uid()));

-- Webhook deliveries already processed (RevenueCat retries with the same event id). No personal data is kept.
create table public.revenuecat_events (
  id text primary key check (char_length(id) <= 200),
  type text not null check (char_length(type) <= 60),
  environment text check (char_length(environment) <= 20),
  processed_at timestamptz not null default now()
);
alter table public.revenuecat_events enable row level security;
-- revenuecat_events: no policies — service role only.

-- Entitlements can now come from the stores as well as Stripe and admin grants.
alter table public.user_entitlements drop constraint user_entitlements_source_check;
alter table public.user_entitlements
  add constraint user_entitlements_source_check check (source in ('default', 'stripe', 'admin', 'app_store', 'play_store'));

-- ===== supabase/migrations/20261023000024_plan_enforcement.sql =====
-- Narrow Gate Fitness — enforce paid features in the database as well as in the server actions.
--
-- The Supabase anon key is public, so a signed-in member can call the REST API with their own session and skip the
-- server actions. Row level security already kept every member to their own rows, but it didn't check the plan, so
-- a Free member could create recipes, meal plans and grocery lists, build custom or AI programs, save more than five
-- workouts, move calendar sessions, enrol in Plus programs and read their prescriptions. These policies add the plan
-- check. Nothing existing is changed or removed: they only govern new writes (and reads of paid prescriptions), so
-- a member who downgrades keeps everything they made.

-- The member's current plan: their entitlement while it's valid, otherwise Free (the same rule as getUserPlan in
-- src/server/auth.ts). Anonymous visitors are Free.
create or replace function public.plan_of(p_user_id uuid)
returns text
language sql
stable
security definer
set search_path = public
as $$
  select coalesce(
    (select e.plan from public.user_entitlements e
      where e.user_id = p_user_id and (e.valid_until is null or e.valid_until > now())),
    'free');
$$;

create or replace function public.plan_rank(p_plan text)
returns integer
language sql
immutable
as $$
  select case p_plan when 'pro' then 2 when 'plus' then 1 else 0 end;
$$;

-- Does the signed-in member's plan include `p_min_plan`?
create or replace function public.has_plan(p_min_plan text)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select public.plan_rank(public.plan_of(auth.uid())) >= public.plan_rank(p_min_plan);
$$;

-- Can the signed-in member use this program's prescriptions: their own program, a published program at their
-- plan's tier or below, or as an admin.
create or replace function public.can_use_program(p_program_id uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1 from public.training_programs p
    where p.id = p_program_id
      and (p.owner_id = auth.uid() or public.is_admin() or (p.is_published and public.has_plan(p.tier)))
  );
$$;

revoke all on function public.plan_of(uuid) from public, anon, authenticated;
grant execute on function public.plan_of(uuid) to authenticated, service_role;

-- Program prescriptions (sets, reps, rest) of paid programs: only for members whose plan includes them. Week and
-- day names stay readable, as the program page shows them as a preview.
drop policy if exists program_exercises_read on public.program_exercises;
create policy program_exercises_read on public.program_exercises
  for select to anon, authenticated using (public.can_use_program(public.program_of_day(day_id)));

-- Enrolling in a program needs a plan that includes it.
drop policy if exists user_programs_visible_program on public.user_programs;
create policy user_programs_visible_program on public.user_programs
  as restrictive for insert to authenticated with check (public.can_use_program(program_id));

-- Private programs: starter programs (built at sign-up) for everyone, custom programs with Plus, AI programs with Pro.
drop policy if exists training_programs_insert on public.training_programs;
create policy training_programs_insert on public.training_programs
  for insert to authenticated with check (
    (
      owner_id = (select auth.uid()) and is_published = false
      and (
        source = 'starter'
        or (source = 'custom' and public.has_plan('plus'))
        or (source = 'ai' and public.has_plan('pro'))
      )
    )
    or (owner_id is null and public.is_admin())
  );

-- Recipes, the meal planner and grocery lists (Plus): creating new rows needs the plan.
do $$
declare
  t text;
begin
  foreach t in array array[
    'recipes', 'recipe_ingredients', 'meal_plan_settings', 'meal_plans', 'meal_plan_entries', 'grocery_lists', 'grocery_items'
  ] loop
    execute format('create policy %I on public.%I as restrictive for insert to authenticated with check (public.has_plan(''plus''))', t || '_plan', t);
  end loop;
end;
$$;

-- Moving a session on the calendar (Plus). Moving it back (deleting the override) stays open to everyone.
create policy planned_session_overrides_plan_insert on public.planned_session_overrides
  as restrictive for insert to authenticated with check (public.has_plan('plus'));
create policy planned_session_overrides_plan_update on public.planned_session_overrides
  as restrictive for update to authenticated using (public.has_plan('plus')) with check (public.has_plan('plus'));

-- Saved workouts: five on Free (PLAN_FREE_TEMPLATE_LIMIT's default in src/lib/domain/plans.ts; keep them equal).
-- A trigger rather than a policy, so two saves at the same moment can't both slip under the limit: it takes a
-- per-member lock before counting.
create or replace function public.enforce_free_template_limit()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  perform pg_advisory_xact_lock(hashtextextended('workout_templates:' || new.user_id::text, 0));
  if public.plan_rank(public.plan_of(new.user_id)) = 0
     and (select count(*) from public.workout_templates where user_id = new.user_id) >= 5 then
    raise exception 'Free plan limit: 5 saved workouts' using errcode = 'P0001';
  end if;
  return new;
end;
$$;
create trigger workout_templates_free_limit before insert on public.workout_templates
  for each row execute function public.enforce_free_template_limit();

-- ===== supabase/migrations/20261023000025_ai_usage_reservation.sql =====
-- Narrow Gate Fitness — make the AI coach's limits exact and impossible to sidestep.
--
-- Before: usage was recorded after the reply was saved, so (a) several requests sent at once could all pass the
-- check before any was counted, and (b) a request whose reply failed to save (for example because the member
-- deleted the conversation mid-reply) was never counted, though the member had already seen the streamed text.
-- Now the server reserves a usage row before calling the AI provider, under a per-member lock that re-checks every
-- limit, and fills in the model and token counts afterwards. A reservation is removed only if the provider call
-- itself fails, so members aren't charged for errors.

create or replace function public.reserve_ai_usage(
  p_user_id uuid,
  p_kind text,
  p_tier text,
  p_chat_limit integer,
  p_plan_limit integer,
  p_smart_limit integer,
  p_per_minute integer
)
returns table (usage_id uuid, model_tier text)
language plpgsql
security definer
set search_path = public
as $$
declare
  v_month timestamptz := date_trunc('month', now() at time zone 'utc') at time zone 'utc';
  v_total integer;
  v_plans integer;
  v_smart integer;
  v_recent integer;
  v_tier text := p_tier;
begin
  perform pg_advisory_xact_lock(hashtextextended('ai_usage:' || p_user_id::text, 0));
  select count(*), count(*) filter (where e.kind = 'plan'), count(*) filter (where e.model_tier = 'smart')
    into v_total, v_plans, v_smart
    from public.ai_usage_events e where e.user_id = p_user_id and e.created_at >= v_month;
  select count(*) into v_recent from public.ai_usage_events e where e.user_id = p_user_id and e.created_at >= now() - interval '60 seconds';
  if v_recent >= p_per_minute then
    raise exception 'ai_rate_limited' using errcode = 'P0001';
  end if;
  if v_total >= p_chat_limit then
    raise exception 'ai_quota' using errcode = 'P0001';
  end if;
  if p_kind = 'plan' and (v_plans >= p_plan_limit or v_smart >= p_smart_limit) then
    raise exception 'ai_quota_plan' using errcode = 'P0001';
  end if;
  -- A chat that would have used the larger model falls back to the fast one once that share is used up.
  if v_tier = 'smart' and v_smart >= p_smart_limit then
    v_tier := 'fast';
  end if;
    values (p_user_id, p_kind, v_tier)
    returning id into usage_id;
  model_tier := v_tier;
  return next;
end;
$$;
revoke all on function public.reserve_ai_usage(uuid, text, text, integer, integer, integer, integer) from public, anon, authenticated;
grant execute on function public.reserve_ai_usage(uuid, text, text, integer, integer, integer, integer) to service_role;

-- Coach messages: members write only their own questions (replies are written by the server), and can only change
-- a suggestion's status, not any message's text. This stops a member planting long fake "assistant" turns that
-- would be sent to the AI as history.
drop policy if exists ai_messages_insert_own on public.ai_messages;
create policy ai_messages_insert_own on public.ai_messages
  for insert to authenticated with check (
    user_id = (select auth.uid())
    and role = 'user'
    and exists (select 1 from public.ai_conversations c where c.id = conversation_id and c.user_id = (select auth.uid()))
  );
revoke update on public.ai_messages from authenticated;
grant update (proposal_status) on public.ai_messages to authenticated;

-- ===== supabase/migrations/20261024000026_coach_memory.sql =====
-- Narrow Gate Fitness — long-term AI coaching memory (Pro).
--
-- Memories are short notes the coach keeps about a member across conversations and devices: a secondary goal, an
-- exercise they prefer, when they train, how they like to be coached, a change they approved. They hold only what
-- the structured data doesn't (goal, experience, equipment, program, logs and targets stay in their own tables and
-- are read fresh every turn). Nothing is saved without the member: memory is off until they turn it on, the coach
-- can only suggest a memory (the member saves, edits or declines it), and every memory can be viewed, edited and
-- deleted. Deleting the account removes them (on delete cascade).

-- Does the signed-in member have the AI coach: Pro, or a subscription that kept its AI allowance from before the
-- October 2026 plan change (the same rule as aiAllowance / legacyTermsApply in src/lib/domain/plans.ts).
create or replace function public.has_ai_coach()
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select public.has_plan('pro') or exists (
    select 1
    from public.legacy_plan_terms t
    join public.subscriptions s on s.stripe_subscription_id = t.stripe_subscription_id
    where t.user_id = auth.uid()
      and t.ai_monthly_limit > 0
      and (t.ends_at is null or t.ends_at > now())
      and s.plan = t.plan
      and s.status in ('active', 'trialing', 'past_due')
      and (s.current_period_end is null or s.current_period_end > now())
  );
$$;
revoke all on function public.has_ai_coach() from public, anon;
grant execute on function public.has_ai_coach() to authenticated, service_role;

-- The member's switch (off by default; turning it on is their consent) and when they agreed.
alter table public.profiles
  add column coach_memory_enabled boolean not null default false,
  add column coach_memory_consent_at timestamptz;
grant update (coach_memory_enabled, coach_memory_consent_at) on public.profiles to authenticated;

-- "Don't remember anything from this chat."
alter table public.ai_conversations add column memory_off boolean not null default false;

create table public.coach_memories (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users (id) on delete cascade,
  category text not null check (category in (
    'goals', 'experience', 'exercise_preferences', 'equipment', 'schedule', 'nutrition',
    'training_changes', 'recovery', 'milestones', 'coaching_style', 'other'
  )),
  content text not null check (char_length(content) between 3 and 300),
  -- coach: suggested by the coach and saved by the member; member: added on the memory screen;
  -- approved_change: recorded when the member confirmed a coach-suggested change.
  source text not null default 'member' check (source in ('coach', 'member', 'approved_change')),
  source_message_id uuid references public.ai_messages (id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index coach_memories_user_idx on public.coach_memories (user_id, created_at desc);
create trigger coach_memories_updated_at before update on public.coach_memories
  for each row execute function public.set_updated_at();

alter table public.coach_memories enable row level security;

-- Members always see and can delete their own memories (also after a downgrade or with memory switched off).
create policy coach_memories_select_own on public.coach_memories
  for select to authenticated using (user_id = (select auth.uid()));
create policy coach_memories_delete_own on public.coach_memories
  for delete to authenticated using (user_id = (select auth.uid()));
-- Adding or editing needs the AI coach and memory switched on.
create policy coach_memories_insert_own on public.coach_memories
  for insert to authenticated with check (
    user_id = (select auth.uid())
    and public.has_ai_coach()
    and exists (select 1 from public.profiles p where p.id = (select auth.uid()) and p.coach_memory_enabled)
  );
create policy coach_memories_update_own on public.coach_memories
  for update to authenticated
  using (user_id = (select auth.uid()))
  with check (
    user_id = (select auth.uid())
    and public.has_ai_coach()
    and exists (select 1 from public.profiles p where p.id = (select auth.uid()) and p.coach_memory_enabled)
  );
revoke update on public.coach_memories from authenticated;
grant update (category, content) on public.coach_memories to authenticated;

-- At most 100 memories per member (MEMORY_LIMIT in src/lib/coach/memory.ts; keep them equal). Locked per member so
-- two saves at once can't both slip under the limit.
create or replace function public.enforce_coach_memory_limit()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  perform pg_advisory_xact_lock(hashtextextended('coach_memories:' || new.user_id::text, 0));
  if (select count(*) from public.coach_memories where user_id = new.user_id) >= 100 then
    raise exception 'coach_memory_limit' using errcode = 'P0001';
  end if;
  return new;
end;
$$;
create trigger coach_memories_limit before insert on public.coach_memories
  for each row execute function public.enforce_coach_memory_limit();

-- ===== supabase/migrations/20261024000027_adaptive_training.sql =====
-- Narrow Gate Fitness — adaptive training and recovery (Pro).
--
-- The training review (and the AI coach) suggest changes from the member's logs: a target load for the next
-- session, a recovery week, one more or one fewer set. Nothing changes unless the member accepts, and every accepted
-- change is recorded with what it replaced, so it can be reviewed and undone. Workout history is never touched.

-- Approved target loads, shown in the workout logger beside "Last time".
create table public.exercise_targets (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users (id) on delete cascade,
  exercise_id uuid not null references public.exercises (id) on delete cascade,
  weight_kg numeric(6, 2) check (weight_kg > 0 and weight_kg <= 1000),
  reps smallint check (reps between 1 and 100),
  note text check (char_length(note) <= 300),
  source text not null check (source in ('review', 'coach')),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (user_id, exercise_id)
);
create trigger exercise_targets_updated_at before update on public.exercise_targets
  for each row execute function public.set_updated_at();

-- Every accepted change, with the values it replaced (for review and undo).
create table public.training_adjustments (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users (id) on delete cascade,
  program_id uuid references public.training_programs (id) on delete cascade,
  kind text not null check (kind in ('exercise_target', 'deload_week', 'volume_change')),
  summary text not null check (char_length(summary) <= 300),
  reason text check (char_length(reason) <= 1000),
  -- [{ "table": "program_exercises" | "program_weeks" | "exercise_targets", "id": uuid, "before": {...}, "after": {...} }]
  changes jsonb not null default '[]',
  source text not null check (source in ('review', 'coach')),
  recommendation_key text check (char_length(recommendation_key) <= 200),
  source_message_id uuid references public.ai_messages (id) on delete set null,
  created_at timestamptz not null default now(),
  reverted_at timestamptz
);
create index training_adjustments_user_idx on public.training_adjustments (user_id, created_at desc);

-- Recommendations the member accepted or turned down, so they aren't offered again.
create table public.training_recommendation_decisions (
  user_id uuid not null references auth.users (id) on delete cascade,
  recommendation_key text not null check (char_length(recommendation_key) <= 200),
  decision text not null check (decision in ('accepted', 'rejected')),
  decided_at timestamptz not null default now(),
  primary key (user_id, recommendation_key)
);

alter table public.exercise_targets enable row level security;
alter table public.training_adjustments enable row level security;
alter table public.training_recommendation_decisions enable row level security;

-- Members always see and can remove their own rows (also after a downgrade); creating or changing them needs Pro.
create policy exercise_targets_select_own on public.exercise_targets for select to authenticated using (user_id = (select auth.uid()));
create policy exercise_targets_delete_own on public.exercise_targets for delete to authenticated using (user_id = (select auth.uid()));
create policy exercise_targets_insert_own on public.exercise_targets for insert to authenticated
  with check (user_id = (select auth.uid()) and public.has_ai_coach());
create policy exercise_targets_update_own on public.exercise_targets for update to authenticated
  using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()) and public.has_ai_coach());

create policy training_adjustments_select_own on public.training_adjustments for select to authenticated using (user_id = (select auth.uid()));
create policy training_adjustments_delete_own on public.training_adjustments for delete to authenticated using (user_id = (select auth.uid()));
create policy training_adjustments_insert_own on public.training_adjustments for insert to authenticated
  with check (user_id = (select auth.uid()) and public.has_ai_coach());
-- Only the undo mark can change.
create policy training_adjustments_update_own on public.training_adjustments for update to authenticated
  using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()));
revoke update on public.training_adjustments from authenticated;
grant update (reverted_at) on public.training_adjustments to authenticated;

create policy training_decisions_select_own on public.training_recommendation_decisions for select to authenticated using (user_id = (select auth.uid()));
create policy training_decisions_delete_own on public.training_recommendation_decisions for delete to authenticated using (user_id = (select auth.uid()));
create policy training_decisions_insert_own on public.training_recommendation_decisions for insert to authenticated
  with check (user_id = (select auth.uid()) and public.has_ai_coach());
create policy training_decisions_update_own on public.training_recommendation_decisions for update to authenticated
  using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()) and public.has_ai_coach());

-- ===== supabase/migrations/20261024000028_ai_meal_plans.sql =====
-- Narrow Gate Fitness — personalized AI meal plans (Pro), and the AI usage kinds for the later AI food features.
--
-- The AI only chooses among dishes the app can already measure (the member's recipes and saved meals and the
-- built-in recipes, all with nutrition from the food database) and suggests portions. Every number shown is
-- computed by the app from those values, never by the AI. A generated plan is a draft until the member approves
-- it; only then does it become a normal meal plan (swap, portions, log to diary, grocery list as before).

-- Each AI request is still one of the member's monthly AI messages; the kind says what it was for.
alter table public.ai_usage_events drop constraint if exists ai_usage_events_kind_check;
alter table public.ai_usage_events add constraint ai_usage_events_kind_check
  check (kind in ('chat', 'plan', 'meal_plan', 'food_photo', 'food_explain'));

-- One draft per member, replaced by the next generation, removed when approved or discarded.
create table public.meal_plan_drafts (
  user_id uuid primary key references auth.users (id) on delete cascade,
  start_date date not null,
  days smallint not null check (days in (1, 3, 7)),
  focus text not null check (focus in ('balanced', 'high_protein', 'weight_loss', 'muscle_gain', 'maintenance')),
  notes text check (char_length(notes) <= 300),
  -- Targets the plan was built for, with how they were derived.
  targets jsonb not null check (jsonb_typeof(targets) = 'object' and octet_length(targets::text) <= 2000),
  settings jsonb not null check (jsonb_typeof(settings) = 'object' and octet_length(settings::text) <= 4000),
  -- [{ date, meals: [{ slotIndex, key, portion, by: 'ai' | 'planner' }] }]: dish keys and portions only.
  days_plan jsonb not null check (jsonb_typeof(days_plan) = 'array' and octet_length(days_plan::text) <= 40000),
  summary text check (char_length(summary) <= 1500),
  model text check (char_length(model) <= 100),
  created_at timestamptz not null default now()
);

alter table public.meal_plan_drafts enable row level security;
create policy meal_plan_drafts_select_own on public.meal_plan_drafts for select to authenticated using (user_id = (select auth.uid()));
create policy meal_plan_drafts_delete_own on public.meal_plan_drafts for delete to authenticated using (user_id = (select auth.uid()));
-- Drafts are written by the server after an AI request (service role); members can't plant their own.

-- ===== supabase/migrations/20261024000029_gps_running.sql =====
-- Narrow Gate Fitness — live GPS runs and walks, running goals (basic tracking is free).
--
-- GPS recordings already fit the activities table (source 'gps', route, splits, moving vs elapsed time, private by
-- default, one save per client-generated id). This adds limits on what a recording can store, a note of the signal
-- quality (so gaps are shown honestly), an optional link to the program session a guided run completed, and
-- running goals.

alter table public.activities
  add column gps_quality jsonb check (gps_quality is null or (jsonb_typeof(gps_quality) = 'object' and octet_length(gps_quality::text) <= 1000)),
  add column workout_session_id uuid references public.workout_sessions (id) on delete set null;

-- Keep a single recording to a sane size (the app simplifies routes to at most 2,000 points before saving).
alter table public.activities
  add constraint activities_route_size check (route is null or (jsonb_typeof(route) = 'object' and octet_length(route::text) <= 150000)),
  add constraint activities_splits_size check (splits is null or jsonb_array_length(splits) <= 600);

-- Running goals: a weekly or monthly distance, or a target time for a distance (e.g. 5 km in 28:00).
create table public.running_goals (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users (id) on delete cascade,
  kind text not null check (kind in ('weekly_distance', 'monthly_distance', 'race_time')),
  distance_m numeric(9, 1) not null check (distance_m > 0 and distance_m <= 1000000),
  target_s integer check (target_s is null or target_s between 60 and 172800),
  created_at timestamptz not null default now(),
  archived_at timestamptz,
  check ((kind = 'race_time') = (target_s is not null))
);
create index running_goals_user_idx on public.running_goals (user_id, created_at desc);

alter table public.running_goals enable row level security;
create policy running_goals_select_own on public.running_goals for select to authenticated using (user_id = (select auth.uid()));
create policy running_goals_insert_own on public.running_goals for insert to authenticated with check (user_id = (select auth.uid()));
create policy running_goals_update_own on public.running_goals for update to authenticated using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()));
create policy running_goals_delete_own on public.running_goals for delete to authenticated using (user_id = (select auth.uid()));

-- At most 10 open goals per member.
create or replace function public.enforce_running_goal_limit()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  perform pg_advisory_xact_lock(hashtextextended('running_goals:' || new.user_id::text, 0));
  if (select count(*) from public.running_goals where user_id = new.user_id and archived_at is null) >= 10 then
    raise exception 'running_goal_limit' using errcode = 'P0001';
  end if;
  return new;
end;
$$;
create trigger running_goals_limit before insert on public.running_goals
  for each row execute function public.enforce_running_goal_limit();

-- ===== supabase/migrations/20261024000030_strength_ranks.sql =====
-- Strength ranks on the muscle map (Plus and Pro) compare each lift with a men's or a women's table. The member picks
-- the table on the map itself; the profile's `sex` answer stays limited to calorie estimates, as onboarding says.
-- Ranks are computed from logged workouts when the map is opened and are never stored, like the milestone badges.

alter table public.profiles
  add column if not exists strength_standards text check (strength_standards in ('men', 'women'));

grant update (strength_standards) on public.profiles to authenticated;

-- ===== supabase/migrations/20261024000031_body_scans.sql =====
-- Body Scan (Pro): guided front, side and optional rear photos with optional measurements, kept apart from the
-- ordinary progress photos. Photos live in the PRIVATE `body-scans` bucket under "<uid>/<scan id>/...". Only the
-- owner can read or delete them; there is no admin access anywhere. Nothing here estimates body fat, and no image is
-- sent to the AI coach or any other service.
--
-- New scans need Pro and the member's explicit consent (recorded with the time). Viewing and deleting never need
-- either, so a member who downgrades or withdraws consent can still see and remove what they stored.

alter table public.profiles add column if not exists body_scan_consent_at timestamptz;
grant update (body_scan_consent_at) on public.profiles to authenticated;

create or replace function public.can_add_body_scan()
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select public.has_plan('pro')
    and exists (select 1 from public.profiles p where p.id = auth.uid() and p.body_scan_consent_at is not null);
$$;
revoke all on function public.can_add_body_scan() from public, anon;
grant execute on function public.can_add_body_scan() to authenticated, service_role;

create table public.body_scans (
  -- Generated on the device before upload, so a retried save can't create a second scan.
  id uuid primary key,
  user_id uuid not null references auth.users (id) on delete cascade,
  taken_on date not null,
  weight_kg numeric(5, 2) check (weight_kg between 25 and 400),
  -- Measurements entered with the scan are stored in the ordinary measurement history.
  measurement_id uuid references public.measurement_entries (id) on delete set null,
  note text check (char_length(note) <= 280),
  created_at timestamptz not null default now()
);
create index body_scans_user_idx on public.body_scans (user_id, taken_on desc);

create table public.body_scan_photos (
  id uuid primary key default gen_random_uuid(),
  scan_id uuid not null references public.body_scans (id) on delete cascade,
  user_id uuid not null references auth.users (id) on delete cascade,
  pose text not null check (pose in ('front', 'side', 'back')),
  storage_path text not null unique check (char_length(storage_path) between 3 and 300),
  created_at timestamptz not null default now(),
  unique (scan_id, pose),
  -- The object must live in the owner's folder for this scan.
  check (split_part(storage_path, '/', 1) = user_id::text),
  check (split_part(storage_path, '/', 2) = scan_id::text)
);
create index body_scan_photos_user_idx on public.body_scan_photos (user_id);

alter table public.body_scans enable row level security;
alter table public.body_scan_photos enable row level security;

create policy body_scans_select_own on public.body_scans
  for select to authenticated using (user_id = (select auth.uid()));
create policy body_scans_delete_own on public.body_scans
  for delete to authenticated using (user_id = (select auth.uid()));
create policy body_scans_insert_own on public.body_scans
  for insert to authenticated with check (user_id = (select auth.uid()) and public.can_add_body_scan());

create policy body_scan_photos_select_own on public.body_scan_photos
  for select to authenticated using (user_id = (select auth.uid()));
create policy body_scan_photos_delete_own on public.body_scan_photos
  for delete to authenticated using (user_id = (select auth.uid()));
create policy body_scan_photos_insert_own on public.body_scan_photos
  for insert to authenticated with check (
    user_id = (select auth.uid())
    and public.can_add_body_scan()
    and exists (select 1 from public.body_scans b where b.id = scan_id and b.user_id = (select auth.uid()))
  );

-- At most 200 scans per member (about four years of weekly scans), checked under a per-member lock.
create or replace function public.body_scan_limit()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  perform pg_advisory_xact_lock(hashtext('body_scans:' || new.user_id::text));
  if (select count(*) from public.body_scans where user_id = new.user_id) >= 200 then
    raise exception 'body_scan_limit' using errcode = 'P0001';
  end if;
  return new;
end;
$$;
create trigger body_scans_limit before insert on public.body_scans for each row execute function public.body_scan_limit();

-- Storage: private, images only, 8 MB per object. Read and delete your own folder; upload only with Pro and consent.
values ('body-scans', 'body-scans', false, 8388608, array['image/jpeg', 'image/png', 'image/webp'])
on conflict (id) do nothing;

create policy body_scans_owner_select on storage.objects
  for select to authenticated
  using (bucket_id = 'body-scans' and (storage.foldername(name))[1] = (select auth.uid())::text);
create policy body_scans_owner_insert on storage.objects
  for insert to authenticated
  with check (bucket_id = 'body-scans' and (storage.foldername(name))[1] = (select auth.uid())::text and public.can_add_body_scan());
create policy body_scans_owner_delete on storage.objects
  for delete to authenticated
  using (bucket_id = 'body-scans' and (storage.foldername(name))[1] = (select auth.uid())::text);

-- ===== supabase/migrations/20261024000032_food_photos.sql =====
-- AI food-photo recognition (Pro). A meal photo is sent to the AI provider only after the member's separate,
-- explicit consent, recorded here with the time. Photos are never stored: the server reads the upload in memory,
-- sends it once, and keeps only the items the member confirms (as ordinary diary entries marked as estimates).

alter table public.profiles add column if not exists food_photo_consent_at timestamptz;
grant update (food_photo_consent_at) on public.profiles to authenticated;

-- Diary entries confirmed from a photo estimate say where they came from.
alter table public.meal_items drop constraint if exists meal_items_source_check;
alter table public.meal_items add constraint meal_items_source_check
  check (source ~ '^(usda:[0-9]{1,10}|off:[0-9]{8,14}|food:[0-9a-f-]{36}|recipe:[0-9a-f-]{36}|app:[a-z0-9-]{1,60}|photo|custom)$');

-- Same reservation as before (one per-member lock re-checks every limit), plus an image cost control: at most
-- 20 food-photo analyses in any 24 hours. Photos also count toward the monthly AI allowance like any request.
create or replace function public.reserve_ai_usage(
  p_user_id uuid,
  p_kind text,
  p_tier text,
  p_chat_limit integer,
  p_plan_limit integer,
  p_smart_limit integer,
  p_per_minute integer
)
returns table (usage_id uuid, model_tier text)
language plpgsql
security definer
set search_path = public
as $$
declare
  v_month timestamptz := date_trunc('month', now() at time zone 'utc') at time zone 'utc';
  v_total integer;
  v_plans integer;
  v_smart integer;
  v_recent integer;
  v_tier text := p_tier;
begin
  perform pg_advisory_xact_lock(hashtextextended('ai_usage:' || p_user_id::text, 0));
  select count(*), count(*) filter (where e.kind = 'plan'), count(*) filter (where e.model_tier = 'smart')
    into v_total, v_plans, v_smart
    from public.ai_usage_events e where e.user_id = p_user_id and e.created_at >= v_month;
  select count(*) into v_recent from public.ai_usage_events e where e.user_id = p_user_id and e.created_at >= now() - interval '60 seconds';
  if v_recent >= p_per_minute then
    raise exception 'ai_rate_limited' using errcode = 'P0001';
  end if;
  if v_total >= p_chat_limit then
    raise exception 'ai_quota' using errcode = 'P0001';
  end if;
  if p_kind = 'plan' and (v_plans >= p_plan_limit or v_smart >= p_smart_limit) then
    raise exception 'ai_quota_plan' using errcode = 'P0001';
  end if;
  if p_kind = 'food_photo' and (
    select count(*) from public.ai_usage_events e
    where e.user_id = p_user_id and e.kind = 'food_photo' and e.created_at >= now() - interval '24 hours'
  ) >= 20 then
    raise exception 'ai_quota_photo' using errcode = 'P0001';
  end if;
  -- A chat that would have used the larger model falls back to the fast one once that share is used up.
  if v_tier = 'smart' and v_smart >= p_smart_limit then
    v_tier := 'fast';
  end if;
    values (p_user_id, p_kind, v_tier)
    returning id into usage_id;
  model_tier := v_tier;
  return next;
end;
$$;
revoke all on function public.reserve_ai_usage(uuid, text, text, integer, integer, integer, integer) from public, anon, authenticated;
grant execute on function public.reserve_ai_usage(uuid, text, text, integer, integer, integer, integer) to service_role;

-- ===== supabase/migrations/20261024000033_food_quality.sql =====
-- Food Quality Scanner. Product data is read from Open Food Facts when a product is opened and is never copied into
-- the app's food tables. The only new data is the member's own product filters (allergens to avoid, vegan or
-- vegetarian, nutrition preferences), used for Plus checks and comparisons.

alter table public.profiles
  add column if not exists food_filters jsonb check (food_filters is null or (jsonb_typeof(food_filters) = 'object' and octet_length(food_filters::text) <= 2000));
grant update (food_filters) on public.profiles to authenticated;

-- ===== supabase/migrations/20261024000034_sleep.sql =====
-- Sleep & Recovery, Stage B1: nights and naps a member logs by hand or with the in-app timer, and (Stage B4) records
-- imported from Apple Health / Health Connect or a wearable. Times are timestamptz; the IANA zone a session was logged
-- in is kept so clock times display as the member saw them, and `night_of` is the local date they got up (computed
-- on the server). Nothing here measures sleep stages or physiology: the app's own entries only know when the member
-- was in bed and, if they said so, when they think they fell asleep and woke. Stage intervals exist only for imported
-- records. Logging needs the same "optional wellness information" consent as recovery check-ins
-- (profiles.wellness_consent_at); viewing and deleting never do, so withdrawing consent never traps data.

create extension if not exists btree_gist;

-- The member's sleep goal (4–12 hours), editable like the other self-service profile fields.
alter table public.profiles
  add column if not exists sleep_goal_minutes smallint not null default 480 check (sleep_goal_minutes between 240 and 720);
grant update (sleep_goal_minutes) on public.profiles to authenticated;

create or replace function public.can_log_sleep()
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (select 1 from public.profiles p where p.id = auth.uid() and p.wellness_consent_at is not null);
$$;
revoke all on function public.can_log_sleep() from public, anon;
grant execute on function public.can_log_sleep() to authenticated, service_role;

create table public.sleep_sessions (
  -- Generated on the device before saving, so a retried save can't create a second session.
  id uuid primary key,
  user_id uuid not null references auth.users (id) on delete cascade,
  kind text not null default 'night' check (kind in ('night', 'nap')),
  -- Got into bed / got out of bed (null while the timer runs).
  started_at timestamptz not null,
  ended_at timestamptz,
  -- Optional detail the member gave: when they think they fell asleep and finally woke, and time awake in between.
  onset_at timestamptz,
  final_wake_at timestamptz,
  awakenings smallint check (awakenings between 0 and 50),
  awake_minutes smallint check (awake_minutes between 0 and 1440),
  timezone text not null check (char_length(timezone) between 1 and 64),
  night_of date not null,
  source text not null default 'manual' check (source in ('manual', 'timer', 'apple_health', 'health_connect', 'wearable')),
  -- The record's id in its source, so one import can't be added twice. The app's own entries have none.
  source_id text check (char_length(source_id) between 1 and 200),
  notes text check (char_length(notes) <= 280),
  -- Where the session ends for overlap checks: ended_at, or 20 hours after bedtime while a timer runs. Kept by the
  -- trigger below (an index expression can't compute it: timestamptz + interval isn't immutable).
  overlap_until timestamptz not null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  check (ended_at is null or ended_at > started_at),
  check (ended_at is null or ended_at - started_at <= interval '24 hours'),
  check (onset_at is null or (onset_at >= started_at and (ended_at is null or onset_at <= ended_at))),
  check (final_wake_at is null or (final_wake_at >= coalesce(onset_at, started_at) and (ended_at is null or final_wake_at <= ended_at))),
  check ((source in ('manual', 'timer')) = (source_id is null)),
  check (overlap_until > started_at),
  unique (user_id, source, source_id),
  -- A member's sessions never overlap, whatever their source.
  exclude using gist (user_id with =, tstzrange(started_at, overlap_until, '[)') with &&)
);
create index sleep_sessions_user_night_idx on public.sleep_sessions (user_id, night_of desc);
create index sleep_sessions_user_started_idx on public.sleep_sessions (user_id, started_at desc);

create or replace function public.sleep_session_prepare()
returns trigger
language plpgsql
set search_path = public
as $$
begin
  new.overlap_until := coalesce(new.ended_at, new.started_at + interval '20 hours');
  return new;
end;
$$;
create trigger sleep_sessions_prepare before insert or update on public.sleep_sessions
  for each row execute function public.sleep_session_prepare();
create trigger sleep_sessions_updated_at before update on public.sleep_sessions
  for each row execute function public.set_updated_at();

-- Stage intervals supplied by a health platform or wearable for one imported session. The app never writes its own.
create table public.sleep_stages (
  id uuid primary key default gen_random_uuid(),
  session_id uuid not null references public.sleep_sessions (id) on delete cascade,
  user_id uuid not null references auth.users (id) on delete cascade,
  stage text not null check (stage in ('awake', 'light', 'deep', 'rem', 'asleep', 'unknown')),
  started_at timestamptz not null,
  ended_at timestamptz not null,
  check (ended_at > started_at),
  check (ended_at - started_at <= interval '24 hours')
);
create index sleep_stages_session_idx on public.sleep_stages (session_id, started_at);
create index sleep_stages_user_idx on public.sleep_stages (user_id);

alter table public.sleep_sessions enable row level security;
alter table public.sleep_stages enable row level security;

create policy sleep_sessions_select_own on public.sleep_sessions
  for select to authenticated using (user_id = (select auth.uid()));
create policy sleep_sessions_insert_own on public.sleep_sessions
  for insert to authenticated with check (user_id = (select auth.uid()) and public.can_log_sleep());
create policy sleep_sessions_update_own on public.sleep_sessions
  for update to authenticated using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()) and public.can_log_sleep());
create policy sleep_sessions_delete_own on public.sleep_sessions
  for delete to authenticated using (user_id = (select auth.uid()));

create policy sleep_stages_select_own on public.sleep_stages
  for select to authenticated using (user_id = (select auth.uid()));
create policy sleep_stages_delete_own on public.sleep_stages
  for delete to authenticated using (user_id = (select auth.uid()));
-- Stages belong to the member's own imported session only.
create policy sleep_stages_insert_own on public.sleep_stages
  for insert to authenticated with check (
    user_id = (select auth.uid())
    and public.can_log_sleep()
    and exists (
      select 1 from public.sleep_sessions s
      where s.id = session_id and s.user_id = (select auth.uid()) and s.source not in ('manual', 'timer')
    )
  );

-- At most 4,000 sessions per member (about ten years of nights and naps), checked under a per-member lock.
create or replace function public.sleep_session_limit()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  perform pg_advisory_xact_lock(hashtext('sleep_sessions:' || new.user_id::text));
  if (select count(*) from public.sleep_sessions where user_id = new.user_id) >= 4000 then
    raise exception 'sleep_session_limit' using errcode = 'P0001';
  end if;
  return new;
end;
$$;
create trigger sleep_sessions_limit before insert on public.sleep_sessions for each row execute function public.sleep_session_limit();

-- ===== supabase/migrations/20261024000035_sleep_checkins.sql =====
-- Sleep & Recovery, Stage B5: brief, optional morning and daily check-ins. One row per member and day; every field
-- is optional so a check-in can be a single tap. A row's `day` is the day the member woke up, so it lines up with
-- the night listed under that date (sleep_sessions.night_of). Evening habits (caffeine, alcohol, late meal, screens)
-- describe the evening before that night. Same wellness consent as sleep sessions; viewing and deleting never need it.

create table public.sleep_checkins (
  user_id uuid not null references auth.users (id) on delete cascade,
  day date not null,
  -- 1 (low) – 5 (high) ratings.
  restedness smallint check (restedness between 1 and 5),
  energy_morning smallint check (energy_morning between 1 and 5),
  energy_afternoon smallint check (energy_afternoon between 1 and 5),
  energy_evening smallint check (energy_evening between 1 and 5),
  mood smallint check (mood between 1 and 5),
  stress smallint check (stress between 1 and 5),
  sleep_quality smallint check (sleep_quality between 1 and 5),
  -- Last caffeine the day before, as a clock time (null = not answered or none).
  caffeine_last time,
  alcohol boolean,
  late_meal boolean,
  exercise_timing text check (exercise_timing in ('none', 'morning', 'afternoon', 'evening')),
  evening_screens boolean,
  disturbances text[] not null default '{}'
    check (cardinality(disturbances) <= 12 and disturbances <@ array['noise', 'light', 'heat', 'cold', 'partner', 'pet', 'child', 'pain', 'bathroom', 'worry', 'other']::text[]),
  travel boolean,
  -- Free text the member chose to record (never a recommendation).
  sleep_aid text check (char_length(sleep_aid) <= 120),
  notes text check (char_length(notes) <= 280),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  primary key (user_id, day)
);
create trigger sleep_checkins_updated_at before update on public.sleep_checkins
  for each row execute function public.set_updated_at();

alter table public.sleep_checkins enable row level security;

create policy sleep_checkins_select_own on public.sleep_checkins
  for select to authenticated using (user_id = (select auth.uid()));
create policy sleep_checkins_insert_own on public.sleep_checkins
  for insert to authenticated with check (user_id = (select auth.uid()) and public.can_log_sleep());
create policy sleep_checkins_update_own on public.sleep_checkins
  for update to authenticated using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()) and public.can_log_sleep());
create policy sleep_checkins_delete_own on public.sleep_checkins
  for delete to authenticated using (user_id = (select auth.uid()));

-- ===== supabase/migrations/20261024000036_sleep_imports.sql =====
-- Sleep & Recovery, Stage B4: a record of each health-platform import (Apple Health / Health Connect), so a member
-- can see what was brought in and a failed or repeated import never adds a record twice. The sessions themselves go
-- into sleep_sessions with their source and the platform's record id (unique per member and source), and overlaps
-- with anything already stored are refused by that table; the counts here say how many were added, skipped as
-- already imported, or skipped because they clashed with an existing entry.

create table public.sleep_import_runs (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users (id) on delete cascade,
  source text not null check (source in ('apple_health', 'health_connect')),
  range_start timestamptz not null,
  range_end timestamptz not null,
  added integer not null default 0 check (added between 0 and 10000),
  duplicates integer not null default 0 check (duplicates between 0 and 10000),
  conflicts integer not null default 0 check (conflicts between 0 and 10000),
  -- The name of the device or app the platform attributed the records to, when it said.
  device text check (char_length(device) <= 120),
  created_at timestamptz not null default now(),
  check (range_end > range_start)
);
create index sleep_import_runs_user_idx on public.sleep_import_runs (user_id, created_at desc);

alter table public.sleep_import_runs enable row level security;
create policy sleep_import_runs_select_own on public.sleep_import_runs
  for select to authenticated using (user_id = (select auth.uid()));
create policy sleep_import_runs_insert_own on public.sleep_import_runs
  for insert to authenticated with check (user_id = (select auth.uid()) and public.can_log_sleep());
create policy sleep_import_runs_delete_own on public.sleep_import_runs
  for delete to authenticated using (user_id = (select auth.uid()));

-- Whether the member has switched automatic import off (records they already imported stay until deleted).
alter table public.profiles add column if not exists sleep_import_enabled boolean not null default true;
grant update (sleep_import_enabled) on public.profiles to authenticated;

-- ===== supabase/migrations/20261024000037_sleep_schedule.sql =====
-- Sleep & Recovery, Stages C1–C3: the wake time a member chooses to keep (the windows hang off it; null means use
-- their typical wake time), and which habit tips they have dismissed.

alter table public.profiles
  add column if not exists sleep_target_wake time,
  add column if not exists sleep_tips_dismissed text[] not null default '{}' check (cardinality(sleep_tips_dismissed) <= 50);
grant update (sleep_target_wake, sleep_tips_dismissed) on public.profiles to authenticated;

-- ===== supabase/migrations/20261024000038_sleep_alarm.sql =====
-- Sleep & Recovery, Stage D2: the member's alarm settings (wake time, window, fixed or smart, sound, days, snooze)
-- as validated JSON on the profile. The phone app schedules them as local notifications; the web app only stores
-- and shows them. Null means never configured.

alter table public.profiles add column if not exists sleep_alarm jsonb;
grant update (sleep_alarm) on public.profiles to authenticated;

-- ===== supabase/migrations/20261024000039_sleep_hardening.sql =====
-- Sleep & Recovery hardening after review: bounds on the profile's sleep JSON and tip list, a per-session cap on
-- imported stage rows, and the session cap trigger no longer touching another member's lock before RLS rejects
-- the row. Nothing here changes behaviour for well-formed data.

alter table public.profiles
  add constraint profiles_sleep_alarm_check
    check (sleep_alarm is null or (jsonb_typeof(sleep_alarm) = 'object' and octet_length(sleep_alarm::text) <= 1000));

alter table public.profiles drop constraint if exists profiles_sleep_tips_dismissed_check;
alter table public.profiles
  add constraint profiles_sleep_tips_dismissed_check
    check (cardinality(sleep_tips_dismissed) <= 50 and octet_length(array_to_string(sleep_tips_dismissed, ',')) <= 2500);

-- The cap only concerns the member's own rows; a row for someone else is RLS's to reject, without taking their lock.
create or replace function public.sleep_session_limit()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if new.user_id is distinct from (select auth.uid()) then
    return new;
  end if;
  perform pg_advisory_xact_lock(hashtext('sleep_sessions:' || new.user_id::text));
  if (select count(*) from public.sleep_sessions where user_id = new.user_id) >= 4000 then
    raise exception 'sleep_session_limit' using errcode = 'P0001';
  end if;
  return new;
end;
$$;

-- At most 1,000 stage rows per session (a night at one-minute resolution is under 1,500 but imports are capped at 500).
create or replace function public.sleep_stage_limit()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if new.user_id is distinct from (select auth.uid()) then
    return new;
  end if;
  perform pg_advisory_xact_lock(hashtext('sleep_stages:' || new.session_id::text));
  if (select count(*) from public.sleep_stages where session_id = new.session_id) >= 1000 then
    raise exception 'sleep_stage_limit' using errcode = 'P0001';
  end if;
  return new;
end;
$$;
revoke all on function public.sleep_stage_limit() from public, anon;
create trigger sleep_stages_limit before insert on public.sleep_stages for each row execute function public.sleep_stage_limit();

-- ===== supabase/migrations/20261024000040_review_hardening.sql =====
-- Hardening after the launch-readiness review: an idempotency key for food logging, bounds on two unbounded
-- columns, and user_id indexes on child tables that the export and record rebuilds scan by member.

-- Food logging: the device sends a per-attempt id so a retried request can't log an item twice.
alter table public.meal_items add column if not exists client_id uuid;
create unique index if not exists meal_items_user_client_uidx on public.meal_items (user_id, client_id) where client_id is not null;

alter table public.training_adjustments
  add constraint training_adjustments_changes_size_check check (octet_length(changes::text) <= 20000);
-- NOT VALID: enforced on every new or changed row, but an existing over-long value (the column had no limit before)
-- can't make this migration fail on a production database. Validate later with
-- `alter table public.profiles validate constraint profiles_avatar_path_check;` once such rows are cleaned.
alter table public.profiles
  add constraint profiles_avatar_path_check check (avatar_path is null or char_length(avatar_path) <= 300) not valid;

create index if not exists workout_sets_user_idx on public.workout_sets (user_id);
create index if not exists meal_items_user_idx on public.meal_items (user_id);
create index if not exists ai_messages_user_idx on public.ai_messages (user_id);
create index if not exists recipe_ingredients_user_idx on public.recipe_ingredients (user_id);
create index if not exists workout_template_exercises_user_idx on public.workout_template_exercises (user_id);

-- ===== supabase/migrations/20261024000041_sleep_vitals.sql =====
-- Sleep & Recovery: wearable-recorded detail on imported sessions. The recording device's name, and the overnight
-- heart rate, heart-rate variability and respiratory rate summarised from the health platform's samples inside the
-- session (averages, lows and highs, how many samples). Only imported sessions may carry them: the app never
-- measures anything itself, so a hand-logged or timer session has nothing to put here.

alter table public.sleep_sessions
  add column if not exists device_name text check (char_length(device_name) <= 120),
  add column if not exists hr_avg smallint check (hr_avg between 20 and 250),
  add column if not exists hr_min smallint check (hr_min between 20 and 250),
  add column if not exists hr_max smallint check (hr_max between 20 and 250),
  add column if not exists hr_samples integer check (hr_samples between 1 and 100000),
  -- HealthKit reports SDNN, Health Connect RMSSD: different statistics, so the method is kept with the number.
  add column if not exists hrv_avg_ms numeric(6, 1) check (hrv_avg_ms between 1 and 500),
  add column if not exists hrv_method text check (hrv_method in ('sdnn', 'rmssd')),
  add column if not exists hrv_samples integer check (hrv_samples between 1 and 100000),
  add column if not exists rr_avg numeric(4, 1) check (rr_avg between 4 and 60),
  add column if not exists rr_min numeric(4, 1) check (rr_min between 4 and 60),
  add column if not exists rr_max numeric(4, 1) check (rr_max between 4 and 60),
  add column if not exists rr_samples integer check (rr_samples between 1 and 100000);

alter table public.sleep_sessions
  add constraint sleep_sessions_vitals_imported_check
    check (source not in ('manual', 'timer') or (hr_avg is null and hrv_avg_ms is null and rr_avg is null and device_name is null)),
  add constraint sleep_sessions_hr_shape_check
    check ((hr_avg is null) = (hr_samples is null) and (hr_min is null or hr_max is null or hr_avg is null or (hr_min <= hr_avg and hr_avg <= hr_max))),
  add constraint sleep_sessions_hrv_shape_check
    check ((hrv_avg_ms is null) = (hrv_method is null) and (hrv_avg_ms is null) = (hrv_samples is null)),
  add constraint sleep_sessions_rr_shape_check
    check ((rr_avg is null) = (rr_samples is null) and (rr_min is null or rr_max is null or rr_avg is null or (rr_min <= rr_avg and rr_avg <= rr_max)));

-- Which platform the member connected and when; shown as the connection status and cleared on disconnect.
alter table public.profiles
  add column if not exists sleep_import_source text check (sleep_import_source in ('apple_health', 'health_connect')),
  add column if not exists sleep_import_connected_at timestamptz;
grant update (sleep_import_source, sleep_import_connected_at) on public.profiles to authenticated;

-- A sync can also complete earlier imports with vitals that weren't read before.
alter table public.sleep_import_runs
  add column if not exists updated integer not null default 0 check (updated between 0 and 10000),
  add column if not exists with_vitals integer not null default 0 check (with_vitals between 0 and 10000);

-- ===== supabase/migrations/20261025000042_plan_of_private.sql =====
-- plan_of(uuid) takes any user id and runs as its definer, and it was callable by every signed-in member through
-- PostgREST (POST /rest/v1/rpc/plan_of), so one member could read another's plan by id. Only the database needs it:
-- has_plan() and can_use_program() (both security definer) call it with the caller's own id. Members keep reading
-- their own plan through the user_entitlements policy.
revoke execute on function public.plan_of(uuid) from authenticated;

-- ===== supabase/migrations/20261025000043_deleted_activities_no_route.sql =====
-- Runs and walks deleted before 2026-10-25 kept their GPS route, splits and signal summary in the soft-deleted row
-- (the app only set deleted_at), and the data export returns soft-deleted rows. This removes the location data from
-- every row the member has already deleted, and makes the rule structural: a deleted activity can't carry a route.
--
-- Irreversible for those rows (the route can't be recovered), and intended to be: the member deleted them. Only rows
-- with deleted_at set are touched; live runs and walks, workouts and accounts are untouched. On a live database this
-- is to be applied only with the owner's approval (docs/launch-audit/D_CODE_CHANGES_AND_TESTS.md).
update public.activities
   set route = null, splits = null, gps_quality = null
 where deleted_at is not null
   and (route is not null or splits is not null or gps_quality is not null);

alter table public.activities
  add constraint activities_deleted_no_route
  check (deleted_at is null or (route is null and splits is null and gps_quality is null));

-- ===== supabase/migrations/20261026000044_free_pro_memberships.sql =====
-- Narrow Gate Fitness — Free and Pro All Access (owner decision of 2026-10-26).
--
-- New customers can choose only Free or Pro All Access ($19.99 a month or $149.99 a year, the same features).
-- Plus is no longer sold; the 'plus' plan value stays valid so existing Plus subscriptions keep their access until
-- they end. Nothing existing is changed or removed by this migration: no subscription, entitlement, activity or
-- route is rewritten. It only adds columns and governs new writes.

-- 1. Refunds and disputes (Stripe). A full refund or a dispute of the payment for a subscription's current period
--    ends the access that payment bought; the subscription row keeps its Stripe status. A later paid period, or a
--    dispute closed in the merchant's favour, restores access (src/server/services/billing.ts).
alter table public.subscriptions
  add column access_revoked_at timestamptz,
  add column access_revoked_reason text check (access_revoked_reason in ('refund', 'dispute')),
  add column revoked_invoice_id text check (revoked_invoice_id is null or char_length(revoked_invoice_id) <= 200),
  add constraint subscriptions_revocation_complete check (
    (access_revoked_at is null and access_revoked_reason is null)
    or (access_revoked_at is not null and access_revoked_reason is not null)
  );

-- 2. Live GPS recording is part of Pro (and of legacy Plus subscriptions, which included it). Manual and treadmill
--    run and walk logging stays free. A trigger rather than a policy, because an update has to compare the old row
--    with the new one: a member on Free can still edit the notes or effort of a run they recorded earlier, delete it,
--    or remove its route, but can't create a GPS recording or attach a route. Server-side writes (the service role,
--    with no signed-in member) aren't affected, so imports, exports and account deletion behave as before.
create or replace function public.enforce_live_gps_plan()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  adds_gps boolean;
begin
  if auth.uid() is null then
    return new;
  end if;
  if tg_op = 'INSERT' then
    adds_gps := new.source = 'gps' or new.route is not null;
  else
    adds_gps := (new.source = 'gps' and old.source is distinct from 'gps')
      or (new.route is not null and new.route is distinct from old.route);
  end if;
  if adds_gps and public.plan_rank(public.plan_of(new.user_id)) < public.plan_rank('plus') then
    raise exception 'Live GPS recording is included with Pro' using errcode = 'P0001';
  end if;
  return new;
end;
$$;
revoke all on function public.enforce_live_gps_plan() from public, anon, authenticated;

create trigger activities_live_gps_plan before insert or update on public.activities
  for each row execute function public.enforce_live_gps_plan();

-- ===== supabase/migrations/20261026000045_legal_acceptances.sql =====
-- Narrow Gate Fitness — evidence of what each member agreed to, and when.
--
-- Sign-up already required unticked "I agree" and "18 or older" boxes, but nothing recorded which version of the
-- Terms and Privacy Policy was shown or when it was accepted. Each row records one acceptance: the document, its
-- version, a SHA-256 fingerprint of the exact text shown (src/lib/legal/versions.ts; the text itself is kept in the
-- repository's history), when, and where (sign-up, re-acceptance after a change, or web checkout's auto-renewal
-- consent). Rows are append-only for members: they can read their own and add their own, never edit or delete.
-- They are removed with the account. Nothing existing is changed.

create table public.legal_acceptances (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users (id) on delete cascade,
  document text not null check (document in ('terms', 'privacy', 'risk_acknowledgment', 'auto_renewal')),
  version text not null check (char_length(version) between 1 and 64),
  document_sha256 text not null check (document_sha256 ~ '^[0-9a-f]{64}$'),
  source text not null check (source in ('signup', 'reaccept', 'checkout')),
  -- For auto-renewal consent: what was agreed to (e.g. "Pro All Access, $19.99 per month").
  details text check (details is null or char_length(details) <= 300),
  accepted_at timestamptz not null default now()
);
create index legal_acceptances_user_idx on public.legal_acceptances (user_id, document, accepted_at desc);

alter table public.legal_acceptances enable row level security;
create policy legal_acceptances_select_own on public.legal_acceptances
  for select to authenticated using (user_id = (select auth.uid()));
create policy legal_acceptances_insert_own on public.legal_acceptances
  for insert to authenticated with check (user_id = (select auth.uid()) and source in ('reaccept', 'checkout'));

-- The time is always the database's, so a record can't be back- or post-dated.
create or replace function public.legal_acceptance_stamp()
returns trigger
language plpgsql
as $$
begin
  new.accepted_at := now();
  return new;
end;
$$;
create trigger legal_acceptances_stamp before insert on public.legal_acceptances
  for each row execute function public.legal_acceptance_stamp();

-- Sign-up: the sign-up form sends the documents accepted with the new account (user metadata), and they're recorded
-- in the same transaction that creates the account, so an account can't exist without the record of how it was
-- created. Malformed entries are ignored rather than blocking the sign-up; the app treats a member without a current
-- record as not having accepted (src/server/legal.ts).
create or replace function public.record_signup_acceptances()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  item jsonb;
begin
  if jsonb_typeof(new.raw_user_meta_data -> 'legal_acceptances') <> 'array' then
    return new;
  end if;
  for item in select * from jsonb_array_elements(new.raw_user_meta_data -> 'legal_acceptances') limit 10 loop
    if item ->> 'document' in ('terms', 'privacy', 'risk_acknowledgment')
       and char_length(coalesce(item ->> 'version', '')) between 1 and 64
       and coalesce(item ->> 'sha256', '') ~ '^[0-9a-f]{64}$' then
      values (new.id, item ->> 'document', item ->> 'version', item ->> 'sha256', 'signup');
    end if;
  end loop;
  return new;
end;
$$;
revoke all on function public.record_signup_acceptances() from public, anon, authenticated;

create trigger on_auth_user_created_legal
  after insert on auth.users
  for each row execute function public.record_signup_acceptances();

-- ===== supabase/migrations/20261101000046_billing_integrity.sql =====
-- Narrow Gate Fitness — billing integrity under concurrency, retries and out-of-order delivery; shared rate limits.
--
-- 1. Webhook events (Stripe and RevenueCat) are claimed, not just inserted. Before, the first delivery inserted the
--    event id and a failure deleted it again. A second delivery of the same event that arrived while the first was
--    still running saw the id, answered 200 "duplicate", and Stripe stopped retrying; if the first then failed, the
--    event was lost. Now an event is `processing` under a short lease, `processed` only after its changes are saved,
--    and `failed` (kept, with a short error code) when they weren't. A delivery that finds another one still holding
--    the lease is told to come back later (the route answers 409, so the provider retries).
-- 2. Stripe subscription rows are written through `upsert_stripe_subscription`, which never moves a subscription to
--    another member and never lets an older read of Stripe overwrite a newer one (`synced_at` is when the server read
--    the subscription from Stripe).
-- 3. App Store / Google Play rows are replaced per member in one transaction (`apply_store_snapshot`), ordered by
--    when the server read RevenueCat, so two overlapping syncs can't interleave or leave half a snapshot behind.
-- 4. The member's entitlement is written with a compare-and-set on a per-member billing version
--    (`apply_entitlement`). Every change to a member's subscription rows bumps the version; a recompute that read
--    the rows before another change landed is refused and recomputed, so the last write always reflects the latest
--    rows. A live admin grant of an equal or higher plan is kept, as before.
-- 5. `rate_limit_hit`: a burst limiter shared by every server instance (sliding window over two fixed windows).
--
-- Every function here is service-role only.

-- ---------------------------------------------------------------------------------------------------------------
-- 1. Webhook event claims
-- ---------------------------------------------------------------------------------------------------------------
alter table public.stripe_events
  add column status text not null default 'processed' check (status in ('processing', 'processed', 'failed')),
  add column attempts integer not null default 1 check (attempts >= 0),
  add column locked_until timestamptz,
  add column last_error text check (char_length(last_error) <= 300),
  add column received_at timestamptz not null default now();
alter table public.stripe_events alter column processed_at drop not null, alter column processed_at drop default;

alter table public.revenuecat_events
  add column status text not null default 'processed' check (status in ('processing', 'processed', 'failed')),
  add column attempts integer not null default 1 check (attempts >= 0),
  add column locked_until timestamptz,
  add column last_error text check (char_length(last_error) <= 300),
  add column received_at timestamptz not null default now();
alter table public.revenuecat_events alter column processed_at drop not null, alter column processed_at drop default;

create index stripe_events_open_idx on public.stripe_events (status) where status <> 'processed';
create index revenuecat_events_open_idx on public.revenuecat_events (status) where status <> 'processed';

-- Claim an event for processing. Returns 'claimed' (process it now), 'duplicate' (already processed) or 'busy'
-- (another delivery holds an unexpired lease).
create or replace function public.claim_webhook_event(
  p_provider text,
  p_event_id text,
  p_type text,
  p_environment text default null,
  p_lease_seconds integer default 120
)
returns text
language plpgsql
security definer
set search_path = public
as $$
declare
  v_status text;
  v_locked timestamptz;
  v_lease interval := make_interval(secs => greatest(10, least(coalesce(p_lease_seconds, 120), 900)));
begin
  if p_event_id is null or char_length(p_event_id) not between 1 and 200 then
    raise exception 'invalid event id' using errcode = '22023';
  end if;
  if p_provider = 'stripe' then
      values (p_event_id, left(coalesce(p_type, ''), 100), 'processing', 1, now() + v_lease, null)
      on conflict (id) do nothing;
    if found then return 'claimed'; end if;
    select status, locked_until into v_status, v_locked from public.stripe_events where id = p_event_id for update;
    if v_status = 'processed' then return 'duplicate'; end if;
    if v_status = 'processing' and v_locked is not null and v_locked > now() then return 'busy'; end if;
    update public.stripe_events
      set status = 'processing', attempts = attempts + 1, locked_until = now() + v_lease, last_error = null
      where id = p_event_id;
    return 'claimed';
  elsif p_provider = 'revenuecat' then
      values (p_event_id, left(coalesce(p_type, ''), 60), left(p_environment, 20), 'processing', 1, now() + v_lease, null)
      on conflict (id) do nothing;
    if found then return 'claimed'; end if;
    select status, locked_until into v_status, v_locked from public.revenuecat_events where id = p_event_id for update;
    if v_status = 'processed' then return 'duplicate'; end if;
    if v_status = 'processing' and v_locked is not null and v_locked > now() then return 'busy'; end if;
    update public.revenuecat_events
      set status = 'processing', attempts = attempts + 1, locked_until = now() + v_lease, last_error = null
      where id = p_event_id;
    return 'claimed';
  else
    raise exception 'unknown provider' using errcode = '22023';
  end if;
end;
$$;

-- Record the outcome of a claimed event. A failure keeps the row (status 'failed', a short error code) so the next
-- delivery can claim it again and the failure stays visible.
create or replace function public.finish_webhook_event(p_provider text, p_event_id text, p_ok boolean, p_error text default null)
returns void
language plpgsql
security definer
set search_path = public
as $$
begin
  if p_provider = 'stripe' then
    update public.stripe_events
      set status = case when p_ok then 'processed' else 'failed' end,
          processed_at = case when p_ok then now() else null end,
          locked_until = null,
          last_error = case when p_ok then null else left(coalesce(p_error, 'error'), 300) end
      where id = p_event_id;
  elsif p_provider = 'revenuecat' then
    update public.revenuecat_events
      set status = case when p_ok then 'processed' else 'failed' end,
          processed_at = case when p_ok then now() else null end,
          locked_until = null,
          last_error = case when p_ok then null else left(coalesce(p_error, 'error'), 300) end
      where id = p_event_id;
  else
    raise exception 'unknown provider' using errcode = '22023';
  end if;
end;
$$;

-- ---------------------------------------------------------------------------------------------------------------
-- 2. Per-member billing version (bumped by every change to a member's subscription rows)
-- ---------------------------------------------------------------------------------------------------------------
create table public.billing_state_versions (
  user_id uuid primary key references auth.users (id) on delete cascade,
  version bigint not null default 0,
  updated_at timestamptz not null default now()
);
alter table public.billing_state_versions enable row level security;
revoke all on public.billing_state_versions from anon, authenticated;
-- billing_state_versions: no policies — service role only.

create or replace function public.bump_billing_version()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if tg_op in ('INSERT', 'UPDATE') then
      on conflict (user_id) do update set version = v.version + 1, updated_at = now();
  end if;
  if tg_op = 'DELETE' or (tg_op = 'UPDATE' and old.user_id is distinct from new.user_id) then
    -- Update only: during an account deletion the member's auth row is already going, and inserting a row that
    -- references it would fail the deletion.
    update public.billing_state_versions set version = version + 1, updated_at = now() where user_id = old.user_id;
  end if;
  return null;
end;
$$;
revoke all on function public.bump_billing_version() from public, anon, authenticated;

create trigger subscriptions_billing_version after insert or update or delete on public.subscriptions
  for each row execute function public.bump_billing_version();
create trigger store_subscriptions_billing_version after insert or update or delete on public.store_subscriptions
  for each row execute function public.bump_billing_version();

  select distinct user_id, 1 from (select user_id from public.subscriptions union select user_id from public.store_subscriptions) s
  on conflict (user_id) do nothing;

-- Write the member's entitlement if nothing changed their subscription rows since `p_version` was read.
-- Returns 'applied', 'stale' (recompute and try again) or 'kept_admin' (a live admin grant of an equal or higher
-- plan stays).
create or replace function public.apply_entitlement(
  p_user_id uuid,
  p_version bigint,
  p_plan text,
  p_source text,
  p_valid_until timestamptz
)
returns text
language plpgsql
security definer
set search_path = public
as $$
declare
  v_version bigint;
  v_plan text;
  v_source text;
  v_valid timestamptz;
begin
  perform pg_advisory_xact_lock(hashtextextended('entitlement:' || p_user_id::text, 0));
  select version into v_version from public.billing_state_versions where user_id = p_user_id;
  if coalesce(v_version, 0) <> coalesce(p_version, 0) then
    return 'stale';
  end if;
  select plan, source, valid_until into v_plan, v_source, v_valid from public.user_entitlements where user_id = p_user_id;
  if found and v_source = 'admin' and (v_valid is null or v_valid > now())
     and public.plan_rank(v_plan) >= public.plan_rank(p_plan) then
    return 'kept_admin';
  end if;
    values (p_user_id, p_plan, p_source, p_valid_until)
    on conflict (user_id) do update set plan = excluded.plan, source = excluded.source, valid_until = excluded.valid_until;
  return 'applied';
end;
$$;

-- ---------------------------------------------------------------------------------------------------------------
-- 3. Stripe subscription rows: ordered, and never moved to another member
-- ---------------------------------------------------------------------------------------------------------------
alter table public.subscriptions add column synced_at timestamptz;

-- Returns 'applied', 'stale' (a newer read of Stripe is already stored) or 'owner_conflict' (the subscription
-- belongs to another member here; nothing is changed).
create or replace function public.upsert_stripe_subscription(
  p_user_id uuid,
  p_subscription_id text,
  p_price_id text,
  p_plan text,
  p_status text,
  p_current_period_end timestamptz,
  p_cancel_at_period_end boolean,
  p_synced_at timestamptz
)
returns text
language plpgsql
security definer
set search_path = public
as $$
declare
  v_owner uuid;
  v_synced timestamptz;
begin
    values (p_user_id, p_subscription_id, p_price_id, p_plan, p_status, p_current_period_end, coalesce(p_cancel_at_period_end, false), p_synced_at)
    on conflict (stripe_subscription_id) do nothing;
  if found then return 'applied'; end if;
  select user_id, synced_at into v_owner, v_synced from public.subscriptions where stripe_subscription_id = p_subscription_id for update;
  if v_owner is distinct from p_user_id then return 'owner_conflict'; end if;
  if v_synced is not null and p_synced_at is not null and v_synced > p_synced_at then return 'stale'; end if;
  update public.subscriptions
    set stripe_price_id = p_price_id,
        plan = p_plan,
        status = p_status,
        current_period_end = p_current_period_end,
        cancel_at_period_end = coalesce(p_cancel_at_period_end, false),
        synced_at = coalesce(p_synced_at, now())
    where stripe_subscription_id = p_subscription_id;
  return 'applied';
end;
$$;

-- ---------------------------------------------------------------------------------------------------------------
-- 4. App Store / Google Play rows: one member's whole RevenueCat snapshot at once, newest read wins
-- ---------------------------------------------------------------------------------------------------------------
create table public.store_sync_state (
  user_id uuid primary key references auth.users (id) on delete cascade,
  fetched_at timestamptz not null,
  updated_at timestamptz not null default now()
);
alter table public.store_sync_state enable row level security;
revoke all on public.store_sync_state from anon, authenticated;
-- store_sync_state: no policies — service role only.

-- `p_rows`: a JSON array of store_subscriptions rows (without user_id). Returns 'applied' or 'stale'.
create or replace function public.apply_store_snapshot(p_user_id uuid, p_fetched_at timestamptz, p_rows jsonb)
returns text
language plpgsql
security definer
set search_path = public
as $$
declare
  v_last timestamptz;
begin
  if jsonb_typeof(coalesce(p_rows, '[]'::jsonb)) <> 'array' then
    raise exception 'rows must be an array' using errcode = '22023';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('store_sync:' || p_user_id::text, 0));
  select fetched_at into v_last from public.store_sync_state where user_id = p_user_id;
  if v_last is not null and v_last > p_fetched_at then
    return 'stale';
  end if;
  delete from public.store_subscriptions s
    where s.user_id = p_user_id
      and not exists (
        select 1 from jsonb_to_recordset(coalesce(p_rows, '[]'::jsonb)) as r(store text, product_id text)
        where r.store = s.store and r.product_id = s.product_id
      );
    user_id, store, product_id, plan, period_type, purchased_at, original_purchased_at, expires_at,
    grace_period_expires_at, unsubscribe_detected_at, billing_issue_detected_at, refunded_at, is_sandbox,
    ownership_type, store_transaction_id
  )
  select p_user_id, r.store, r.product_id, r.plan, r.period_type, r.purchased_at, r.original_purchased_at, r.expires_at,
         r.grace_period_expires_at, r.unsubscribe_detected_at, r.billing_issue_detected_at, r.refunded_at,
         coalesce(r.is_sandbox, false), r.ownership_type, r.store_transaction_id
    from jsonb_to_recordset(coalesce(p_rows, '[]'::jsonb)) as r(
      store text, product_id text, plan text, period_type text, purchased_at timestamptz, original_purchased_at timestamptz,
      expires_at timestamptz, grace_period_expires_at timestamptz, unsubscribe_detected_at timestamptz,
      billing_issue_detected_at timestamptz, refunded_at timestamptz, is_sandbox boolean, ownership_type text,
      store_transaction_id text
    )
  on conflict (user_id, store, product_id) do update set
    plan = excluded.plan,
    period_type = excluded.period_type,
    purchased_at = excluded.purchased_at,
    original_purchased_at = excluded.original_purchased_at,
    expires_at = excluded.expires_at,
    grace_period_expires_at = excluded.grace_period_expires_at,
    unsubscribe_detected_at = excluded.unsubscribe_detected_at,
    billing_issue_detected_at = excluded.billing_issue_detected_at,
    refunded_at = excluded.refunded_at,
    is_sandbox = excluded.is_sandbox,
    ownership_type = excluded.ownership_type,
    store_transaction_id = excluded.store_transaction_id;
    on conflict (user_id) do update set fetched_at = excluded.fetched_at, updated_at = now();
  return 'applied';
end;
$$;

-- ---------------------------------------------------------------------------------------------------------------
-- 5. Shared burst rate limits
-- ---------------------------------------------------------------------------------------------------------------
create table public.rate_limit_counters (
  key text not null check (char_length(key) between 1 and 200),
  window_start timestamptz not null,
  hits integer not null default 0,
  primary key (key, window_start)
);
create index rate_limit_counters_window_idx on public.rate_limit_counters (window_start);
alter table public.rate_limit_counters enable row level security;
revoke all on public.rate_limit_counters from anon, authenticated;
-- rate_limit_counters: no policies — service role only.

-- Count one request for `p_key` and say whether it is within `p_limit` per `p_window_seconds`. The estimate weighs
-- the previous fixed window by how much of it still overlaps the sliding window, so a burst straddling a window
-- boundary can't get twice the limit. A refused request is not counted. Atomic under concurrency: the counter row
-- for the current window is locked by the upsert.
create or replace function public.rate_limit_hit(p_key text, p_limit integer, p_window_seconds integer)
returns table (allowed boolean, retry_after_seconds integer)
language plpgsql
security definer
set search_path = public
as $$
declare
  v_now timestamptz := clock_timestamp();
  v_epoch double precision := extract(epoch from v_now);
  v_window timestamptz;
  v_prev integer;
  v_cur integer;
  v_elapsed double precision;
  v_estimate double precision;
begin
  if p_limit < 1 or p_window_seconds < 1 or p_key is null then
    raise exception 'invalid rate limit' using errcode = '22023';
  end if;
  v_window := to_timestamp(floor(v_epoch / p_window_seconds) * p_window_seconds);
  v_elapsed := (v_epoch - extract(epoch from v_window)) / p_window_seconds;
  -- Lock (or create) this window's counter first, so concurrent calls for the key serialize here.
    on conflict (key, window_start) do update set hits = c.hits
    returning c.hits into v_cur;
  select coalesce((select hits from public.rate_limit_counters
                   where key = left(p_key, 200) and window_start = v_window - make_interval(secs => p_window_seconds)), 0)
    into v_prev;
  v_estimate := v_prev * (1 - v_elapsed) + v_cur;
  if v_estimate + 1 > p_limit then
    allowed := false;
    retry_after_seconds := greatest(1, ceil(p_window_seconds * (1 - v_elapsed))::integer);
    return next;
    return;
  end if;
  update public.rate_limit_counters set hits = hits + 1 where key = left(p_key, 200) and window_start = v_window;
  -- Occasional clean-up of old windows.
  if random() < 0.01 then
    delete from public.rate_limit_counters where window_start < v_now - interval '2 days';
  end if;
  allowed := true;
  retry_after_seconds := 0;
  return next;
end;
$$;

-- ---------------------------------------------------------------------------------------------------------------
-- Service role only
-- ---------------------------------------------------------------------------------------------------------------
revoke all on function public.claim_webhook_event(text, text, text, text, integer) from public, anon, authenticated;
revoke all on function public.finish_webhook_event(text, text, boolean, text) from public, anon, authenticated;
revoke all on function public.apply_entitlement(uuid, bigint, text, text, timestamptz) from public, anon, authenticated;
revoke all on function public.upsert_stripe_subscription(uuid, text, text, text, text, timestamptz, boolean, timestamptz) from public, anon, authenticated;
revoke all on function public.apply_store_snapshot(uuid, timestamptz, jsonb) from public, anon, authenticated;
revoke all on function public.rate_limit_hit(text, integer, integer) from public, anon, authenticated;
grant execute on function public.claim_webhook_event(text, text, text, text, integer) to service_role;
grant execute on function public.finish_webhook_event(text, text, boolean, text) to service_role;
grant execute on function public.apply_entitlement(uuid, bigint, text, text, timestamptz) to service_role;
grant execute on function public.upsert_stripe_subscription(uuid, text, text, text, text, timestamptz, boolean, timestamptz) to service_role;
grant execute on function public.apply_store_snapshot(uuid, timestamptz, jsonb) to service_role;
grant execute on function public.rate_limit_hit(text, integer, integer) to service_role;

-- ===== supabase/migrations/20261101000047_program_builder_enforcement.sql =====
-- Narrow Gate Fitness — close the remaining ways to get the paid program builder through the database API, and a few
-- defence-in-depth gaps found in the 2026-11-01 database audit (docs/security/PRELAUNCH_SECURITY_REPORT.md).
--
-- 1. M1: a Free member could insert a "starter" program with their own token (starter inserts had no plan check),
--    fill it with any weeks, days and exercises, and relabel it "custom" or "ai": the paid builder's result without
--    the plan, and without the builder's rate limit. Now starter programs are created by the server only (the app's
--    onboarding and schedule rebuild do this with the service role), a member can never change a program's source,
--    and editing the contents of a member's starter program needs Plus/Pro (the app's only editors of those contents,
--    adaptive training and coach suggestions, are Pro features already).
-- 2. L3: has_ai_coach() ignored a refunded or disputed period (access_revoked_at), unlike the app's own rule.
-- 3. L4: members could insert their own AI "proposal" JSON on a question and then apply it as if the coach wrote it.
-- 4. L6: anon and authenticated held TRUNCATE, REFERENCES and TRIGGER on every table, and write grants on billing
--    tables that RLS alone was denying. Removed (nothing in the app uses them).

-- 1a. Starter programs: server only.
drop policy if exists training_programs_insert on public.training_programs;
create policy training_programs_insert on public.training_programs
  for insert to authenticated with check (
    (
      owner_id = (select auth.uid()) and is_published = false
      and ((source = 'custom' and public.has_plan('plus')) or (source = 'ai' and public.has_plan('pro')))
    )
    or (owner_id is null and public.is_admin())
  );

-- 1b. A program's source never changes under a member's session (the server's service role has no auth.uid()).
create or replace function public.lock_training_program_source()
returns trigger
language plpgsql
set search_path = public
as $$
begin
  if auth.uid() is not null and new.source is distinct from old.source then
    raise exception 'A program''s source can''t be changed' using errcode = '42501';
  end if;
  return new;
end;
$$;
revoke all on function public.lock_training_program_source() from public, anon, authenticated;
create trigger training_programs_lock_source before update on public.training_programs
  for each row execute function public.lock_training_program_source();

-- 1c. The contents of a member's starter program are edited only with Plus/Pro. Security invoker: it sees only the
-- caller's own programs (the parent ownership check in the write policies already requires that), so it can't be
-- used to probe other members' programs.
create or replace function public.is_member_starter_program(p_program_id uuid)
returns boolean
language sql
stable
set search_path = public
as $$
  select exists (select 1 from public.training_programs p where p.id = p_program_id and p.owner_id is not null and p.source = 'starter');
$$;
revoke all on function public.is_member_starter_program(uuid) from public, anon;
grant execute on function public.is_member_starter_program(uuid) to authenticated, service_role;

create policy program_weeks_starter_plan_insert on public.program_weeks
  as restrictive for insert to authenticated
  with check (not public.is_member_starter_program(program_id) or public.has_plan('plus'));
create policy program_weeks_starter_plan_update on public.program_weeks
  as restrictive for update to authenticated
  using (not public.is_member_starter_program(program_id) or public.has_plan('plus'))
  with check (not public.is_member_starter_program(program_id) or public.has_plan('plus'));

create policy program_days_starter_plan_insert on public.program_days
  as restrictive for insert to authenticated
  with check (not public.is_member_starter_program(public.program_of_week(week_id)) or public.has_plan('plus'));
create policy program_days_starter_plan_update on public.program_days
  as restrictive for update to authenticated
  using (not public.is_member_starter_program(public.program_of_week(week_id)) or public.has_plan('plus'))
  with check (not public.is_member_starter_program(public.program_of_week(week_id)) or public.has_plan('plus'));

create policy program_exercises_starter_plan_insert on public.program_exercises
  as restrictive for insert to authenticated
  with check (not public.is_member_starter_program(public.program_of_day(day_id)) or public.has_plan('plus'));
create policy program_exercises_starter_plan_update on public.program_exercises
  as restrictive for update to authenticated
  using (not public.is_member_starter_program(public.program_of_day(day_id)) or public.has_plan('plus'))
  with check (not public.is_member_starter_program(public.program_of_day(day_id)) or public.has_plan('plus'));

-- 2. The legacy AI allowance ends with a refunded or disputed period, as in src/lib/domain/plans.ts.
create or replace function public.has_ai_coach()
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select public.has_plan('pro') or exists (
    select 1
    from public.legacy_plan_terms t
    join public.subscriptions s on s.stripe_subscription_id = t.stripe_subscription_id
    where t.user_id = auth.uid()
      and t.ai_monthly_limit > 0
      and (t.ends_at is null or t.ends_at > now())
      and s.plan = t.plan
      and s.status in ('active', 'trialing', 'past_due')
      and s.access_revoked_at is null
      and (s.current_period_end is null or s.current_period_end > now())
  );
$$;
revoke all on function public.has_ai_coach() from public, anon;
grant execute on function public.has_ai_coach() to authenticated, service_role;

-- 3. Members write only plain questions: no proposal or proposal status of their own.
drop policy if exists ai_messages_insert_own on public.ai_messages;
create policy ai_messages_insert_own on public.ai_messages
  for insert to authenticated with check (
    user_id = (select auth.uid())
    and role = 'user'
    and proposal is null
    and proposal_status is null
    and exists (select 1 from public.ai_conversations c where c.id = conversation_id and c.user_id = (select auth.uid()))
  );

-- 4. Defence in depth: privileges RLS was the only barrier for.
revoke truncate, references, trigger on all tables in schema public from anon, authenticated;
alter default privileges for role postgres in schema public revoke truncate, references, trigger on tables from anon, authenticated;
revoke all on public.stripe_events, public.revenuecat_events from anon, authenticated;
revoke insert, update, delete on public.subscriptions, public.user_entitlements, public.billing_customers, public.store_subscriptions,
  public.legacy_plan_terms, public.ai_usage_events from anon, authenticated;

-- ===== supabase/migrations/20261102000048_low_findings_hardening.sql =====
-- Narrow Gate Fitness — the remaining Low findings of the 2026-11-01 security review
-- (docs/security/PRELAUNCH_SECURITY_REPORT.md F14–F18; docs/security/DATABASE_AUDIT.md L1, L2, L5, L7, L8).
-- Nothing a member can do in the app changes; only writes the app never makes are refused, and a few error messages
-- that told one member something about another are gone.

-- ---------------------------------------------------------------------------------------------------------------
-- F14 (L1): an enrolment can't be repointed at a program the member couldn't enrol in.
-- The insert policy already requires can_use_program(program_id); an update could change program_id freely. The app
-- never changes it (it pauses one enrolment and inserts another).
-- ---------------------------------------------------------------------------------------------------------------
create or replace function public.check_user_program_change()
returns trigger
language plpgsql
set search_path = public
as $$
begin
  if auth.uid() is not null and new.program_id is distinct from old.program_id and not public.can_use_program(new.program_id) then
    raise exception 'That program isn''t included in your plan' using errcode = '42501';
  end if;
  return new;
end;
$$;
revoke all on function public.check_user_program_change() from public, anon, authenticated;
create trigger user_programs_program_change before update of program_id on public.user_programs
  for each row execute function public.check_user_program_change();

-- ---------------------------------------------------------------------------------------------------------------
-- F15 (L2): six SECURITY DEFINER triggers checked a row's user_id before row level security did, so a row naming
-- another member's id got that member's plan, consent or limit back in the error. Now a row that isn't the caller's
-- own goes straight on to RLS, which refuses it with its usual message (as migration 039 did for the sleep triggers).
-- The server (service role, no auth.uid()) is unaffected. Bodies are otherwise unchanged.
-- ---------------------------------------------------------------------------------------------------------------
create or replace function public.enforce_free_template_limit()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if auth.uid() is not null and new.user_id is distinct from auth.uid() then
    return new;
  end if;
  perform pg_advisory_xact_lock(hashtextextended('workout_templates:' || new.user_id::text, 0));
  if public.plan_rank(public.plan_of(new.user_id)) = 0
     and (select count(*) from public.workout_templates where user_id = new.user_id) >= 5 then
    raise exception 'Free plan limit: 5 saved workouts' using errcode = 'P0001';
  end if;
  return new;
end;
$$;

create or replace function public.enforce_live_gps_plan()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  adds_gps boolean;
begin
  if auth.uid() is null or new.user_id is distinct from auth.uid() then
    return new;
  end if;
  if tg_op = 'INSERT' then
    adds_gps := new.source = 'gps' or new.route is not null;
  else
    adds_gps := (new.source = 'gps' and old.source is distinct from 'gps')
      or (new.route is not null and new.route is distinct from old.route);
  end if;
  if adds_gps and public.plan_rank(public.plan_of(new.user_id)) < public.plan_rank('plus') then
    raise exception 'Live GPS recording is included with Pro' using errcode = 'P0001';
  end if;
  return new;
end;
$$;

create or replace function public.enforce_wellness_consent()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if auth.uid() is not null and new.user_id is distinct from auth.uid() then
    return new;
  end if;
  if new.limitations is not null and btrim(new.limitations) <> '' then
    if not exists (
      select 1 from public.profiles p
      where p.id = new.user_id and p.wellness_consent_at is not null
    ) then
      raise exception 'Consent is required before storing physical limitation notes'
        using errcode = 'check_violation';
    end if;
  end if;
  return new;
end;
$$;

create or replace function public.enforce_coach_memory_limit()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if auth.uid() is not null and new.user_id is distinct from auth.uid() then
    return new;
  end if;
  perform pg_advisory_xact_lock(hashtextextended('coach_memories:' || new.user_id::text, 0));
  if (select count(*) from public.coach_memories where user_id = new.user_id) >= 100 then
    raise exception 'coach_memory_limit' using errcode = 'P0001';
  end if;
  return new;
end;
$$;

create or replace function public.enforce_running_goal_limit()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if auth.uid() is not null and new.user_id is distinct from auth.uid() then
    return new;
  end if;
  perform pg_advisory_xact_lock(hashtextextended('running_goals:' || new.user_id::text, 0));
  if (select count(*) from public.running_goals where user_id = new.user_id and archived_at is null) >= 10 then
    raise exception 'running_goal_limit' using errcode = 'P0001';
  end if;
  return new;
end;
$$;

create or replace function public.body_scan_limit()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if auth.uid() is not null and new.user_id is distinct from auth.uid() then
    return new;
  end if;
  perform pg_advisory_xact_lock(hashtext('body_scans:' || new.user_id::text));
  if (select count(*) from public.body_scans where user_id = new.user_id) >= 200 then
    raise exception 'body_scan_limit' using errcode = 'P0001';
  end if;
  return new;
end;
$$;

-- ---------------------------------------------------------------------------------------------------------------
-- F17 (L7): links to another member's rows. A foreign key only proves the row exists, so a member could point their
-- own row at someone else's session, enrolment, message, measurement, food or private program (an existence check,
-- and junk links in the data). These links now have to point at the member's own rows (or, for programs and foods,
-- at the public catalog). A missing row and someone else's row get the same error. Security invoker: the check sees
-- only what the member can already see. The server (service role) is unaffected.
-- ---------------------------------------------------------------------------------------------------------------
create or replace function public.check_member_reference()
returns trigger
language plpgsql
set search_path = public
as $$
declare
  v_col text := tg_argv[0];
  v_kind text := tg_argv[1];
  v_ref uuid := (to_jsonb(new) ->> v_col)::uuid;
  v_ok boolean;
begin
  if auth.uid() is null or v_ref is null then
    return new;
  end if;
  if tg_op = 'UPDATE' and v_ref is not distinct from (to_jsonb(old) ->> v_col)::uuid then
    return new;
  end if;
  v_ok := case v_kind
    when 'program' then exists (
      select 1 from public.training_programs p
      where p.id = v_ref and (p.is_published or p.owner_id = auth.uid() or public.is_admin()))
    when 'program_day' then exists (
      select 1 from public.program_days d
      join public.program_weeks w on w.id = d.week_id
      join public.training_programs p on p.id = w.program_id
      where d.id = v_ref and (p.is_published or p.owner_id = auth.uid() or public.is_admin()))
    when 'food' then exists (select 1 from public.foods f where f.id = v_ref and (f.owner_id is null or f.owner_id = auth.uid()))
    when 'user_programs' then exists (select 1 from public.user_programs x where x.id = v_ref and x.user_id = auth.uid())
    when 'workout_sessions' then exists (select 1 from public.workout_sessions x where x.id = v_ref and x.user_id = auth.uid())
    when 'ai_messages' then exists (select 1 from public.ai_messages x where x.id = v_ref and x.user_id = auth.uid())
    when 'measurement_entries' then exists (select 1 from public.measurement_entries x where x.id = v_ref and x.user_id = auth.uid())
    else false
  end;
  if not v_ok then
    raise exception 'The linked % was not found', replace(v_col, '_id', '') using errcode = '23503';
  end if;
  return new;
end;
$$;
revoke all on function public.check_member_reference() from public, anon, authenticated;

create trigger workout_sessions_ref_user_program before insert or update of user_program_id on public.workout_sessions
  for each row execute function public.check_member_reference('user_program_id', 'user_programs');
create trigger workout_sessions_ref_program_day before insert or update of program_day_id on public.workout_sessions
  for each row execute function public.check_member_reference('program_day_id', 'program_day');
create trigger personal_records_ref_session before insert or update of session_id on public.personal_records
  for each row execute function public.check_member_reference('session_id', 'workout_sessions');
create trigger activities_ref_workout_session before insert or update of workout_session_id on public.activities
  for each row execute function public.check_member_reference('workout_session_id', 'workout_sessions');
create trigger planned_session_overrides_ref_program_day before insert or update of program_day_id on public.planned_session_overrides
  for each row execute function public.check_member_reference('program_day_id', 'program_day');
create trigger coach_memories_ref_source_message before insert or update of source_message_id on public.coach_memories
  for each row execute function public.check_member_reference('source_message_id', 'ai_messages');
create trigger training_adjustments_ref_program before insert or update of program_id on public.training_adjustments
  for each row execute function public.check_member_reference('program_id', 'program');
create trigger training_adjustments_ref_source_message before insert or update of source_message_id on public.training_adjustments
  for each row execute function public.check_member_reference('source_message_id', 'ai_messages');
create trigger body_scans_ref_measurement before insert or update of measurement_id on public.body_scans
  for each row execute function public.check_member_reference('measurement_id', 'measurement_entries');
create trigger meal_items_ref_food before insert or update of food_id on public.meal_items
  for each row execute function public.check_member_reference('food_id', 'food');

-- ---------------------------------------------------------------------------------------------------------------
-- F17 (L8): program_of_week and program_of_day are callable by anyone over the API (row level security on the
-- catalog uses them for signed-out visitors too), and returned the program of any week or day id, including a
-- member's private program. They now answer only for programs the caller can see (published, their own, or any for
-- an admin), which is all the policies that use them need; for anything else they return null, as for a missing id.
-- ---------------------------------------------------------------------------------------------------------------
create or replace function public.program_of_week(p_week_id uuid)
returns uuid
language sql
stable
security definer
set search_path = public
as $$
  select w.program_id
  from public.program_weeks w
  join public.training_programs p on p.id = w.program_id
  where w.id = p_week_id and (p.is_published or p.owner_id = auth.uid() or public.is_admin());
$$;

create or replace function public.program_of_day(p_day_id uuid)
returns uuid
language sql
stable
security definer
set search_path = public
as $$
  select w.program_id
  from public.program_days d
  join public.program_weeks w on w.id = d.week_id
  join public.training_programs p on p.id = w.program_id
  where d.id = p_day_id and (p.is_published or p.owner_id = auth.uid() or public.is_admin());
$$;

-- ---------------------------------------------------------------------------------------------------------------
-- F16 (L5): legal acceptance records. Members could add their own rows with any version, fingerprint and details,
-- which weakens them as evidence. Now:
-- - legal_document_versions lists every published version with its fingerprint (seeded below from
--   src/lib/legal/versions.ts; the server registers new ones from the same file before recording them);
-- - every acceptance must name a listed version, and only auto-renewal consent carries details;
-- - members no longer write acceptances directly: the server records re-acceptance and checkout consent (with the
--   details it computed from the approved price), and sign-up records only listed versions.
-- Existing rows are kept as they are.
-- ---------------------------------------------------------------------------------------------------------------
create table public.legal_document_versions (
  document text not null check (document in ('terms', 'privacy', 'risk_acknowledgment', 'auto_renewal')),
  version text not null check (char_length(version) between 1 and 64),
  document_sha256 text not null check (document_sha256 ~ '^[0-9a-f]{64}$'),
  registered_at timestamptz not null default now(),
  primary key (document, version, document_sha256)
);
alter table public.legal_document_versions enable row level security;
revoke all on public.legal_document_versions from public, anon, authenticated;
grant select, insert on public.legal_document_versions to service_role;

on conflict do nothing;

create or replace function public.legal_acceptance_check()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if not exists (
    select 1 from public.legal_document_versions v
    where v.document = new.document and v.version = new.version and v.document_sha256 = new.document_sha256
  ) then
    raise exception 'Unknown legal document version' using errcode = '23514';
  end if;
  if (new.document = 'auto_renewal') <> (new.details is not null) then
    raise exception 'Only auto-renewal consent records what was agreed to, and it must' using errcode = '23514';
  end if;
  if new.document = 'auto_renewal' and new.source <> 'checkout' then
    raise exception 'Auto-renewal consent is recorded at checkout' using errcode = '23514';
  end if;
  return new;
end;
$$;
revoke all on function public.legal_acceptance_check() from public, anon, authenticated;
create trigger legal_acceptances_check before insert on public.legal_acceptances
  for each row execute function public.legal_acceptance_check();

drop policy if exists legal_acceptances_insert_own on public.legal_acceptances;
revoke insert, update, delete on public.legal_acceptances from anon, authenticated;

-- Sign-up records only listed versions (an entry that isn't listed is skipped, never blocking the sign-up).
create or replace function public.record_signup_acceptances()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  item jsonb;
begin
  if jsonb_typeof(new.raw_user_meta_data -> 'legal_acceptances') <> 'array' then
    return new;
  end if;
  for item in select * from jsonb_array_elements(new.raw_user_meta_data -> 'legal_acceptances') limit 10 loop
    if item ->> 'document' in ('terms', 'privacy', 'risk_acknowledgment')
       and exists (
         select 1 from public.legal_document_versions v
         where v.document = item ->> 'document' and v.version = item ->> 'version' and v.document_sha256 = item ->> 'sha256'
       ) then
      values (new.id, item ->> 'document', item ->> 'version', item ->> 'sha256', 'signup');
    end if;
  end loop;
  return new;
end;
$$;
revoke all on function public.record_signup_acceptances() from public, anon, authenticated;

-- ---------------------------------------------------------------------------------------------------------------
-- F18: an AI coach request can carry a request id from the client. A retry with the same id gets the saved reply
-- instead of a second answer (and a second charge against the member's allowance); while the first is still being
-- answered, the retry is told so. One question and one reply per request id and member.
-- ---------------------------------------------------------------------------------------------------------------
alter table public.ai_messages add column if not exists request_id uuid;
create unique index if not exists ai_messages_request_once on public.ai_messages (user_id, role, request_id) where request_id is not null;

-- ===== supabase/migrations/20261102000049_ai_reply_length.sql =====
-- Narrow Gate Fitness — AI coach replies are saved whole (AI audit 2026-11-01, D3).
-- A coach reply could stream to the member in full and then be saved cut at 20,000 characters (the chat replaces the
-- streamed draft with the saved message), so a long answer lost its end, "shortened" note included. A reply can use
-- up to 12,000 output tokens per round (src/lib/coach/prompt.ts), about 48,000 characters at most; the limit becomes
-- 60,000, and the server ends anything longer with a visible note (fitStoredReply). Members can't write replies
-- (only the server does), so this changes nothing a member can do.
--
-- Rollback: update public.ai_messages set content = left(content, 20000) where char_length(content) > 20000;
--           then restore the check below with 20000.

alter table public.ai_messages drop constraint if exists ai_messages_content_check;
alter table public.ai_messages add constraint ai_messages_content_check check (char_length(content) <= 60000);

-- ===== supabase/migrations/20261102000050_coach_feedback.sql =====
-- Narrow Gate Fitness — optional feedback on AI coach replies, for the TestFlight beta.
-- Under a coach reply a member may answer "Was this coaching advice useful?" (Yes / Partially / No), add an optional
-- comment, or report a safety concern. It is OFF: the flag below is inserted disabled and the app shows nothing until
-- the owner switches it on (src/server/flags.ts `isFlagOn`, which treats a missing flag as off). Before switching it
-- on: update the privacy policy and the App Store privacy details (members' feedback is new data the app collects).
--
-- Members can only rate replies the coach gave them, read and change their own feedback, and it goes with their
-- account (deleted with it, included in their export).

create table public.ai_message_feedback (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users (id) on delete cascade,
  message_id uuid not null references public.ai_messages (id) on delete cascade,
  rating text check (rating in ('yes', 'partially', 'no')),
  comment text check (char_length(comment) <= 1000),
  safety_concern boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (user_id, message_id),
  -- A rating, a safety report, or both.
  check (rating is not null or safety_concern)
);
create index ai_message_feedback_safety_idx on public.ai_message_feedback (created_at desc) where safety_concern;
create trigger ai_message_feedback_updated_at before update on public.ai_message_feedback
  for each row execute function public.set_updated_at();

alter table public.ai_message_feedback enable row level security;

-- Only on a reply the coach gave this member.
create or replace function public.is_own_coach_reply(p_message_id uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (select 1 from public.ai_messages m where m.id = p_message_id and m.user_id = auth.uid() and m.role = 'assistant');
$$;
revoke all on function public.is_own_coach_reply(uuid) from public;
grant execute on function public.is_own_coach_reply(uuid) to authenticated;

create policy "Members read their own coach feedback" on public.ai_message_feedback
  for select to authenticated using (user_id = auth.uid());
create policy "Members give feedback on their own coach replies" on public.ai_message_feedback
  for insert to authenticated with check (user_id = auth.uid() and public.is_own_coach_reply(message_id));
create policy "Members change their own coach feedback" on public.ai_message_feedback
  for update to authenticated using (user_id = auth.uid()) with check (user_id = auth.uid() and public.is_own_coach_reply(message_id));
create policy "Members remove their own coach feedback" on public.ai_message_feedback
  for delete to authenticated using (user_id = auth.uid());

values ('coach_feedback', false, 'TestFlight: ask "Was this coaching advice useful?" under AI coach replies, with a safety-report option. Off until the owner authorizes collecting it.')
on conflict (key) do nothing;

-- ===== supabase/migrations/20261103000051_activation_events.sql =====
-- First-workout activation, measured on the server (launch-critical item 1).
--
-- What it records: four facts about a member's own workouts, each once per workout, with a timestamp and nothing
-- else (no exercises, weights, notes or device data):
--   workout_started    the server first saw the workout (the logger saves it once the member does something)
--   set_completed      the server first saw a completed set in it
--   workout_completed  it was finished and saved
--   workout_abandoned  it was discarded while still in progress
-- Account creation and onboarding come from profiles (created_at, onboarding_completed_at), which already exist.
--
-- Server-validated: rows are written only by these triggers, from the workout rows the server itself stores. Members
-- can read their own rows (they are part of the data export) but cannot insert, change or delete any. No-duplicate by
-- construction: one row per (member, event, workout). First-party only: nothing leaves the database, and the rows
-- are deleted with the account (on delete cascade).

create table public.activation_events (
  id bigint generated always as identity primary key,
  user_id uuid not null references auth.users (id) on delete cascade,
  event text not null check (event in ('workout_started', 'set_completed', 'workout_completed', 'workout_abandoned')),
  -- The workout's client id (workout_sessions.client_id): stable across retries, devices and the discard.
  workout_client_id uuid not null,
  occurred_at timestamptz not null,
  -- How the server learned it: a draft sync, the finish, the discard, or this migration's backfill of old workouts.
  source text not null check (source in ('sync', 'finish', 'discard', 'backfill')),
  created_at timestamptz not null default now(),
  unique (user_id, event, workout_client_id)
);
create index activation_events_user_event_idx on public.activation_events (user_id, event, occurred_at);

alter table public.activation_events enable row level security;
create policy "activation_events: read own" on public.activation_events for select to authenticated using (user_id = (select auth.uid()));
revoke all on public.activation_events from anon, authenticated;
grant select on public.activation_events to authenticated;

-- A workout's started time as the server will believe it: the client's own start, but never in the future and never
-- more than two days before the server first saw it.
create or replace function public.activation_clamp_start(p_started timestamptz)
returns timestamptz
language sql
stable
as $$
  select greatest(least(p_started, now()), now() - interval '2 days');
$$;

create or replace function public.activation_has_completed_set(p_draft jsonb)
returns boolean
language sql
immutable
as $$
  select p_draft is not null and jsonb_path_exists(p_draft, '$.exercises[*].sets[*] ? (@.completed == true)');
$$;

create or replace function public.activation_record(p_user uuid, p_event text, p_client uuid, p_at timestamptz, p_source text)
returns void
language sql
security definer
set search_path = public
as $$
  values (p_user, p_event, p_client, p_at, p_source)
  on conflict (user_id, event, workout_client_id) do nothing;
$$;
revoke execute on function public.activation_record(uuid, text, uuid, timestamptz, text) from anon, authenticated, public;

create or replace function public.activation_on_workout_write()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if tg_op = 'INSERT' then
    perform public.activation_record(new.user_id, 'workout_started', new.client_id, public.activation_clamp_start(new.started_at), case when new.draft is not null then 'sync' else 'finish' end);
  end if;
  if new.status = 'in_progress' and public.activation_has_completed_set(new.draft)
     and (tg_op = 'INSERT' or not public.activation_has_completed_set(old.draft)) then
    perform public.activation_record(new.user_id, 'set_completed', new.client_id, now(), 'sync');
  end if;
  if new.status = 'completed' and (tg_op = 'INSERT' or old.status is distinct from 'completed') then
    -- Finished without the server ever seeing a completed set (a workout logged entirely offline): the first set is
    -- known only to have happened by the finish.
    if exists (select 1 from public.workout_sets s where s.user_id = new.user_id and s.completed
               and s.workout_exercise_id in (select e.id from public.workout_exercises e where e.session_id = new.id)) then
      perform public.activation_record(new.user_id, 'set_completed', new.client_id, least(coalesce(new.ended_at, now()), now()), 'finish');
    end if;
    perform public.activation_record(new.user_id, 'workout_completed', new.client_id, least(coalesce(new.ended_at, now()), now()), 'finish');
  end if;
  return null;
end;
$$;

create trigger workout_sessions_activation_write
  after insert or update of status, draft on public.workout_sessions
  for each row execute function public.activation_on_workout_write();

create or replace function public.activation_on_workout_delete()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  -- Only a discard of a workout still in progress. Deleting a finished workout from history is not abandonment, and
  -- when the whole account is being deleted (the sign-in row is already gone) nothing is recorded.
  if old.status = 'in_progress' and exists (select 1 from auth.users u where u.id = old.user_id) then
    perform public.activation_record(old.user_id, 'workout_abandoned', old.client_id, now(), 'discard');
  end if;
  return null;
end;
$$;

create trigger workout_sessions_activation_delete
  after delete on public.workout_sessions
  for each row execute function public.activation_on_workout_delete();

-- Workouts from before this migration: their starts and finishes are known; when their first sets happened is not.
select user_id, 'workout_started', client_id, started_at, 'backfill' from public.workout_sessions
on conflict do nothing;
select user_id, 'workout_completed', client_id, coalesce(ended_at, updated_at), 'backfill' from public.workout_sessions where status = 'completed'
on conflict do nothing;

-- Admin-only cohort summary. New members are the accounts created in [p_from, p_to); returning members are older
-- accounts that trained in that window. Aggregates only; no member is identifiable from it except in a tiny cohort,
-- which the admin page says. Times are minutes (medians), days are the member's own calendar days (their time zone).
create or replace function public.admin_activation_metrics(p_from timestamptz default now() - interval '30 days', p_to timestamptz default now())
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  result jsonb;
begin
  if not public.is_admin() then
    raise exception 'Not authorized' using errcode = '42501';
  end if;
  with cohort as (
    select p.id, p.created_at, p.onboarding_completed_at, coalesce(nullif(p.timezone, ''), 'UTC') as tz
    from public.profiles p
    where p.created_at >= p_from and p.created_at < p_to
  ),
  firsts as (
    select c.*,
      (select min(e.occurred_at) from public.activation_events e where e.user_id = c.id and e.event = 'workout_started') as first_start,
      (select min(e.occurred_at) from public.activation_events e where e.user_id = c.id and e.event = 'set_completed') as first_set,
      (select min(e.occurred_at) from public.activation_events e where e.user_id = c.id and e.event = 'workout_completed') as first_done
    from cohort c
  ),
  first_workout as (
    select f.id,
      (select e.workout_client_id from public.activation_events e where e.user_id = f.id and e.event = 'workout_started' order by e.occurred_at, e.id limit 1) as client_id
    from firsts f
  ),
  -- Days (0 = the sign-up day) on which the member started or finished a workout.
  active_days as (
    select distinct c.id, ((e.occurred_at at time zone c.tz)::date - (c.created_at at time zone c.tz)::date) as day
    from cohort c join public.activation_events e on e.user_id = c.id and e.event in ('workout_started', 'workout_completed')
  ),
  cohort_days as (
    select c.id, ((now() at time zone c.tz)::date - (c.created_at at time zone c.tz)::date) as age_days from cohort c
  ),
  cohort_workouts as (
    select e.workout_client_id, e.user_id from public.activation_events e join cohort c on c.id = e.user_id where e.event = 'workout_started'
  ),
  stale as (
    -- Still "in progress" but untouched for a day: left, not finished (and not yet discarded).
    select s.user_id, s.client_id from public.workout_sessions s join cohort c on c.id = s.user_id
    where s.status = 'in_progress' and s.updated_at < now() - interval '24 hours'
  )
  select jsonb_build_object(
    'window', jsonb_build_object('from', p_from, 'to', p_to),
    'new_members', jsonb_build_object(
      'accounts', (select count(*) from cohort),
      'onboarded', (select count(*) from cohort where onboarding_completed_at is not null),
      'started_first_workout', (select count(first_start) from firsts),
      'completed_first_set', (select count(first_set) from firsts),
      'completed_first_workout', (select count(first_done) from firsts)
    ),
    'median_minutes', jsonb_build_object(
      'signup_to_onboarded', (select round((percentile_cont(0.5) within group (order by extract(epoch from onboarding_completed_at - created_at) / 60))::numeric, 1) from firsts where onboarding_completed_at is not null),
      'onboarded_to_first_workout_start', (select round((percentile_cont(0.5) within group (order by extract(epoch from first_start - onboarding_completed_at) / 60))::numeric, 1) from firsts where first_start is not null and onboarding_completed_at is not null),
      'first_workout_start_to_first_set', (select round((percentile_cont(0.5) within group (order by extract(epoch from first_set - first_start) / 60))::numeric, 1) from firsts where first_set is not null and first_start is not null),
      'signup_to_first_set', (select round((percentile_cont(0.5) within group (order by extract(epoch from first_set - created_at) / 60))::numeric, 1) from firsts where first_set is not null),
      'signup_to_first_workout_completed', (select round((percentile_cont(0.5) within group (order by extract(epoch from first_done - created_at) / 60))::numeric, 1) from firsts where first_done is not null)
    ),
    -- Returned on day N: trained on that calendar day. Only members whose day N is over are counted ("eligible").
    'return_activity', jsonb_build_object(
      'day1', jsonb_build_object('eligible', (select count(*) from cohort_days where age_days > 1), 'returned', (select count(*) from cohort_days d where d.age_days > 1 and exists (select 1 from active_days a where a.id = d.id and a.day = 1))),
      'day7', jsonb_build_object('eligible', (select count(*) from cohort_days where age_days > 7), 'returned', (select count(*) from cohort_days d where d.age_days > 7 and exists (select 1 from active_days a where a.id = d.id and a.day = 7))),
      'day14', jsonb_build_object('eligible', (select count(*) from cohort_days where age_days > 14), 'returned', (select count(*) from cohort_days d where d.age_days > 14 and exists (select 1 from active_days a where a.id = d.id and a.day = 14))),
      'days1to7', jsonb_build_object('eligible', (select count(*) from cohort_days where age_days > 7), 'returned', (select count(*) from cohort_days d where d.age_days > 7 and exists (select 1 from active_days a where a.id = d.id and a.day between 1 and 7)))
    ),
    'abandonment', jsonb_build_object(
      'workouts_started', (select count(*) from cohort_workouts),
      'discarded', (select count(*) from public.activation_events e join cohort c on c.id = e.user_id where e.event = 'workout_abandoned'),
      'left_in_progress_24h', (select count(*) from stale),
      'first_workout_abandoned', (select count(*) from first_workout fw where fw.client_id is not null and (
        exists (select 1 from public.activation_events e where e.user_id = fw.id and e.workout_client_id = fw.client_id and e.event = 'workout_abandoned')
        or exists (select 1 from stale s where s.user_id = fw.id and s.client_id = fw.client_id)))
    ),
    'returning_members', jsonb_build_object(
      'trained_in_window', (select count(distinct e.user_id) from public.activation_events e join public.profiles p on p.id = e.user_id
        where p.created_at < p_from and e.event = 'workout_completed' and e.occurred_at >= p_from and e.occurred_at < p_to),
      'workouts_completed', (select count(*) from public.activation_events e join public.profiles p on p.id = e.user_id
        where p.created_at < p_from and e.event = 'workout_completed' and e.occurred_at >= p_from and e.occurred_at < p_to)
    )
  ) into result;
  return result;
end;
$$;
revoke execute on function public.admin_activation_metrics(timestamptz, timestamptz) from anon, public;
grant execute on function public.admin_activation_metrics(timestamptz, timestamptz) to authenticated;

-- ===== supabase/migrations/20261103000052_sandbox_testers.sql =====
-- Sandbox tester allow-list (launch-critical item 4).
--
-- App Store / Google Play sandbox purchases (development builds, TestFlight, App Review) cost nothing, and every build
-- talks to the one deployed server. Until now the server either ignored all of them (REVENUECAT_ALLOW_SANDBOX unset:
-- App Review's purchase would not unlock Pro) or counted all of them (set: every TestFlight tester gets free Pro on
-- the production server). This list lets named accounts count sandbox purchases and nobody else:
--   - keyed by the account's stable user id (auth.users.id, which is also its RevenueCat app user id), never by email;
--   - checked on the server when RevenueCat is read (store-billing.ts) and again whenever the plan is recomputed
--     (billing.ts), so removing or expiring an entry stops a stored sandbox purchase from granting anything;
--   - written only by administrators (the admin Subscriptions page) or the service role; members can't read or write
--     it, so nobody can enrol themselves.
-- Production purchases are unaffected, and a sandbox purchase never becomes a production one: store_subscriptions
-- keeps RevenueCat's is_sandbox flag on every row.

create table public.sandbox_testers (
  user_id uuid primary key references auth.users (id) on delete cascade,
  -- Who this is and why (e.g. "App Review demo account", "TestFlight: internal QA"). Shown to admins, and included in
  -- the member's own data export, so keep it factual.
  note text not null check (char_length(note) between 1 and 200),
  added_by uuid references auth.users (id) on delete set null,
  -- Optional end of the access (e.g. the end of a TestFlight round). Null: until removed.
  expires_at timestamptz,
  created_at timestamptz not null default now()
);

alter table public.sandbox_testers enable row level security;
-- No policies: only the service role (server code) reads or writes it.
revoke all on public.sandbox_testers from anon, authenticated;

create or replace function public.is_sandbox_tester(p_user_id uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (select 1 from public.sandbox_testers t where t.user_id = p_user_id and (t.expires_at is null or t.expires_at > now()));
$$;
revoke execute on function public.is_sandbox_tester(uuid) from anon, authenticated, public;

-- ===== supabase/migrations/20261103000053_faith_discipleship.sql =====
-- Narrow Gate Fitness — Faith & Discipleship: Bible reader data, reading journeys with the daily Bible-and-prayer rule,
-- daily Faith and Fitness goals, memorization, studies, AI Bible study history and reminder kinds.
--
-- Everything here is private to its owner (owner-only RLS, no admin access) and cascades away with the account.
-- Existing Faith tables (prayer journal, practices, reminders, the 40-day challenge) are only extended; no existing
-- row is changed or removed. Journey progress is written only by the SECURITY DEFINER functions below, which validate
-- dates on the server, so a client cannot mark days complete, backdate check-ins or undo a reset.

-- ---------------------------------------------------------------------------------------------------------------
-- Helpers
-- ---------------------------------------------------------------------------------------------------------------

-- The 66 books and their chapter counts (the same canon as src/data/bible/books.json).
create or replace function public.bible_chapter_count(p_book text)
returns smallint
language sql
immutable
parallel safe
as $$
  select ('{"GEN":50,"EXO":40,"LEV":27,"NUM":36,"DEU":34,"JOS":24,"JDG":21,"RUT":4,"1SA":31,"2SA":24,"1KI":22,"2KI":25,"1CH":29,"2CH":36,"EZR":10,"NEH":13,"EST":10,"JOB":42,"PSA":150,"PRO":31,"ECC":12,"SNG":8,"ISA":66,"JER":52,"LAM":5,"EZK":48,"DAN":12,"HOS":14,"JOL":3,"AMO":9,"OBA":1,"JON":4,"MIC":7,"NAM":3,"HAB":3,"ZEP":3,"HAG":2,"ZEC":14,"MAL":4,"MAT":28,"MRK":16,"LUK":24,"JHN":21,"ACT":28,"ROM":16,"1CO":16,"2CO":13,"GAL":6,"EPH":6,"PHP":4,"COL":4,"1TH":5,"2TH":3,"1TI":6,"2TI":4,"TIT":3,"PHM":1,"HEB":13,"JAS":5,"1PE":5,"2PE":3,"1JN":5,"2JN":1,"3JN":1,"JUD":1,"REV":22}'::jsonb ->> p_book)::smallint;
$$;

create or replace function public.is_bible_chapter(p_book text, p_chapter integer)
returns boolean
language sql
immutable
parallel safe
as $$
  select coalesce(p_chapter between 1 and public.bible_chapter_count(p_book), false);
$$;

-- A member's time zone, or UTC when the stored name isn't one Postgres knows.
create or replace function public.faith_safe_tz(p_tz text)
returns text
language plpgsql
stable
as $$
begin
  if p_tz is null or p_tz = '' then
    return 'UTC';
  end if;
  perform now() at time zone p_tz;
  return p_tz;
exception when others then
  return 'UTC';
end;
$$;

-- ---------------------------------------------------------------------------------------------------------------
-- Bible reader: position, history, highlights, bookmarks, notes
-- ---------------------------------------------------------------------------------------------------------------

create table public.bible_reading_state (
  user_id uuid primary key references auth.users (id) on delete cascade,
  book_id text not null,
  chapter smallint not null,
  verse smallint check (verse between 1 and 176),
  font_scale numeric(3, 2) not null default 1.00 check (font_scale between 0.80 and 1.80),
  updated_at timestamptz not null default now(),
  check (public.is_bible_chapter(book_id, chapter))
);

create table public.bible_reading_history (
  id bigint generated always as identity primary key,
  user_id uuid not null references auth.users (id) on delete cascade,
  book_id text not null,
  chapter smallint not null,
  read_on date not null,
  read_at timestamptz not null default now(),
  unique (user_id, book_id, chapter, read_on),
  check (public.is_bible_chapter(book_id, chapter))
);
create index bible_reading_history_user_idx on public.bible_reading_history (user_id, read_at desc);

create table public.bible_highlights (
  user_id uuid not null references auth.users (id) on delete cascade,
  book_id text not null,
  chapter smallint not null,
  verse smallint not null check (verse between 1 and 176),
  color text not null check (color in ('gold', 'sage', 'sky', 'rose')),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  primary key (user_id, book_id, chapter, verse),
  check (public.is_bible_chapter(book_id, chapter))
);
create index bible_highlights_user_idx on public.bible_highlights (user_id, updated_at desc);

create table public.bible_bookmarks (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users (id) on delete cascade,
  book_id text not null,
  chapter smallint not null,
  verse smallint check (verse between 1 and 176),
  label text check (char_length(label) <= 120),
  created_at timestamptz not null default now(),
  check (public.is_bible_chapter(book_id, chapter))
);
create unique index bible_bookmarks_unique_idx on public.bible_bookmarks (user_id, book_id, chapter, coalesce(verse, 0));
create index bible_bookmarks_user_idx on public.bible_bookmarks (user_id, created_at desc);

create table public.bible_notes (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users (id) on delete cascade,
  book_id text not null,
  chapter smallint not null,
  verse_start smallint not null check (verse_start between 1 and 176),
  verse_end smallint not null check (verse_end between 1 and 176),
  body text not null check (char_length(body) between 1 and 10000),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  check (verse_end >= verse_start),
  check (public.is_bible_chapter(book_id, chapter))
);
create index bible_notes_user_idx on public.bible_notes (user_id, book_id, chapter);
create index bible_notes_user_updated_idx on public.bible_notes (user_id, updated_at desc);
create trigger bible_notes_updated_at before update on public.bible_notes for each row execute function public.set_updated_at();
create trigger bible_highlights_updated_at before update on public.bible_highlights for each row execute function public.set_updated_at();

-- ---------------------------------------------------------------------------------------------------------------
-- Scripture memorization (the text itself always comes from the verified BSB, never stored here)
-- ---------------------------------------------------------------------------------------------------------------

create table public.scripture_memory (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users (id) on delete cascade,
  book_id text not null,
  chapter smallint not null,
  verse_start smallint not null check (verse_start between 1 and 176),
  verse_end smallint not null check (verse_end between 1 and 176),
  status text not null default 'learning' check (status in ('learning', 'memorized')),
  -- How much of the verse is hidden in practice (0 = none … 4 = all), raised as the member succeeds.
  level smallint not null default 0 check (level between 0 and 4),
  review_count integer not null default 0 check (review_count >= 0),
  next_review_on date,
  last_reviewed_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  check (verse_end >= verse_start and verse_end - verse_start < 30),
  check (public.is_bible_chapter(book_id, chapter)),
  unique (user_id, book_id, chapter, verse_start, verse_end)
);
create index scripture_memory_user_idx on public.scripture_memory (user_id, status, next_review_on);
create trigger scripture_memory_updated_at before update on public.scripture_memory for each row execute function public.set_updated_at();

-- ---------------------------------------------------------------------------------------------------------------
-- Guided Bible studies: the member's progress and private notes per lesson (lesson content ships with the app)
-- ---------------------------------------------------------------------------------------------------------------

create table public.bible_study_progress (
  user_id uuid not null references auth.users (id) on delete cascade,
  study_slug text not null check (char_length(study_slug) between 1 and 80),
  lesson_slug text not null check (char_length(lesson_slug) between 1 and 80),
  completed_at timestamptz,
  notes text check (char_length(notes) <= 10000),
  updated_at timestamptz not null default now(),
  primary key (user_id, study_slug, lesson_slug)
);
create trigger bible_study_progress_updated_at before update on public.bible_study_progress for each row execute function public.set_updated_at();

-- ---------------------------------------------------------------------------------------------------------------
-- AI Bible study: conversation history and its own usage ledger (separate from the fitness coach's quota)
-- ---------------------------------------------------------------------------------------------------------------

create table public.bible_ai_messages (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users (id) on delete cascade,
  thread_id uuid not null,
  role text not null check (role in ('user', 'assistant')),
  content text not null check (char_length(content) between 1 and 20000),
  -- Scripture the answer cited, as verified references ["John 3:16", …].
  citations jsonb not null default '[]'::jsonb check (jsonb_typeof(citations) = 'array'),
  created_at timestamptz not null default now()
);
create index bible_ai_messages_thread_idx on public.bible_ai_messages (user_id, thread_id, created_at);

create table public.bible_ai_usage (
  id bigint generated always as identity primary key,
  user_id uuid not null references auth.users (id) on delete cascade,
  created_at timestamptz not null default now(),
  model text check (char_length(model) <= 80),
  input_tokens integer check (input_tokens >= 0),
  output_tokens integer check (output_tokens >= 0),
  status text not null default 'reserved' check (status in ('reserved', 'done', 'failed'))
);
create index bible_ai_usage_user_idx on public.bible_ai_usage (user_id, created_at desc);

-- Reserve one Bible-study question atomically: per-minute, per-day and per-month limits (passed by the server from
-- its configuration). Raises bible_ai_rate_limited / bible_ai_quota. Service role only.
create or replace function public.reserve_bible_ai_usage(p_user_id uuid, p_per_minute integer, p_daily integer, p_monthly integer)
returns bigint
language plpgsql
security definer
set search_path = public
as $$
declare
  v_id bigint;
begin
  perform pg_advisory_xact_lock(hashtextextended('bible_ai:' || p_user_id::text, 0));
  if (select count(*) from public.bible_ai_usage u where u.user_id = p_user_id and u.status <> 'failed' and u.created_at >= now() - interval '60 seconds') >= p_per_minute then
    raise exception 'bible_ai_rate_limited' using errcode = 'P0001';
  end if;
  if (select count(*) from public.bible_ai_usage u where u.user_id = p_user_id and u.status <> 'failed' and u.created_at >= now() - interval '24 hours') >= p_daily then
    raise exception 'bible_ai_quota' using errcode = 'P0001';
  end if;
  if (select count(*) from public.bible_ai_usage u where u.user_id = p_user_id and u.status <> 'failed' and u.created_at >= date_trunc('month', now())) >= p_monthly then
    raise exception 'bible_ai_quota' using errcode = 'P0001';
  end if;
  return v_id;
end;
$$;
revoke execute on function public.reserve_bible_ai_usage(uuid, integer, integer, integer) from public, anon, authenticated;
grant execute on function public.reserve_bible_ai_usage(uuid, integer, integer, integer) to service_role;

-- ---------------------------------------------------------------------------------------------------------------
-- Daily Faith challenge and Fitness goal (optional; never part of the journey rule)
-- ---------------------------------------------------------------------------------------------------------------

create table public.faith_daily_goals (
  user_id uuid not null references auth.users (id) on delete cascade,
  goal_date date not null,
  kind text not null check (kind in ('faith_challenge', 'fitness')),
  completed_at timestamptz not null default now(),
  note text check (char_length(note) <= 1000),
  primary key (user_id, goal_date, kind),
  -- A day near today (time zones differ by at most ~a day); the server action checks the member's own date.
  check (goal_date between (completed_at at time zone 'UTC')::date - 2 and (completed_at at time zone 'UTC')::date + 1)
);

-- ---------------------------------------------------------------------------------------------------------------
-- Reading journeys: enrolment, attempts, daily check-ins
-- ---------------------------------------------------------------------------------------------------------------

create table public.faith_journeys (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users (id) on delete cascade,
  plan_kind text not null check (plan_kind in ('guided', 'gospels', 'new_testament', 'old_testament', 'chronological', 'full_bible', 'book', 'topic')),
  -- The book (BSB book id) for 'book', the topic slug for 'topic'.
  plan_param text check (char_length(plan_param) between 1 and 40),
  duration_days smallint not null check (duration_days in (30, 60, 90, 180, 365)),
  -- The member's chosen first day (never in the past when enrolling).
  start_on date not null,
  status text not null default 'active' check (status in ('active', 'completed', 'ended')),
  created_at timestamptz not null default now(),
  ended_at timestamptz,
  check ((plan_kind in ('book', 'topic')) = (plan_param is not null)),
  check (plan_kind <> 'book' or public.bible_chapter_count(plan_param) is not null),
  check ((status = 'active') = (ended_at is null))
);
create unique index faith_journeys_one_active_idx on public.faith_journeys (user_id) where status = 'active';
create index faith_journeys_user_idx on public.faith_journeys (user_id, created_at desc);

create table public.faith_journey_attempts (
  id uuid primary key default gen_random_uuid(),
  journey_id uuid not null references public.faith_journeys (id) on delete cascade,
  user_id uuid not null references auth.users (id) on delete cascade,
  attempt_number integer not null check (attempt_number >= 1),
  -- Day 1 of this attempt (the member's local date).
  started_on date not null,
  status text not null default 'active' check (status in ('active', 'interrupted', 'completed', 'ended')),
  -- The day that wasn't completed, and what was missing on it.
  interrupted_on date,
  interruption_reason text check (interruption_reason in ('reading', 'prayer', 'both')),
  days_completed integer not null default 0 check (days_completed >= 0),
  created_at timestamptz not null default now(),
  ended_at timestamptz,
  unique (journey_id, attempt_number),
  check ((status = 'interrupted') = (interrupted_on is not null and interruption_reason is not null)),
  check ((status = 'active') = (ended_at is null))
);
create unique index faith_journey_attempts_one_active_idx on public.faith_journey_attempts (journey_id) where status = 'active';
create index faith_journey_attempts_user_idx on public.faith_journey_attempts (user_id, created_at desc);

-- One row per journey and calendar day (the member's local date) holding that day's two required activities.
create table public.faith_journey_checkins (
  journey_id uuid not null references public.faith_journeys (id) on delete cascade,
  user_id uuid not null references auth.users (id) on delete cascade,
  check_date date not null,
  -- The schedule day whose reading was marked complete (a reading counts only for its own day).
  reading_day smallint check (reading_day between 1 and 365),
  reading_completed_at timestamptz,
  reading_source text check (reading_source in ('online', 'offline')),
  prayer_completed_at timestamptz,
  prayer_source text check (prayer_source in ('online', 'offline')),
  updated_at timestamptz not null default now(),
  primary key (journey_id, check_date),
  check ((reading_completed_at is null) = (reading_day is null))
);
create index faith_journey_checkins_user_idx on public.faith_journey_checkins (user_id, check_date desc);

-- How long after local midnight a check-in made offline before midnight may still count for the previous day.
-- The member's deadline is midnight; this only lets a device that was offline deliver what it recorded in time.
create or replace function public.faith_offline_grace()
returns interval
language sql
immutable
as $$ select interval '3 hours' $$;

/**
 * Apply the daily rule to one journey as of p_now, idempotently:
 *   - days up to "settle_through" are final: yesterday becomes final 3 hours after local midnight (offline grace), or at
 *     once when p_force_through says so (a check-in for the new day proves the member is online);
 *   - the first final day of the active attempt without BOTH the day's reading (for that schedule day) and prayer
 *     interrupts the attempt (date + reason recorded) and starts a new attempt at Day 1 on the next day;
 *   - a new attempt that has no completed day yet simply moves its Day 1 forward instead of piling up empty attempts;
 *   - nothing is ever deleted.
 * Concurrent callers (several devices, the scheduled job) serialize on the journey row.
 */
create or replace function public.faith_journey_settle_at(p_journey_id uuid, p_now timestamptz, p_force_through date default null)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  j public.faith_journeys%rowtype;
  a public.faith_journey_attempts%rowtype;
  v_tz text;
  v_through date;
  v_last_day date;
  v_miss date;
  v_row public.faith_journey_checkins%rowtype;
  v_reason text;
  v_guard integer := 0;
begin
  select * into j from public.faith_journeys where id = p_journey_id for update;
  if not found or j.status <> 'active' then
    return;
  end if;
  select public.faith_safe_tz(p.timezone) into v_tz from public.profiles p where p.id = j.user_id;
  v_tz := coalesce(v_tz, 'UTC');
  v_through := ((p_now at time zone v_tz) - public.faith_offline_grace())::date - 1;
  if p_force_through is not null and p_force_through > v_through then
    v_through := least(p_force_through, (p_now at time zone v_tz)::date - 1);
  end if;

  loop
    v_guard := v_guard + 1;
    exit when v_guard > 1000;
    select * into a from public.faith_journey_attempts where journey_id = j.id and status = 'active' for update;
    if not found then
        values (j.id, j.user_id, coalesce((select max(attempt_number) from public.faith_journey_attempts where journey_id = j.id), 0) + 1, j.start_on)
        returning * into a;
    end if;
    exit when a.started_on > v_through;

    v_last_day := least(v_through, a.started_on + j.duration_days - 1);
    -- The first final day of this attempt that isn't complete.
    select d::date into v_miss
      from generate_series(a.started_on, v_last_day, interval '1 day') d
      where not exists (
        select 1 from public.faith_journey_checkins c
        where c.journey_id = j.id and c.check_date = d::date
          and c.prayer_completed_at is not null
          and c.reading_completed_at is not null
          and c.reading_day = (d::date - a.started_on + 1)
      )
      order by d
      limit 1;

    if v_miss is null then
      -- Every final day so far is complete. Finished the whole schedule?
      if a.started_on + j.duration_days - 1 <= v_through then
        update public.faith_journey_attempts set status = 'completed', days_completed = j.duration_days, ended_at = p_now where id = a.id;
        update public.faith_journeys set status = 'completed', ended_at = p_now where id = j.id;
      end if;
      exit;
    end if;

    if v_miss = a.started_on and a.attempt_number > 1 and a.days_completed = 0
       and not exists (select 1 from public.faith_journey_checkins c where c.journey_id = j.id and c.check_date = v_miss) then
      -- A restarted attempt whose Day 1 passed untouched: move Day 1 forward rather than recording another attempt.
      update public.faith_journey_attempts set started_on = v_miss + 1 where id = a.id;
      continue;
    end if;

    select * into v_row from public.faith_journey_checkins c where c.journey_id = j.id and c.check_date = v_miss;
    v_reason := case
      when v_row.prayer_completed_at is not null then 'reading'
      when v_row.reading_completed_at is not null and v_row.reading_day = (v_miss - a.started_on + 1) then 'prayer'
      else 'both'
    end;
    update public.faith_journey_attempts
      set status = 'interrupted', interrupted_on = v_miss, interruption_reason = v_reason,
          days_completed = v_miss - a.started_on, ended_at = p_now
      where id = a.id;
      values (j.id, j.user_id, a.attempt_number + 1, v_miss + 1);
  end loop;
end;
$$;
revoke execute on function public.faith_journey_settle_at(uuid, timestamptz, date) from public, anon, authenticated;
grant execute on function public.faith_journey_settle_at(uuid, timestamptz, date) to service_role;

-- Settle every active journey (the scheduled job). Returns how many were looked at.
create or replace function public.faith_journeys_settle_due(p_now timestamptz default now())
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare
  r record;
  n integer := 0;
begin
  for r in select id from public.faith_journeys where status = 'active' loop
    perform public.faith_journey_settle_at(r.id, p_now);
    n := n + 1;
  end loop;
  return n;
end;
$$;
revoke execute on function public.faith_journeys_settle_due(timestamptz) from public, anon, authenticated;
grant execute on function public.faith_journeys_settle_due(timestamptz) to service_role;

/**
 * Record one of the day's two required activities ('reading' or 'prayer') for p_user as of p_now.
 * p_occurred_at: when the member tapped it, for a check-in a device saved while offline. It may count for the
 * previous local day only if it happened on that day and arrives within the offline grace after midnight, and only
 * while that day isn't final yet; otherwise it's refused (never silently moved to another day).
 * Duplicate check-ins are harmless (the first time is kept). Returns the day's state.
 */
create or replace function public.faith_journey_check_in_at(p_user uuid, p_activity text, p_now timestamptz, p_occurred_at timestamptz default null)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  j public.faith_journeys%rowtype;
  a public.faith_journey_attempts%rowtype;
  v_tz text;
  v_today date;
  v_date date;
  v_source text := 'online';
  v_at timestamptz := p_now;
  v_day integer;
  v_row public.faith_journey_checkins%rowtype;
begin
  if p_activity not in ('reading', 'prayer') then
    raise exception 'faith_invalid_activity' using errcode = 'P0001';
  end if;
  select * into j from public.faith_journeys where user_id = p_user and status = 'active';
  if not found then
    raise exception 'faith_no_journey' using errcode = 'P0001';
  end if;
  select public.faith_safe_tz(p.timezone) into v_tz from public.profiles p where p.id = p_user;
  v_tz := coalesce(v_tz, 'UTC');
  v_today := (p_now at time zone v_tz)::date;
  v_date := v_today;

  if p_occurred_at is not null and p_occurred_at < p_now - interval '2 minutes' then
    if p_occurred_at > p_now then
      raise exception 'faith_invalid_time' using errcode = 'P0001';
    end if;
    v_date := (p_occurred_at at time zone v_tz)::date;
    v_source := 'offline';
    v_at := p_occurred_at;
    if v_date = v_today then
      null;
    elsif v_date = v_today - 1 and (p_now at time zone v_tz) < (v_today::timestamp + public.faith_offline_grace()) then
      null;
    else
      raise exception 'faith_offline_too_late' using errcode = 'P0001';
    end if;
  end if;

  -- A check-in for today proves the member is online: yesterday is final now. One for yesterday settles nothing new.
  perform public.faith_journey_settle_at(j.id, p_now, case when v_date = v_today then v_today - 1 end);
  select * into j from public.faith_journeys where id = j.id;
  if j.status <> 'active' then
    raise exception 'faith_no_journey' using errcode = 'P0001';
  end if;
  select * into a from public.faith_journey_attempts where journey_id = j.id and status = 'active';
  if v_date < a.started_on then
    -- Before the journey starts, or a day of an attempt that has already been interrupted.
    raise exception 'faith_day_closed' using errcode = 'P0001';
  end if;
  v_day := v_date - a.started_on + 1;
  if v_day > j.duration_days then
    raise exception 'faith_day_closed' using errcode = 'P0001';
  end if;

    values (
      j.id, p_user, v_date,
      case when p_activity = 'reading' then v_day end,
      case when p_activity = 'reading' then v_at end,
      case when p_activity = 'reading' then v_source end,
      case when p_activity = 'prayer' then v_at end,
      case when p_activity = 'prayer' then v_source end
    )
    on conflict (journey_id, check_date) do update set
      reading_day = case when p_activity = 'reading' and (c.reading_completed_at is null or c.reading_day <> v_day) then v_day else c.reading_day end,
      reading_completed_at = case when p_activity = 'reading' and (c.reading_completed_at is null or c.reading_day <> v_day) then v_at else c.reading_completed_at end,
      reading_source = case when p_activity = 'reading' and (c.reading_completed_at is null or c.reading_day <> v_day) then v_source else c.reading_source end,
      prayer_completed_at = case when p_activity = 'prayer' and c.prayer_completed_at is null then v_at else c.prayer_completed_at end,
      prayer_source = case when p_activity = 'prayer' and c.prayer_completed_at is null then v_source else c.prayer_source end,
      updated_at = now()
    returning * into v_row;

  -- The last day of the schedule, completed: the journey is finished.
  if v_day = j.duration_days and v_row.prayer_completed_at is not null and v_row.reading_day = v_day then
    perform public.faith_journey_settle_at(j.id, p_now, v_date + 1);
    -- settle_at only finalizes days before today; finish explicitly when the last day is today.
    update public.faith_journey_attempts set status = 'completed', days_completed = j.duration_days, ended_at = p_now
      where id = a.id and status = 'active';
    update public.faith_journeys set status = 'completed', ended_at = p_now where id = j.id and status = 'active';
  end if;

  return jsonb_build_object(
    'date', v_date, 'day', v_day, 'source', v_source,
    'reading', v_row.reading_completed_at is not null and v_row.reading_day = v_day,
    'prayer', v_row.prayer_completed_at is not null
  );
end;
$$;
revoke execute on function public.faith_journey_check_in_at(uuid, text, timestamptz, timestamptz) from public, anon, authenticated;
grant execute on function public.faith_journey_check_in_at(uuid, text, timestamptz, timestamptz) to service_role;

-- The member-facing check-in: their own account, the server's clock.
create or replace function public.faith_journey_check_in(p_activity text, p_occurred_at timestamptz default null)
returns jsonb
language sql
security definer
set search_path = public
as $$
  select public.faith_journey_check_in_at((select auth.uid()), p_activity, now(), p_occurred_at);
$$;
revoke execute on function public.faith_journey_check_in(text, timestamptz) from public, anon;
grant execute on function public.faith_journey_check_in(text, timestamptz) to authenticated;

-- Undo a mistaken tap, today only (a day that is already final can't be changed).
create or replace function public.faith_journey_undo(p_activity text)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_user uuid := (select auth.uid());
  j public.faith_journeys%rowtype;
  v_today date;
begin
  select * into j from public.faith_journeys where user_id = v_user and status = 'active';
  if not found then
    return;
  end if;
  select ((now() at time zone public.faith_safe_tz(p.timezone)))::date into v_today from public.profiles p where p.id = v_user;
  if p_activity = 'reading' then
    update public.faith_journey_checkins set reading_day = null, reading_completed_at = null, reading_source = null, updated_at = now()
      where journey_id = j.id and check_date = v_today;
  elsif p_activity = 'prayer' then
    update public.faith_journey_checkins set prayer_completed_at = null, prayer_source = null, updated_at = now()
      where journey_id = j.id and check_date = v_today;
  end if;
end;
$$;
revoke execute on function public.faith_journey_undo(text) from public, anon;
grant execute on function public.faith_journey_undo(text) to authenticated;

-- Settle the caller's own journey now (every Faith page load calls this, in addition to the scheduled job).
create or replace function public.faith_journey_settle_mine()
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_id uuid;
begin
  select id into v_id from public.faith_journeys where user_id = (select auth.uid()) and status = 'active';
  if v_id is not null then
    perform public.faith_journey_settle_at(v_id, now());
  end if;
end;
$$;
revoke execute on function public.faith_journey_settle_mine() from public, anon;
grant execute on function public.faith_journey_settle_mine() to authenticated;

/**
 * Start a journey (ending the current one, whose history is kept). p_start_on: today or up to 30 days ahead in the
 * member's time zone. The plan's feasibility (enough Scripture for the duration) is checked by the server action
 * before this is called; here the kind, duration and dates are enforced.
 */
create or replace function public.faith_journey_enroll(p_kind text, p_param text, p_duration integer, p_start_on date)
returns uuid
language plpgsql
security definer
set search_path = public
as $$
declare
  v_user uuid := (select auth.uid());
  v_today date;
  v_id uuid;
begin
  if v_user is null then
    raise exception 'not_authenticated' using errcode = '42501';
  end if;
  select ((now() at time zone public.faith_safe_tz(p.timezone)))::date into v_today from public.profiles p where p.id = v_user;
  if p_start_on is null or p_start_on < v_today or p_start_on > v_today + 30 then
    raise exception 'faith_invalid_start' using errcode = 'P0001';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('faith_journey:' || v_user::text, 0));
  update public.faith_journey_attempts set status = 'ended', ended_at = now()
    where user_id = v_user and status = 'active';
  update public.faith_journeys set status = 'ended', ended_at = now() where user_id = v_user and status = 'active';
    values (v_user, p_kind, nullif(p_param, ''), p_duration, p_start_on)
    returning id into v_id;
  return v_id;
end;
$$;
revoke execute on function public.faith_journey_enroll(text, text, integer, date) from public, anon;
grant execute on function public.faith_journey_enroll(text, text, integer, date) to authenticated;

-- End the active journey (history kept).
create or replace function public.faith_journey_end()
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_user uuid := (select auth.uid());
begin
  update public.faith_journey_attempts set status = 'ended', ended_at = now() where user_id = v_user and status = 'active';
  update public.faith_journeys set status = 'ended', ended_at = now() where user_id = v_user and status = 'active';
end;
$$;
revoke execute on function public.faith_journey_end() from public, anon;
grant execute on function public.faith_journey_end() to authenticated;

-- ---------------------------------------------------------------------------------------------------------------
-- Existing tables, extended (no data changed)
-- ---------------------------------------------------------------------------------------------------------------

-- Prayer journal: more kinds of prayer, and archiving.
alter table public.faith_journal_entries drop constraint if exists faith_journal_entries_kind_check;
alter table public.faith_journal_entries
  add constraint faith_journal_entries_kind_check check (kind in ('reflection', 'request', 'praise', 'intercession', 'confession', 'daily')),
  add column archived_at timestamptz;
create index faith_journal_user_archived_idx on public.faith_journal_entries (user_id, archived_at, entry_date desc);

-- Reminders: Bible reading, Faith challenge, Fitness goal, the accountability reminders and memorization reviews.
alter table public.faith_reminders drop constraint if exists faith_reminders_kind_check;
alter table public.faith_reminders
  add constraint faith_reminders_kind_check check (kind in ('devotional', 'prayer', 'practices', 'reading', 'challenge', 'fitness', 'accountability', 'final', 'memorize'));

create table public.faith_reminder_prefs (
  user_id uuid primary key references auth.users (id) on delete cascade,
  -- No reminder is scheduled between these times (local). Null: no quiet hours.
  quiet_start time,
  quiet_end time,
  updated_at timestamptz not null default now(),
  check ((quiet_start is null) = (quiet_end is null))
);
create trigger faith_reminder_prefs_updated_at before update on public.faith_reminder_prefs for each row execute function public.set_updated_at();

-- ---------------------------------------------------------------------------------------------------------------
-- Row Level Security: owner-only
-- ---------------------------------------------------------------------------------------------------------------

-- Row level security on every new table (stated one by one so static checks can see it; the policies follow).
alter table public.bible_reading_state enable row level security;
alter table public.bible_reading_history enable row level security;
alter table public.bible_highlights enable row level security;
alter table public.bible_bookmarks enable row level security;
alter table public.bible_notes enable row level security;
alter table public.scripture_memory enable row level security;
alter table public.bible_study_progress enable row level security;
alter table public.faith_daily_goals enable row level security;
alter table public.faith_reminder_prefs enable row level security;
alter table public.faith_journeys enable row level security;
alter table public.faith_journey_attempts enable row level security;
alter table public.faith_journey_checkins enable row level security;
alter table public.bible_ai_usage enable row level security;

do $$
declare
  t text;
begin
  -- Members read and write their own rows.
  foreach t in array array['bible_reading_state', 'bible_reading_history', 'bible_highlights', 'bible_bookmarks', 'bible_notes',
                           'scripture_memory', 'bible_study_progress', 'faith_daily_goals', 'faith_reminder_prefs'] loop
    execute format('alter table public.%I enable row level security', t);
    execute format('create policy %I on public.%I for select to authenticated using (user_id = (select auth.uid()))', t || '_select_own', t);
    execute format('create policy %I on public.%I for insert to authenticated with check (user_id = (select auth.uid()))', t || '_insert_own', t);
    execute format('create policy %I on public.%I for update to authenticated using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()))', t || '_update_own', t);
    execute format('create policy %I on public.%I for delete to authenticated using (user_id = (select auth.uid()))', t || '_delete_own', t);
  end loop;
  -- Read-only to the member: progress and usage are written only by the functions above / the server.
  foreach t in array array['faith_journeys', 'faith_journey_attempts', 'faith_journey_checkins', 'bible_ai_usage'] loop
    execute format('alter table public.%I enable row level security', t);
    execute format('create policy %I on public.%I for select to authenticated using (user_id = (select auth.uid()))', t || '_select_own', t);
  end loop;
  -- AI Bible study history: the member reads and deletes their own; the server writes it.
  alter table public.bible_ai_messages enable row level security;
  create policy bible_ai_messages_select_own on public.bible_ai_messages for select to authenticated using (user_id = (select auth.uid()));
  create policy bible_ai_messages_delete_own on public.bible_ai_messages for delete to authenticated using (user_id = (select auth.uid()));
end;
$$;

revoke insert, update, delete on public.faith_journeys, public.faith_journey_attempts, public.faith_journey_checkins, public.bible_ai_usage, public.bible_ai_messages from anon, authenticated;
grant delete on public.bible_ai_messages to authenticated;

-- ---------------------------------------------------------------------------------------------------------------
-- Scheduled settlement: every 15 minutes, so a missed day resets even if the member never opens the app.
-- (Page loads and check-ins also settle, so the rule holds even where pg_cron isn't available.)
-- ---------------------------------------------------------------------------------------------------------------

do $$
begin
  create extension if not exists pg_cron;
  perform cron.schedule('faith-journeys-settle', '*/15 * * * *', 'select public.faith_journeys_settle_due()');
exception when others then
  raise notice 'pg_cron is not available here (%); journeys settle on page load and check-in only.', sqlerrm;
end;
$$;

comment on table public.faith_journeys is 'Bible reading journeys (plan, duration, chosen start). Owner-readable; written only by faith_journey_* functions.';
comment on table public.faith_journey_attempts is 'Each attempt at a journey: interrupted attempts keep the missed date and what was missing. Never deleted by a reset.';
comment on table public.faith_journey_checkins is 'The two required daily activities (reading for that schedule day, prayer) per local calendar day.';

-- ===== supabase/migrations/20261103000054_bible_display_prefs.sql =====
-- Bible reader display preferences (Faith is free: no plan check anywhere).
--   bible_red_letters : show the words of Jesus in red (default on). Display only; the text is never changed.
--   bible_page_theme  : the reading page in the Bible reader, dark (default) or light.
alter table public.profiles
  add column if not exists bible_red_letters boolean not null default true,
  add column if not exists bible_page_theme text not null default 'dark' check (bible_page_theme in ('dark', 'light'));

-- Self-editable like the other display preferences (column-level grants; row access stays owner-only by RLS).
grant update (bible_red_letters, bible_page_theme) on public.profiles to authenticated;

-- ===== supabase/migrations/20261103000055_notifications.sql =====
-- ---------------------------------------------------------------------------------------------------------------
-- Smart reminders (Profile → Notifications). Account-level settings for the workout, food and recovery reminders
-- (the Faith ones stay in faith_reminders), shared preferences for every reminder (pause all, quiet hours, a daily
-- limit), and the member's phones, so a choice made on one device follows them and duplicates can be avoided.
-- Everything is off by default; nothing here sends anything: the iPhone / Android app schedules local notifications.
-- Owner-only. No marketing or promotional notification type exists.
-- ---------------------------------------------------------------------------------------------------------------

-- Two more optional Faith reminders: reading-plan progress and prayer follow-up (weekly).
alter table public.faith_reminders drop constraint if exists faith_reminders_kind_check;
alter table public.faith_reminders
  add constraint faith_reminders_kind_check check (kind in ('devotional', 'prayer', 'practices', 'reading', 'challenge', 'fitness',
                                                           'accountability', 'final', 'memorize', 'plan_progress', 'prayer_followup'));

create table public.notification_reminders (
  user_id uuid not null references auth.users (id) on delete cascade,
  kind text not null check (kind in ('workout', 'plan_week', 'weekly_review', 'breakfast', 'lunch', 'dinner', 'snack', 'water',
                                     'recovery', 'winddown')),
  enabled boolean not null default false,
  remind_at time not null default '07:00',
  -- JavaScript weekdays: 0 = Sunday … 6 = Saturday.
  weekdays smallint[] not null default '{0,1,2,3,4,5,6}'
    check (cardinality(weekdays) <= 7 and weekdays <@ array[0, 1, 2, 3, 4, 5, 6]::smallint[]),
  -- Water only: every so many minutes until end_at.
  interval_minutes smallint check (interval_minutes in (60, 90, 120, 180, 240)),
  end_at time,
  -- Workout only: the message style.
  style text not null default 'friendly' check (style in ('friendly', 'faith')),
  updated_at timestamptz not null default now(),
  primary key (user_id, kind),
  check (kind = 'water' or (interval_minutes is null and end_at is null)),
  check (kind <> 'water' or end_at is null or end_at > remind_at)
);
create trigger notification_reminders_updated_at before update on public.notification_reminders
  for each row execute function public.set_updated_at();

create table public.notification_prefs (
  user_id uuid primary key references auth.users (id) on delete cascade,
  -- "Pause all optional reminders": choices are kept, nothing is scheduled.
  paused boolean not null default false,
  -- No reminder of any kind is scheduled between these local times. Null: no quiet hours.
  quiet_start time,
  quiet_end time,
  -- The most optional reminders on any one day.
  daily_limit smallint not null default 8 check (daily_limit between 1 and 20),
  updated_at timestamptz not null default now(),
  check ((quiet_start is null) = (quiet_end is null))
);
create trigger notification_prefs_updated_at before update on public.notification_prefs
  for each row execute function public.set_updated_at();

-- Quiet hours chosen for Faith reminders now apply to every reminder: carry them over.
select user_id, quiet_start, quiet_end from public.faith_reminder_prefs where quiet_start is not null
on conflict (user_id) do nothing;

create table public.notification_devices (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users (id) on delete cascade,
  -- A random id the app keeps on the phone (not a hardware identifier).
  device_key text not null check (device_key ~ '^[A-Za-z0-9-]{16,64}$'),
  platform text not null check (platform in ('ios', 'android')),
  label text not null check (char_length(label) between 1 and 60),
  -- Whether this phone shows the member's reminders (turn one off to avoid duplicates on two phones).
  delivers boolean not null default true,
  timezone text check (char_length(timezone) <= 64),
  permission text not null default 'unknown' check (permission in ('granted', 'denied', 'prompt', 'unknown')),
  last_sync_at timestamptz not null default now(),
  created_at timestamptz not null default now(),
  unique (user_id, device_key)
);
create index notification_devices_user_idx on public.notification_devices (user_id, last_sync_at desc);

alter table public.notification_reminders enable row level security;
alter table public.notification_prefs enable row level security;
alter table public.notification_devices enable row level security;

do $$
declare
  t text;
begin
  foreach t in array array['notification_reminders', 'notification_prefs', 'notification_devices'] loop
    execute format('create policy %I on public.%I for select to authenticated using (user_id = (select auth.uid()))', t || '_select_own', t);
    execute format('create policy %I on public.%I for insert to authenticated with check (user_id = (select auth.uid()))', t || '_insert_own', t);
    execute format('create policy %I on public.%I for update to authenticated using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()))', t || '_update_own', t);
    execute format('create policy %I on public.%I for delete to authenticated using (user_id = (select auth.uid()))', t || '_delete_own', t);
  end loop;
end $$;

-- At most 10 phones per member: the oldest is forgotten when an 11th checks in.
create or replace function public.notification_devices_limit() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  delete from public.notification_devices
  where user_id = new.user_id
    and id in (select id from public.notification_devices where user_id = new.user_id order by last_sync_at desc offset 10);
  return null;
end $$;
revoke all on function public.notification_devices_limit() from public, anon, authenticated;
create trigger notification_devices_limit after insert on public.notification_devices
  for each row execute function public.notification_devices_limit();

comment on table public.notification_reminders is 'Optional workout, food, water and recovery reminder settings (off by default). Owner-only.';
comment on table public.notification_prefs is 'Reminder preferences for every reminder: pause all, quiet hours, daily limit. Owner-only.';
comment on table public.notification_devices is 'The member''s phones that schedule reminders, and whether each one shows them. Owner-only.';
comment on table public.faith_reminder_prefs is 'Superseded by notification_prefs (quiet hours now apply to every reminder); kept, not read.';

-- ===== supabase/migrations/20261103000056_activation_report_exclusions.sql =====
-- ---------------------------------------------------------------------------------------------------------------
-- First-workout activation report: count real members only. Until now every new profile was in the cohort, so App
-- Review / TestFlight sandbox testers (migration 052), admins, demo accounts and automated-test accounts
-- (@example.com and similar reserved test domains) would have inflated or skewed the figures once testing starts on the
-- production project. They are now left out by default (p_include_test = true includes them), and the report says how
-- many were left out. Events are still recorded for everyone; only the report changes.
-- ---------------------------------------------------------------------------------------------------------------

create or replace function public.activation_is_test_account(p_user uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (select 1 from public.sandbox_testers t where t.user_id = p_user)
      or exists (select 1 from public.profiles p where p.id = p_user and p.role = 'admin')
      or exists (
        select 1 from auth.users u
        where u.id = p_user
          and (coalesce((u.raw_app_meta_data ->> 'demo')::boolean, false)
               or lower(u.email) ~ '@(example\.(com|org|net)|[a-z0-9.-]+\.(test|example|invalid|localhost))$')
      );
$$;
revoke all on function public.activation_is_test_account(uuid) from public, anon, authenticated;

drop function if exists public.admin_activation_metrics(timestamptz, timestamptz);

create function public.admin_activation_metrics(
  p_from timestamptz default now() - interval '30 days',
  p_to timestamptz default now(),
  p_include_test boolean default false
)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  result jsonb;
begin
  if not public.is_admin() then
    raise exception 'Not authorized' using errcode = '42501';
  end if;
  with signups as (
    select p.id, p.created_at, p.onboarding_completed_at, coalesce(nullif(p.timezone, ''), 'UTC') as tz,
      public.activation_is_test_account(p.id) as is_test
    from public.profiles p
    where p.created_at >= p_from and p.created_at < p_to
  ),
  cohort as (
    select id, created_at, onboarding_completed_at, tz from signups where p_include_test or not is_test
  ),
  firsts as (
    select c.*,
      (select min(e.occurred_at) from public.activation_events e where e.user_id = c.id and e.event = 'workout_started') as first_start,
      (select min(e.occurred_at) from public.activation_events e where e.user_id = c.id and e.event = 'set_completed') as first_set,
      (select min(e.occurred_at) from public.activation_events e where e.user_id = c.id and e.event = 'workout_completed') as first_done
    from cohort c
  ),
  first_workout as (
    select f.id,
      (select e.workout_client_id from public.activation_events e where e.user_id = f.id and e.event = 'workout_started' order by e.occurred_at, e.id limit 1) as client_id
    from firsts f
  ),
  -- Days (0 = the sign-up day) on which the member started or finished a workout.
  active_days as (
    select distinct c.id, ((e.occurred_at at time zone c.tz)::date - (c.created_at at time zone c.tz)::date) as day
    from cohort c join public.activation_events e on e.user_id = c.id and e.event in ('workout_started', 'workout_completed')
  ),
  cohort_days as (
    select c.id, ((now() at time zone c.tz)::date - (c.created_at at time zone c.tz)::date) as age_days from cohort c
  ),
  cohort_workouts as (
    select e.workout_client_id, e.user_id from public.activation_events e join cohort c on c.id = e.user_id where e.event = 'workout_started'
  ),
  stale as (
    -- Still "in progress" but untouched for a day: left, not finished (and not yet discarded).
    select s.user_id, s.client_id from public.workout_sessions s join cohort c on c.id = s.user_id
    where s.status = 'in_progress' and s.updated_at < now() - interval '24 hours'
  )
  select jsonb_build_object(
    'window', jsonb_build_object('from', p_from, 'to', p_to),
    -- Accounts left out of every figure (testers, admins, demo and test addresses); 0 when p_include_test.
    'excluded_test_accounts', (select count(*) from signups where is_test and not p_include_test),
    'new_members', jsonb_build_object(
      'accounts', (select count(*) from cohort),
      'onboarded', (select count(*) from cohort where onboarding_completed_at is not null),
      'started_first_workout', (select count(first_start) from firsts),
      'completed_first_set', (select count(first_set) from firsts),
      'completed_first_workout', (select count(first_done) from firsts)
    ),
    'median_minutes', jsonb_build_object(
      'signup_to_onboarded', (select round((percentile_cont(0.5) within group (order by extract(epoch from onboarding_completed_at - created_at) / 60))::numeric, 1) from firsts where onboarding_completed_at is not null),
      'onboarded_to_first_workout_start', (select round((percentile_cont(0.5) within group (order by extract(epoch from first_start - onboarding_completed_at) / 60))::numeric, 1) from firsts where first_start is not null and onboarding_completed_at is not null),
      'first_workout_start_to_first_set', (select round((percentile_cont(0.5) within group (order by extract(epoch from first_set - first_start) / 60))::numeric, 1) from firsts where first_set is not null and first_start is not null),
      'signup_to_first_set', (select round((percentile_cont(0.5) within group (order by extract(epoch from first_set - created_at) / 60))::numeric, 1) from firsts where first_set is not null),
      'signup_to_first_workout_completed', (select round((percentile_cont(0.5) within group (order by extract(epoch from first_done - created_at) / 60))::numeric, 1) from firsts where first_done is not null)
    ),
    -- Returned on day N: trained on that calendar day. Only members whose day N is over are counted ("eligible").
    'return_activity', jsonb_build_object(
      'day1', jsonb_build_object('eligible', (select count(*) from cohort_days where age_days > 1), 'returned', (select count(*) from cohort_days d where d.age_days > 1 and exists (select 1 from active_days a where a.id = d.id and a.day = 1))),
      'day7', jsonb_build_object('eligible', (select count(*) from cohort_days where age_days > 7), 'returned', (select count(*) from cohort_days d where d.age_days > 7 and exists (select 1 from active_days a where a.id = d.id and a.day = 7))),
      'day14', jsonb_build_object('eligible', (select count(*) from cohort_days where age_days > 14), 'returned', (select count(*) from cohort_days d where d.age_days > 14 and exists (select 1 from active_days a where a.id = d.id and a.day = 14))),
      'days1to7', jsonb_build_object('eligible', (select count(*) from cohort_days where age_days > 7), 'returned', (select count(*) from cohort_days d where d.age_days > 7 and exists (select 1 from active_days a where a.id = d.id and a.day between 1 and 7)))
    ),
    'abandonment', jsonb_build_object(
      'workouts_started', (select count(*) from cohort_workouts),
      'discarded', (select count(*) from public.activation_events e join cohort c on c.id = e.user_id where e.event = 'workout_abandoned'),
      'left_in_progress_24h', (select count(*) from stale),
      'first_workout_abandoned', (select count(*) from first_workout fw where fw.client_id is not null and (
        exists (select 1 from public.activation_events e where e.user_id = fw.id and e.workout_client_id = fw.client_id and e.event = 'workout_abandoned')
        or exists (select 1 from stale s where s.user_id = fw.id and s.client_id = fw.client_id)))
    ),
    'returning_members', jsonb_build_object(
      'trained_in_window', (select count(distinct e.user_id) from public.activation_events e join public.profiles p on p.id = e.user_id
        where p.created_at < p_from and e.event = 'workout_completed' and e.occurred_at >= p_from and e.occurred_at < p_to
          and (p_include_test or not public.activation_is_test_account(p.id))),
      'workouts_completed', (select count(*) from public.activation_events e join public.profiles p on p.id = e.user_id
        where p.created_at < p_from and e.event = 'workout_completed' and e.occurred_at >= p_from and e.occurred_at < p_to
          and (p_include_test or not public.activation_is_test_account(p.id)))
    )
  ) into result;
  return result;
end;
$$;
revoke execute on function public.admin_activation_metrics(timestamptz, timestamptz, boolean) from anon, public;
grant execute on function public.admin_activation_metrics(timestamptz, timestamptz, boolean) to authenticated;

-- ===== supabase/migrations/20261106000057_layout_prefs.sql =====
-- Dashboard layout preferences: which Home modules a member hides or reorders, and which Faith sections they hide.
-- One nullable JSON column (null = the app's default order for the member's goal and experience). Additive and
-- reversible: rolling back is `alter table public.profiles drop column layout_prefs;` and nothing else reads it.
-- Shape (validated by the app, src/lib/layout-prefs.ts):
--   { "home": { "order": ["workout", "nutrition", ...], "hidden": ["sleep"] }, "faith": { "hidden": ["themes"] } }
alter table public.profiles
  add column if not exists layout_prefs jsonb check (layout_prefs is null or jsonb_typeof(layout_prefs) = 'object');

comment on column public.profiles.layout_prefs is 'Home and Faith dashboard layout chosen by the member (null = default for their goal).';

-- Self-editable like the other display preferences (column-level grant; row access stays owner-only by RLS).
grant update (layout_prefs) on public.profiles to authenticated;

-- ===== supabase/migrations/20261112000058_water_entries_client_id.sql =====
-- ROLLBACK (run in this order; loses no pre-existing data — every row written before this migration has
-- client_id null, and dropping the column only removes the idempotency keys of water logged after it):
--   drop index if exists public.water_entries_user_client_uidx;
--   alter table public.water_entries drop column if exists client_id;
-- Roll back the app code first (or together): the current addWaterAction writes client_id.
--
-- Water logging idempotency (N7): the device sends one id per tap and reuses it when that tap is retried, so a
-- request whose response was lost can't add the same glass twice. The same pattern as meal_items.client_id
-- (20261024000040_review_hardening.sql). Existing rows keep client_id null and are unaffected; inserts without a
-- client id (older clients) behave exactly as before, since the unique index only covers non-null ids.
--
-- Additive and live-safe: adding a nullable column with no default is a catalog-only change (no table rewrite).
-- The index is a plain `create unique index`, like every index in these migrations, because the migration runner
-- (supabase db push / migration up, and the bundled setup-all.sql in the SQL editor) runs each file inside a
-- transaction, and `create index concurrently` cannot run inside a transaction block. A plain build holds a SHARE
-- lock on water_entries (writes wait, reads continue) only while it runs; on a small table that is milliseconds.
-- On a large production table, build it first outside a transaction so writes never block:
--   create unique index concurrently if not exists water_entries_user_client_uidx
--     on public.water_entries (user_id, client_id) where client_id is not null;
-- and this file's `if not exists` then makes the statement below a no-op. (If a concurrent build fails it leaves an
-- INVALID index: drop it and rerun.) No existing row can violate it: all existing client_ids are null.

alter table public.water_entries add column if not exists client_id uuid;

create unique index if not exists water_entries_user_client_uidx
  on public.water_entries (user_id, client_id) where client_id is not null;

comment on column public.water_entries.client_id is 'Per-tap id sent by the device; a retried request with the same id is not counted twice (null for older entries).';

-- ===== supabase/migrations/20261112000059_foods_basis.sql =====
-- ROLLBACK (loses no pre-existing data — every row written before this migration has basis null, and the columns
-- the app fell back to before are untouched and still written on every cache upsert):
--   alter table public.foods drop column if exists basis;
-- The constraint below is attached to the column and goes with it. Roll back the app code first (or together):
-- the current food-resolve cache upsert and the My foods queries name the basis column.
--
-- Full nutrition basis for cached foods (N5): a barcode (Open Food Facts) or USDA food is cached in foods when it
-- is logged, but the columns hold one serving of plain numbers with unlisted macros stored as 0, so a re-log from
-- My foods lost the `missing` list (totals no longer read "at least"), sugar, sodium and the label serving. The
-- basis as built at lookup time is now stored alongside, in the same format and with the same check as
-- meal_items.basis (20261019000008_food_amounts.sql); the app prefers it when it is valid and otherwise rebuilds
-- from the columns exactly as before, so rows without a basis (custom, built-in, and foods cached earlier) log
-- with the same numbers as today. A cached row gets its basis the next time that product is looked up again.
--
-- Additive and live-safe: a nullable column with no default is a catalog-only change (no rewrite). The CHECK is
-- validated against existing rows, which are all null, under a brief ACCESS EXCLUSIVE lock. No index is added.
-- RLS: the foods policies are row-level (owner_id), not column lists, and there are no column grants on foods, so
-- the column is readable / writable exactly where the row already is. Cached rows are per user (owner_id = the
-- member); built-in rows (owner_id null) never get a basis. Account deletion cascades on owner_id, and the data
-- export reads foods with select * by owner_id (src/server/services/account.ts), so both already cover it.

alter table public.foods
  add column if not exists basis jsonb check (
    basis is null
    or coalesce(jsonb_typeof(basis) = 'object' and jsonb_typeof(basis -> 'per100') = 'object' and octet_length(basis::text) <= 8000, false)
  );

comment on column public.foods.basis is 'Nutrition basis as looked up (per 100 g/ml or per serving, label serving, sugar, sodium, missing macros) for cached barcode / USDA foods; null = rebuild from the columns.';

-- ===== supabase/migrations/20261112000060_workout_finish_claim.sql =====
-- ROLLBACK (loses no workout data; only the in-flight claim markers go):
--   alter table public.workout_sessions drop column if exists finish_claimed_at;
--   alter table public.workout_sessions drop column if exists finish_claim;
-- Roll back the app code first (or together): finishWorkout writes these columns.
--
-- Finishing a workout is several writes (session, exercises, sets, records, status). Two finishes of the same workout
-- at once (a double tap, or a retry while the first request is still running on gym Wi-Fi) both cleared and re-wrote
-- the exercises, so the sets were saved twice. finishWorkout now claims the session first with a conditional update
-- (status in progress and no live claim); only the request that wins the claim writes, the others wait for it to
-- finish and report the workout as already saved. A claim older than two minutes is treated as abandoned (the
-- server died mid-save), so a later retry can take it over.
--
-- Additive and live-safe: nullable columns with no default are a catalog-only change (no table rewrite).
alter table public.workout_sessions add column if not exists finish_claim uuid;
alter table public.workout_sessions add column if not exists finish_claimed_at timestamptz;

-- ===== supabase/migrations/20261112000061_faith_journey_timezone.sql =====
-- ROLLBACK (no reading history is lost; the journeys go back to following the profile's time zone):
--   Re-run the four function definitions from 20261103000053_faith_discipleship.sql (faith_journey_settle_at,
--   faith_journey_check_in_at, faith_journey_undo, faith_journey_enroll), then:
--   drop function if exists public.faith_journey_set_timezone(text);
--   drop function if exists public.faith_journey_set_timezone_at(uuid, text, timestamptz);
--   drop trigger if exists faith_journeys_timezone_default on public.faith_journeys;
--   drop function if exists public.faith_journey_timezone_default();
--   drop function if exists public.faith_journey_zone_at(public.faith_journeys, timestamptz);
--   alter table public.faith_journeys drop column if exists timezone_switch_at, drop column if exists pending_timezone,
--     drop column if exists timezone_since, drop column if exists previous_timezone, drop column if exists timezone;
-- Roll back the app code first (or together): the journey screen reads these columns.
--
-- Reading journeys keep their own time zone (owner decision T10, 2026-11-12).
--
-- Before: every journey day followed the member's profile time zone, so changing it mid-journey could reopen a day
-- that was already final, or close today early. Now:
--   * A journey takes the member's time zone when it is created, and keeps it. Changing the profile time zone no
--     longer moves journey days. Existing journeys are given the member's current profile zone, so nothing about them
--     changes today.
--   * The member can change a journey's zone explicitly (faith_journey_set_timezone). The change waits for a day
--     boundary: it takes effect at the later of the next midnight in the old zone and the same midnight in the new
--     zone. At that instant both zones show the same date, so no day is skipped, repeated or lengthened to rescue a
--     missed one. Days already final are never re-judged; the strict restart rule is unchanged. A change that would
--     skip a whole calendar day (zones 24 hours or more apart) is refused.
--   * Each moment is judged in the zone in force at that moment: an offline check-in counts for the day it was
--     made on, in the zone that applied then.
--
-- Additive and live-safe: new nullable columns (a catalog-only change), a backfill of active and past journeys from
-- the profile (one UPDATE; small table), and function redefinitions.

alter table public.faith_journeys
  add column if not exists timezone text check (timezone is null or char_length(timezone) between 1 and 64),
  -- The zone used before the last change took effect, and when that change took effect.
  add column if not exists previous_timezone text check (previous_timezone is null or char_length(previous_timezone) between 1 and 64),
  add column if not exists timezone_since timestamptz,
  -- A requested change, and the instant it takes effect (a day boundary in both zones).
  add column if not exists pending_timezone text check (pending_timezone is null or char_length(pending_timezone) between 1 and 64),
  add column if not exists timezone_switch_at timestamptz,
  add constraint faith_journeys_pending_tz_check check ((pending_timezone is null) = (timezone_switch_at is null));

update public.faith_journeys j
  set timezone = public.faith_safe_tz(p.timezone)
  from public.profiles p
  where p.id = j.user_id and j.timezone is null;

-- New journeys take the member's time zone as it is when they start.
create or replace function public.faith_journey_timezone_default()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if new.timezone is null then
    select public.faith_safe_tz(p.timezone) into new.timezone from public.profiles p where p.id = new.user_id;
    new.timezone := coalesce(new.timezone, 'UTC');
  end if;
  return new;
end;
$$;
drop trigger if exists faith_journeys_timezone_default on public.faith_journeys;
create trigger faith_journeys_timezone_default before insert on public.faith_journeys
  for each row execute function public.faith_journey_timezone_default();

-- The time zone a journey's days follow at a given instant.
create or replace function public.faith_journey_zone_at(j public.faith_journeys, p_at timestamptz)
returns text
language plpgsql
stable
set search_path = public
as $$
begin
  if j.pending_timezone is not null and p_at >= j.timezone_switch_at then
    return public.faith_safe_tz(j.pending_timezone);
  end if;
  if j.previous_timezone is not null and j.timezone_since is not null and p_at < j.timezone_since then
    return public.faith_safe_tz(j.previous_timezone);
  end if;
  return public.faith_safe_tz(coalesce(j.timezone, 'UTC'));
end;
$$;
revoke execute on function public.faith_journey_zone_at(public.faith_journeys, timestamptz) from public, anon;
grant execute on function public.faith_journey_zone_at(public.faith_journeys, timestamptz) to authenticated, service_role;

create or replace function public.faith_journey_settle_at(p_journey_id uuid, p_now timestamptz, p_force_through date default null)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  j public.faith_journeys%rowtype;
  a public.faith_journey_attempts%rowtype;
  v_tz text;
  v_through date;
  v_last_day date;
  v_miss date;
  v_row public.faith_journey_checkins%rowtype;
  v_reason text;
  v_guard integer := 0;
begin
  select * into j from public.faith_journeys where id = p_journey_id for update;
  if not found or j.status <> 'active' then
    return;
  end if;
  -- The journey's own time zone (fixed when it started; an explicit change takes effect at a day boundary).
  v_tz := public.faith_journey_zone_at(j, p_now - public.faith_offline_grace());
  v_through := ((p_now at time zone v_tz) - public.faith_offline_grace())::date - 1;
  if p_force_through is not null and p_force_through > v_through then
    v_through := least(p_force_through, (p_now at time zone public.faith_journey_zone_at(j, p_now))::date - 1);
  end if;

  loop
    v_guard := v_guard + 1;
    exit when v_guard > 1000;
    select * into a from public.faith_journey_attempts where journey_id = j.id and status = 'active' for update;
    if not found then
        values (j.id, j.user_id, coalesce((select max(attempt_number) from public.faith_journey_attempts where journey_id = j.id), 0) + 1, j.start_on)
        returning * into a;
    end if;
    exit when a.started_on > v_through;

    v_last_day := least(v_through, a.started_on + j.duration_days - 1);
    -- The first final day of this attempt that isn't complete.
    select d::date into v_miss
      from generate_series(a.started_on, v_last_day, interval '1 day') d
      where not exists (
        select 1 from public.faith_journey_checkins c
        where c.journey_id = j.id and c.check_date = d::date
          and c.prayer_completed_at is not null
          and c.reading_completed_at is not null
          and c.reading_day = (d::date - a.started_on + 1)
      )
      order by d
      limit 1;

    if v_miss is null then
      -- Every final day so far is complete. Finished the whole schedule?
      if a.started_on + j.duration_days - 1 <= v_through then
        update public.faith_journey_attempts set status = 'completed', days_completed = j.duration_days, ended_at = p_now where id = a.id;
        update public.faith_journeys set status = 'completed', ended_at = p_now where id = j.id;
      end if;
      exit;
    end if;

    if v_miss = a.started_on and a.attempt_number > 1 and a.days_completed = 0
       and not exists (select 1 from public.faith_journey_checkins c where c.journey_id = j.id and c.check_date = v_miss) then
      -- A restarted attempt whose Day 1 passed untouched: move Day 1 forward rather than recording another attempt.
      update public.faith_journey_attempts set started_on = v_miss + 1 where id = a.id;
      continue;
    end if;

    select * into v_row from public.faith_journey_checkins c where c.journey_id = j.id and c.check_date = v_miss;
    v_reason := case
      when v_row.prayer_completed_at is not null then 'reading'
      when v_row.reading_completed_at is not null and v_row.reading_day = (v_miss - a.started_on + 1) then 'prayer'
      else 'both'
    end;
    update public.faith_journey_attempts
      set status = 'interrupted', interrupted_on = v_miss, interruption_reason = v_reason,
          days_completed = v_miss - a.started_on, ended_at = p_now
      where id = a.id;
      values (j.id, j.user_id, a.attempt_number + 1, v_miss + 1);
  end loop;
end;
$$;

revoke execute on function public.faith_journey_settle_at(uuid, timestamptz, date) from public, anon, authenticated;
grant execute on function public.faith_journey_settle_at(uuid, timestamptz, date) to service_role;

create or replace function public.faith_journey_check_in_at(p_user uuid, p_activity text, p_now timestamptz, p_occurred_at timestamptz default null)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  j public.faith_journeys%rowtype;
  a public.faith_journey_attempts%rowtype;
  v_tz text;
  v_today date;
  v_date date;
  v_source text := 'online';
  v_at timestamptz := p_now;
  v_day integer;
  v_row public.faith_journey_checkins%rowtype;
begin
  if p_activity not in ('reading', 'prayer') then
    raise exception 'faith_invalid_activity' using errcode = 'P0001';
  end if;
  select * into j from public.faith_journeys where user_id = p_user and status = 'active';
  if not found then
    raise exception 'faith_no_journey' using errcode = 'P0001';
  end if;
  -- The journey's own time zone, as in force now (and, for an offline check-in, as in force when it was made).
  v_tz := public.faith_journey_zone_at(j, p_now);
  v_today := (p_now at time zone v_tz)::date;
  v_date := v_today;

  if p_occurred_at is not null and p_occurred_at < p_now - interval '2 minutes' then
    if p_occurred_at > p_now then
      raise exception 'faith_invalid_time' using errcode = 'P0001';
    end if;
    v_date := (p_occurred_at at time zone public.faith_journey_zone_at(j, p_occurred_at))::date;
    v_source := 'offline';
    v_at := p_occurred_at;
    if v_date = v_today then
      null;
    -- The grace runs from the end of that day in the zone that applied to it (the same as before when the journey's
    -- zone hasn't changed).
    elsif v_date < v_today and p_now < ((v_date + 1)::timestamp at time zone public.faith_journey_zone_at(j, p_occurred_at)) + public.faith_offline_grace() then
      null;
    else
      raise exception 'faith_offline_too_late' using errcode = 'P0001';
    end if;
  end if;

  -- A check-in for today proves the member is online: yesterday is final now. One for yesterday settles nothing new.
  perform public.faith_journey_settle_at(j.id, p_now, case when v_date = v_today then v_today - 1 end);
  select * into j from public.faith_journeys where id = j.id;
  if j.status <> 'active' then
    raise exception 'faith_no_journey' using errcode = 'P0001';
  end if;
  select * into a from public.faith_journey_attempts where journey_id = j.id and status = 'active';
  if v_date < a.started_on then
    -- Before the journey starts, or a day of an attempt that has already been interrupted.
    raise exception 'faith_day_closed' using errcode = 'P0001';
  end if;
  v_day := v_date - a.started_on + 1;
  if v_day > j.duration_days then
    raise exception 'faith_day_closed' using errcode = 'P0001';
  end if;

    values (
      j.id, p_user, v_date,
      case when p_activity = 'reading' then v_day end,
      case when p_activity = 'reading' then v_at end,
      case when p_activity = 'reading' then v_source end,
      case when p_activity = 'prayer' then v_at end,
      case when p_activity = 'prayer' then v_source end
    )
    on conflict (journey_id, check_date) do update set
      reading_day = case when p_activity = 'reading' and (c.reading_completed_at is null or c.reading_day <> v_day) then v_day else c.reading_day end,
      reading_completed_at = case when p_activity = 'reading' and (c.reading_completed_at is null or c.reading_day <> v_day) then v_at else c.reading_completed_at end,
      reading_source = case when p_activity = 'reading' and (c.reading_completed_at is null or c.reading_day <> v_day) then v_source else c.reading_source end,
      prayer_completed_at = case when p_activity = 'prayer' and c.prayer_completed_at is null then v_at else c.prayer_completed_at end,
      prayer_source = case when p_activity = 'prayer' and c.prayer_completed_at is null then v_source else c.prayer_source end,
      updated_at = now()
    returning * into v_row;

  -- The last day of the schedule, completed: the journey is finished.
  if v_day = j.duration_days and v_row.prayer_completed_at is not null and v_row.reading_day = v_day then
    perform public.faith_journey_settle_at(j.id, p_now, v_date + 1);
    -- settle_at only finalizes days before today; finish explicitly when the last day is today.
    update public.faith_journey_attempts set status = 'completed', days_completed = j.duration_days, ended_at = p_now
      where id = a.id and status = 'active';
    update public.faith_journeys set status = 'completed', ended_at = p_now where id = j.id and status = 'active';
  end if;

  return jsonb_build_object(
    'date', v_date, 'day', v_day, 'source', v_source,
    'reading', v_row.reading_completed_at is not null and v_row.reading_day = v_day,
    'prayer', v_row.prayer_completed_at is not null
  );
end;
$$;

revoke execute on function public.faith_journey_check_in_at(uuid, text, timestamptz, timestamptz) from public, anon, authenticated;
grant execute on function public.faith_journey_check_in_at(uuid, text, timestamptz, timestamptz) to service_role;

create or replace function public.faith_journey_undo(p_activity text)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_user uuid := (select auth.uid());
  j public.faith_journeys%rowtype;
  v_today date;
begin
  select * into j from public.faith_journeys where user_id = v_user and status = 'active';
  if not found then
    return;
  end if;
  v_today := (now() at time zone public.faith_journey_zone_at(j, now()))::date;
  if p_activity = 'reading' then
    update public.faith_journey_checkins set reading_day = null, reading_completed_at = null, reading_source = null, updated_at = now()
      where journey_id = j.id and check_date = v_today;
  elsif p_activity = 'prayer' then
    update public.faith_journey_checkins set prayer_completed_at = null, prayer_source = null, updated_at = now()
      where journey_id = j.id and check_date = v_today;
  end if;
end;
$$;

revoke execute on function public.faith_journey_undo(text) from public, anon;
grant execute on function public.faith_journey_undo(text) to authenticated;

create or replace function public.faith_journey_enroll(p_kind text, p_param text, p_duration integer, p_start_on date)
returns uuid
language plpgsql
security definer
set search_path = public
as $$
declare
  v_user uuid := (select auth.uid());
  v_today date;
  v_id uuid;
begin
  if v_user is null then
    raise exception 'not_authenticated' using errcode = '42501';
  end if;
  select ((now() at time zone public.faith_safe_tz(p.timezone)))::date into v_today from public.profiles p where p.id = v_user;
  if p_start_on is null or p_start_on < v_today or p_start_on > v_today + 30 then
    raise exception 'faith_invalid_start' using errcode = 'P0001';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('faith_journey:' || v_user::text, 0));
  update public.faith_journey_attempts set status = 'ended', ended_at = now()
    where user_id = v_user and status = 'active';
  update public.faith_journeys set status = 'ended', ended_at = now() where user_id = v_user and status = 'active';
  -- The journey keeps the member's time zone as it is today (journey_timezone_default fills it in).
    values (v_user, p_kind, nullif(p_param, ''), p_duration, p_start_on)
    returning id into v_id;
  return v_id;
end;
$$;

revoke execute on function public.faith_journey_enroll(text, text, integer, date) from public, anon;
grant execute on function public.faith_journey_enroll(text, text, integer, date) to authenticated;

/**
 * Change the time zone of a member's active journey as of p_now. Takes effect at the later of the next midnight in the
 * current zone and that same date's midnight in the new zone, so both zones agree on the date at the switch. Passing
 * the zone already in force cancels a change that hasn't taken effect yet. Returns when the change takes effect.
 */
create or replace function public.faith_journey_set_timezone_at(p_user uuid, p_tz text, p_now timestamptz)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  j public.faith_journeys%rowtype;
  v_cur text;
  v_change_on date;
  v_switch timestamptz;
begin
  if p_user is null then
    raise exception 'not_authenticated' using errcode = '42501';
  end if;
  if p_tz is null or p_tz = '' or public.faith_safe_tz(p_tz) <> p_tz then
    raise exception 'faith_invalid_timezone' using errcode = 'P0001';
  end if;
  select id into j.id from public.faith_journeys where user_id = p_user and status = 'active';
  if j.id is null then
    raise exception 'faith_no_journey' using errcode = 'P0001';
  end if;
  -- Days that are already over are judged first, in the zone that applied to them.
  perform public.faith_journey_settle_at(j.id, p_now);
  select * into j from public.faith_journeys where id = j.id and status = 'active' for update;
  if not found then
    raise exception 'faith_no_journey' using errcode = 'P0001';
  end if;
  -- A change whose moment has passed becomes the journey's zone (the old one is kept for the days before it).
  if j.pending_timezone is not null and p_now >= j.timezone_switch_at then
    update public.faith_journeys
      set previous_timezone = timezone, timezone = pending_timezone, timezone_since = timezone_switch_at,
          pending_timezone = null, timezone_switch_at = null
      where id = j.id
      returning * into j;
  end if;
  v_cur := public.faith_journey_zone_at(j, p_now);
  if p_tz = v_cur then
    update public.faith_journeys set pending_timezone = null, timezone_switch_at = null where id = j.id;
    return jsonb_build_object('timezone', v_cur, 'pending', null, 'switch_at', null);
  end if;
  v_change_on := (p_now at time zone v_cur)::date + 1;
  v_switch := greatest(v_change_on::timestamp at time zone v_cur, v_change_on::timestamp at time zone p_tz);
  if (v_switch at time zone v_cur)::date <> v_change_on or (v_switch at time zone p_tz)::date <> v_change_on then
    raise exception 'faith_timezone_jump' using errcode = 'P0001';
  end if;
  update public.faith_journeys set pending_timezone = p_tz, timezone_switch_at = v_switch where id = j.id;
  return jsonb_build_object('timezone', v_cur, 'pending', p_tz, 'switch_at', v_switch, 'change_on', v_change_on);
end;
$$;
revoke execute on function public.faith_journey_set_timezone_at(uuid, text, timestamptz) from public, anon, authenticated;
grant execute on function public.faith_journey_set_timezone_at(uuid, text, timestamptz) to service_role;

-- The member-facing change: their own active journey, the server's clock.
create or replace function public.faith_journey_set_timezone(p_tz text)
returns jsonb
language sql
security definer
set search_path = public
as $$
  select public.faith_journey_set_timezone_at((select auth.uid()), p_tz, now());
$$;
revoke execute on function public.faith_journey_set_timezone(text) from public, anon;
grant execute on function public.faith_journey_set_timezone(text) to authenticated;

-- ===== supabase/migrations/20261112000062_workout_drop_sets.sql =====
-- ROLLBACK (drops only the drop-set marker; every set, its reps and weight stay):
--   alter table public.workout_sets drop constraint if exists workout_sets_drop_not_warmup;
--   alter table public.workout_sets drop column if exists is_drop;
-- Roll back the app code first (or together): finishWorkout and the workout editor write this column.
--
-- Drop sets: a set done straight after a working set at a lower weight, with no rest in between. They are real
-- working sets (their reps and weight count towards volume and records), so they live in workout_sets like any
-- other set; is_drop only says "this one followed the set before it with no rest", which the logger, history and
-- "last time" need to show and align sets correctly. A warm-up can't be a drop set.
--
-- Additive and live-safe: a boolean with a constant default is a catalog-only change on Postgres 11+ (no rewrite),
-- and every existing set is a normal set (false).
alter table public.workout_sets add column if not exists is_drop boolean not null default false;

do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'workout_sets_drop_not_warmup') then
    alter table public.workout_sets add constraint workout_sets_drop_not_warmup check (not (is_drop and is_warmup));
  end if;
end $$;

-- ===== supabase/migrations/20261113000063_weekly_reports.sql =====
-- ROLLBACK (removes the weekly reports and nothing else; workouts, food, runs, sleep and weight are untouched):
--   drop table if exists public.weekly_reports;
--   alter table public.ai_usage_events drop constraint if exists ai_usage_events_kind_check;
--   alter table public.ai_usage_events add constraint ai_usage_events_kind_check
--     check (kind in ('chat', 'plan', 'meal_plan', 'food_photo', 'food_explain'));
--   (the second step fails while weekly_report usage rows exist; delete those rows first or leave the wider check)
-- Roll back the app code first: /progress/reports and the weekly-report job read and write this table.
--
-- Weekly progress reports (Pro). One row per member per Monday–Sunday week (the member's own time zone), written
-- only by the server: the scheduled job or the member opening their reports. The unique key makes generation
-- retry-safe: a second attempt for the same week finds the row and does nothing.
--
-- `metrics` holds the aggregates computed from the member's own records (counts, totals, averages; no food names,
-- notes, journal text or photos). `analysis` is the written part: rule-based or AI, as `analysis_source` says.
create table if not exists public.weekly_reports (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users (id) on delete cascade,
  week_start date not null check (extract(isodow from week_start) = 1),
  time_zone text not null check (char_length(time_zone) between 1 and 64),
  metrics jsonb not null,
  analysis jsonb not null,
  analysis_source text not null check (analysis_source in ('rules', 'ai')),
  model text,
  generated_at timestamptz not null default now(),
  read_at timestamptz,
  unique (user_id, week_start)
);
create index if not exists weekly_reports_user_week on public.weekly_reports (user_id, week_start desc);

alter table public.weekly_reports enable row level security;

-- Members read and delete their own reports and can mark them read; only the server (service role) creates them.
drop policy if exists weekly_reports_select_own on public.weekly_reports;
create policy weekly_reports_select_own on public.weekly_reports for select to authenticated using (user_id = (select auth.uid()));
drop policy if exists weekly_reports_delete_own on public.weekly_reports;
create policy weekly_reports_delete_own on public.weekly_reports for delete to authenticated using (user_id = (select auth.uid()));
drop policy if exists weekly_reports_update_own on public.weekly_reports;
create policy weekly_reports_update_own on public.weekly_reports for update to authenticated using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()));
revoke update on public.weekly_reports from authenticated;
grant select, delete on public.weekly_reports to authenticated;
grant update (read_at) on public.weekly_reports to authenticated;

-- The AI write-up of a report counts against the member's monthly AI allowance like other AI requests.
alter table public.ai_usage_events drop constraint if exists ai_usage_events_kind_check;
alter table public.ai_usage_events add constraint ai_usage_events_kind_check
  check (kind in ('chat', 'plan', 'meal_plan', 'food_photo', 'food_explain', 'weekly_report'));

-- ===== supabase/migrations/20261113000064_habit_programs.sql =====
-- ROLLBACK (removes habit-program enrollments and check-ins only; workouts, food, journal and Bible data untouched):
--   drop table if exists public.habit_program_checkins;
--   drop table if exists public.habit_program_enrollments;
-- Roll back the app code first: /train/habits reads and writes these tables.
--
-- Habit programs: structured nutrition, faith-and-fitness and lifestyle programs made of daily and weekly activities
-- (lessons, food logging, protein, workouts, optional Scripture, prayer and reflection) rather than sets and reps. The
-- program content lives in the app (src/data/habit-programs); the database keeps who is enrolled and what they did.
--
-- No restart rule: a missed day stays missed and the member carries on. (The strict-restart 40-day challenge and
-- reading journeys keep their own tables and rules, unchanged.)
--
-- Enrolling needs Pro (checked here, not only in the app). After Pro ends, a member keeps reading, exporting and
-- deleting what they recorded; ticking off new days needs Pro again.
create table if not exists public.habit_program_enrollments (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users (id) on delete cascade,
  program_slug text not null check (program_slug ~ '^[a-z0-9-]{1,64}$'),
  started_on date not null,
  status text not null default 'active' check (status in ('active', 'completed', 'stopped')),
  -- The member's own goals for this program (e.g. a protein target in grams), adjustable at any time.
  goals jsonb not null default '{}'::jsonb check (pg_column_size(goals) < 4000),
  completed_at timestamptz,
  stopped_at timestamptz,
  created_at timestamptz not null default now(),
  check (status <> 'completed' or completed_at is not null)
);
create unique index if not exists habit_program_one_active on public.habit_program_enrollments (user_id, program_slug) where status = 'active';
create index if not exists habit_program_enrollments_user on public.habit_program_enrollments (user_id, created_at desc);

create table if not exists public.habit_program_checkins (
  id uuid primary key default gen_random_uuid(),
  enrollment_id uuid not null references public.habit_program_enrollments (id) on delete cascade,
  user_id uuid not null references auth.users (id) on delete cascade,
  day_number smallint not null check (day_number between 1 and 120),
  activity_key text not null check (activity_key ~ '^[a-z0-9_-]{1,48}$'),
  -- A short answer to a weekly check-in question (never prayer or journal text: reflection lives in the private
  -- prayer journal, which keeps its own privacy settings).
  answer text check (char_length(answer) <= 500),
  checked_on date not null,
  created_at timestamptz not null default now(),
  unique (enrollment_id, day_number, activity_key)
);
create index if not exists habit_program_checkins_user on public.habit_program_checkins (user_id);

alter table public.habit_program_enrollments enable row level security;
alter table public.habit_program_checkins enable row level security;

drop policy if exists habit_enrollments_select_own on public.habit_program_enrollments;
create policy habit_enrollments_select_own on public.habit_program_enrollments for select to authenticated using (user_id = (select auth.uid()));
drop policy if exists habit_enrollments_insert_pro on public.habit_program_enrollments;
