insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('5fc3044f-cc7a-53a4-9a5a-20b6a148b84d', 'plank', 'Front Plank', array['core']::text[], array['shoulders', 'glutes']::text[], array['bodyweight', 'mat']::text[], 'core', 'core', 'compound', 'beginner', true, true, 'Holding a straight-body position on the forearms to build trunk endurance.', array['Place your forearms on the floor with elbows under shoulders.', 'Extend your legs back and lift your hips so your body forms a straight line.', 'Brace your abs and squeeze your glutes.', 'Breathe steadily and hold for the prescribed time.']::text[], array['Squeeze glutes', 'Ribs down', 'Push the floor away']::text[], array['Hips sagging', 'Hips piked high', 'Holding your breath']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('cd2c9602-80b4-5ccd-a7c6-8fae81822ddf', 'side-plank', 'Side Plank', array['obliques', 'core']::text[], array['glutes', 'shoulders']::text[], array['bodyweight', 'mat']::text[], 'core', 'core', 'compound', 'beginner', true, true, 'Holding a sideways plank to train lateral trunk stability.', array['Lie on your side with your elbow under your shoulder.', 'Stack your feet (or stagger them, or bend the knees to make it easier).', 'Lift your hips so your body forms a straight line.', 'Hold, then switch sides.']::text[], array['Hips forward and high', 'Shoulder away from ear', 'Long body']::text[], array['Hips sagging', 'Rolling forward', 'Shrugging']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('0776620a-5f8a-5281-af09-10ba8ed6fb7e', 'dead-bug', 'Dead Bug', array['core']::text[], array['hip flexors']::text[], array['bodyweight', 'mat']::text[], 'core', 'core', 'compound', 'beginner', false, true, 'A controlled anti-extension drill on your back that teaches core bracing.', array['Lie on your back with arms reaching to the ceiling and knees bent 90 degrees above your hips.', 'Press your lower back gently into the floor.', 'Slowly extend one arm overhead and the opposite leg toward the floor.', 'Return and switch sides without losing back contact.']::text[], array['Low back stays down', 'Exhale as you extend', 'Slow and controlled']::text[], array['Arching the lower back', 'Moving too fast', 'Holding breath']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('16a7773c-217a-58af-805f-5242283617ce', 'bird-dog', 'Bird Dog', array['core', 'glutes']::text[], array['spinal erectors', 'shoulders']::text[], array['bodyweight', 'mat']::text[], 'core', 'core', 'compound', 'beginner', false, true, 'Extending opposite arm and leg from all fours to build trunk control.', array['Start on hands and knees, hands under shoulders and knees under hips.', 'Brace and slowly extend one arm forward and the opposite leg back.', 'Hold briefly without rotating your hips.', 'Return and switch sides.']::text[], array['Hips level', 'Reach long', 'Slow tempo']::text[], array['Arching the back', 'Rotating the hips', 'Rushing']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('984525de-991d-57d6-adce-5330562cc669', 'pallof-press', 'Pallof Press', array['obliques', 'core']::text[], array['shoulders', 'glutes']::text[], array['cable', 'band']::text[], 'core', 'rotation', 'compound', 'beginner', false, true, 'An anti-rotation press that trains the core to resist twisting forces.', array['Anchor a band or cable at chest height and stand side-on to it.', 'Hold the handle at your chest with both hands and step out to create tension.', 'Press your hands straight out in front of you, resisting the pull to rotate.', 'Hold briefly, return to the chest, then switch sides after the set.']::text[], array['Don''t let it turn you', 'Stack ribs over hips', 'Breathe out on the press']::text[], array['Rotating toward the anchor', 'Standing too close', 'Shrugging']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('24b0a926-f849-5907-bdd4-1700b2b3e7f8', 'cable-woodchop', 'Cable Woodchop', array['obliques', 'core']::text[], array['shoulders', 'hips']::text[], array['cable', 'band']::text[], 'core', 'rotation', 'compound', 'intermediate', false, false, 'A diagonal rotational pull that trains force transfer from hips to hands.', array['Set a cable or band high and stand side-on with feet wider than hips.', 'Grab the handle with both hands, arms extended toward the anchor.', 'Rotate through your hips and torso to pull the handle diagonally down and across your body.', 'Return slowly along the same path.']::text[], array['Pivot the back foot', 'Rotate from the hips', 'Arms stay long']::text[], array['Pulling only with the arms', 'Twisting the lower back without hip turn', 'Going too heavy']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('c7747f5f-2b16-5d87-81d4-1fabe02b3402', 'hanging-knee-raise', 'Hanging Knee Raise', array['abdominals', 'hip flexors']::text[], array['forearms', 'lats']::text[], array['pull_up_bar']::text[], 'core', 'core', 'compound', 'intermediate', false, false, 'Raising the knees while hanging from a bar to train the abs and grip.', array['Hang from a pull-up bar with an overhand grip and shoulders engaged.', 'Curl your pelvis and lift your knees toward your chest.', 'Lower under control without swinging.']::text[], array['Curl the pelvis up', 'No swinging', 'Slow lowering']::text[], array['Swinging for momentum', 'Only lifting the thighs without pelvic curl', 'Dropping fast']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('052d69a0-c7f2-5f0f-a34d-3f1e0226c21c', 'ab-wheel-rollout', 'Ab Wheel Rollout', array['abdominals']::text[], array['lats', 'shoulders']::text[], array['ab_wheel']::text[], 'core', 'core', 'compound', 'advanced', false, false, 'Rolling a wheel forward from the knees while resisting lower-back arching.', array['Kneel on a mat holding the ab wheel beneath your shoulders.', 'Brace and roll forward slowly, keeping your hips extended.', 'Go only as far as you can without your lower back sagging.', 'Pull back to the start using your abs.']::text[], array['Tuck the pelvis', 'Short range first', 'Lead back with the abs']::text[], array['Lower back arching', 'Going too far too soon', 'Hips leading the return']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('f8594286-c16e-5157-b37f-7c0eebc4d36b', 'medicine-ball-rotational-throw', 'Medicine Ball Rotational Throw', array['obliques', 'hips']::text[], array['shoulders', 'core']::text[], array['medicine_ball']::text[], 'plyometric', 'rotation', 'compound', 'intermediate', false, false, 'A side-on explosive throw into a wall that trains rotational power for striking and throwing sports.', array['Stand side-on to a solid wall about an arm''s length away, holding a medicine ball at hip height.', 'Load by rotating the ball away from the wall and shifting weight to your back leg.', 'Rotate explosively through the hips and torso to throw the ball into the wall.', 'Catch the rebound (or let it drop if it doesn''t rebound) and reset each rep.']::text[], array['Hips lead, arms follow', 'Pivot the back foot', 'Throw through the wall']::text[], array['Throwing with the arms only', 'Ball too heavy to move fast', 'Rushing reps without resetting']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('d99fa237-f8e7-5c95-9f1f-f2cc2a21af45', 'farmers-carry', 'Farmer''s Carry', array['forearms', 'traps', 'core']::text[], array['glutes', 'quadriceps', 'upper back']::text[], array['dumbbell', 'kettlebell', 'trap_bar']::text[], 'strength', 'carry', 'compound', 'beginner', true, false, 'Walking while holding heavy weights at your sides — trains grip, posture and work capacity.', array['Deadlift a pair of heavy dumbbells or kettlebells to your sides.', 'Stand tall with shoulders down and back.', 'Walk with short, quick, controlled steps for the prescribed time or distance.', 'Set the weights down with a controlled hinge.']::text[], array['Tall posture', 'Crush the handles', 'Short steps']::text[], array['Leaning to one side', 'Shrugging the shoulders up', 'Long, unstable strides']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('d7b8f8d8-137f-5b57-85ef-c267027ccadb', 'suitcase-carry', 'Suitcase Carry', array['obliques', 'forearms']::text[], array['traps', 'glutes']::text[], array['dumbbell', 'kettlebell']::text[], 'core', 'carry', 'compound', 'beginner', true, false, 'A one-sided carry that challenges your trunk to stay upright.', array['Pick up one heavy dumbbell or kettlebell at your side.', 'Stand tall without leaning toward or away from the weight.', 'Walk for the prescribed time or distance, then switch hands.']::text[], array['Stay level', 'Shoulders even', 'Brace like a plank']::text[], array['Leaning', 'Rushing', 'Letting the weight swing']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('c14796ff-1258-52a2-a569-548b263b23d4', 'sandbag-bear-hug-carry', 'Sandbag Bear-Hug Carry', array['upper back', 'core']::text[], array['biceps', 'quadriceps', 'glutes']::text[], array['sandbag']::text[], 'strength', 'carry', 'compound', 'intermediate', true, false, 'Carrying a sandbag hugged against the chest — a strongman and grappling staple.', array['Lift the sandbag from the floor to your chest using a squat and hip extension.', 'Wrap your arms around it and hug it tightly against your torso.', 'Walk for the prescribed time or distance while breathing behind the brace.', 'Set it down by squatting with control.']::text[], array['Hug tight', 'Upper back strong', 'Short breaths behind the brace']::text[], array['Letting the bag slide down', 'Rounding excessively under load', 'Holding your breath the entire carry']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('637be12d-f7d7-531a-b675-4d1ee34230c4', 'sandbag-to-shoulder', 'Sandbag to Shoulder', array['glutes', 'hamstrings', 'upper back']::text[], array['biceps', 'core', 'quadriceps']::text[], array['sandbag']::text[], 'strength', 'power', 'compound', 'advanced', false, false, 'Lifting a sandbag from the floor onto one shoulder — trains odd-object strength.', array['Straddle the sandbag and hinge to grip it underneath.', 'Lap the bag by pulling it onto your thighs as you sit into a squat.', 'Extend your hips explosively and pop the bag up onto one shoulder.', 'Lower it to the floor with control and alternate shoulders.']::text[], array['Lap, then extend', 'Hips drive the bag', 'Alternate sides']::text[], array['Curling the bag with the arms', 'Skipping the lap position', 'Rushing without resetting']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('8ed6334f-9270-52ad-940a-428ade2184ee', 'sled-push', 'Sled Push', array['quadriceps', 'glutes']::text[], array['calves', 'core', 'shoulders']::text[], array['sled']::text[], 'conditioning', 'conditioning', 'compound', 'beginner', true, true, 'Driving a loaded sled forward — high-output conditioning with no eccentric soreness.', array['Grip the sled handles with arms extended or bent, body leaning forward.', 'Drive through the balls of your feet with powerful, short steps.', 'Keep a straight line from head to heel.', 'Push for the prescribed distance or time.']::text[], array['Low and strong', 'Drive the knees', 'Steady breathing']::text[], array['Standing too upright', 'Overstriding', 'Rounding the back']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('65e83f70-bb2a-539f-a63d-cc815722afff', 'dead-hang', 'Dead Hang', array['forearms', 'grip']::text[], array['lats', 'shoulders']::text[], array['pull_up_bar']::text[], 'strength', 'carry', 'isolation', 'beginner', true, false, 'Hanging from a bar to build grip endurance and decompress the shoulders.', array['Grip the bar overhand with hands shoulder width apart.', 'Lift your feet and hang with your arms straight.', 'Keep the shoulders active (not fully shrugged to your ears).', 'Hold for the prescribed time and step down safely.']::text[], array['Crush the bar', 'Active shoulders', 'Breathe']::text[], array['Dropping off without control', 'Excessive swinging', 'Holding breath']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('85f75596-8333-52d9-9841-8eb3b5a78e28', 'power-clean', 'Power Clean', array['glutes', 'hamstrings', 'quadriceps', 'traps']::text[], array['upper back', 'calves', 'core']::text[], array['barbell']::text[], 'plyometric', 'power', 'compound', 'advanced', false, false, 'An Olympic-style lift that moves the bar from floor to shoulders explosively. Learn with qualified coaching.', array['Set up like a deadlift with a hook or overhand grip just outside the legs.', 'Lift the bar to mid-thigh with a flat back, keeping it close.', 'Extend hips, knees and ankles explosively, shrugging as the bar rises.', 'Pull yourself under and catch the bar on the front of the shoulders in a partial squat with elbows high.', 'Stand to finish, then lower the bar safely.']::text[], array['Patient off the floor', 'Jump and shrug', 'Fast elbows']::text[], array['Pulling early with the arms', 'Bar swinging away from the body', 'Catching with elbows low']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('70d0d7da-4b27-5741-a362-e32f9f9c97b8', 'box-jump', 'Box Jump', array['quadriceps', 'glutes', 'calves']::text[], array['hamstrings', 'core']::text[], array['box']::text[], 'plyometric', 'power', 'compound', 'intermediate', false, false, 'Jumping onto a box to develop lower-body explosiveness with reduced landing impact.', array['Stand facing a stable box about a foot away.', 'Swing your arms back and dip into a quarter squat.', 'Jump explosively and land softly on the box with both feet, knees tracking over toes.', 'Stand up fully, then step down — don''t jump down.']::text[], array['Land quiet', 'Step down, don''t jump down', 'Quality over height']::text[], array['Box too high', 'Landing with knees caving', 'Rebounding off the floor for reps']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('807a91fa-cc52-5a16-9884-22408919b8b1', 'broad-jump', 'Broad Jump', array['glutes', 'quadriceps', 'hamstrings']::text[], array['calves', 'core']::text[], array['bodyweight']::text[], 'plyometric', 'power', 'compound', 'intermediate', false, false, 'A horizontal jump for distance that builds hip power.', array['Stand with feet hip width apart.', 'Swing your arms back and hinge into a quarter squat.', 'Explode forward, swinging the arms and extending the hips.', 'Land softly in a balanced squat and stick the landing before resetting.']::text[], array['Swing and drive', 'Stick the landing', 'Reset every rep']::text[], array['Landing stiff-legged', 'Knees caving on landing', 'Chaining reps without control']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('06d0cc29-b99b-511c-a7a6-2038c8d54788', 'medicine-ball-slam', 'Medicine Ball Slam', array['lats', 'core', 'shoulders']::text[], array['glutes', 'hip flexors']::text[], array['medicine_ball']::text[], 'conditioning', 'power', 'compound', 'beginner', false, false, 'Lifting a slam ball overhead and throwing it down forcefully — power and conditioning.', array['Hold a slam ball (a non-bouncing medicine ball) at chest height.', 'Reach it overhead, rising onto your toes.', 'Slam it into the floor in front of you, hinging and pulling with the lats.', 'Squat to pick it up and repeat.']::text[], array['Full reach overhead', 'Throw through the floor', 'Hinge to pick up']::text[], array['Using a bouncy ball that rebounds into the face', 'Rounding to pick it up', 'Arm-only throws']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('a9890942-848b-59ac-9fd2-3de4c5f785f0', 'burpee', 'Burpee', array['full body']::text[], array['chest', 'quadriceps', 'core']::text[], array['bodyweight']::text[], 'conditioning', 'conditioning', 'compound', 'intermediate', false, false, 'A squat-thrust with a push-up and jump — a full-body conditioning staple.', array['From standing, squat and place your hands on the floor.', 'Jump or step your feet back into a plank and lower your chest to the floor.', 'Push up, jump or step your feet back toward your hands.', 'Stand and jump with arms overhead.']::text[], array['Find a steady rhythm', 'Step back to scale', 'Land softly']::text[], array['Sagging hips in the plank', 'Landing heavily', 'Sacrificing form for speed']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('34e245ab-b4e7-5110-a622-6005b9070bba', 'step-back-burpee', 'Step-Back Burpee (No Jump)', array['full body']::text[], array['quadriceps', 'core', 'shoulders']::text[], array['bodyweight']::text[], 'conditioning', 'conditioning', 'compound', 'beginner', false, true, 'A low-impact burpee that steps instead of jumping.', array['From standing, squat down and place hands on the floor.', 'Step one foot back, then the other, into a plank.', 'Step the feet back in one at a time.', 'Stand tall and reach overhead.']::text[], array['Smooth steps', 'Strong plank', 'Steady breathing']::text[], array['Rounding the back', 'Sagging hips', 'Rushing']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('6fedda54-728a-5348-8de6-db334a96966a', 'sprawl', 'Sprawl', array['hips', 'core']::text[], array['chest', 'quadriceps']::text[], array['bodyweight', 'mat']::text[], 'conditioning', 'conditioning', 'compound', 'intermediate', false, false, 'A wrestling defense drill: shooting the legs back and dropping the hips to the mat.', array['Stand in an athletic stance.', 'Drop your hands to the mat and kick your legs back wide.', 'Drive your hips down toward the mat with chest up.', 'Snap your feet back under you and return to stance.']::text[], array['Hips heavy', 'Legs back and wide', 'Back to stance fast']::text[], array['Landing on the knees', 'Piking the hips up', 'Slow recovery to stance']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('761a6fe4-c43a-50cf-9d5e-fedf41329f3b', 'mountain-climber', 'Mountain Climber', array['core', 'hip flexors']::text[], array['shoulders', 'quadriceps']::text[], array['bodyweight']::text[], 'conditioning', 'conditioning', 'compound', 'beginner', true, false, 'Driving knees toward the chest alternately from a high plank.', array['Start in a high plank with hands under shoulders.', 'Drive one knee toward your chest, then quickly switch legs.', 'Keep hips level and maintain a steady pace.']::text[], array['Shoulders over hands', 'Hips low', 'Quick feet']::text[], array['Hips bouncing up', 'Shoulders drifting behind hands', 'Holding breath']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('961215a1-9eb9-50a8-9ba5-05ec03bf2ed0', 'bear-crawl', 'Bear Crawl', array['shoulders', 'core']::text[], array['quadriceps', 'hip flexors']::text[], array['bodyweight']::text[], 'conditioning', 'conditioning', 'compound', 'beginner', true, false, 'Crawling on hands and feet with knees hovering — coordination and conditioning.', array['Start on hands and knees, then lift your knees an inch off the floor.', 'Move opposite hand and foot forward together in small steps.', 'Keep your back flat and hips low.', 'Crawl forward, backward or laterally for the prescribed time.']::text[], array['Knees low', 'Small steps', 'Flat back']::text[], array['Hips high in the air', 'Big, sloppy steps', 'Holding breath']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('1e65218d-b2f2-58bf-b3fa-59e382b15b76', 'jump-rope', 'Jump Rope', array['calves', 'cardiovascular system']::text[], array['shoulders', 'forearms']::text[], array['jump_rope']::text[], 'cardio', 'conditioning', 'compound', 'beginner', true, false, 'Skipping rope for footwork rhythm and aerobic or interval conditioning.', array['Hold the handles at hip height with elbows close to your sides.', 'Turn the rope with your wrists, not your arms.', 'Jump just high enough to clear the rope, landing softly on the balls of your feet.', 'Keep a relaxed, steady rhythm for the prescribed time.']::text[], array['Small jumps', 'Wrists turn the rope', 'Stay relaxed']::text[], array['Jumping too high', 'Swinging the arms wide', 'Landing flat-footed']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('3596814c-ae30-5e9b-a0f3-079d8687dd96', 'rowing-intervals', 'Rowing Machine', array['cardiovascular system', 'upper back', 'legs']::text[], array['glutes', 'core', 'biceps']::text[], array['rower']::text[], 'cardio', 'conditioning', 'compound', 'beginner', true, true, 'Indoor rowing for aerobic base and intervals with low joint impact.', array['Strap your feet in and grip the handle with arms straight.', 'Drive with the legs first, then swing the torso back slightly, then pull the handle to your lower ribs.', 'Return in reverse order: arms, torso, then legs.', 'Maintain the prescribed pace or effort for the interval.']::text[], array['Legs, body, arms', 'Arms, body, legs on the way back', 'Smooth, powerful strokes']::text[], array['Pulling with arms first', 'Rounding the back', 'Rushing the recovery']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('f826d072-40fc-58c6-96c7-6e471df49ded', 'bike-intervals', 'Air / Stationary Bike', array['cardiovascular system', 'quadriceps']::text[], array['glutes', 'hamstrings']::text[], array['bike']::text[], 'cardio', 'conditioning', 'compound', 'beginner', true, true, 'Cycling on an air or stationary bike for steady aerobic work or intervals.', array['Adjust the seat so your knee is slightly bent at the bottom of the pedal stroke.', 'Warm up at an easy pace for a few minutes.', 'Ride at the prescribed effort for each interval, then recover as programmed.']::text[], array['Seat height matters', 'Smooth cadence', 'Breathe rhythmically']::text[], array['Seat too low', 'Starting intervals too hard', 'Skipping the warm-up']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('814f80b6-2f9d-5078-96eb-f07d8ed23949', 'brisk-walk', 'Brisk / Incline Walk', array['cardiovascular system']::text[], array['glutes', 'calves']::text[], array['bodyweight']::text[], 'cardio', 'conditioning', 'compound', 'beginner', true, true, 'Walking at a pace where you can talk in short sentences — a low-impact aerobic foundation.', array['Walk outdoors or on a treadmill at a pace that raises your breathing.', 'Add a gentle incline on a treadmill to increase effort without running.', 'Swing your arms naturally and stand tall.', 'Keep the effort conversational for the prescribed time.']::text[], array['Tall posture', 'Conversational pace', 'Arms swing naturally']::text[], array['Holding treadmill rails', 'Too steep too soon', 'Overstriding']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('a59bbdba-02a5-54f7-b57f-80db7677d4a2', 'shadowboxing', 'Shadowboxing', array['shoulders', 'cardiovascular system']::text[], array['core', 'calves']::text[], array['bodyweight']::text[], 'conditioning', 'conditioning', 'compound', 'beginner', true, false, 'Throwing punches and moving in stance without a target — builds rhythm, footwork and endurance.', array['Take a boxing stance with hands up guarding your face.', 'Move on the balls of your feet, staying light.', 'Throw straight punches, hooks and uppercuts in combinations without locking the elbows.', 'Mix in defensive movement (slips, rolls) and footwork for each round.']::text[], array['Hands back to guard', 'Exhale on each strike', 'Stay light on your feet']::text[], array['Dropping the hands', 'Hyperextending elbows', 'Standing flat-footed']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('9c86af10-9366-5884-a2b5-da53bc0294ca', 'heavy-bag-rounds', 'Heavy Bag Rounds', array['shoulders', 'core', 'cardiovascular system']::text[], array['chest', 'triceps', 'hips']::text[], array['heavy_bag']::text[], 'conditioning', 'conditioning', 'compound', 'intermediate', true, false, 'Timed rounds of striking a heavy bag. Use hand wraps and gloves.', array['Wrap your hands and put on bag gloves.', 'Take your stance at arm''s length from the bag.', 'Throw combinations with good form, moving around the bag between flurries.', 'Work for the prescribed round time, then rest.']::text[], array['Rotate from the hips', 'Return to guard', 'Pace your output']::text[], array['Punching without wraps/gloves', 'Pushing instead of striking', 'Gassing out in the first minute']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('7579a68a-dd81-5fec-96d3-c1c142c1dbec', 'battle-rope-waves', 'Battle Rope Waves', array['shoulders', 'cardiovascular system']::text[], array['core', 'forearms', 'legs']::text[], array['battle_rope']::text[], 'conditioning', 'conditioning', 'compound', 'beginner', true, true, 'Creating waves with heavy ropes for upper-body-dominant intervals.', array['Hold one rope end in each hand and stand in a half squat.', 'Alternate raising and lowering your arms quickly to create waves.', 'Keep your core braced and maintain the waves to the anchor.']::text[], array['Athletic stance', 'Fast hands', 'Waves reach the anchor']::text[], array['Standing straight up', 'Tiny waves', 'Holding breath']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('93d8ff12-fe6c-52ca-95f3-b725628e909f', 'lateral-shuffle', 'Lateral Shuffle', array['glutes', 'adductors']::text[], array['calves', 'quadriceps']::text[], array['bodyweight']::text[], 'conditioning', 'conditioning', 'compound', 'beginner', true, false, 'Side-to-side athletic shuffling for footwork and change of direction.', array['Get into an athletic stance with knees bent and chest up.', 'Push off your trailing foot to shuffle sideways without crossing your feet.', 'After a few steps, plant and shuffle back the other way.']::text[], array['Stay low', 'Don''t click heels', 'Push, don''t reach']::text[], array['Standing tall', 'Crossing feet', 'Leaning the torso']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('b706c2f6-7278-5ade-9bdf-9a0cc6a7b9e9', 'hip-escape', 'Hip Escape (Shrimp)', array['core', 'hips']::text[], array['obliques', 'glutes']::text[], array['mat']::text[], 'conditioning', 'conditioning', 'compound', 'beginner', true, false, 'A fundamental grappling movement drill: travelling along the mat by moving the hips away.', array['Lie on your back with knees bent and feet on the mat.', 'Push off one foot and turn onto your side, driving your hips backward away from an imaginary opponent.', 'Frame with your hands as your hips move.', 'Return to your back and repeat to the other side, travelling down the mat.']::text[], array['Hips move first', 'Frame with the arms', 'Turn onto the shoulder']::text[], array['Staying flat on the back', 'Pushing only with arms', 'Not turning to the side']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('9e7b9fa4-211b-523f-8dae-959ed5ef72e0', 'cat-cow', 'Cat-Cow', array['spine']::text[], array['core', 'neck']::text[], array['mat']::text[], 'mobility', 'mobility', null, 'beginner', false, true, 'Gently flexing and extending the spine on hands and knees.', array['Start on hands and knees.', 'Inhale as you let your belly drop and lift your chest and tailbone (cow).', 'Exhale as you round your back toward the ceiling and tuck your chin (cat).', 'Move slowly with your breath.']::text[], array['Move with the breath', 'Segment the spine', 'Pain-free range']::text[], array['Rushing', 'Forcing end range', 'Only moving the neck']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('478f8361-bdb3-55ff-b2e3-798cb7a2fcab', 'worlds-greatest-stretch', 'World''s Greatest Stretch', array['hip flexors', 'hamstrings', 'thoracic spine']::text[], array['adductors', 'glutes']::text[], array['bodyweight']::text[], 'mobility', 'mobility', null, 'beginner', false, false, 'A lunge-based flow combining hip, hamstring and upper-back mobility — a great warm-up.', array['Step into a long lunge and place both hands inside the front foot.', 'Drop your inside elbow toward the front foot''s instep.', 'Rotate and reach the same arm to the ceiling, following it with your eyes.', 'Return the hand down, straighten the front leg for a hamstring stretch, then switch sides.']::text[], array['Back leg long', 'Rotate through upper back', 'Breathe out into each position']::text[], array['Rushing', 'Back knee collapsing', 'Forcing range']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('91fd27fe-1075-5ed1-a3c8-de3636a33b50', '90-90-hip-switch', '90/90 Hip Switch', array['hip rotators']::text[], array['glutes', 'adductors']::text[], array['mat']::text[], 'mobility', 'mobility', null, 'beginner', false, true, 'Rotating the hips between internal and external rotation while seated.', array['Sit with both knees bent at about 90 degrees, one leg in front and one to the side.', 'Sit tall, using your hands behind you for support if needed.', 'Rotate both knees to the other side so the legs switch positions.', 'Continue switching slowly and with control.']::text[], array['Sit tall', 'Slow transitions', 'Use hands if needed']::text[], array['Slumping', 'Forcing the knees down', 'Moving quickly']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('4ca92770-cc91-5a2a-828f-01e86dce89fc', 'thoracic-open-book', 'Thoracic Open Book', array['thoracic spine']::text[], array['chest', 'shoulders']::text[], array['mat']::text[], 'mobility', 'mobility', null, 'beginner', false, true, 'A side-lying rotation that improves upper-back mobility.', array['Lie on your side with knees bent to 90 degrees and arms extended in front of you.', 'Keep your knees together and open your top arm across your body like a book.', 'Follow your hand with your eyes and rotate as far as comfortable.', 'Return slowly and repeat, then switch sides.']::text[], array['Knees stay stacked', 'Rotate the rib cage', 'Exhale as you open']::text[], array['Knees lifting apart', 'Forcing the arm to the floor', 'Holding the breath']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('57fb2ce8-405e-5a57-b3af-60d3e93b5aa2', 'couch-stretch', 'Couch Stretch', array['hip flexors', 'quadriceps']::text[], '{}'::text[], array['mat']::text[], 'mobility', 'mobility', null, 'intermediate', true, false, 'A kneeling hip-flexor and quad stretch with the back foot elevated.', array['Kneel with your back to a couch or wall, placing one shin up against it.', 'Step the other foot forward into a half-kneeling position.', 'Squeeze the glute of the down leg and tuck your pelvis.', 'Hold the stretch, then switch sides. Use a lower elevation if this is intense.']::text[], array['Squeeze the glute', 'Tuck the pelvis', 'Pad the knee']::text[], array['Arching the lower back', 'Going too deep too soon', 'Bare knee on hard floor']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('40d84c3e-5194-5aaa-8ba0-5f74903b28ba', 'supine-hamstring-stretch', 'Supine Hamstring Stretch', array['hamstrings']::text[], array['calves']::text[], array['band', 'mat']::text[], 'mobility', 'mobility', null, 'beginner', true, true, 'Lying on your back and raising a straight leg with a band or towel.', array['Lie on your back and loop a band or towel around one foot.', 'Keep the other leg bent or flat on the floor.', 'Raise the looped leg with a soft knee until you feel a gentle stretch.', 'Hold and breathe, then switch sides.']::text[], array['Gentle tension', 'Hips stay down', 'Breathe slowly']::text[], array['Yanking the leg', 'Lifting the hips', 'Locking the knee hard']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('e14235bb-fe7b-5c34-acea-7d2fe278b788', 'childs-pose', 'Child''s Pose', array['lower back', 'lats']::text[], array['hips', 'shoulders']::text[], array['mat']::text[], 'mobility', 'mobility', null, 'beginner', true, true, 'A restful kneeling stretch for the back, hips and shoulders.', array['Kneel and sit your hips back toward your heels, knees apart as comfortable.', 'Walk your hands forward and rest your forehead on the mat or a pillow.', 'Breathe deeply into your back.']::text[], array['Long exhales', 'Reach through fingertips', 'Support with pillows if needed']::text[], array['Forcing hips down', 'Tensing shoulders', 'Holding breath']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('01177fed-1cfd-547d-be52-6ff5bc8eedc6', 'ankle-knee-to-wall', 'Knee-to-Wall Ankle Mobility', array['ankles', 'calves']::text[], '{}'::text[], array['bodyweight']::text[], 'mobility', 'mobility', null, 'beginner', false, true, 'Driving the knee toward a wall over the toes to improve ankle dorsiflexion.', array['Face a wall in a half-kneeling or split stance with the front foot a few inches from the wall.', 'Keeping the heel down, drive the front knee forward to touch the wall.', 'Return and repeat, moving the foot back slightly as mobility improves.']::text[], array['Heel stays down', 'Knee tracks over 2nd toe', 'Smooth rocks']::text[], array['Heel lifting', 'Knee collapsing inward', 'Bouncing']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('11200ed2-83d7-5157-ac59-e560dce6c5d5', 'band-pass-through', 'Band Shoulder Pass-Through', array['shoulders', 'chest']::text[], array['upper back']::text[], array['band']::text[], 'mobility', 'mobility', null, 'beginner', false, true, 'Passing a band from in front of the hips to behind the back with straight arms.', array['Hold a light band with a very wide grip in front of your hips.', 'With straight arms, raise the band overhead and behind you as far as comfortable.', 'Reverse the motion to return to the front.', 'Narrow your grip only as comfort allows.']::text[], array['Wide grip', 'Ribs down', 'Pain-free range only']::text[], array['Grip too narrow', 'Arching the back', 'Forcing through pinching']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('f22015a1-4de3-5166-9917-d100a0b70718', 'deep-squat-hold', 'Deep Squat Hold', array['hips', 'ankles']::text[], array['adductors', 'lower back']::text[], array['bodyweight']::text[], 'mobility', 'mobility', null, 'beginner', true, false, 'Resting in the bottom of a squat to improve hip and ankle mobility.', array['Stand with feet slightly wider than shoulders, toes turned out.', 'Sit down into a deep squat, holding onto a post or door frame if needed.', 'Use your elbows to gently press your knees out.', 'Breathe and hold for the prescribed time.']::text[], array['Heels down (elevate if needed)', 'Chest up', 'Relax into it']::text[], array['Forcing past discomfort', 'Heels lifting', 'Rounding hard']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('23f9503b-882b-5ac2-88c9-7542b301ba3c', 'figure-four-stretch', 'Figure-Four Glute Stretch', array['glutes', 'hip rotators']::text[], '{}'::text[], array['mat']::text[], 'mobility', 'mobility', null, 'beginner', true, true, 'Crossing one ankle over the opposite knee to stretch the glutes.', array['Lie on your back with knees bent.', 'Cross one ankle over the opposite thigh.', 'Pull the bottom thigh toward your chest until you feel a stretch in the crossed leg''s glute.', 'Hold, then switch sides. This can also be done seated in a chair.']::text[], array['Flex the top foot', 'Head relaxed', 'Gentle pull']::text[], array['Lifting the head', 'Pulling too hard', 'Holding breath']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('df7455a7-5c9e-51f7-8ec9-64ebc9b5333d', 'single-leg-balance', 'Single-Leg Balance', array['foot and ankle stabilizers']::text[], array['glutes', 'core']::text[], array['bodyweight']::text[], 'mobility', 'mobility', null, 'beginner', true, true, 'Standing on one leg to train balance — keep a support within reach.', array['Stand next to a counter or wall for safety.', 'Lift one foot slightly off the floor and balance on the other.', 'Use fingertip support as needed, removing it as balance improves.', 'Hold for the prescribed time and switch legs.']::text[], array['Soft standing knee', 'Eyes on a fixed point', 'Support within reach']::text[], array['Locking the knee', 'Holding breath', 'Training without support nearby']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('db7805bc-6353-5b8c-b66c-fbe0d879b23c', 'standing-march', 'Standing March', array['hip flexors', 'core']::text[], array['calves']::text[], array['bodyweight']::text[], 'cardio', 'conditioning', null, 'beginner', true, true, 'Marching in place with alternating knee lifts — gentle cardio and balance work.', array['Stand tall near a support if needed.', 'Lift one knee toward hip height, then lower and lift the other.', 'Swing the arms naturally and keep a steady rhythm.']::text[], array['Tall posture', 'Controlled lifts', 'Steady breathing']::text[], array['Leaning back', 'Stomping', 'Holding breath']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('809c6bdb-54e9-554f-a5ba-fce61fb1b2b6', 'paused-bench-press', 'Paused Bench Press', array['chest', 'triceps']::text[], array['front delts', 'lats']::text[], array['barbell', 'bench', 'rack']::text[], 'strength', 'horizontal_push', 'compound', 'intermediate', false, false, 'A bench press with a deliberate, motionless pause on the chest — the way the lift is judged in competition. Builds strength off the chest and bar-path control.', array['Set up as for a regular bench press: eyes under the bar, shoulder blades squeezed together, feet planted.', 'Unrack and lower the bar under control to your lower chest.', 'Hold the bar motionless on your chest for 1–2 seconds while staying tight — don''t sink or relax.', 'Press the bar up and slightly back toward your face to lockout.']::text[], array['Stay tight in the pause', 'Touch the same spot every rep', 'Drive your feet into the floor as you press']::text[], array['Bouncing or sinking the bar into the chest', 'Losing upper-back tightness during the pause', 'Lifting the hips off the bench']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('61847406-f414-5c18-bab1-f9271bbe0f67', 'pin-press', 'Pin Press (Bench)', array['triceps', 'chest']::text[], array['front delts']::text[], array['barbell', 'rack', 'bench']::text[], 'strength', 'horizontal_push', 'compound', 'advanced', false, false, 'A partial-range bench press started from safety pins set a few inches above the chest. Overloads the top half of the press and lockout. A board press is a close alternative.', array['Place a bench inside a power rack and set the safety pins 2–4 inches (5–10 cm) above your chest at the bottom of a press.', 'Set up with your normal bench grip and arch, with the bar resting on the pins.', 'Brace, then press the bar off the pins to full lockout.', 'Lower under control back to the pins, let it settle completely, and repeat.']::text[], array['Dead stop on every rep', 'Elbows under the bar', 'Squeeze the bar hard']::text[], array['Bouncing off the pins', 'Pins set so high the range is trivial', 'Losing shoulder-blade position']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('1930e372-8382-5a36-be4d-4fe0ed63ae25', 'pause-squat', 'Pause Squat', array['quadriceps', 'glutes']::text[], array['adductors', 'spinal erectors', 'core']::text[], array['barbell', 'rack']::text[], 'strength', 'squat', 'compound', 'intermediate', false, false, 'A back squat with a 2–3 second hold in the bottom position. Teaches you to stay braced at depth and builds strength out of the hole.', array['Unrack the bar as for a back squat and set your stance.', 'Brace and descend under control to your normal depth.', 'Hold the bottom position for the prescribed count (usually 2–3 seconds) without relaxing or shifting.', 'Drive up out of the hole, keeping the chest up and knees tracking over the toes.']::text[], array['Stay braced in the hole', 'Count the pause honestly', 'Drive the upper back into the bar']::text[], array['Relaxing and losing tension at the bottom', 'Cutting the pause short', 'Loading as heavy as a normal squat']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('fcca9705-1f13-5a98-be73-b6a597140f2e', 'tempo-squat', 'Tempo Squat', array['quadriceps', 'glutes']::text[], array['adductors', 'core']::text[], array['barbell', 'rack']::text[], 'strength', 'squat', 'compound', 'intermediate', false, false, 'A back squat with a slow, controlled lowering phase (typically 3–5 seconds). Reinforces bar path and positioning with lighter loads.', array['Unrack the bar and set your stance as for a back squat.', 'Lower for the prescribed count (for example 4 seconds), keeping the bar over mid-foot.', 'Reach your normal depth without pausing unless instructed.', 'Stand up with normal speed and reset your brace before the next rep.']::text[], array['Slow and smooth on the way down', 'Same position every rep', 'Breathe and brace before each rep']::text[], array['Rushing the last part of the descent', 'Using too much load to control the tempo', 'Shifting onto the toes']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('9942894f-f006-5cfd-9772-6f300523bae1', 'box-squat', 'Barbell Box Squat', array['glutes', 'hamstrings', 'quadriceps']::text[], array['adductors', 'spinal erectors']::text[], array['barbell', 'rack', 'box']::text[], 'strength', 'squat', 'compound', 'intermediate', false, false, 'A back squat to a box set at or just below parallel. Teaches sitting back, builds hip strength and is often used for speed (dynamic-effort) work.', array['Place a sturdy box or bench behind you so the top is at or slightly below parallel when you squat to it.', 'Unrack the bar and take a stance slightly wider than your normal squat.', 'Sit back and down under control until you are seated on the box — don''t crash onto it.', 'Keep your brace, pause briefly, then drive your hips and chest up together to stand.']::text[], array['Sit back, shins near vertical', 'Stay tight on the box', 'Explode up']::text[], array['Dropping onto the box', 'Rocking back and relaxing on the box', 'Box set far too high']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('2ebf39f5-55e0-58d3-889e-62919d68f7d3', 'deficit-deadlift', 'Deficit Deadlift', array['hamstrings', 'glutes', 'spinal erectors']::text[], array['quadriceps', 'lats', 'forearms']::text[], array['barbell']::text[], 'strength', 'hinge', 'compound', 'advanced', false, false, 'A deadlift performed standing on a 1–3 inch (2.5–7.5 cm) platform, increasing range of motion to build strength off the floor.', array['Stand on a stable plate or low platform with the bar over mid-foot.', 'Hinge down and grip the bar; the deeper start will require more knee and hip bend.', 'Brace, pull the slack out of the bar and set your back flat.', 'Push the floor away to lift the bar, keeping it close, and finish standing tall.']::text[], array['Keep the bar touching your legs', 'Push the floor away', 'Chest and hips rise together']::text[], array['Using too high a deficit', 'Hips shooting up first', 'Rounding the lower back to reach the bar']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('f13cf4b7-2ab4-5172-8b1d-a46d4018338e', 'block-pull', 'Block Pull (Rack Pull)', array['glutes', 'spinal erectors', 'upper back']::text[], array['hamstrings', 'traps', 'forearms']::text[], array['barbell', 'rack']::text[], 'strength', 'hinge', 'compound', 'intermediate', false, false, 'A partial deadlift started with the plates on blocks or the bar on rack pins around knee height. Overloads lockout and builds upper-back strength.', array['Set the bar on blocks or rack pins so it starts just below or at your knees.', 'Set up as for a deadlift: grip, brace and pull the slack out of the bar.', 'Drive the hips forward to lock out, finishing tall with glutes squeezed.', 'Lower under control back to the blocks or pins and reset each rep.']::text[], array['Wedge in before you pull', 'Hips through to finish', 'Don''t lean back at lockout']::text[], array['Hyperextending the lower back at the top', 'Bouncing off the pins', 'Starting so high it becomes a shrug']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('fda7a430-e50a-56b6-b745-1e2a8db9099b', 'good-morning', 'Barbell Good Morning', array['hamstrings', 'spinal erectors']::text[], array['glutes', 'upper back']::text[], array['barbell', 'rack']::text[], 'strength', 'hinge', 'compound', 'intermediate', false, false, 'A hip hinge with the bar on your back that strengthens the posterior chain for squatting and deadlifting. Use moderate loads.', array['Unrack a light-to-moderate bar onto your upper back as for a back squat.', 'With a soft knee bend, push your hips back and lower your torso while keeping your back flat.', 'Stop when you feel a strong hamstring stretch or your torso nears parallel — whichever comes first.', 'Drive your hips forward to return to standing.']::text[], array['Hips back, not down', 'Flat back throughout', 'Bar stays over mid-foot']::text[], array['Rounding the back', 'Going heavy too early', 'Turning it into a squat']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('967fa69c-5094-5faa-9091-3f63b6c78fd0', 'log-press', 'Log Clean & Press', array['front delts', 'triceps']::text[], array['upper chest', 'upper back', 'glutes', 'core']::text[], array['strongman_implements']::text[], 'strength', 'vertical_push', 'compound', 'advanced', false, false, 'The classic strongman overhead event: clean a log with neutral handles to the chest, then press or push-press it overhead.', array['Roll or deadlift the log to your lap, then roll it up your torso to the rack position on your chest (the clean).', 'Set your elbows high, take a big breath and brace.', 'Dip with the knees and drive the log overhead, moving your head back and then through once it passes your face.', 'Lock out with the log over your mid-foot, then lower under control to the chest or lap.']::text[], array['Elbows up in the rack', 'Dip straight down, drive straight up', 'Head through at lockout']::text[], array['Pressing from a poor rack with elbows down', 'Leaning back excessively', 'Dropping the log from overhead onto the body']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('80cbc61c-e1c4-5b3d-975a-0df38cc9702e', 'yoke-carry', 'Yoke Carry', array['upper back', 'core', 'quadriceps']::text[], array['glutes', 'calves', 'traps']::text[], array['strongman_implements']::text[], 'strength', 'carry', 'compound', 'advanced', true, false, 'Carrying a loaded yoke frame on your upper back over a set distance — heavy bracing under load with fast, short steps.', array['Set the yoke crossbar at upper-back height and get under it as for a back squat.', 'Grip the uprights, brace hard and stand the yoke up.', 'Walk with short, quick steps, keeping the yoke level and your eyes forward.', 'Set it down under control at the end of the distance or if it begins to swing.']::text[], array['Short, fast steps', 'Brace like a heavy squat', 'Push up into the bar']::text[], array['Long strides that make the yoke swing', 'Looking down', 'Losing the brace mid-run']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('2fa09726-cca7-53e2-a302-bf81dd04f052', 'atlas-stone-load', 'Atlas Stone Load', array['glutes', 'hamstrings', 'spinal erectors']::text[], array['biceps', 'upper back', 'quadriceps', 'forearms']::text[], array['strongman_implements']::text[], 'strength', 'hinge', 'compound', 'advanced', false, false, 'Lifting a round stone from the floor to the lap and then onto a platform or over a bar. Use tacky only where permitted and start light.', array['Stand over the stone with feet wide, reach down and wrap your arms and fingers around it.', 'Lift the stone to your lap by extending the hips, sitting back slightly to cradle it.', 'Re-grip high on the stone, then drive the hips forward and extend upward to roll it onto the platform.', 'Step back and lower the stone under control or let it roll off the platform away from your feet.']::text[], array['Hug the stone tight to your body', 'Lap, re-grip, extend', 'Hips through to finish']::text[], array['Trying to lift the stone with straight arms only', 'Feet too narrow', 'Going straight to maximal stones without practice']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('5f1cb047-74bd-508d-a3e3-9ddb99498866', 'a-skip', 'A-Skip', array['hip flexors', 'calves']::text[], array['glutes', 'core']::text[], array['bodyweight']::text[], 'plyometric', 'power', 'compound', 'beginner', false, false, 'A rhythmic sprint drill that rehearses knee drive, upright posture and an active foot strike under the hips.', array['Stand tall and begin skipping forward, driving one knee up to about hip height.', 'Keep the foot of the lifted leg pulled up (toes toward the shin).', 'Strike the ground actively under your hips with the ball of the foot, then switch legs.', 'Swing your arms in opposition, elbows around 90 degrees, for the prescribed distance.']::text[], array['Tall hips', 'Knee up, toe up', 'Punch the ground down and back']::text[], array['Leaning back', 'Landing out in front of the body', 'Floppy, relaxed ankles']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('e41e1d32-24ae-54dd-8f8d-1b5c92ffa06e', 'wall-drill', 'Acceleration Wall Drill', array['hip flexors', 'glutes']::text[], array['calves', 'core']::text[], array['bodyweight']::text[], 'plyometric', 'power', 'compound', 'beginner', false, false, 'Leaning into a wall at an acceleration angle to practice body lean, knee drive and fast, piston-like leg exchanges.', array['Place your hands on a wall at shoulder height and walk your feet back until your body forms a straight line at about 45 degrees.', 'Drive one knee up so the thigh is roughly parallel to the floor, toes pulled up.', 'On the cue, switch legs quickly, punching the down leg into the ground behind your hips.', 'Perform single, double or triple exchanges as prescribed, holding the straight-line posture.']::text[], array['Straight line from head to heel', 'Punch the ground behind you', 'Quick switches']::text[], array['Piking at the hips', 'Stepping forward instead of under', 'Slow, lazy exchanges']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('c5eb307e-2c5f-532d-8e50-8d96577b14d4', 'acceleration-sprint', 'Acceleration Sprint', array['glutes', 'quadriceps', 'hamstrings']::text[], array['calves', 'hip flexors', 'core']::text[], array['bodyweight']::text[], 'conditioning', 'power', 'compound', 'intermediate', false, false, 'Short maximal sprints of 10–30 m from a static or crouched start, trained with full recovery to improve first-step quickness.', array['Warm up thoroughly with drills and two or three build-up runs before any maximal sprint.', 'Start from a two-point (staggered stance) or three-point position.', 'Push hard out of the start with a forward lean, driving the knees and pushing the ground behind you.', 'Rise gradually over the first 10–15 m and sprint through the finish mark; walk back and rest fully between reps.']::text[], array['Push, don''t reach', 'Lean from the ankles', 'Powerful arm drive']::text[], array['Standing straight up out of the start', 'Over-striding', 'Shortening rest so the reps become conditioning']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('c2df350a-8c0c-55a5-82fd-dbd20a047cc9', 'flying-sprint', 'Flying Sprint', array['hamstrings', 'glutes', 'hip flexors']::text[], array['calves', 'quadriceps', 'core']::text[], array['bodyweight']::text[], 'conditioning', 'power', 'compound', 'advanced', false, false, 'A build-up zone of 20–30 m followed by a 10–30 m segment at maximal speed. Develops top-end (maximal) velocity.', array['Mark a build-up zone (20–30 m) followed by a fly zone (10–30 m).', 'Gradually accelerate through the build-up zone, reaching near top speed as you enter the fly zone.', 'Sprint the fly zone at maximal speed with tall posture and relaxed face and shoulders.', 'Decelerate gradually afterwards and rest fully (3–5 minutes) before the next rep.']::text[], array['Run tall', 'Fast, relaxed', 'Step over the opposite knee']::text[], array['Sprinting maximally while under-warmed', 'Tensing the face and shoulders', 'Stopping abruptly after the fly zone']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('dba265bf-5f10-508c-8708-4b2e92f57993', 'bounding', 'Bounding', array['glutes', 'hamstrings', 'calves']::text[], array['quadriceps', 'hip flexors', 'core']::text[], array['bodyweight']::text[], 'plyometric', 'power', 'compound', 'advanced', false, false, 'Exaggerated, powerful running strides that emphasize horizontal force and elastic stiffness. A staple speed-strength exercise.', array['Begin with a short jog to build rhythm.', 'Push off one leg, driving the opposite knee forward and up to cover as much distance as possible.', 'Land on the ball of the foot under your hips and immediately push into the next bound.', 'Use big opposite-arm swings and perform the prescribed distance or number of contacts.']::text[], array['Push long', 'Stay tall', 'Quick ground contacts']::text[], array['Landing heel-first far in front', 'Too many contacts while fatigued', 'Collapsing at the hip on landing']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('5c69f61f-f5d2-5e4f-86ff-f54a72d0e7c7', 'pogo-jumps', 'Pogo Jumps', array['calves']::text[], array['quadriceps', 'core']::text[], array['bodyweight']::text[], 'plyometric', 'power', 'compound', 'beginner', false, false, 'Small, rapid, stiff-ankle hops that build ankle stiffness and reactive strength for sprinting and change of direction.', array['Stand tall with feet hip-width apart and hands on hips or relaxed.', 'Bounce off the balls of your feet using mainly the ankles, keeping the knees only slightly bent.', 'Spend as little time on the ground as possible, as if the floor were hot.', 'Perform the prescribed number of contacts, stopping if rhythm or quality fades.']::text[], array['Stiff ankles', 'Quick off the ground', 'Stay tall']::text[], array['Bending the knees deeply', 'Landing on the heels', 'Turning it into slow, high jumps']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('e22ff9a8-4712-5d9c-b095-b149989d80a2', 'pro-agility-shuttle', '5-10-5 Pro Agility Shuttle', array['quadriceps', 'glutes', 'adductors']::text[], array['calves', 'hamstrings', 'core']::text[], array['bodyweight']::text[], 'conditioning', 'conditioning', 'compound', 'intermediate', false, false, 'A classic change-of-direction test and drill: 5 yards one way, 10 yards back, 5 yards through the middle. Use cones or any markers.', array['Place three markers in a line 5 yards (about 4.5 m) apart and straddle the middle one in a low athletic stance.', 'Sprint 5 yards to one side and touch the line with your hand.', 'Plant, turn and sprint 10 yards to the far line and touch it.', 'Plant and turn again, then sprint 5 yards back through the middle marker. Rest fully between reps.']::text[], array['Low hips into the turn', 'Plant the outside foot', 'Push out of the cut']::text[], array['Rounding the turn instead of planting', 'Standing up tall before each cut', 'Reps done tired with sloppy plants']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('f0452657-e876-523b-836c-33cd307df059', 't-drill', 'T-Drill', array['quadriceps', 'glutes', 'adductors']::text[], array['calves', 'hamstrings']::text[], array['bodyweight']::text[], 'conditioning', 'conditioning', 'compound', 'intermediate', false, false, 'A change-of-direction drill combining a forward sprint, lateral shuffles both ways and a backpedal around four markers laid out in a T.', array['Set a start marker, a marker 10 yards ahead, and two more 5 yards to each side of the far marker.', 'Sprint forward to the middle marker and touch it.', 'Shuffle left 5 yards and touch, shuffle right 10 yards and touch, then shuffle back to the middle.', 'Backpedal to the start. Rest fully between reps.']::text[], array['Don''t cross your feet on the shuffle', 'Stay low through the transitions', 'Eyes forward']::text[], array['Crossing the feet', 'Standing up between movements', 'Drifting wide of the markers']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('957b1c8d-9b7c-5c38-847e-d6a268b2fdae', 'three-cone-drill', 'Three-Cone (L) Drill', array['quadriceps', 'glutes']::text[], array['adductors', 'calves', 'core']::text[], array['bodyweight']::text[], 'conditioning', 'conditioning', 'compound', 'intermediate', false, false, 'Three markers set in an L, 5 yards apart, run with sharp cuts and a tight turn around the far cone — trains deceleration and re-acceleration.', array['Set three markers in an L shape, each 5 yards apart.', 'Sprint to the second marker and touch the line, then sprint back to the start and touch.', 'Sprint back to the second marker, turn tightly around it, weave around the third marker and come back around the second.', 'Finish by sprinting past the start marker. Rest fully between reps.']::text[], array['Lean into the turns', 'Short steps to decelerate', 'Explode out of each cut']::text[], array['Wide, looping turns', 'Decelerating too late', 'Rushing reps without full recovery']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('4bb90d46-f620-5a9c-a503-c559239d78ad', 'agility-ladder-drills', 'Agility Ladder Drills', array['calves', 'hip flexors']::text[], array['quadriceps', 'adductors', 'core']::text[], array['bodyweight']::text[], 'conditioning', 'conditioning', 'compound', 'beginner', true, false, 'Footwork patterns (two-in, lateral in-out, Icky shuffle, crossovers) through an agility ladder — or lines taped or chalked on the floor.', array['Lay out an agility ladder, or tape or chalk 10 boxes about 18 inches (45 cm) apart on the floor.', 'Start with simple patterns such as one foot in each box, then two feet in each box.', 'Progress to lateral in-in-out-out and the Icky shuffle as rhythm improves.', 'Stay on the balls of your feet and keep each rep crisp for the prescribed time.']::text[], array['Light, quick feet', 'Arms drive the rhythm', 'Eyes up, not on your feet']::text[], array['Watching your feet the whole time', 'Flat-footed contacts', 'Sacrificing accuracy for speed']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('ceb5a8cc-c1f0-58e3-8554-a6318204dd99', 'reactive-mirror-drill', 'Reactive Mirror Drill', array['quadriceps', 'glutes', 'adductors']::text[], array['calves', 'core']::text[], array['bodyweight']::text[], 'conditioning', 'conditioning', 'compound', 'intermediate', true, false, 'A partner leads with random shuffles, sprints and backpedals while you mirror them as quickly as possible. Trains perception and reaction, not just planned cuts. Solo option: react to random visual or audio cues.', array['Face a partner 3–5 yards away inside a small marked area, both in athletic stances.', 'Your partner moves unpredictably — shuffles, short sprints, backpedals.', 'Mirror their movement as fast as possible, staying square and balanced.', 'Work for short bouts (5–10 seconds) with full rest; switch leader each round.']::text[], array['Read the hips, not the head', 'Stay low and balanced', 'First step fast']::text[], array['Bouts that are too long', 'Crossing the feet', 'Guessing instead of reacting']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('c631f157-eb87-5892-b2e7-9fed9e607975', 'lateral-bound', 'Lateral Bound (Skater Jump)', array['glutes', 'adductors', 'quadriceps']::text[], array['calves', 'core']::text[], array['bodyweight']::text[], 'plyometric', 'power', 'compound', 'intermediate', false, false, 'Single-leg sideways jumps that build lateral power and the ability to absorb force on one leg — key for cutting.', array['Stand on your right leg in a quarter squat.', 'Push off powerfully to jump sideways to the left, landing softly on your left leg.', 'Stick the landing for a moment, hips back and knee tracking over the toes.', 'Bound back to the right. Add a quick rebound once landings are stable.']::text[], array['Push the ground away sideways', 'Stick the landing', 'Knee over toes']::text[], array['Knee caving on landing', 'Jumping for distance before you can stick it', 'Landing stiff-legged']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('66025b63-53b7-5ff1-826c-f453bb5b1281', 'zone-2-run', 'Easy Zone 2 Run', array['cardiovascular system']::text[], array['calves', 'quadriceps', 'glutes']::text[], array['bodyweight']::text[], 'cardio', 'conditioning', 'compound', 'beginner', true, false, 'Continuous running at an easy, conversational effort (roughly zone 2 — you can speak in full sentences). Builds the aerobic base.', array['Start with a 3–5 minute brisk walk.', 'Run at a pace where you can still speak in full sentences — slower than feels necessary.', 'Keep a short, quick stride with your feet landing under your hips.', 'If breathing becomes labored, slow down or walk briefly, then continue for the prescribed time.']::text[], array['Conversational pace', 'Short, light steps', 'Relaxed shoulders']::text[], array['Running every easy run too fast', 'Over-striding and heel striking far in front', 'Increasing weekly time too quickly']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('b15e921d-c014-5f44-bc28-44abd4c4cf67', 'run-walk-intervals', 'Run/Walk Intervals', array['cardiovascular system']::text[], array['calves', 'quadriceps']::text[], array['bodyweight']::text[], 'cardio', 'conditioning', 'compound', 'beginner', true, false, 'Alternating easy running and brisk walking. The proven way for new runners to build up to continuous running without overdoing it.', array['Warm up with 5 minutes of brisk walking.', 'Run easily for the prescribed interval at a conversational pace.', 'Walk briskly for the recovery period (shown as rest) — keep moving.', 'Repeat for the prescribed number of rounds, then cool down with an easy walk.']::text[], array['Easy, not fast', 'Walk with purpose', 'Finish feeling you could do more']::text[], array['Running the intervals too fast', 'Skipping the walk breaks', 'Jumping ahead in the progression']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('4cb3891d-4641-5c34-a598-f8954f2d52f2', 'running-intervals', 'Running Intervals', array['cardiovascular system']::text[], array['hamstrings', 'calves', 'glutes']::text[], array['bodyweight']::text[], 'cardio', 'conditioning', 'compound', 'intermediate', true, false, 'Repeated hard running efforts (for example 1–4 minutes at a strong, controlled pace) with easy jog or walk recoveries. Raises aerobic capacity and speed endurance.', array['Warm up with 10 minutes of easy running plus a few short strides.', 'Run each interval at a hard but sustainable effort — you could only speak a few words.', 'Recover with easy jogging or walking for the prescribed rest.', 'Keep every interval at a similar pace; stop the session if pace falls apart.']::text[], array['Even pace across reps', 'Relaxed upper body', 'Recover actively']::text[], array['Sprinting the first rep and fading', 'Doing intervals on consecutive days', 'Skipping the warm-up']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('57825e2f-f3f2-5b6b-9fac-2762558113f2', 'stair-climb', 'Stair Climber / Stair Climb', array['cardiovascular system', 'glutes', 'quadriceps']::text[], array['calves', 'hamstrings']::text[], array['bodyweight']::text[], 'cardio', 'conditioning', 'compound', 'beginner', true, true, 'Steady climbing on a stair-climber machine or a flight of stairs. A low-impact way to raise heart rate and build leg endurance.', array['Use a stair-climber machine, or a safe flight of stairs with a handrail.', 'Stand tall and place your whole foot on each step, pushing through the heel.', 'Choose a pace you can sustain for the prescribed time at the target effort.', 'On real stairs, walk down carefully between climbs as recovery.']::text[], array['Tall posture', 'Whole foot on the step', 'Light hands on the rails']::text[], array['Leaning heavily on the handrails', 'Rising onto the toes only', 'Starting too fast']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('ab482996-9bda-567a-98b2-a74a90b2bdf8', 'cable-chest-fly', 'Cable Chest Fly', array['chest']::text[], array['front delts']::text[], array['cable', 'dumbbell']::text[], 'strength', 'isolation', 'isolation', 'beginner', false, false, 'A chest isolation movement using cables (or dumbbells on a bench) that keeps tension on the pecs through a long range of motion.', array['Set both cable pulleys at about shoulder height (or lie on a bench holding dumbbells above your chest).', 'With a slight bend in the elbows, open your arms wide until you feel a stretch across the chest.', 'Bring the handles together in a hugging arc in front of your chest, squeezing the pecs.', 'Return slowly to the stretched position.']::text[], array['Hug a tree', 'Fixed elbow bend', 'Slow stretch']::text[], array['Turning it into a press by bending the elbows', 'Going too heavy and losing range', 'Shrugging the shoulders']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('57a1edda-bcfd-5524-89f7-7c07daf77fe3', 'rear-delt-fly', 'Rear Delt Fly', array['rear delts']::text[], array['rhomboids', 'middle traps']::text[], array['dumbbell', 'cable', 'machine']::text[], 'strength', 'isolation', 'isolation', 'beginner', false, false, 'Raising light dumbbells out to the sides while hinged forward (or using a cable or reverse pec-deck) to build the rear delts and upper back.', array['Hinge forward with a flat back, holding light dumbbells under your chest with a slight elbow bend.', 'Raise the weights out to the sides, leading with the elbows, until arms are roughly in line with your body.', 'Pause briefly and squeeze the backs of the shoulders.', 'Lower slowly and repeat.']::text[], array['Lead with the elbows', 'Pinkies slightly up', 'No swinging']::text[], array['Using momentum from the torso', 'Shrugging the traps', 'Going too heavy']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('2d8915bb-4ed5-5ead-abb8-766de2c365d1', 'overhead-triceps-extension', 'Overhead Triceps Extension', array['triceps']::text[], array['core']::text[], array['dumbbell', 'cable']::text[], 'strength', 'isolation', 'isolation', 'beginner', false, false, 'Extending the elbows overhead with a dumbbell or cable rope, training the long head of the triceps in a stretched position.', array['Hold one dumbbell with both hands (or a rope attachment facing away from a low cable) above your head.', 'Keep your upper arms close to your head and lower the weight behind your head by bending the elbows.', 'Go to a comfortable deep stretch.', 'Extend the elbows to return to the top without moving the upper arms.']::text[], array['Elbows point forward', 'Ribs down', 'Full stretch, full lockout']::text[], array['Flaring the elbows wide', 'Arching the lower back', 'Moving the upper arms']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('5ac0981f-ccd9-572b-ac1d-9bd7db2e95be', 'axle-clean-and-press', 'Axle Clean & Press', array['front delts', 'triceps']::text[], array['upper back', 'forearms', 'glutes', 'core']::text[], array['strongman_implements']::text[], 'strength', 'vertical_push', 'compound', 'advanced', false, false, 'A thick-handled (about 2-inch) bar cleaned to the shoulders and pressed or push-pressed overhead — a staple strongman pressing event that also hammers grip.', array['Set up over the axle with a double-overhand grip just outside the legs and deadlift it to the hips.', 'Pull it high onto the belt or upper thighs, re-grip if needed, then roll the wrists under to rack it on the front of the shoulders.', 'Dip straight down with the knees and drive the bar overhead, moving your head back and then through.', 'Lock out over mid-foot, then lower under control to the shoulders and the floor.']::text[], array['Elbows fast in the clean', 'Dip and drive — straight down, straight up', 'Head through at lockout']::text[], array['Reverse-curling a heavy axle and straining the biceps', 'Pressing from a soft rack with low elbows', 'Leaning far back instead of driving with the legs']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('74f89801-b0f9-5e78-bc99-2c9210cced6e', 'one-arm-dumbbell-push-press', 'One-Arm Dumbbell Push Press', array['front delts', 'triceps']::text[], array['obliques', 'glutes', 'quadriceps']::text[], array['dumbbell', 'kettlebell']::text[], 'strength', 'vertical_push', 'compound', 'intermediate', false, false, 'A single heavy dumbbell driven overhead with a leg dip — the go-to substitute for the strongman circus dumbbell and a strong unilateral press.', array['Clean or curl one dumbbell to the shoulder with the handle angled slightly and the elbow under the bell.', 'Brace hard, keep the free arm out for balance and dip a few inches with the knees.', 'Drive up through the legs and punch the dumbbell overhead to a locked elbow.', 'Lower to the shoulder under control; finish all reps, then switch arms.']::text[], array['Stack wrist over elbow', 'Short, fast dip', 'Stay tall — don''t side-bend']::text[], array['Leaning sideways to press', 'A long, slow dip that kills the drive', 'Dropping the bell from overhead']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('72eba5c9-358c-5472-af70-99d107bb5614', 'strongman-farmers-walk', 'Farmer''s Walk (Strongman Handles)', array['forearms', 'traps']::text[], array['core', 'glutes', 'quadriceps', 'upper back']::text[], array['strongman_implements']::text[], 'strength', 'carry', 'compound', 'advanced', true, false, 'Picking up heavy farmer''s handles and running them over a set distance as fast as possible — the classic strongman grip and moving event.', array['Stand between the handles with the centre of each handle level with your ankle bone.', 'Grip the middle of the handles, brace and deadlift them up with a flat back.', 'Take short, fast steps, keeping the handles level and your eyes up.', 'Set the handles down under control at the finish line or if your grip starts to open.']::text[], array['Grip in the middle so the handles stay level', 'Quick feet, short steps', 'Shoulders packed, chest up']::text[], array['Long strides that make the handles swing', 'Gripping off-centre so the handles tip', 'Dropping the handles from height onto your feet']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('63f12039-31b2-5e72-8d5d-be6c52f4cd75', 'trap-bar-carry', 'Trap Bar Carry', array['forearms', 'traps']::text[], array['core', 'glutes', 'quadriceps']::text[], array['trap_bar']::text[], 'strength', 'carry', 'compound', 'intermediate', true, false, 'Deadlifting a loaded trap bar and walking with it — the closest gym substitute for strongman farmer''s handles, and easy to load heavy.', array['Load the trap bar and stand in the centre with your feet hip width apart.', 'Grip the handles in the middle, brace and stand up as in a trap bar deadlift.', 'Walk with short, controlled steps, keeping the bar level and away from your shins.', 'Set it down under control at the end of the distance.']::text[], array['Centre your grip', 'Short steps', 'Stay tall and braced']::text[], array['Walking so fast the bar swings into your legs', 'Shrugging and rounding the shoulders', 'Using a load you can''t set down safely']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('d333be77-2d02-5a62-acdd-5ddfe59f0a5d', 'keg-carry', 'Keg Carry', array['upper back', 'biceps', 'core']::text[], array['glutes', 'quadriceps', 'forearms']::text[], array['strongman_implements']::text[], 'strength', 'carry', 'compound', 'advanced', true, false, 'Lifting a sand- or water-filled keg and carrying it bear-hugged or on the shoulder over a distance — a common strongman medley event.', array['Stand over the keg, grip the handles or the rim, and deadlift it to the lap or chest.', 'Bear-hug it high and tight against your chest (or roll it onto one shoulder).', 'Walk with short, quick steps, staying upright and breathing behind the brace.', 'Set it down by sitting back and lowering it to the floor under control.']::text[], array['Hug it high and tight', 'Lean back slightly, not forward', 'Short, fast steps']::text[], array['Letting the keg slip down the stomach', 'Rounding over the keg', 'Holding the breath for the whole run']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('c200902e-b0ac-5629-9a2b-979fdc771190', 'zercher-carry', 'Zercher Carry', array['upper back', 'core', 'biceps']::text[], array['quadriceps', 'glutes']::text[], array['barbell', 'rack']::text[], 'strength', 'carry', 'compound', 'intermediate', true, false, 'Walking with a barbell held in the crook of the elbows — a strongman-style substitute for the yoke and keg that builds bracing and upper-back strength.', array['Set the bar in a rack at about waist height and cradle it in the crook of your elbows, hands clasped.', 'Stand it up, brace and step back from the rack.', 'Walk the distance with short steps and an upright torso.', 'Return to the rack (or a second rack) and set the bar down under control.']::text[], array['Elbows tight to the ribs', 'Stay tall', 'Short, deliberate steps']::text[], array['Letting the upper back round', 'Starting too heavy before the elbows are used to it', 'Walking without a safe place to set the bar down']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('f978f070-040e-5f2c-b11c-e41378a806dc', 'zercher-squat', 'Zercher Squat', array['quadriceps', 'glutes']::text[], array['upper back', 'core', 'biceps']::text[], array['barbell', 'rack']::text[], 'strength', 'squat', 'compound', 'intermediate', false, false, 'A squat with the bar in the crook of the elbows. Strongman athletes use it because it mirrors picking up and holding odd objects like stones and kegs.', array['Set the bar in the rack at about mid-torso height and cradle it in your elbows, hands together.', 'Unrack, take two steps back and set your feet a little wider than shoulder width.', 'Brace and sit down between your hips, keeping the chest up and elbows tight.', 'Drive up through the whole foot to standing.']::text[], array['Elbows tight, chest proud', 'Sit between the hips', 'Big brace before each rep']::text[], array['Letting the bar roll toward the forearms', 'Rounding the upper back', 'Cutting depth']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('b2a3942c-8578-57c4-9885-47fa8ab0ad47', 'sled-drag', 'Heavy Sled Drag', array['quadriceps', 'glutes', 'calves']::text[], array['hamstrings', 'core']::text[], array['sled']::text[], 'strength', 'carry', 'compound', 'beginner', true, false, 'Dragging a heavy sled with a harness or straps, walking forward or backward. A low-soreness strength builder and the standard substitute for the strongman truck or vehicle pull.', array['Attach the sled to a harness or straps held at the hips.', 'Lean into the pull with a flat back and drive through the balls of the feet.', 'Take short, powerful steps for the prescribed distance (backward drags hit the quads harder).', 'Keep tension on the strap the whole way — no jerking starts.']::text[], array['Lean in, flat back', 'Short, hard steps', 'Keep the strap tight']::text[], array['Standing too upright so you can''t drive', 'Jerking the strap at the start', 'Overstriding']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('8856cdbe-b9b8-56b9-9ac3-52f1fed82c72', 'arm-over-arm-sled-pull', 'Arm-Over-Arm Sled Pull', array['lats', 'biceps', 'forearms']::text[], array['upper back', 'core', 'glutes']::text[], array['sled']::text[], 'strength', 'horizontal_pull', 'compound', 'intermediate', true, false, 'Pulling a sled toward you hand over hand on a rope from a seated or braced stance — the strongman arm-over-arm truck pull, scaled to the gym.', array['Attach a thick rope to a loaded sled and sit or stand braced with feet against a stop if available.', 'Reach forward, grip the rope and pull it to your hip, then reach with the other hand.', 'Keep a steady, fast rhythm so the sled never stops moving.', 'Finish when the sled reaches you; reset the rope for the next run.']::text[], array['Long reach, hard pull', 'Never let the sled stop', 'Stay braced through the trunk']::text[], array['Short, choppy pulls', 'Pulling only with the arms instead of the back', 'Letting the rope slack between hands']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('368685ea-3f9d-50a6-bd35-3cb1d176d14c', 'sandbag-load-over-bar', 'Sandbag Load to Platform', array['glutes', 'hamstrings', 'spinal erectors']::text[], array['upper back', 'biceps', 'quadriceps']::text[], array['sandbag']::text[], 'strength', 'hinge', 'compound', 'intermediate', false, false, 'Lifting a heavy sandbag from the floor to the lap and onto a platform or over a bar — the best stone substitute when you don''t have Atlas stones.', array['Stand over the bag with a wide stance and wrap your arms and fingers underneath it.', 'Hinge and pull it to your lap, sitting back to cradle it.', 'Re-grip high, then drive the hips forward and extend to load it onto a box, platform or over a bar.', 'Step back, reset and repeat for the prescribed reps.']::text[], array['Lap, re-grip, extend', 'Hips through to finish', 'Hug the bag tight']::text[], array['Lifting with straight arms only', 'A platform too high to start', 'Rushing reps and losing position']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('6159d662-13ec-51eb-b504-87d17f806dc2', 'air-bike-sprint', 'Air Bike Sprint', array['quadriceps', 'glutes']::text[], array['shoulders', 'core', 'heart and lungs']::text[], array['bike']::text[], 'cardio', 'conditioning', 'compound', 'intermediate', true, false, 'Short, all-out efforts on an air (fan) bike. With long rests they train the alactic (explosive) system; with short rests they become brutal glycolytic intervals.', array['Set the seat so your knee is slightly bent at the bottom of the pedal stroke.', 'Start each sprint from a slow roll and go all-out with arms and legs for the prescribed seconds.', 'Ease off immediately and pedal very easily (or rest completely) for the full recovery.', 'Stop the set when a sprint is clearly slower than your first.']::text[], array['Push and pull with the arms', 'Maximal from the first second', 'Respect the rest — it''s part of the work']::text[], array['Cutting rest so alactic work turns into fatigue work', 'Pacing a ''sprint''', 'Seat too low']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('a7f3bd2e-9286-5e7e-b6f5-a3f0a20155bf', 'neck-isometrics', 'Neck Isometrics (4-Way)', array['neck']::text[], array['upper traps']::text[], array['bodyweight']::text[], 'strength', 'other', 'isolation', 'beginner', true, true, 'Holding the head still against your own hand (front, back and each side). A safe, low-soreness way for fighters and grapplers to build neck strength.', array['Sit or stand tall with your head in a neutral position.', 'Place a hand on your forehead and press your head into it while your hand resists so nothing moves.', 'Build to a firm (not maximal) effort and hold for the prescribed time, breathing steadily.', 'Repeat with the hand behind your head and on each side.']::text[], array['No movement — just pressure', 'Build the effort gradually', 'Keep breathing']::text[], array['Jerking into maximal effort', 'Letting the head tilt or turn', 'Training through neck pain']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('dca90a46-3658-5ed0-8e2e-89599ca5889f', 'band-neck-training', 'Banded Neck Flexion & Extension', array['neck']::text[], array['upper traps']::text[], array['band']::text[], 'strength', 'other', 'isolation', 'beginner', false, true, 'Slow, controlled neck movements against a light band (or a neck harness with a light plate) in four directions to build a resilient neck for combat sports.', array['Anchor a light band at head height and loop it around your forehead, facing away from the anchor.', 'Slowly nod the chin down against the band, then return to neutral under control.', 'Turn to face the anchor (band behind the head) for extension, then side-on for each side bend.', 'Use slow 2-second lifts and 2-second lowers for every rep.']::text[], array['Slow and controlled', 'Small range, no end-range cranking', 'Shoulders stay still']::text[], array['Using a heavy band or plate too soon', 'Fast, jerky reps', 'Shrugging the shoulders to help']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('e39b1ee2-7192-5bee-87a2-b5c708738f75', 'medicine-ball-shot-put', 'Medicine Ball Shot Put Throw', array['chest', 'triceps', 'obliques']::text[], array['glutes', 'front delts']::text[], array['medicine_ball']::text[], 'plyometric', 'power', 'compound', 'intermediate', false, false, 'Driving a medicine ball explosively from the shoulder into a wall with a rear-leg push and hip rotation — trains the same sequence as a straight punch.', array['Stand side-on to a solid wall in your fighting stance, holding the ball at your rear shoulder.', 'Load the rear hip, then drive off the back foot and rotate the hips toward the wall.', 'Punch the ball into the wall as hard as you can, following through with the arm.', 'Catch or collect the ball, reset fully and repeat; switch stances for the other side.']::text[], array['Feet, hips, then hand', 'Throw through the wall', 'Reset between reps']::text[], array['Throwing only with the arm', 'Using a ball so heavy it''s slow', 'Rushing reps so power drops']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('fec01aff-b1ed-5700-b8ac-9a76e683e31a', 'medicine-ball-scoop-toss', 'Medicine Ball Scoop Toss', array['obliques', 'glutes']::text[], array['hamstrings', 'shoulders']::text[], array['medicine_ball']::text[], 'plyometric', 'rotation', 'compound', 'intermediate', false, false, 'Scooping a medicine ball from beside the back hip and throwing it into a wall with full hip rotation — builds rotational power for hooks, throws and takedowns.', array['Stand side-on to a wall about 1–2 m away, holding the ball at hip height.', 'Load into your back hip with a slight squat, ball beside the back pocket.', 'Drive the hips around and scoop the ball explosively into the wall at chest height.', 'Catch, reset fully and repeat; complete all reps, then switch sides.']::text[], array['Load the back hip', 'Hips lead the arms', 'Explode every rep']::text[], array['Twisting from the lower back instead of the hips', 'Arms doing all the work', 'Going so fast reps lose speed']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('6d41f500-89b6-575f-98a9-962c987ad6cf', 'landmine-rotation', 'Landmine Rotation', array['obliques', 'core']::text[], array['shoulders', 'glutes']::text[], array['landmine', 'barbell']::text[], 'core', 'rotation', 'compound', 'intermediate', false, false, 'Swinging the end of a landmine barbell in an arc from hip to hip with straight arms, controlled by the trunk and hips.', array['Hold the end of a landmine bar at chest height with both hands, arms extended.', 'Rotate the bar down toward one hip, pivoting the back foot and turning the hips.', 'Drive back through the middle and over to the other hip under control.', 'Keep the arms long and let the hips and trunk create the movement.']::text[], array['Pivot the feet', 'Arms long', 'Control the end range']::text[], array['Bending the elbows to move the bar', 'Twisting only through the lower back', 'Using a load you can''t stop']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('fc34e9f2-fff3-5064-a2cc-d0a41fb2c3f7', 'trap-bar-jump', 'Trap Bar Jump', array['glutes', 'quadriceps', 'calves']::text[], array['hamstrings', 'traps']::text[], array['trap_bar']::text[], 'plyometric', 'power', 'compound', 'intermediate', false, false, 'A loaded jump holding a light trap bar (about 10–30% of your trap bar deadlift). A safe, coachable way to build lower-body power for fighters and field athletes.', array['Stand in a light trap bar with handles at your sides.', 'Dip quickly into a quarter squat and jump as high as you can.', 'Land softly in the same quarter-squat position with the bar still at your sides.', 'Reset and stand tall between reps.']::text[], array['Fast dip, faster jump', 'Land quiet and balanced', 'Light enough to be fast']::text[], array['Going so heavy the jump is slow', 'Landing stiff-legged', 'Rebounding reps without resetting']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('72b1c751-8acd-5be7-a221-09b81d1b83d8', 'copenhagen-plank', 'Copenhagen Plank', array['adductors', 'obliques']::text[], array['glutes', 'core']::text[], array['bench', 'bodyweight']::text[], 'core', 'core', 'compound', 'intermediate', true, false, 'A side plank with the top leg resting on a bench. Well supported for reducing groin injuries in sports with kicking, cutting and sprawling.', array['Lie on your side beside a bench and place your top knee (easier) or foot (harder) on it.', 'Prop yourself up on the forearm, elbow under the shoulder.', 'Lift your hips so your body forms a straight line, with the bottom leg hanging or lifted to the bench.', 'Hold for the prescribed time, then switch sides.']::text[], array['Squeeze the top leg down into the bench', 'Hips high', 'Straight line head to feet']::text[], array['Starting with the long-lever (foot) version too soon', 'Hips sagging', 'Rolling forward']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('7694c265-91ed-5760-93d7-acb8e8aa051a', 'nordic-hamstring-curl', 'Nordic Hamstring Curl', array['hamstrings']::text[], array['glutes', 'calves']::text[], array['bodyweight', 'mat']::text[], 'strength', 'hinge', 'isolation', 'intermediate', false, false, 'Kneeling with your ankles anchored and lowering your body forward as slowly as possible. Strongly supported for reducing hamstring strains in sprinting sports — start with low volume.', array['Kneel on a pad with your ankles anchored under a heavy object, bench or partner''s hands.', 'Keep a straight line from knees to head with hips extended.', 'Lower yourself forward as slowly as you can, resisting with the hamstrings.', 'Catch yourself with your hands, push back up lightly and repeat.']::text[], array['Hips stay locked out', 'Fight the fall the whole way', 'Low reps, high quality']::text[], array['Bending at the hips to shorten the lever', 'Doing high volume in the first weeks (very sore hamstrings)', 'Dropping fast at the end']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('c5df7274-899b-578f-a89e-9ce99625f32b', 'band-external-rotation', 'Band External Rotation', array['rotator cuff']::text[], array['rear delts']::text[], array['band', 'cable']::text[], 'strength', 'isolation', 'isolation', 'beginner', false, true, 'Rotating the forearm outward against a light band or cable with the elbow at your side — simple shoulder-health work for punchers, pressers and throwers.', array['Anchor a light band at elbow height and stand side-on with the working arm away from the anchor.', 'Keep the elbow tucked to your side (a rolled towel helps) and bent to 90 degrees.', 'Rotate the forearm outward, away from your body, without moving the elbow.', 'Return slowly; finish the set, then switch sides.']::text[], array['Elbow pinned to your side', 'Slow on the way back', 'Light and smooth']::text[], array['Swinging the elbow away from the body', 'Using too heavy a band', 'Rotating the torso instead of the shoulder']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('751d0a4f-6485-5ef0-9fdf-27a429cc178a', 'hack-squat', 'Hack Squat (Machine)', array['quadriceps']::text[], array['glutes', 'adductors']::text[], array['machine']::text[], 'strength', 'squat', 'compound', 'beginner', false, false, 'A machine squat on an angled sled. Stable and easy to push close to failure, it lets bodybuilders load the quads deep into the stretch.', array['Set your back against the pad and shoulders under the yokes, feet shoulder width in the middle of the platform.', 'Release the safeties, brace and lower under control until the thighs are below parallel (or your controlled depth).', 'Pause briefly in the bottom without bouncing.', 'Drive through the whole foot to just short of lockout and repeat.']::text[], array['Deep and controlled', 'Knees travel forward over the toes', 'Back stays on the pad']::text[], array['Cutting depth to move more weight', 'Bouncing out of the bottom', 'Heels lifting']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('6e830b45-94be-5700-8d49-e7686d8a67cf', 'machine-chest-press', 'Machine Chest Press', array['chest']::text[], array['front delts', 'triceps']::text[], array['machine']::text[], 'strength', 'horizontal_push', 'compound', 'beginner', false, false, 'A seated pressing machine that removes balance demands so you can safely train the chest hard and close to failure.', array['Adjust the seat so the handles line up with your mid-chest.', 'Set your shoulder blades back and down against the pad.', 'Press the handles forward until the arms are almost straight.', 'Return slowly until you feel a deep stretch across the chest.']::text[], array['Shoulder blades pinned', 'Slow stretch', 'Drive through the palms']::text[], array['Seat too high or low', 'Shoulders rolling forward at lockout', 'Short, bouncy reps']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('23a1b42e-f182-51f2-8416-0414ce7bf53c', 'chest-supported-row', 'Chest-Supported Row', array['lats', 'upper back']::text[], array['rear delts', 'biceps']::text[], array['dumbbell', 'bench', 'machine']::text[], 'strength', 'horizontal_pull', 'compound', 'beginner', false, false, 'Rowing dumbbells (or a machine) with your chest on an incline bench, taking the lower back out of it so the upper back does all the work.', array['Set a bench to about 30–45 degrees and lie face down with the dumbbells hanging below you.', 'Let the shoulder blades spread for a full stretch at the bottom.', 'Row the dumbbells toward your hips, squeezing the shoulder blades together.', 'Lower slowly to a full stretch and repeat.']::text[], array['Chest stays on the pad', 'Elbows toward the hips', 'Full stretch every rep']::text[], array['Lifting the chest off the bench to cheat', 'Shrugging instead of rowing', 'Cutting the stretch short']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('f170573e-1859-506b-9521-1dc95803d4d1', 'straight-arm-pulldown', 'Straight-Arm Pulldown', array['lats']::text[], array['teres major', 'triceps (long head)', 'core']::text[], array['cable', 'band']::text[], 'strength', 'isolation', 'isolation', 'beginner', false, false, 'Pulling a cable bar or rope down to the thighs with straight arms — isolates the lats through a long range without the biceps limiting you.', array['Stand facing a high cable, hinge slightly at the hips and hold the bar or rope with straight arms overhead.', 'Keeping the elbows soft but fixed, sweep the handle down in an arc to your thighs.', 'Squeeze the lats at the bottom.', 'Let the arms rise slowly until you feel a full stretch through the lats.']::text[], array['Arms stay long', 'Pull with the armpits', 'Slow on the stretch']::text[], array['Bending the elbows into a pushdown', 'Rocking the torso', 'Going too heavy to control the stretch']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('ebacf413-66ef-5271-88ea-762cd045a00b', 'cable-lateral-raise', 'Cable Lateral Raise', array['side delts']::text[], array['upper traps']::text[], array['cable']::text[], 'strength', 'isolation', 'isolation', 'beginner', false, false, 'A one-arm lateral raise from a low cable. The cable keeps tension on the side delt even at the bottom, where dumbbells go slack.', array['Set a cable at the lowest position and stand side-on, holding the handle with the far hand across your body.', 'With a slight elbow bend, raise the arm out to the side to about shoulder height.', 'Pause briefly, then lower slowly back across the body.', 'Finish the set, then switch sides.']::text[], array['Lead with the elbow', 'Slow, controlled lower', 'Stay tall']::text[], array['Leaning away to swing the weight', 'Raising well above shoulder height with a shrug', 'Going too heavy']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('74820203-59d3-518d-82b5-4ec3b0b2b028', 'incline-dumbbell-curl', 'Incline Dumbbell Curl', array['biceps']::text[], array['forearms']::text[], array['dumbbell', 'bench']::text[], 'strength', 'isolation', 'isolation', 'beginner', false, false, 'Curling from a bench set at about 45–60 degrees so the arms hang behind the body, training the biceps hard in the lengthened (stretched) position.', array['Set a bench to about 45–60 degrees and lie back with a dumbbell in each hand, arms hanging straight down.', 'Keep the upper arms still and curl the weights up, turning the palms up.', 'Squeeze at the top without letting the elbows drift forward.', 'Lower slowly all the way to a full stretch.']::text[], array['Elbows stay back', 'Full stretch at the bottom', 'Slow lower']::text[], array['Swinging the elbows forward', 'Half reps', 'Using weights too heavy for the stretched position']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('f2f91154-45f0-52f1-8228-71f2ec6fbf2f', 'seated-leg-curl', 'Seated Leg Curl', array['hamstrings']::text[], array['calves']::text[], array['machine']::text[], 'strength', 'isolation', 'isolation', 'beginner', false, false, 'A seated hamstring curl. Because the hips are flexed, the hamstrings work at longer lengths than in a lying curl — a favourite for hamstring growth.', array['Adjust the machine so your knees line up with the pivot and the pad sits just above your heels.', 'Lock the thigh pad down firmly and lean slightly forward.', 'Curl the pad down and back as far as you can, squeezing the hamstrings.', 'Return slowly to a full stretch with the legs almost straight.']::text[], array['Lean forward a little', 'Full squeeze, full stretch', 'Control the return']::text[], array['Thigh pad too loose', 'Short range at the top', 'Letting the weight stack crash']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('6e0d6f03-417b-5d52-99c7-1327056511dd', 'seated-calf-raise', 'Seated Calf Raise', array['calves (soleus)']::text[], array['calves (gastrocnemius)']::text[], array['machine', 'dumbbell']::text[], 'strength', 'isolation', 'isolation', 'beginner', false, false, 'A calf raise with bent knees (machine or dumbbells on the knees), which shifts the work to the soleus — the deeper calf muscle that standing raises miss.', array['Sit with the balls of your feet on a step or the machine platform and the pad (or dumbbells) on your lower thighs.', 'Lower the heels slowly into a deep stretch and pause for a second.', 'Push up as high as you can onto the balls of the feet.', 'Squeeze at the top, then lower slowly again.']::text[], array['Pause in the stretch', 'Full height at the top', 'No bouncing']::text[], array['Bouncing out of the bottom', 'Short range of motion', 'Rolling onto the outside of the foot']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('099f14d0-c13e-5c8d-83a9-a070512a487c', 'cable-crunch', 'Kneeling Cable Crunch', array['abs']::text[], array['obliques']::text[], array['cable', 'band']::text[], 'core', 'core', 'isolation', 'beginner', false, false, 'Crunching the ribs toward the pelvis against a high cable while kneeling — a loadable ab exercise you can progress like any other muscle.', array['Kneel facing a high cable with a rope held beside your head.', 'Keep the hips still and curl your ribs down toward your pelvis, rounding the spine.', 'Squeeze the abs hard at the bottom.', 'Return slowly until the abs are stretched and repeat.']::text[], array['Ribs to hips', 'Hips stay still', 'Exhale as you crunch']::text[], array['Sitting back with the hips to move the weight', 'Pulling with the arms', 'Going too heavy to round the spine']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('3d6e2331-9349-59f9-9824-5452ccb938e2', 'posing-practice', 'Posing Practice', array['full body']::text[], array['abs', 'quadriceps', 'lats']::text[], array['bodyweight']::text[], 'conditioning', 'other', 'compound', 'beginner', true, true, 'Rehearsing your division''s mandatory poses, quarter turns and transitions. Holding poses under tension is hard work, and stage presentation is judged as much as muscle.', array['Set up in front of a mirror or camera in good light, wearing posing trunks or a suit if you have them.', 'Run through each mandatory pose for your division, holding each for 10–20 seconds while breathing steadily.', 'Practise quarter turns and the transitions between poses until they are smooth and controlled.', 'Finish with one full routine run-through and record it to review with your coach.']::text[], array['Flex hard, but smile and breathe', 'Smooth transitions', 'Practise like it''s show day']::text[], array['Only practising in the final weeks', 'Holding the breath until you''re light-headed', 'Copying poses that don''t suit your physique']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('27302af2-e57a-5e69-9e98-213f4efeb035', 'hip-abduction', 'Hip Abduction (Machine or Band)', array['glutes']::text[], array['hip rotators']::text[], array['machine', 'band']::text[], 'strength', 'isolation', 'isolation', 'beginner', false, true, 'Pushing the knees out against resistance trains the upper glutes (gluteus medius and minimus), which steady the pelvis in single-leg work, running and squats.', array['Sit in the abduction machine with your back against the pad, or sit on a bench with a band just above your knees.', 'Lean your torso slightly forward and brace lightly.', 'Push your knees apart as far as you comfortably can, pausing for a second at the end.', 'Return slowly until the plates almost touch (or the band is nearly slack), keeping tension on the glutes.']::text[], array['Lead with the knees', 'Pause at the widest point', 'Slow on the way back']::text[], array['Swinging the weight with momentum', 'Cutting the range short', 'Letting the plates crash between reps']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('d128d1f4-47de-5672-9510-1999638d6609', 'back-extension', 'Back Extension (45° Hyperextension)', array['glutes', 'hamstrings']::text[], array['spinal erectors']::text[], array['bench']::text[], 'strength', 'hinge', 'compound', 'beginner', false, false, 'A hinge on a 45° hyperextension bench that loads the glutes and hamstrings through a long range with little spinal compression.', array['Set the pad just below your hip crease so you can hinge freely, with your feet locked under the rollers.', 'Cross your arms over your chest (or hold a plate) and brace.', 'Hinge down slowly until you feel a stretch in your hamstrings, keeping your back neutral.', 'Squeeze your glutes to lift your torso back into a straight line with your legs — no further.']::text[], array['Hinge at the hips, not the low back', 'Squeeze the glutes to finish', 'Stop at a straight line']::text[], array['Hyperextending the lower back at the top', 'Pad set too high so the hips can''t hinge', 'Bouncing out of the bottom']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('043de385-5cd7-5f70-9995-7b6754a34ed6', 'incline-barbell-bench-press', 'Incline Barbell Bench Press', array['upper chest', 'front deltoids']::text[], array['triceps']::text[], array['barbell', 'bench', 'rack']::text[], 'strength', 'horizontal_push', 'compound', 'intermediate', false, false, 'A barbell bench press on a bench set to about 30 degrees, shifting more of the work to the upper chest and front shoulders than the flat press.', array['Set the incline bench to about 30 degrees and the rack hooks so you can unrack the bar with a slight bend in the elbows.', 'Lie back with your eyes under the bar, feet flat, and shoulder blades squeezed back and down into the bench.', 'Grip slightly wider than shoulder width, unrack, and hold the bar over your shoulders.', 'Lower the bar under control to your upper chest, just below the collarbones.', 'Press it back up to lockout over your shoulders.']::text[], array['Low incline, not a shoulder press', 'Shoulder blades pinned', 'Forearms vertical under the bar']::text[], array['Setting the bench so steep it becomes an overhead press', 'Lowering the bar to the lower chest or belly', 'Lifting the hips off the seat to finish the rep']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('4b0c6316-8c85-5286-9d16-0fca442ca787', 'tempo-bench-press', 'Tempo Bench Press', array['chest', 'triceps']::text[], array['front deltoids']::text[], array['barbell', 'bench', 'rack']::text[], 'strength', 'horizontal_push', 'compound', 'intermediate', false, false, 'A flat barbell bench press with a slow, counted lowering phase (about three seconds), used to build control of the bar path and time under tension with lighter loads.', array['Set up as for a regular bench press: eyes under the bar, shoulder blades back and down, feet planted.', 'Unrack and hold the bar over your shoulders.', 'Lower the bar to your lower chest on a steady three-second count, keeping the same path every rep.', 'Touch the chest briefly without bouncing or relaxing.', 'Press back to lockout in about one second.']::text[], array['Count the descent out loud', 'Same touch point every rep', 'Stay tight at the bottom']::text[], array['Speeding up over the last few inches', 'Using a load too heavy to control for the full count', 'Losing upper-back tightness while lowering']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('69120c84-a632-5696-8092-1bdbc692094c', 'dumbbell-squeeze-press', 'Dumbbell Squeeze Press', array['chest', 'triceps']::text[], array['front deltoids']::text[], array['dumbbell', 'bench']::text[], 'strength', 'horizontal_push', 'compound', 'beginner', false, false, 'A flat dumbbell press with the two dumbbells held together, palms facing each other, and squeezed hard against each other through the whole rep. Also called the crush press.', array['Lie on a flat bench holding two dumbbells over your chest with palms facing each other.', 'Press the dumbbells together so they touch along their length and keep squeezing them inward.', 'With elbows tucked close to your sides, lower the dumbbells together to the middle of your chest.', 'Press them back up to straight arms without letting them drift apart.']::text[], array['Crush the dumbbells together', 'Elbows close to the ribs', 'Slow on the way down']::text[], array['Letting the dumbbells separate as you press', 'Flaring the elbows out wide', 'Using dumbbells too heavy to keep squeezed']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('7a17c694-7a3a-567d-8971-d45bda2a9120', 'tempo-push-up', 'Tempo Push-Up', array['chest', 'triceps']::text[], array['front deltoids', 'core']::text[], array['bodyweight']::text[], 'strength', 'horizontal_push', 'compound', 'beginner', false, false, 'A push-up with a slow, three-second lowering phase that makes bodyweight pressing harder without adding load or reps.', array['Start in a high plank with hands slightly wider than shoulders and your body in one straight line.', 'Brace your core and glutes.', 'Lower your chest toward the floor on a steady three-second count, elbows at about 45 degrees.', 'Stop with your chest just above the floor.', 'Push back up to the plank in about one second.']::text[], array['Count three on the way down', 'Body moves as one plank', 'Same speed all the way down']::text[], array['Dropping quickly through the last part of the descent', 'Hips sagging as you tire', 'Shortening the range to keep the count']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('9f282e2c-cd76-5ac7-af81-770a304ac044', 'dumbbell-fly', 'Dumbbell Fly', array['chest']::text[], array['front deltoids']::text[], array['dumbbell', 'bench']::text[], 'strength', 'isolation', 'isolation', 'beginner', false, false, 'A chest isolation exercise lying on a flat bench: the arms open in a wide arc with a fixed, slight elbow bend and close again over the chest.', array['Lie on a flat bench with feet planted, holding two dumbbells over your chest with palms facing each other and a slight bend in the elbows.', 'Set your shoulder blades back and down into the bench.', 'Open your arms out to the sides in a wide arc, keeping the elbow bend fixed, until your upper arms are about level with your torso.', 'Bring the dumbbells back up along the same arc until they meet over your chest.']::text[], array['Hug a barrel', 'Elbow bend stays the same', 'Stretch, don''t drop']::text[], array['Bending and straightening the elbows so it turns into a press', 'Lowering the arms far below the bench', 'Using dumbbells too heavy to control at the bottom']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('80d6048d-ec8c-528c-b545-72f9ea4cce59', 'incline-dumbbell-fly', 'Incline Dumbbell Fly', array['upper chest']::text[], array['front deltoids']::text[], array['dumbbell', 'bench']::text[], 'strength', 'isolation', 'isolation', 'beginner', false, false, 'A dumbbell fly on a bench set to about 30 degrees, keeping the dumbbells over the upper chest to emphasize the upper part of the pecs.', array['Set an adjustable bench to about 30 degrees and lie back with the dumbbells over your upper chest, palms facing each other.', 'Keep a slight bend in the elbows and your shoulder blades pinned to the bench.', 'Open the arms out to the sides in a wide arc until your upper arms are about level with your torso.', 'Sweep them back up along the same arc until the dumbbells meet over the upper chest.']::text[], array['Low incline', 'Fixed elbow bend', 'Dumbbells over the upper chest']::text[], array['Setting the bench too steep', 'Letting the dumbbells drift toward the belly at the top', 'Turning the fly into a press']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('56f79408-929a-53d1-9b16-5424e69a70ea', 'decline-bench-press', 'Decline Barbell Bench Press', array['chest', 'triceps']::text[], array['front deltoids']::text[], array['barbell', 'bench', 'rack']::text[], 'strength', 'horizontal_push', 'compound', 'intermediate', false, false, 'A barbell bench press on a bench declined about 15–20 degrees, head lower than the hips, which emphasizes the lower chest and shortens the bar''s path.', array['Hook your legs under the roller pads of a decline bench and lie back with your eyes under the bar.', 'Grip slightly wider than shoulder width and squeeze your shoulder blades together.', 'Unrack the bar (a spotter helps with the hand-off) and hold it over your shoulders.', 'Lower it under control to your lower chest, keeping the forearms vertical.', 'Press it back up to lockout over the shoulders.']::text[], array['Legs locked under the pads', 'Touch the lower chest', 'Forearms vertical']::text[], array['Lowering the bar toward the neck', 'Bouncing the bar off the chest', 'Racking or unracking alone with heavy loads']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('beac3e44-5b53-57c2-824f-d38313e62cc2', 'decline-dumbbell-press', 'Decline Dumbbell Press', array['chest', 'triceps']::text[], array['front deltoids']::text[], array['dumbbell', 'bench']::text[], 'strength', 'horizontal_push', 'compound', 'intermediate', false, false, 'A dumbbell press on a decline bench, head lower than the hips, letting each arm find its own path while emphasizing the lower chest.', array['Sit on the decline bench with the dumbbells on your thighs and hook your legs under the roller pads.', 'Lie back carefully, bringing the dumbbells to your chest, then press them up over your shoulders.', 'Lower them under control to the sides of your lower chest, elbows about 45 degrees from your body.', 'Press back up until your arms are straight.']::text[], array['Legs locked in', 'Elbows about 45 degrees', 'Controlled lowering']::text[], array['Losing control of the dumbbells when lying back or sitting up', 'Letting the dumbbells drift toward the face', 'Short, bouncy reps']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('ec1367f2-fe87-57c5-8c42-3db122fdba90', 'knee-push-up', 'Knee Push-Up', array['chest', 'triceps']::text[], array['front deltoids', 'core']::text[], array['bodyweight', 'mat']::text[], 'strength', 'horizontal_push', 'compound', 'beginner', false, true, 'A push-up from the knees instead of the toes, which reduces the share of bodyweight pressed while keeping the same straight-body technique.', array['Kneel on a mat and place your hands on the floor slightly wider than your shoulders, far enough forward that your body is straight from knees to head.', 'Lift your feet behind you and brace your core and glutes.', 'Lower your chest toward the floor with the elbows at about 45 degrees.', 'Push back up to straight arms, keeping the hips in line.']::text[], array['Straight line from knees to head', 'Hips stay forward', 'Chest leads']::text[], array['Bending at the hips with the butt in the air', 'Kneeling too close to the hands', 'Dropping the head']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('44cfab3e-dbd6-5349-be45-e024cbfb615a', 'close-grip-push-up', 'Close-Grip Push-Up', array['triceps', 'chest']::text[], array['front deltoids', 'core']::text[], array['bodyweight']::text[], 'strength', 'horizontal_push', 'compound', 'intermediate', false, false, 'A push-up with the hands about shoulder width apart and the elbows kept tight to the body, shifting more of the work onto the triceps.', array['Start in a high plank with your hands directly under your shoulders, about shoulder width apart.', 'Brace so your body forms a straight line from head to heels.', 'Lower your chest toward the floor, keeping your elbows tucked so they travel back along your ribs.', 'Stop with your chest just above the floor, then press back up to straight arms.']::text[], array['Elbows brush the ribs', 'Hands under the shoulders', 'Lock out fully at the top']::text[], array['Letting the elbows flare out to the sides', 'Placing the hands so close that the wrists bend awkwardly', 'Hips sagging or piking']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('15be14df-8862-502a-9c4c-f5ab8c42df4d', 'ez-bar-skull-crusher', 'EZ-Bar Skull Crusher', array['triceps']::text[], array['forearms']::text[], array['barbell', 'bench']::text[], 'strength', 'isolation', 'isolation', 'intermediate', false, false, 'A lying triceps extension with an EZ-curl bar: the upper arms stay still while the elbows bend to lower the bar toward the forehead.', array['Lie on a flat bench holding an EZ-bar on the angled grips, arms straight over your shoulders.', 'Let your upper arms tilt slightly back toward your head and keep them there.', 'Bend only your elbows to lower the bar under control to just above your forehead.', 'Extend the elbows to bring the bar back to the start without moving the upper arms.']::text[], array['Upper arms stay still', 'Elbows point at the ceiling', 'Slow on the way down']::text[], array['Letting the elbows flare out wide', 'Moving the upper arms so it becomes a pullover or press', 'Lowering too fast near the face']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('f87bddb3-634d-59d3-8d51-c18406654e3f', 'dumbbell-lying-triceps-extension', 'Dumbbell Lying Triceps Extension', array['triceps']::text[], array['forearms']::text[], array['dumbbell', 'bench']::text[], 'strength', 'isolation', 'isolation', 'beginner', false, false, 'A lying triceps extension with a dumbbell in each hand, palms facing each other, lowered beside the head by bending only the elbows.', array['Lie on a flat bench holding a dumbbell in each hand, arms straight over your shoulders and palms facing each other.', 'Tilt your upper arms slightly back toward your head and keep them fixed.', 'Bend your elbows to lower the dumbbells beside your head.', 'Extend the elbows to press them back up to straight arms.']::text[], array['Upper arms fixed', 'Palms face each other', 'Full stretch, full lockout']::text[], array['Letting the upper arms swing back and forth', 'Flaring the elbows', 'Clanging the dumbbells together at the top']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('703e8266-9bce-59d5-8994-7ada652c5780', 'dumbbell-kickback', 'Dumbbell Triceps Kickback', array['triceps']::text[], array['rear deltoids']::text[], array['dumbbell']::text[], 'strength', 'isolation', 'isolation', 'beginner', false, false, 'A triceps isolation exercise done hinged forward: the upper arms are held level with the floor beside the torso and the elbows straighten to push the dumbbells back.', array['Hold a dumbbell in each hand, soften your knees and hinge forward with a flat back.', 'Lift your upper arms so they are level with the floor and tucked beside your torso, elbows bent about 90 degrees.', 'Straighten your elbows to push the dumbbells back until your arms are straight.', 'Pause briefly, then bend the elbows to lower the dumbbells under control.']::text[], array['Upper arms stay still', 'Squeeze at lockout', 'Flat back']::text[], array['Swinging the dumbbells with momentum', 'Letting the upper arms drop as the elbows extend', 'Rounding the back']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('dfe50427-7937-5a23-8133-a89896e35cd0', 'bench-dip', 'Bench Dip', array['triceps']::text[], array['chest', 'front deltoids']::text[], array['bench', 'bodyweight']::text[], 'strength', 'vertical_push', 'compound', 'beginner', false, false, 'A bodyweight triceps exercise with the hands on the edge of a bench behind you and the feet on the floor in front, lowering by bending the elbows.', array['Sit on the edge of a sturdy bench, hands on the edge beside your hips with fingers pointing forward.', 'Walk your feet forward until your hips are just in front of the bench, knees bent about 90 degrees.', 'Bend your elbows straight back to lower your hips until your upper arms are about level with the floor.', 'Press through your palms to straighten your arms.']::text[], array['Elbows point straight back', 'Hips close to the bench', 'Shoulders down, chest up']::text[], array['Lowering further than your shoulders comfortably allow', 'Letting the elbows flare out', 'Pushing with the legs instead of the arms']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('4adb0e87-1195-5f69-9498-83dc29fa7bb9', 'wide-grip-pull-up', 'Wide-Grip Pull-Up', array['lats', 'upper back']::text[], array['teres major', 'biceps', 'forearms', 'core']::text[], array['pull_up_bar']::text[], 'strength', 'vertical_pull', 'compound', 'advanced', false, false, 'A pull-up with the hands set well outside shoulder width. The wider grip shortens the range and puts more of the work on the lats and less on the arms.', array['Hang from the bar with an overhand grip about one and a half times shoulder width.', 'Set your shoulders by pulling them down and slightly back, legs still.', 'Pull your elbows down and out toward your sides until your chin passes the bar.', 'Lower under control all the way to straight arms.']::text[], array['Elbows down and out', 'Chest up toward the bar', 'Full hang each rep']::text[], array['Setting the grip so wide the range shrinks to a few inches', 'Kipping or swinging', 'Shrugging the shoulders up at the top']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('9e16d107-22c9-5c1a-a722-3bd2572b9fac', 'band-assisted-chin-up', 'Band-Assisted Chin-Up', array['lats', 'biceps']::text[], array['upper back', 'forearms']::text[], array['pull_up_bar', 'band']::text[], 'strength', 'vertical_pull', 'compound', 'beginner', false, false, 'A chin-up (underhand, shoulder-width grip) with a resistance band looped over the bar under one knee or foot to take off part of your bodyweight.', array['Loop a resistance band around the bar and put one knee or foot in the loop.', 'Take an underhand grip about shoulder width and hang with straight arms.', 'Pull your chest toward the bar, driving the elbows down in front of your body, until your chin clears it.', 'Lower slowly to straight arms; move to a lighter band as you get stronger.']::text[], array['Same form as a full chin-up', 'Elbows drive down', 'Control the band on the way down']::text[], array['Letting the band fling you up from the bottom', 'Stopping short of straight arms', 'Leaning far back to reach the bar']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('208131f1-81bd-5674-9331-8d095777bf47', 'wide-grip-lat-pulldown', 'Wide-Grip Lat Pulldown', array['lats']::text[], array['teres major', 'upper back', 'biceps']::text[], array['cable', 'machine']::text[], 'strength', 'vertical_pull', 'compound', 'beginner', false, false, 'A lat pulldown with the hands out on the angled ends of the long lat bar, well outside shoulder width, emphasising the lats with less help from the arms.', array['Set the thigh pad so your legs are locked in, and grip the bar out near its bends with an overhand grip.', 'Sit tall with straight arms and lean back only slightly.', 'Pull the bar to your upper chest, driving the elbows down and out to your sides.', 'Let the bar rise slowly until your arms are straight and you feel the lats stretch.']::text[], array['Elbows to the sides of the ribs', 'Chest up to meet the bar', 'Slow on the way up']::text[], array['Pulling the bar behind the neck', 'Leaning back so far it becomes a row', 'Letting the weight stack yank the arms up']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('726f482b-30d8-549d-9fef-ce30aadd249b', 'dumbbell-bent-over-row', 'Bent-Over Dumbbell Row', array['upper back', 'lats']::text[], array['rear deltoids', 'biceps', 'spinal erectors']::text[], array['dumbbell']::text[], 'strength', 'horizontal_pull', 'compound', 'intermediate', false, false, 'A two-dumbbell row from an unsupported hip hinge. Each arm works on its own path, and holding the hinge trains the back muscles that keep the spine still.', array['Hold a dumbbell in each hand with palms facing in, feet about hip width.', 'Push your hips back with soft knees until your torso is at about 45 degrees or lower, back flat.', 'Row both dumbbells toward your lower ribs, elbows close to your sides.', 'Lower them to straight arms without letting your torso rise.']::text[], array['Flat back, still torso', 'Elbows past the ribs', 'Pause at the top']::text[], array['Standing up a little more each rep', 'Swinging the dumbbells up with the hips', 'Rounding the back to reach lower']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('4908e2b1-0749-55c1-806b-495bde7c1a93', 'reverse-grip-barbell-row', 'Reverse-Grip Barbell Row', array['lats', 'upper back']::text[], array['biceps', 'rear deltoids', 'spinal erectors']::text[], array['barbell']::text[], 'strength', 'horizontal_pull', 'compound', 'intermediate', false, false, 'A bent-over barbell row taken with an underhand (palms-forward) grip. The elbows stay closer to the body, shifting more of the work to the lats and biceps.', array['Hold the bar with an underhand grip at about shoulder width.', 'Hinge forward with soft knees to about 45 degrees or lower, back flat and bar hanging under the shoulders.', 'Row the bar to your lower ribs, keeping the elbows tucked close to your sides.', 'Lower to straight arms under control, holding the hinge.']::text[], array['Elbows tight to the sides', 'Bar to the belly', 'Hold the hinge']::text[], array['Turning it into a standing curl by straightening up', 'Jerking the bar off the bottom', 'Letting the wrists bend back under load']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('a85e46c5-d2ca-5ead-a637-707a70ea9372', 'bent-over-band-row', 'Bent-Over Band Row', array['upper back', 'lats']::text[], array['rear deltoids', 'biceps', 'spinal erectors']::text[], array['band']::text[], 'strength', 'horizontal_pull', 'compound', 'beginner', false, true, 'A bent-over row against a resistance band anchored under the feet. The band gets harder toward the top of the row, and it needs no weights, so it suits home training.', array['Stand on the middle of a resistance band with feet about hip width and hold one end in each hand.', 'Hinge forward with soft knees until your torso is at about 45 degrees, back flat, arms hanging straight.', 'Row your hands to your lower ribs, squeezing the shoulder blades together.', 'Lower slowly to straight arms without letting the band pull you out of the hinge.']::text[], array['Flat back', 'Squeeze at the top', 'Slow return']::text[], array['Letting the band snap the arms down', 'Standing up as the band gets harder', 'Shrugging instead of rowing']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('dea275f5-a203-5c63-8223-d0432a60f5a2', 'standing-cable-row', 'Standing Cable Row', array['upper back', 'lats']::text[], array['rear deltoids', 'biceps', 'core']::text[], array['cable']::text[], 'strength', 'horizontal_pull', 'compound', 'beginner', false, false, 'A cable row done standing with the pulley at chest height. Without a seat or foot plate, the legs and trunk have to brace to keep the body still.', array['Set a cable at about chest height with a handle or straight bar, grip it and step back until the weight lifts.', 'Stand tall with soft knees and the arms reaching forward.', 'Row the handle to your ribs, squeezing the shoulder blades together.', 'Let the arms extend forward again slowly without leaning toward the stack.']::text[], array['Stand tall and brace', 'Elbows back, shoulders down', 'Don''t lean back to finish']::text[], array['Leaning back to move more weight', 'Shrugging toward the ears', 'Letting the stack pull the shoulders forward']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('ad6db0d9-16ec-5c0b-9be8-0d7f6c25bc48', 'reverse-grip-inverted-row', 'Reverse-Grip Inverted Row', array['upper back', 'lats']::text[], array['biceps', 'core']::text[], array['barbell', 'rack', 'bodyweight']::text[], 'strength', 'horizontal_pull', 'compound', 'beginner', false, false, 'An inverted row under a bar taken with an underhand grip, which brings in more biceps. It is a common step toward the chin-up.', array['Set a bar at about waist height in a rack and lie underneath it.', 'Grip it underhand at about shoulder width, body straight from heels to shoulders.', 'Pull your chest to the bar, keeping the elbows close to your sides.', 'Lower to straight arms with the body still rigid.']::text[], array['Body like a plank', 'Chest to the bar', 'Bend the knees to make it easier']::text[], array['Hips sagging toward the floor', 'Reaching the chin to the bar instead of the chest', 'Stopping short of straight arms']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('424563fb-2199-55f1-83fb-915c6cc390af', 'barbell-curl', 'Barbell Curl', array['biceps']::text[], array['brachialis', 'forearms']::text[], array['barbell']::text[], 'strength', 'isolation', 'isolation', 'beginner', false, false, 'A standing curl with a straight barbell and an underhand grip. Both arms lift together, so it is the curl that takes the most load.', array['Stand tall holding the bar with an underhand grip about shoulder width, arms straight.', 'Keep your elbows by your sides and curl the bar up toward your shoulders.', 'Squeeze the biceps at the top without letting the elbows drift forward.', 'Lower slowly to straight arms.']::text[], array['Elbows pinned to the sides', 'Stand still', 'Lower slower than you lift']::text[], array['Swinging the bar up with the hips and back', 'Elbows travelling forward at the top', 'Stopping short of straight arms']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('1a8049e3-8776-5252-8455-690ca73e9224', 'ez-bar-curl', 'EZ-Bar Curl', array['biceps']::text[], array['brachialis', 'forearms']::text[], array['barbell']::text[], 'strength', 'isolation', 'isolation', 'beginner', false, false, 'A standing curl with the cambered EZ bar. The angled handles turn the palms partly inward, which many lifters find easier on the wrists than a straight bar.', array['Grip the EZ bar underhand on the inner or outer angled sections and stand tall, arms straight.', 'Keeping your elbows by your sides, curl the bar toward your shoulders.', 'Pause briefly at the top.', 'Lower slowly until your arms are straight.']::text[], array['Elbows still', 'Full range', 'Controlled lower']::text[], array['Leaning back to start the bar moving', 'Half reps at the bottom', 'Rolling the shoulders forward at the top']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('aad1c40e-b0d4-5699-a442-d84fe3d85636', 'cable-curl', 'Cable Biceps Curl', array['biceps']::text[], array['brachialis', 'forearms']::text[], array['cable']::text[], 'strength', 'isolation', 'isolation', 'beginner', false, false, 'A standing curl from a low pulley. The cable keeps tension on the biceps at the bottom of the curl, where free weights go light.', array['Attach a straight or EZ handle to a low pulley and stand facing it, holding the handle underhand with straight arms.', 'Step back just enough to lift the weight off the stack and stand tall.', 'Curl the handle toward your shoulders, keeping the elbows by your sides.', 'Lower slowly against the cable until your arms are straight.']::text[], array['Elbows by the ribs', 'Squeeze at the top', 'Resist the cable on the way down']::text[], array['Leaning back to cheat the weight up', 'Standing so far away the cable pulls you forward', 'Letting the stack drop between reps']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('55cb2e2e-a322-5fcb-918c-4bb667ce3da7', 'band-curl', 'Resistance Band Biceps Curl', array['biceps']::text[], array['brachialis', 'forearms']::text[], array['band']::text[], 'strength', 'isolation', 'isolation', 'beginner', false, true, 'A standing curl against a resistance band anchored under the feet. The band gets harder as you curl, and needs no weights.', array['Stand on the middle of a band with feet about hip width, holding one end in each hand, palms forward.', 'Keep your elbows by your sides and curl your hands toward your shoulders.', 'Squeeze at the top, where the band is most stretched.', 'Lower slowly so the band doesn''t snap your arms down.']::text[], array['Elbows pinned', 'Slow on the way down', 'Widen the stance for more tension']::text[], array['Letting the band pull the arms down quickly', 'Elbows drifting forward', 'Leaning back at the top']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('921c2924-b11b-56f9-ac8e-3dabc56eab88', 'zottman-curl', 'Zottman Curl', array['biceps', 'forearms']::text[], array['brachialis']::text[], array['dumbbell']::text[], 'strength', 'isolation', 'isolation', 'intermediate', false, false, 'A dumbbell curl lifted palms-up and lowered palms-down. Turning the forearms at the top makes the slow lowering work the brachialis and forearm muscles as well as the biceps.', array['Stand with a dumbbell in each hand, palms facing forward, elbows by your sides.', 'Curl the dumbbells up toward your shoulders.', 'At the top, turn your forearms so the palms face down.', 'Lower slowly with palms down, then turn the palms forward again at the bottom.']::text[], array['Up palms up, down palms down', 'Take three seconds to lower', 'Elbows still']::text[], array['Turning the forearms before the curl reaches the top', 'Dropping the weights on the way down', 'Going too heavy for the palms-down lowering']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('86f199f9-874e-5134-9ef3-70fa82c5843d', 'reverse-grip-curl', 'Reverse-Grip Barbell Curl', array['brachialis', 'forearms']::text[], array['biceps']::text[], array['barbell']::text[], 'strength', 'isolation', 'isolation', 'beginner', false, false, 'A curl with an overhand (palms-down) grip on a barbell or EZ bar. It shifts the work from the biceps to the brachialis and the muscles on top of the forearm.', array['Hold the bar with an overhand grip about shoulder width, arms straight in front of your thighs.', 'Keep your wrists straight and elbows by your sides.', 'Curl the bar up toward your shoulders.', 'Lower slowly to straight arms.']::text[], array['Knuckles up, wrists straight', 'Elbows by the sides', 'Lighter than your normal curl']::text[], array['Letting the wrists bend down as the bar rises', 'Swinging the bar with the hips', 'Using a load that cuts the range short']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('b7a0652a-5dd3-57e2-a41a-c8ac8ad5da82', 'cable-rope-hammer-curl', 'Cable Rope Hammer Curl', array['brachialis', 'forearms']::text[], array['biceps']::text[], array['cable']::text[], 'strength', 'isolation', 'isolation', 'beginner', false, false, 'A hammer curl with a rope on a low pulley. The neutral grip trains the brachialis and forearms, and the cable keeps tension through the whole range.', array['Attach a rope to a low pulley and stand facing it, holding one end in each hand with thumbs up.', 'Step back so the weight lifts and stand tall with straight arms.', 'Curl the rope toward your shoulders, keeping the elbows by your sides and the thumbs pointing up.', 'Lower slowly until your arms are straight.']::text[], array['Thumbs up the whole way', 'Elbows pinned', 'Slow lower']::text[], array['Turning the palms up as you curl', 'Leaning back to finish the rep', 'Letting the elbows flare out']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('b5b9abdc-d414-5d93-8a2e-2b3e340b776e', 'incline-hammer-curl', 'Incline Hammer Curl', array['brachialis', 'biceps']::text[], array['forearms']::text[], array['dumbbell', 'bench']::text[], 'strength', 'isolation', 'isolation', 'intermediate', false, false, 'A neutral-grip curl lying back on an incline bench so the arms hang behind the body. It trains the brachialis and biceps from a stretched position.', array['Set a bench to about 45–60 degrees and lie back with a dumbbell in each hand, arms hanging straight down and palms facing in.', 'Keep the upper arms still and curl the dumbbells up with the thumbs pointing up.', 'Squeeze at the top without letting the elbows swing forward.', 'Lower slowly to a full stretch.']::text[], array['Thumbs up', 'Elbows stay back', 'Full stretch at the bottom']::text[], array['Swinging the elbows forward to lift the weight', 'Lifting the head and shoulders off the bench', 'Cutting the stretch short']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('009d6b47-be85-56a1-9e94-fed0ac74eb1e', 'standing-dumbbell-shoulder-press', 'Standing Dumbbell Shoulder Press', array['shoulders', 'triceps']::text[], array['upper chest', 'core', 'upper back']::text[], array['dumbbell']::text[], 'strength', 'vertical_push', 'compound', 'intermediate', false, false, 'Pressing two dumbbells overhead while standing, so the trunk and legs have to hold you steady with no bench to lean on.', array['Stand with feet about hip width and lift the dumbbells to shoulder height, palms facing forward or slightly in.', 'Squeeze your glutes and brace your core so your ribs stay down.', 'Press the dumbbells up until your arms are straight and the weights are over the middle of your head.', 'Lower them under control back to shoulder height and repeat.']::text[], array['Ribs down, glutes tight', 'Wrists stacked over elbows', 'Head through at the top']::text[], array['Leaning back to finish the press', 'Letting the dumbbells drift forward', 'Bending the knees to bounce the weights up']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('ec84b2ec-4994-5d4c-b18f-b99fb6742776', 'seated-barbell-shoulder-press', 'Seated Barbell Shoulder Press', array['shoulders', 'triceps']::text[], array['upper chest', 'upper back']::text[], array['barbell', 'bench', 'rack']::text[], 'strength', 'vertical_push', 'compound', 'intermediate', false, false, 'A barbell overhead press from an upright, back-supported bench, which takes the legs out of the lift and keeps the focus on the shoulders and triceps.', array['Set an upright bench inside a rack with the bar at about chin height when you are seated.', 'Sit with your back against the pad and feet flat, grip the bar just outside shoulder width and unrack it to the front of your shoulders.', 'Brace and press the bar straight up, moving your head back slightly to let it pass.', 'Lock out with the bar over your head, then lower it under control to the top of your chest.']::text[], array['Back stays on the pad', 'Bar path close to the face', 'Forearms vertical']::text[], array['Arching the lower back off the bench', 'Lowering the bar only partway', 'Bouncing the bar off the chest']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('9b3bb761-44f7-52dc-846e-d1bc1188d6a5', 'single-arm-dumbbell-shoulder-press', 'Single-Arm Dumbbell Shoulder Press', array['shoulders', 'triceps']::text[], array['obliques', 'core', 'upper back']::text[], array['dumbbell']::text[], 'strength', 'vertical_push', 'compound', 'beginner', false, false, 'A strict standing press with one dumbbell, which works each shoulder on its own and makes the trunk resist leaning toward the weight.', array['Stand tall with feet about hip width and hold one dumbbell at shoulder height, the free hand on your hip.', 'Brace your core and squeeze your glutes so your hips stay level.', 'Press the dumbbell straight up until your arm is straight beside your head.', 'Lower it under control back to the shoulder; finish the set, then switch arms.']::text[], array['Stay tall, no side bend', 'Elbow under the wrist', 'Press up, not out']::text[], array['Leaning away from the dumbbell to press it', 'Using a knee bend to drive it up', 'Shrugging the shoulder to the ear']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('698ef62c-35c8-575f-89b7-86dd2708eccb', 'seated-single-arm-dumbbell-shoulder-press', 'Seated Single-Arm Dumbbell Shoulder Press', array['shoulders', 'triceps']::text[], array['obliques', 'upper chest']::text[], array['dumbbell', 'bench']::text[], 'strength', 'vertical_push', 'compound', 'beginner', false, false, 'Pressing one dumbbell overhead from an upright bench, a steady way to train one shoulder at a time without the legs helping.', array['Sit on an upright bench with your back against the pad and feet flat on the floor.', 'Hold one dumbbell at shoulder height and rest the free hand on your hip or thigh.', 'Press the dumbbell up until your arm is straight overhead.', 'Lower it under control to shoulder height; finish the set, then switch arms.']::text[], array['Back against the pad', 'Shoulders level', 'Smooth, even tempo']::text[], array['Leaning away from the working arm', 'Stopping short of a straight arm', 'Letting the dumbbell drop quickly']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('68eaf69d-bafb-5bb7-8578-171c398ad2cb', 'kettlebell-overhead-press', 'Kettlebell Overhead Press', array['shoulders', 'triceps']::text[], array['obliques', 'core', 'forearms', 'upper back']::text[], array['kettlebell']::text[], 'strength', 'vertical_push', 'compound', 'intermediate', false, false, 'A strict one-arm press from the kettlebell rack position, with the bell resting on the back of the forearm, pressed to a straight arm overhead.', array['Clean the kettlebell to the rack: bell resting on the back of the forearm, wrist straight, elbow tucked close to the ribs.', 'Stand tall with feet about hip width, brace your core and squeeze your glutes; rest the free hand on your hip.', 'Press the bell straight up, letting the forearm stay vertical, until the arm is straight beside your head.', 'Lower it under control back to the rack; finish the set, then switch arms.']::text[], array['Straight wrist, knuckles up', 'Forearm vertical under the bell', 'Squeeze the glutes']::text[], array['Bent wrist so the bell pulls the hand back', 'Leaning sideways away from the bell', 'Elbow flaring wide at the start']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('78ef4fac-d054-503d-b653-841ec236b601', 'dumbbell-push-press', 'Dumbbell Push Press', array['shoulders', 'triceps']::text[], array['quadriceps', 'glutes', 'core']::text[], array['dumbbell']::text[], 'strength', 'vertical_push', 'compound', 'intermediate', false, false, 'Two dumbbells driven overhead with a short knee dip and leg drive, so you can handle more than you could strict-press.', array['Stand with feet about hip width and hold the dumbbells at your shoulders, elbows slightly in front.', 'Brace and dip a few inches by bending the knees, keeping your torso upright.', 'Drive up hard through the legs and press the dumbbells overhead to straight arms.', 'Lower the dumbbells back to your shoulders under control and reset before the next rep.']::text[], array['Short, straight dip', 'Legs first, then arms', 'Finish with biceps by the ears']::text[], array['Dipping forward onto the toes', 'Starting the press before the legs finish', 'Dropping the dumbbells to the shoulders without control']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('a634f900-5319-5bde-b137-05478ab26f15', 'strict-log-press', 'Strict Log Press', array['shoulders', 'triceps']::text[], array['upper chest', 'upper back', 'core']::text[], array['strongman_implements']::text[], 'strength', 'vertical_push', 'compound', 'advanced', false, false, 'Pressing a strongman log from the chest to overhead with no leg drive, which builds the pressing strength behind the log clean and press.', array['Clean the log to the rack position on your chest (or take it from a rack), elbows high and the log resting on your upper chest.', 'Stand tall with feet about hip width, brace hard and squeeze your glutes.', 'Keeping the knees straight, press the log up and slightly back so your head moves through under it.', 'Lock out overhead, then lower it under control back to the chest.']::text[], array['Knees stay locked', 'Head back, then through', 'Big breath and brace before each rep']::text[], array['Leaning back hard to get the log past the face', 'Using a knee bend (that is a push press)', 'Losing the brace at lockout']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('6653a0f7-55fc-5f0f-ace5-4f887612f39b', 'dumbbell-front-raise', 'Dumbbell Front Raise', array['front deltoids']::text[], array['upper chest', 'side deltoids', 'serratus']::text[], array['dumbbell']::text[], 'strength', 'isolation', 'isolation', 'beginner', false, false, 'Raising the dumbbells straight forward to shoulder height to isolate the front of the shoulders.', array['Stand tall with feet about hip width, dumbbells in front of your thighs, palms facing your body.', 'Brace your core and keep a slight bend in the elbows.', 'Raise both dumbbells forward and up until your arms are about level with your shoulders.', 'Pause briefly, then lower slowly back to your thighs.']::text[], array['Lift with the shoulders, not the hips', 'Soft elbows', 'Stop at shoulder height']::text[], array['Swinging the torso to get the weights up', 'Shrugging the shoulders toward the ears', 'Dropping the dumbbells quickly']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('b0f96e01-f6e1-5b03-ac20-cfa717b3c947', 'incline-y-raise', 'Incline Dumbbell Y-Raise', array['traps', 'rear deltoids']::text[], array['side deltoids', 'middle traps', 'rotator cuff']::text[], array['dumbbell', 'bench']::text[], 'strength', 'isolation', 'isolation', 'beginner', false, false, 'Lying face down on an incline bench and raising light dumbbells overhead into a Y to train the lower traps and the back of the shoulders.', array['Set a bench to about 30–45° and lie face down on it, chest on the pad and feet on the floor.', 'Let light dumbbells hang straight down under your shoulders, thumbs pointing up.', 'Keeping the elbows straight, raise your arms forward and up into a Y, out about 30° from your head, until they are in line with your torso.', 'Pause, then lower slowly back to the hang.']::text[], array['Thumbs up', 'Shoulder blades down and back', 'Chest stays on the pad']::text[], array['Lifting the chest off the bench', 'Shrugging the shoulders toward the ears', 'Going too heavy and bending the elbows']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('98bc9887-1d5b-50dc-acea-1f143517e6cd', 'crunch', 'Crunch', array['abdominals']::text[], array['obliques']::text[], array['bodyweight', 'mat']::text[], 'core', 'core', 'isolation', 'beginner', false, true, 'Curling the shoulders and upper back off the floor from a bent-knee position to work the abdominals through a short range.', array['Lie on your back with knees bent and feet flat on the floor about hip width apart.', 'Rest your fingertips lightly at the sides of your head, elbows out.', 'Breathe out and curl your ribs toward your pelvis until your shoulder blades lift off the floor.', 'Pause briefly, then lower slowly back down.']::text[], array['Ribs toward hips', 'Chin slightly tucked', 'Lower slowly']::text[], array['Pulling on the head with the hands', 'Swinging up with momentum', 'Lifting the lower back off the floor']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('237b082b-dd3e-530d-811a-aa73a702edfc', 'sit-up', 'Sit-Up', array['abdominals', 'hip flexors']::text[], array['obliques']::text[], array['bodyweight', 'mat']::text[], 'core', 'core', 'compound', 'beginner', false, true, 'Rolling the whole torso up from lying to sitting upright with the knees bent, working the abdominals and hip flexors through a long range.', array['Lie on your back with knees bent and feet flat on the floor; anchor the feet under something stable if you need to.', 'Rest your fingertips lightly at the sides of your head or cross your arms on your chest.', 'Curl your head and shoulders up first, then keep rolling until your torso is upright.', 'Roll back down under control, one segment of the spine at a time.']::text[], array['Curl up, don''t jerk', 'Exhale on the way up', 'Control the way down']::text[], array['Yanking on the neck with the hands', 'Throwing the arms to get up', 'Dropping back to the floor']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('8e1c8605-2e3f-58d5-a0fe-b50ab482f668', 'lying-leg-raise', 'Lying Leg Raise', array['abdominals', 'hip flexors']::text[], array['obliques']::text[], array['bodyweight', 'mat']::text[], 'core', 'core', 'compound', 'intermediate', false, true, 'Lifting straight legs from just above the floor to vertical while lying on your back, with the abdominals holding the pelvis and lower back steady.', array['Lie on your back with legs straight together and arms by your sides, palms down.', 'Brace so your lower back stays gently pressed toward the floor.', 'Keeping the knees straight, raise your legs until they point at the ceiling.', 'Lower them slowly until the heels are just above the floor, without letting the lower back arch, and repeat.']::text[], array['Lower back stays down', 'Slow on the way down', 'Legs long and together']::text[], array['Arching the lower back as the legs lower', 'Dropping the legs quickly', 'Pushing hard into the floor with the hands to swing the legs up']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('856152b6-bb9f-5dd3-b9f3-db94e52061be', 'high-plank', 'High Plank (Straight-Arm Plank)', array['core']::text[], array['shoulders', 'serratus', 'glutes']::text[], array['bodyweight', 'mat']::text[], 'core', 'core', 'compound', 'beginner', true, true, 'Holding the top of a push-up with straight arms and a straight body, training the trunk and shoulders to hold position.', array['Place your hands on the floor directly under your shoulders, a little wider than shoulder width.', 'Step your feet back so your body forms a straight line from head to heels, toes tucked.', 'Push the floor away, brace your abs and squeeze your glutes.', 'Breathe steadily and hold for the prescribed time.']::text[], array['Push the floor away', 'Ribs down, glutes tight', 'Hands under shoulders']::text[], array['Hips sagging toward the floor', 'Hips piked high', 'Shoulders sinking between the shoulder blades']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('71d7477d-c388-573d-8e01-5ac931a7f892', 'incline-plank', 'Incline Plank (Hands Elevated)', array['core']::text[], array['shoulders', 'glutes']::text[], array['bodyweight', 'bench', 'box']::text[], 'core', 'core', 'compound', 'beginner', true, true, 'A straight-arm plank with the hands on a bench or box, which takes some of the body weight off the arms and trunk; a starting point for the floor plank.', array['Place your hands on the edge of a sturdy bench or box, shoulder width apart.', 'Walk your feet back until your body forms a straight line from head to heels, arms straight under the shoulders.', 'Brace your abs and squeeze your glutes.', 'Breathe steadily and hold for the prescribed time.']::text[], array['Straight line head to heels', 'Shoulders over hands', 'Squeeze glutes']::text[], array['Letting the hips sag', 'Using a bench or box that can slide', 'Holding your breath']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('892003a6-3735-5fea-897a-2304306bd5f4', 'hollow-body-hold', 'Hollow Body Hold', array['abdominals']::text[], array['hip flexors', 'obliques']::text[], array['bodyweight', 'mat']::text[], 'core', 'core', 'compound', 'intermediate', true, true, 'Holding a shallow banana shape on your back, lower back pressed down and arms and legs reaching long, to train the abs to resist arching.', array['Lie on your back with your arms overhead and legs straight together.', 'Press your lower back into the floor and tuck your chin slightly.', 'Lift your shoulder blades, arms and legs a few inches off the floor, keeping the lower back down.', 'Breathe steadily and hold for the prescribed time.']::text[], array['Lower back glued down', 'Reach long through hands and toes', 'Ribs pulled toward hips']::text[], array['Lower back peeling off the floor', 'Legs held too low for your strength', 'Holding your breath']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('c3047d43-0218-5367-95e5-37979389b83a', 'reverse-crunch', 'Reverse Crunch', array['abdominals']::text[], array['obliques', 'hip flexors']::text[], array['bodyweight', 'mat']::text[], 'core', 'core', 'isolation', 'beginner', false, true, 'Curling the pelvis up off the floor to bring the knees toward the chest while lying on your back, working the abs from the bottom up.', array['Lie on your back with arms by your sides, palms down, hips and knees bent about 90° so the shins are level.', 'Breathe out and curl your pelvis up off the floor, bringing your knees toward your chest.', 'Keep your upper back and shoulders on the floor.', 'Lower your hips slowly back to the start without letting the feet drop.']::text[], array['Curl the tailbone up', 'Knees to chest, not just up', 'Slow on the way down']::text[], array['Swinging the legs to throw the hips up', 'Pushing hard through the hands', 'Dropping the hips quickly']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('50c72fc1-d529-53a4-8d96-2ed9383a9c39', 'v-up', 'V-Up', array['abdominals', 'hip flexors']::text[], array['obliques']::text[], array['bodyweight', 'mat']::text[], 'core', 'core', 'compound', 'advanced', false, true, 'Lifting the straight legs and the torso at the same time to meet in a V balanced on the seat, then lowering both back to the floor.', array['Lie flat on your back with arms overhead and legs straight together.', 'Brace, then lift your arms, shoulders and straight legs at the same time.', 'Reach your hands toward your shins as your body folds into a V, balancing on your seat.', 'Lower your torso and legs together back to the floor under control.']::text[], array['Legs and chest meet in the middle', 'Reach for the shins', 'Control the way down']::text[], array['Bending the knees to make it easier without meaning to', 'Flopping back to the floor', 'Leading only with the arms and head']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('a12765ae-7f15-5049-846f-060930d9bd1c', 'hanging-leg-raise', 'Hanging Leg Raise', array['abdominals', 'hip flexors']::text[], array['forearms', 'lats', 'obliques']::text[], array['pull_up_bar']::text[], 'core', 'core', 'compound', 'advanced', false, false, 'Raising straight legs to at least hip height while hanging from a bar, a harder version of the hanging knee raise.', array['Hang from a pull-up bar with an overhand grip, arms straight and shoulders engaged.', 'Brace and raise your straight legs together until they are at least level with your hips, curling the pelvis up at the top.', 'Pause briefly without swinging.', 'Lower your legs slowly back to the hang.']::text[], array['Legs straight and together', 'Curl the pelvis at the top', 'No swinging']::text[], array['Swinging for momentum', 'Bending the knees as the legs rise', 'Dropping the legs quickly']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('d365efac-aa02-5e6b-913e-e98af97e53a0', 'overhead-squat', 'Overhead Squat', array['quadriceps', 'glutes']::text[], array['shoulders', 'upper back', 'core', 'adductors']::text[], array['barbell', 'rack']::text[], 'strength', 'squat', 'compound', 'advanced', false, false, 'A squat with the barbell locked out overhead on a wide grip. It asks for an upright torso, strong overhead stability and good ankle and hip mobility, so it is usually trained light as a skill and strength lift.', array['Take the bar from a rack (or press it from behind the neck) and lock it out overhead with a wide, snatch-width grip.', 'Set your feet about shoulder width with the toes turned slightly out, arms straight and the bar over the middle of your feet.', 'Brace, then sit down between your hips, keeping the chest up and actively pushing the bar up toward the ceiling.', 'Descend as deep as you can while the bar stays over mid-foot and your back stays neutral.', 'Drive up through the whole foot to standing, arms locked the whole time.']::text[], array['Push the bar up into the ceiling', 'Bar stays over mid-foot', 'Knees track over the toes', 'Chest up, ribs down']::text[], array['Letting the bar drift forward of the feet', 'Bending the elbows under load', 'Heels lifting as the torso tips forward', 'Loading it before the bodyweight or PVC version is solid']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('c47e1bc6-12e4-5c5b-b51f-7eebe16dde4a', 'single-leg-hip-thrust', 'Single-Leg Hip Thrust', array['glutes']::text[], array['hamstrings', 'quadriceps', 'core']::text[], array['bench', 'bodyweight']::text[], 'strength', 'hinge', 'compound', 'intermediate', false, false, 'A hip thrust from a bench driven by one leg while the other knee is held up. It loads each glute through a longer range than a floor bridge without needing a barbell.', array['Sit on the floor with the bottom of your shoulder blades against the edge of a stable bench.', 'Plant one foot flat, about hip width from the midline, with the knee bent; lift the other knee up toward your chest.', 'Brace and drive through the heel of the planted foot to lift your hips until your torso is level with the bench.', 'Squeeze the glute at the top with the chin tucked, then lower the hips under control.', 'Do all reps on one side, then switch.']::text[], array['Drive through the heel', 'Hips stay level', 'Chin tucked, ribs down']::text[], array['Letting the hip on the free-leg side drop or rotate', 'Arching the lower back at the top', 'Bench sliding back during the set']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('1276423e-fbc3-5bc9-9da4-8ac3cbeea495', 'barbell-glute-bridge', 'Barbell Glute Bridge', array['glutes']::text[], array['hamstrings', 'core']::text[], array['barbell', 'mat']::text[], 'strength', 'hinge', 'compound', 'intermediate', false, false, 'A glute bridge from the floor with a barbell across the hips. The range is shorter than a bench hip thrust, which makes it simple to set up and easy to load heavy for the glutes.', array['Sit on the floor and roll a padded barbell over your legs until it rests in the crease of your hips.', 'Lie back with your knees bent and feet flat about hip width, heels roughly under the knees at the top.', 'Hold the bar in place with both hands, brace and tuck the ribs down.', 'Drive through your heels to lift the hips until your shoulders, hips and knees form a straight line, squeezing the glutes.', 'Pause, then lower the hips to the floor under control.']::text[], array['Ribs down, chin tucked', 'Push through the heels', 'Squeeze the glutes at the top']::text[], array['Arching the lower back to get the hips higher', 'Feet too far away, shifting work to the hamstrings', 'Skipping a bar pad on the hips', 'Bouncing the hips off the floor']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('334e70c1-7766-5266-88e3-2284b32aac0b', 'single-leg-glute-bridge', 'Single-Leg Glute Bridge', array['glutes']::text[], array['hamstrings', 'core']::text[], array['bodyweight', 'mat']::text[], 'strength', 'hinge', 'compound', 'beginner', false, false, 'A glute bridge driven by one leg while the other is held straight in the air. It doubles the load on each side without equipment and shows up left-right differences.', array['Lie on your back with both knees bent and feet flat, arms on the floor by your sides.', 'Straighten one leg so it points forward in line with the bent leg''s thigh.', 'Press through the heel of the planted foot and lift the hips until your shoulders, hips and knee form a straight line.', 'Keep the hips level, pause briefly, then lower under control.', 'Do all reps on one side, then switch.']::text[], array['Hips stay level', 'Drive through the heel', 'Ribs down']::text[], array['Letting the hip on the lifted-leg side drop', 'Arching the lower back at the top', 'Pushing through the toes instead of the heel']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('e787ace6-eb75-5cf2-ab58-d321a0a20184', 'wall-sit', 'Wall Sit', array['quadriceps']::text[], array['glutes', 'adductors']::text[], array['bodyweight']::text[], 'strength', 'squat', 'compound', 'beginner', true, true, 'An isometric squat hold with your back against a wall and thighs level. It builds quad endurance with no equipment and no impact.', array['Stand with your back against a wall and walk your feet out about two feet in front of you, hip width apart.', 'Slide your back down the wall until your thighs are level with the floor and your knees are bent about 90°.', 'Adjust your feet so the knees sit over the ankles, then rest your hands on your thighs or let them hang.', 'Hold for the prescribed time while breathing steadily, then slide back up the wall to stand.']::text[], array['Back and head on the wall', 'Knees over the ankles', 'Weight through the heels']::text[], array['Pushing the hands into the thighs to take the load off', 'Feet too close, so the knees travel far past the toes', 'Holding the breath']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('16cc9731-d91c-5bdd-b9e1-8d004866c1fd', 'stiff-leg-deadlift', 'Stiff-Leg Deadlift', array['hamstrings', 'glutes']::text[], array['spinal erectors', 'forearms']::text[], array['barbell', 'dumbbell']::text[], 'strength', 'hinge', 'compound', 'intermediate', false, false, 'A hip hinge with the knees held nearly straight throughout. Compared with a Romanian deadlift the knees bend less, so the hamstrings are stretched further at the bottom and the load is usually lighter.', array['Stand tall holding a barbell or dumbbells in front of your thighs, feet about hip width.', 'Unlock the knees just slightly and keep them at that angle for the whole set.', 'Push your hips back and hinge forward, keeping the weight close to your legs and your back flat.', 'Lower until your hamstrings stop you, typically to around mid-shin, without letting the back round.', 'Drive the hips forward to return to standing.']::text[], array['Knees soft but fixed', 'Hips back', 'Flat back, long neck', 'Weight close to the legs']::text[], array['Rounding the back to reach lower', 'Locking the knees hard', 'Letting the weight swing away from the body', 'Bending the knees as it gets hard, turning it into an RDL']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('66fd62af-b557-5780-9656-442804983fc6', 'kettlebell-deadlift', 'Kettlebell Deadlift', array['glutes', 'hamstrings']::text[], array['quadriceps', 'spinal erectors', 'forearms']::text[], array['kettlebell']::text[], 'strength', 'hinge', 'compound', 'beginner', false, false, 'A deadlift with one kettlebell on the floor between the feet. It is a common first way to learn the hip hinge and the groundwork for the kettlebell swing.', array['Stand with your feet about hip to shoulder width and the kettlebell on the floor between your feet, in line with your ankles.', 'Push your hips back and bend your knees to reach the handle with both hands, back flat and chest up.', 'Pull your shoulders down and back, brace, and take the slack out of your arms.', 'Push the floor away and stand up tall, squeezing the glutes at the top with straight arms.', 'Hinge back down the same way and set the bell on the floor.']::text[], array['Hips back, chest proud', 'Bell between the ankles', 'Push the floor away', 'Stand tall, don''t lean back']::text[], array['Placing the bell in front of the toes', 'Squatting straight down with no hip hinge', 'Rounding the back to reach the bell', 'Leaning back at the top']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('44319062-18b8-5ae1-b17f-e009d241de2e', 'b-stance-romanian-deadlift', 'B-Stance Romanian Deadlift', array['hamstrings', 'glutes']::text[], array['core', 'spinal erectors', 'forearms']::text[], array['dumbbell', 'barbell']::text[], 'strength', 'hinge', 'compound', 'intermediate', false, false, 'A Romanian deadlift in a staggered “kickstand” stance: the back foot rests on its toes beside the front heel for balance while the front leg does most of the work. A stepping stone between the two-leg and single-leg versions.', array['Stand holding dumbbells in front of your thighs, then slide one foot back so its toes are level with the front heel and its heel is up.', 'Keep most of your weight, about 70–80%, on the front foot; the back foot is only for balance.', 'Soften the front knee and push your hips back, lowering the dumbbells close to the front leg with a flat back.', 'Lower until you feel a strong stretch in the front hamstring, usually to just below the knee.', 'Drive the front hip forward to stand, finish all reps, then switch sides.']::text[], array['Weight on the front heel', 'Hips square', 'Back foot is a kickstand']::text[], array['Shifting the weight onto the back foot', 'Letting the hips rotate open', 'Rounding the back to go lower']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('27e5a563-9dad-5e82-9e76-4417255d5524', 'deficit-romanian-deadlift', 'Deficit Romanian Deadlift', array['hamstrings', 'glutes']::text[], array['spinal erectors', 'forearms']::text[], array['barbell', 'dumbbell']::text[], 'strength', 'hinge', 'compound', 'advanced', false, false, 'A Romanian deadlift performed standing on a low, stable platform so the weight can travel lower than the feet allow on the floor, adding range for lifters who can already hinge deep with a flat back.', array['Stand on a sturdy platform or plates about 5–10 cm high, holding the bar in front of your thighs.', 'Soften your knees and push your hips back, sliding the bar down your thighs.', 'Keep hinging past the knees while your back stays flat, to around mid-shin or wherever your hamstrings stop you.', 'Drive the hips forward to stand tall.']::text[], array['Hips back, not down', 'Bar touches the legs', 'Only as deep as a flat back allows']::text[], array['Rounding the lower back to use the extra range', 'Using a platform that wobbles', 'Turning it into a squat by bending the knees more']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('1c69d266-9fdf-5bc2-ab12-487664e42fc4', 'single-leg-calf-raise', 'Single-Leg Calf Raise', array['calves']::text[], array['foot and ankle stabilizers']::text[], array['bodyweight', 'dumbbell']::text[], 'strength', 'isolation', 'isolation', 'beginner', false, true, 'A standing calf raise on one leg, which doubles the load without equipment and trains each side on its own. Holding a wall or rail with the free hand keeps the focus on the calf rather than balance.', array['Stand on one foot on the floor or with the ball of the foot on a step, lightly holding a wall or rail with one hand.', 'Bend the other knee so that foot is off the floor behind you; hold a dumbbell in the working side''s hand if needed.', 'Lower the heel for a stretch, then rise onto the ball of the foot as high as you can.', 'Pause at the top, then lower slowly. Finish the set and switch legs.']::text[], array['Full height, full stretch', 'Push through the big toe', 'Slow on the way down']::text[], array['Bouncing out of the bottom', 'Rolling onto the outside of the foot', 'Leaning hard on the support hand']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('8d6e45e3-aece-52bd-a9f6-c5de8131548b', 'standing-quad-stretch', 'Standing Quad Stretch', array['quadriceps']::text[], array['hip flexors']::text[], array['bodyweight']::text[], 'mobility', 'mobility', null, 'beginner', true, true, 'A standing stretch for the front of the thigh: hold one ankle behind you and draw the heel toward the glute.', array['Stand tall on one leg, holding a wall or chair with one hand if you need balance.', 'Bend the other knee and take hold of that ankle (or the top of the foot) with the same-side hand.', 'Draw the heel toward your glute, keeping the knees side by side and the thigh pointing down.', 'Tuck the pelvis slightly and squeeze the glute to deepen the stretch; hold, then switch sides.']::text[], array['Knees together', 'Tuck the pelvis', 'Stand tall']::text[], array['Arching the lower back', 'Letting the bent knee drift forward or out to the side', 'Yanking the heel in instead of easing into it']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('ed14753d-fa7c-563b-92b2-914e4a6eea5f', 'half-kneeling-hip-flexor-stretch', 'Half-Kneeling Hip Flexor Stretch', array['hip flexors']::text[], array['quadriceps', 'glutes']::text[], array['mat']::text[], 'mobility', 'mobility', null, 'beginner', true, true, 'A kneeling stretch for the front of the hip with the back foot flat on the floor. Tucking the pelvis does most of the work; it is a gentler starting point than the couch stretch.', array['Kneel on a pad with one knee down and the other foot flat in front, front knee bent about 90°.', 'Rest the top of the back foot on the floor and place your hands on your hips.', 'Tuck your pelvis under and squeeze the glute of the back leg until you feel a stretch at the front of that hip.', 'Keep the torso tall and, if needed, shift the hips forward slightly; hold, then switch sides.']::text[], array['Tuck the pelvis', 'Squeeze the back glute', 'Ribs down, torso tall']::text[], array['Arching the lower back instead of tucking', 'Lunging far forward so the stretch moves out of the hip', 'Kneeling on a hard floor with no pad']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('f3f7ce67-1024-5bec-b87f-545105ad9694', 'wall-calf-stretch', 'Wall Calf Stretch', array['calves']::text[], array['ankles']::text[], array['bodyweight']::text[], 'mobility', 'mobility', null, 'beginner', true, true, 'A standing stretch for the calf of the straight back leg, with the hands on a wall and the heel pressed to the floor.', array['Stand facing a wall and place both hands on it at about shoulder height.', 'Step one foot back and keep that leg straight, toes pointing forward and the heel on the floor.', 'Bend the front knee and lean your hips toward the wall until you feel a stretch in the back calf.', 'Hold, breathing slowly, then switch legs.']::text[], array['Back heel down', 'Back knee straight', 'Toes pointing at the wall']::text[], array['Letting the back heel lift', 'Turning the back foot out', 'Bending the back knee, which shifts the stretch lower']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
