insert into public.training_programs (id, slug, name, summary, description, category_id, difficulty, duration_weeks, days_per_week, session_minutes, goals, equipment, tier, progression, warmup, cooldown, low_impact, needs_specialist_review, is_published, source) values ('564cc661-d184-5e8c-b40b-3bfeae3fa8f3', 'daily-mobility-flow', 'Daily Mobility Flow', 'Short daily routines for hips, spine, shoulders and ankles.', 'Fifteen to twenty minutes of mobility you can do on its own or after training. Move within a comfortable, pain-free range — longer holds and regular practice are what improve range of motion. If a movement causes pain, skip it; this is not a rehabilitation program.', '5f664aca-35b8-56b3-941c-843e25abd264', 'beginner', 4, 4, 15, array['mobility', 'general_health', 'type:mobility', 'type:low_impact']::text[], array['mat', 'band', 'bodyweight']::text[], 'pro', 'Hold times grow by about 5 seconds each week as positions become more comfortable.', array['1 minute of slow nasal breathing', 'Cat-cow × 5']::text[], array['Child''s pose — 60 seconds of slow breathing']::text[], true, false, true, 'curated') on conflict (slug) do update set name = excluded.name, summary = excluded.summary, description = excluded.description, category_id = excluded.category_id, difficulty = excluded.difficulty, duration_weeks = excluded.duration_weeks, days_per_week = excluded.days_per_week, session_minutes = excluded.session_minutes, goals = excluded.goals, equipment = excluded.equipment, tier = excluded.tier, progression = excluded.progression, warmup = excluded.warmup, cooldown = excluded.cooldown, low_impact = excluded.low_impact, needs_specialist_review = excluded.needs_specialist_review, is_published = true;
