insert into public.training_programs (id, slug, name, summary, description, category_id, difficulty, duration_weeks, days_per_week, session_minutes, goals, equipment, tier, progression, warmup, cooldown, low_impact, needs_specialist_review, is_published, source) values ('cb30a218-6402-5a0d-b42d-852bc9c06f54', 'womens-strength-progression', 'Strong Foundations: Women''s Strength', 'A full-body strength plan that progresses load — not just reps — three days a week.', 'Shaped by feedback from women lifters who wanted real strength progression rather than ''toning'' circuits. Research shows women gain muscle at a similar relative rate to men and often gain upper-body strength faster, so nothing here assumes you should lift light: heavy compound lifts, upper-body pulling strength and glute development, with adjustable volume.', '90a96eaf-8db5-5a1e-af56-8d9457c32895', 'beginner', 8, 3, 50, array['build_strength', 'build_muscle', 'general_health', 'lose_fat', 'type:strength', 'type:hypertrophy']::text[], array['barbell', 'dumbbell', 'bench', 'rack', 'pull_up_bar', 'band', 'cable']::text[], 'plus', 'Add load when all reps are completed at or below the target RPE; target effort rises from RPE 7 to about 9 by week 5. Pull-ups progress from band-assisted to bodyweight by using lighter bands every 1–2 weeks. Week 8 is a deload.', array['3–5 minutes easy cardio (walk, bike, rower or skipping)', 'World''s greatest stretch × 3 per side', 'Bodyweight squats × 10', 'Band pull-aparts or arm circles × 15', '2–3 ramp-up sets of your first lift, building toward working weight']::text[], array['3–5 minutes easy walking or cycling to bring heart rate down', 'Child''s pose — 60 seconds', 'Figure-four glute stretch — 30–45 seconds per side', 'Slow nasal breathing — 1–2 minutes']::text[], false, false, true, 'curated') on conflict (slug) do update set name = excluded.name, summary = excluded.summary, description = excluded.description, category_id = excluded.category_id, difficulty = excluded.difficulty, duration_weeks = excluded.duration_weeks, days_per_week = excluded.days_per_week, session_minutes = excluded.session_minutes, goals = excluded.goals, equipment = excluded.equipment, tier = excluded.tier, progression = excluded.progression, warmup = excluded.warmup, cooldown = excluded.cooldown, low_impact = excluded.low_impact, needs_specialist_review = excluded.needs_specialist_review, is_published = true;
