insert into public.training_programs (id, slug, name, summary, description, category_id, difficulty, duration_weeks, days_per_week, session_minutes, goals, equipment, tier, progression, warmup, cooldown, low_impact, needs_specialist_review, is_published, source) values ('108f1698-2933-536b-81c3-4d98b323dbf2', 'intermediate-weekly-undulating', 'Weekly Undulating Strength: Volume, Light & Heavy Days', 'Three days a week — a volume day, a recovery day and a heavy day — with weekly records instead of session-to-session jumps.', 'For lifters whose novice progression has stalled. In the style of the Texas Method from Rippetoe and Kilgore''s Practical Programming: Monday''s 5 × 5 at about 90% of Friday''s weight builds the stress, Wednesday''s light day lets you recover, and Friday you set a new rep record. Progress comes weekly rather than every session. Bench and overhead press alternate weeks as the main press.', '42a6d9d6-53e5-5755-8274-3a0b73c46fb9', 'intermediate', 8, 3, 40, array['build_strength', 'type:strength', 'type:powerlifting']::text[], array['barbell', 'rack', 'bench', 'pull_up_bar']::text[], 'plus', 'Each week: add 2.5 kg / 5 lb to the intensity-day top set and set volume day at about 90% of it (light day squats at 80% of volume day). Weeks 1–3 chase new 5-rep maxes, week 4 is lighter, weeks 5–7 rotate to heavy triples and doubles, and week 8 is a deload. If you miss intensity-day reps twice, drop volume day to 4 × 5 before cutting the weight.', array['3–5 minutes easy cardio (walk, bike, rower or skipping)', 'World''s greatest stretch × 3 per side', 'Bodyweight squats × 10', 'Band pull-aparts or arm circles × 15', '2–3 ramp-up sets of your first lift, building toward working weight']::text[], array['3–5 minutes easy walking or cycling to bring heart rate down', 'Child''s pose — 60 seconds', 'Figure-four glute stretch — 30–45 seconds per side', 'Slow nasal breathing — 1–2 minutes']::text[], false, false, true, 'curated') on conflict (slug) do update set name = excluded.name, summary = excluded.summary, description = excluded.description, category_id = excluded.category_id, difficulty = excluded.difficulty, duration_weeks = excluded.duration_weeks, days_per_week = excluded.days_per_week, session_minutes = excluded.session_minutes, goals = excluded.goals, equipment = excluded.equipment, tier = excluded.tier, progression = excluded.progression, warmup = excluded.warmup, cooldown = excluded.cooldown, low_impact = excluded.low_impact, needs_specialist_review = excluded.needs_specialist_review, is_published = true;
insert into public.program_weeks (id, program_id, week_number, focus, is_deload) values ('93c73af4-cb7e-52e7-b5f9-0349d63af56d', '108f1698-2933-536b-81c3-4d98b323dbf2', 1, 'Weekly records: a new 5-rep max on intensity day (week 1)', false) on conflict (id) do update set focus = excluded.focus, is_deload = excluded.is_deload;
