insert into public.training_programs (id, slug, name, summary, description, category_id, difficulty, duration_weeks, days_per_week, session_minutes, goals, equipment, tier, progression, warmup, cooldown, low_impact, needs_specialist_review, is_published, source) values ('89edf3a7-cf49-5b29-b6c9-4926622a474f', 'powerlifting-base-block', 'Powerlifting Base Block', 'Four days of percentage-based squat, bench and deadlift training with RPE checks.', 'An intermediate block to build strength and technique in the competition lifts. Three weeks of sets of 4–5 at 72.5–77.5%, a deload, then three weeks of triples at 80–85% and a deload with an optional re-test. Squat and bench are trained twice a week, the deadlift once plus front squats. Each set has a percentage and an RPE: if the RPE is much higher than written, use the RPE.', '355ad483-2f7b-50b3-b6ce-6ac1400d6063', 'intermediate', 8, 4, 50, array['build_strength', 'type:powerlifting', 'type:strength']::text[], array['barbell', 'rack', 'bench', 'dumbbell', 'cable']::text[], 'plus', 'Percentages of your current 1RM rise 2.5% a week. If a set is more than 1 RPE above target, keep the weight for the rest of that session. Weeks 4 and 8 are deloads; at the end of week 8 you can work up to a smooth heavy triple to estimate your new max for the next block.', array['3–5 minutes easy cardio (walk, bike, rower or skipping)', 'World''s greatest stretch × 3 per side', 'Bodyweight squats × 10', 'Band pull-aparts or arm circles × 15', '2–3 ramp-up sets of your first lift, building toward working weight']::text[], array['3–5 minutes easy walking or cycling to bring heart rate down', 'Child''s pose — 60 seconds', 'Figure-four glute stretch — 30–45 seconds per side', 'Slow nasal breathing — 1–2 minutes']::text[], false, false, true, 'curated') on conflict (slug) do update set name = excluded.name, summary = excluded.summary, description = excluded.description, category_id = excluded.category_id, difficulty = excluded.difficulty, duration_weeks = excluded.duration_weeks, days_per_week = excluded.days_per_week, session_minutes = excluded.session_minutes, goals = excluded.goals, equipment = excluded.equipment, tier = excluded.tier, progression = excluded.progression, warmup = excluded.warmup, cooldown = excluded.cooldown, low_impact = excluded.low_impact, needs_specialist_review = excluded.needs_specialist_review, is_published = true;
