insert into public.training_programs (id, slug, name, summary, description, category_id, difficulty, duration_weeks, days_per_week, session_minutes, goals, equipment, tier, progression, warmup, cooldown, low_impact, needs_specialist_review, is_published, source) values ('da25aeff-99dc-5604-a47d-7532730c5ddf', 'bench-press-specialist', 'Bench Press Specialist', 'Bench three times a week — heavy, volume and paused — with the upper-back and triceps work to support it.', 'An 8-week bench block for lifters who want a bigger press. Day 1 is heavy, day 3 builds volume with close-grip work, and day 4 practises competition-style paused reps. Lower-body training is kept to maintenance so your recovery goes to the bench, and rows balance the pressing. Use the custom program builder if you want exact loads calculated from your max.', '7d659f3d-da44-5338-9410-fe56f85fcea1', 'intermediate', 8, 4, 50, array['build_strength', 'build_muscle', 'type:powerlifting', 'type:strength']::text[], array['barbell', 'rack', 'bench', 'dumbbell', 'cable', 'pull_up_bar']::text[], 'plus', 'Target RPE rises by about 0.5 a week (capped at RPE 9 for multi-set work). When every set of the main bench lift is completed at or below the target RPE, add 2.5 kg / 5 lb next week. Week 8 is a deload — or test a new max at the end of it if you feel fresh.', array['3–5 minutes easy cardio (walk, bike, rower or skipping)', 'World''s greatest stretch × 3 per side', 'Bodyweight squats × 10', 'Band pull-aparts or arm circles × 15', '2–3 ramp-up sets of your first lift, building toward working weight']::text[], array['3–5 minutes easy walking or cycling to bring heart rate down', 'Child''s pose — 60 seconds', 'Figure-four glute stretch — 30–45 seconds per side', 'Slow nasal breathing — 1–2 minutes']::text[], false, false, true, 'curated') on conflict (slug) do update set name = excluded.name, summary = excluded.summary, description = excluded.description, category_id = excluded.category_id, difficulty = excluded.difficulty, duration_weeks = excluded.duration_weeks, days_per_week = excluded.days_per_week, session_minutes = excluded.session_minutes, goals = excluded.goals, equipment = excluded.equipment, tier = excluded.tier, progression = excluded.progression, warmup = excluded.warmup, cooldown = excluded.cooldown, low_impact = excluded.low_impact, needs_specialist_review = excluded.needs_specialist_review, is_published = true;
