insert into public.training_programs (id, slug, name, summary, description, category_id, difficulty, duration_weeks, days_per_week, session_minutes, goals, equipment, tier, progression, warmup, cooldown, low_impact, needs_specialist_review, is_published, source) values ('2870e6e8-4f48-50a1-8a83-48812bfb4128', 'squat-specialist', 'Squat Specialist', 'Three squat sessions a week — heavy, paused and tempo — plus targeted quad and posterior-chain work.', 'An 8-week block for building a stronger squat. Heavy sets early in the week, pause squats for position and power out of the hole, and tempo squats for control. Upper-body work is kept to maintenance. Use the custom program builder for loads based on your max.', 'b23c068a-75d2-5672-94b4-160c5a19e769', 'intermediate', 8, 4, 45, array['build_strength', 'build_muscle', 'type:powerlifting', 'type:strength']::text[], array['barbell', 'rack', 'bench', 'dumbbell', 'machine', 'pull_up_bar']::text[], 'plus', 'Target RPE rises by about 0.5 a week (capped at RPE 9 for multi-set work). Add 2.5–5 kg / 5–10 lb to the heavy squat when every set is completed at or below the target RPE. Week 8 is a deload.', array['3–5 minutes easy cardio (walk, bike, rower or skipping)', 'World''s greatest stretch × 3 per side', 'Bodyweight squats × 10', 'Band pull-aparts or arm circles × 15', '2–3 ramp-up sets of your first lift, building toward working weight']::text[], array['3–5 minutes easy walking or cycling to bring heart rate down', 'Child''s pose — 60 seconds', 'Figure-four glute stretch — 30–45 seconds per side', 'Slow nasal breathing — 1–2 minutes']::text[], false, false, true, 'curated') on conflict (slug) do update set name = excluded.name, summary = excluded.summary, description = excluded.description, category_id = excluded.category_id, difficulty = excluded.difficulty, duration_weeks = excluded.duration_weeks, days_per_week = excluded.days_per_week, session_minutes = excluded.session_minutes, goals = excluded.goals, equipment = excluded.equipment, tier = excluded.tier, progression = excluded.progression, warmup = excluded.warmup, cooldown = excluded.cooldown, low_impact = excluded.low_impact, needs_specialist_review = excluded.needs_specialist_review, is_published = true;
