insert into public.training_programs (id, slug, name, summary, description, category_id, difficulty, duration_weeks, days_per_week, session_minutes, goals, equipment, tier, progression, warmup, cooldown, low_impact, needs_specialist_review, is_published, source) values ('96b60f4a-3194-506a-8121-f43083cf9827', 'strongman-4-day-events', 'Strongman 4-Day: Statics & Events', 'Max-effort log and deadlift days, a squat/volume day and a full event day with real implements.', 'How competitive strongmen commonly organise a week: a max-effort overhead day (log or axle), a max-effort deadlift day with an above-the-knee pull, a squat and overhead-volume day, and a dedicated event day — yoke, farmer''s walk, stones and a drag — written as distance with a target time. Two 3-week waves (triples, then heavier doubles and singles), each followed by a deload. Needs a log, yoke, farmer''s handles, stones and a sled.', '813b72f1-cbac-52f4-8034-3cf0560cfa7f', 'intermediate', 8, 4, 55, array['build_strength', 'athletic_performance', 'type:strongman', 'type:strength']::text[], array['barbell', 'rack', 'bench', 'strongman_implements', 'sled', 'cable', 'pull_up_bar']::text[], 'plus', 'Static lifts follow RPE targets that rise through each wave (triples in weeks 1–3, doubles and a heavy single in weeks 5–7). Events progress by load: when every 20 m run is under the target time, add the listed jump next week; stones move up when every rep is smooth. Weeks 4 and 8 deload. Peaking for a contest? Use the custom strongman builder''s contest-prep goal for event rehearsals and openers.', array['3–5 minutes easy cardio (walk, bike, rower or skipping)', 'World''s greatest stretch × 3 per side', 'Bodyweight squats × 10', 'Band pull-aparts or arm circles × 15', '2–3 ramp-up sets of your first lift, building toward working weight']::text[], array['3–5 minutes easy walking or cycling to bring heart rate down', 'Child''s pose — 60 seconds', 'Figure-four glute stretch — 30–45 seconds per side', 'Slow nasal breathing — 1–2 minutes']::text[], false, false, true, 'curated') on conflict (slug) do update set name = excluded.name, summary = excluded.summary, description = excluded.description, category_id = excluded.category_id, difficulty = excluded.difficulty, duration_weeks = excluded.duration_weeks, days_per_week = excluded.days_per_week, session_minutes = excluded.session_minutes, goals = excluded.goals, equipment = excluded.equipment, tier = excluded.tier, progression = excluded.progression, warmup = excluded.warmup, cooldown = excluded.cooldown, low_impact = excluded.low_impact, needs_specialist_review = excluded.needs_specialist_review, is_published = true;
