insert into public.training_programs (id, slug, name, summary, description, category_id, difficulty, duration_weeks, days_per_week, session_minutes, goals, equipment, tier, progression, warmup, cooldown, low_impact, needs_specialist_review, is_published, source) values ('6fee5ff2-7979-5b1d-99b1-09284748c679', 'full-body-hypertrophy-3-day', 'Full-Body Hypertrophy: 3 Days', 'Three full-body sessions a week: every muscle trained three times with about 10 hard sets per muscle that build through the block.', 'The most time-efficient way to build muscle for beginners and busy lifters. Research shows growth depends mostly on weekly hard sets taken close to failure, and that training each muscle at least twice a week is a sensible default — full-body sessions three times a week hit both. Each day uses a different squat, hinge, press and pull plus small-muscle work, with lengthened-position exercises like incline curls and overhead triceps extensions.', '8f19916a-c1e0-5027-887e-6f78ca07b045', 'beginner', 6, 3, 45, array['build_muscle', 'build_strength', 'type:hypertrophy', 'type:strength']::text[], array['barbell', 'rack', 'bench', 'dumbbell', 'cable', 'machine']::text[], 'pro', 'Double progression: add reps until every set reaches the top of the range at the week''s reps-in-reserve target, then add the smallest load jump. Weeks 1–2 build effort, weeks 3–5 add a set to key exercises, week 6 is a deload. Repeat the block a little heavier.', array['3–5 minutes easy cardio (walk, bike, rower or skipping)', 'World''s greatest stretch × 3 per side', 'Bodyweight squats × 10', 'Band pull-aparts or arm circles × 15', '2–3 ramp-up sets of your first lift, building toward working weight']::text[], array['3–5 minutes easy walking or cycling to bring heart rate down', 'Child''s pose — 60 seconds', 'Figure-four glute stretch — 30–45 seconds per side', 'Slow nasal breathing — 1–2 minutes']::text[], false, false, true, 'curated') on conflict (slug) do update set name = excluded.name, summary = excluded.summary, description = excluded.description, category_id = excluded.category_id, difficulty = excluded.difficulty, duration_weeks = excluded.duration_weeks, days_per_week = excluded.days_per_week, session_minutes = excluded.session_minutes, goals = excluded.goals, equipment = excluded.equipment, tier = excluded.tier, progression = excluded.progression, warmup = excluded.warmup, cooldown = excluded.cooldown, low_impact = excluded.low_impact, needs_specialist_review = excluded.needs_specialist_review, is_published = true;
