insert into public.training_programs (id, slug, name, summary, description, category_id, difficulty, duration_weeks, days_per_week, session_minutes, goals, equipment, tier, progression, warmup, cooldown, low_impact, needs_specialist_review, is_published, source) values ('ae908ce2-c943-57ae-810b-2d0419958705', 'womens-glute-strength', 'Glutes & Strength: 4-Day Upper/Lower', 'Two glute-focused lower days and two upper days — heavy hip thrusts and squats plus real upper-body strength.', 'A glute-specialization program that doesn''t skip strength. Lower days pair heavy hip thrusts, squats and deadlifts with split squats, back extensions and abduction work for the upper glutes; upper days build pressing and pulling strength (including your first chin-up). Glutes get the most volume, while upper-body muscles train at a productive maintenance-to-growth level. Popular with women, suitable for anyone.', '90a96eaf-8db5-5a1e-af56-8d9457c32895', 'beginner', 6, 4, 45, array['build_muscle', 'build_strength', 'lose_fat', 'general_health', 'type:hypertrophy', 'type:strength']::text[], array['barbell', 'rack', 'bench', 'dumbbell', 'cable', 'machine', 'band', 'pull_up_bar']::text[], 'plus', 'Double progression: add reps until every set reaches the top of the range at the week''s reps-in-reserve target, then add load. Weeks 3–5 add a set to hip thrusts and key upper-body lifts. Week 6 is a deload — then repeat with heavier weights.', array['3–5 minutes easy cardio (walk, bike, rower or skipping)', 'World''s greatest stretch × 3 per side', 'Bodyweight squats × 10', 'Band pull-aparts or arm circles × 15', 'Glute bridges × 10 and banded side steps × 10 per side', '2–3 ramp-up sets of your first lift']::text[], array['3–5 minutes easy walking or cycling to bring heart rate down', 'Child''s pose — 60 seconds', 'Figure-four glute stretch — 30–45 seconds per side', 'Slow nasal breathing — 1–2 minutes']::text[], false, false, true, 'curated') on conflict (slug) do update set name = excluded.name, summary = excluded.summary, description = excluded.description, category_id = excluded.category_id, difficulty = excluded.difficulty, duration_weeks = excluded.duration_weeks, days_per_week = excluded.days_per_week, session_minutes = excluded.session_minutes, goals = excluded.goals, equipment = excluded.equipment, tier = excluded.tier, progression = excluded.progression, warmup = excluded.warmup, cooldown = excluded.cooldown, low_impact = excluded.low_impact, needs_specialist_review = excluded.needs_specialist_review, is_published = true;
