insert into public.training_programs (id, slug, name, summary, description, category_id, difficulty, duration_weeks, days_per_week, session_minutes, goals, equipment, tier, progression, warmup, cooldown, low_impact, needs_specialist_review, is_published, source) values ('94d451ab-c64e-5bca-8cfb-fb6f4f9b69b4', 'power-hypertrophy-5-day', 'Power-Hypertrophy 5-Day', 'Two heavy power days and three body-part hypertrophy days with speed work — high volume for experienced lifters.', 'In the style of Layne Norton''s PHAT: an upper and a lower power day early in the week, then back-and-shoulders, legs, and chest-and-arms hypertrophy days that open with explosive speed sets at 65–70% of your power-day weights. It''s a lot of volume — about 15–20 hard sets for the big muscles — so it suits lifters with a few years of training and good recovery.', '8f19916a-c1e0-5027-887e-6f78ca07b045', 'advanced', 6, 5, 50, array['build_muscle', 'build_strength', 'type:hypertrophy', 'type:strength']::text[], array['barbell', 'rack', 'bench', 'dumbbell', 'cable', 'machine', 'pull_up_bar', 'dip_station']::text[], 'plus', 'Power days: add load when every set reaches the top of 3–5 reps at the target RPE. Speed sets stay at 65–70% of your current power-day weights. Hypertrophy work: double progression with a set added to key exercises in weeks 3–5. Week 6 is a deload.', array['3–5 minutes easy cardio (walk, bike, rower or skipping)', 'World''s greatest stretch × 3 per side', 'Bodyweight squats × 10', 'Band pull-aparts or arm circles × 15', '2–3 ramp-up sets of your first lift, building toward working weight']::text[], array['3–5 minutes easy walking or cycling to bring heart rate down', 'Child''s pose — 60 seconds', 'Figure-four glute stretch — 30–45 seconds per side', 'Slow nasal breathing — 1–2 minutes']::text[], false, false, true, 'curated') on conflict (slug) do update set name = excluded.name, summary = excluded.summary, description = excluded.description, category_id = excluded.category_id, difficulty = excluded.difficulty, duration_weeks = excluded.duration_weeks, days_per_week = excluded.days_per_week, session_minutes = excluded.session_minutes, goals = excluded.goals, equipment = excluded.equipment, tier = excluded.tier, progression = excluded.progression, warmup = excluded.warmup, cooldown = excluded.cooldown, low_impact = excluded.low_impact, needs_specialist_review = excluded.needs_specialist_review, is_published = true;
