insert into public.training_programs (id, slug, name, summary, description, category_id, difficulty, duration_weeks, days_per_week, session_minutes, goals, equipment, tier, progression, warmup, cooldown, low_impact, needs_specialist_review, is_published, source) values ('bb9ddb06-3183-530d-8929-77eaa2271c8e', 'physique-show-prep', 'Physique Show Prep', 'Twelve weeks of hypertrophy, rising conditioning and daily posing, tapering into show week.', 'A training plan for bodybuilding, classic, men''s/women''s physique, figure, bikini and wellness competitors. Five sessions a week hold muscle while conditioning rises gradually; evidence-based prep guidance (Helms, Aragon & Fitschen) suggests losing about 0.5–1% of body weight per week and keeping training heavy enough to signal muscle retention. Week 7 is lighter and week 12 tapers. Nutrition, water and peak-week strategy should be guided by a qualified coach or registered dietitian — this program does not prescribe extreme dieting, dehydration or sodium manipulation, which carry real risks and often make you look flatter. Every session ends with posing practice.', 'e2746996-75ef-5993-a5cd-d47a8c68cd71', 'advanced', 12, 5, 65, array['build_muscle', 'lose_fat', 'type:hypertrophy', 'type:cardio']::text[], array['barbell', 'rack', 'bench', 'dumbbell', 'cable', 'machine', 'pull_up_bar', 'bike']::text[], 'plus', 'Keep the weights you''re lifting and 1–3 reps in reserve — in a deficit, holding strength is the win. Low-intensity cardio rises from about 20 to 35 minutes per session over the prep and posing from 10 to 20 minutes; your coach adjusts both from weekly weigh-ins. Week 7 is lighter and week 12 is a taper.', array['3–5 minutes easy cardio (walk, bike, rower or skipping)', 'World''s greatest stretch × 3 per side', 'Bodyweight squats × 10', 'Band pull-aparts or arm circles × 15', '2–3 ramp-up sets of your first lift, building toward working weight']::text[], array['3–5 minutes easy walking or cycling to bring heart rate down', 'Child''s pose — 60 seconds', 'Figure-four glute stretch — 30–45 seconds per side', 'Slow nasal breathing — 1–2 minutes']::text[], false, true, true, 'curated') on conflict (slug) do update set name = excluded.name, summary = excluded.summary, description = excluded.description, category_id = excluded.category_id, difficulty = excluded.difficulty, duration_weeks = excluded.duration_weeks, days_per_week = excluded.days_per_week, session_minutes = excluded.session_minutes, goals = excluded.goals, equipment = excluded.equipment, tier = excluded.tier, progression = excluded.progression, warmup = excluded.warmup, cooldown = excluded.cooldown, low_impact = excluded.low_impact, needs_specialist_review = excluded.needs_specialist_review, is_published = true;
