insert into public.training_programs (id, slug, name, summary, description, category_id, difficulty, duration_weeks, days_per_week, session_minutes, goals, equipment, tier, progression, warmup, cooldown, low_impact, needs_specialist_review, is_published, source) values ('08b41fbb-65d7-5d6d-b0cd-b6554822306e', 'lean-and-conditioned', 'Lean & Conditioned', 'Strength to protect muscle plus sustainable cardio to support fat loss.', 'Fat loss is driven mainly by a modest, sustainable calorie deficit; this program supports that with resistance training to maintain muscle and a mix of steady and interval cardio. It is not a substitute for medical advice on weight management.', '26f6bdad-c7c6-58a0-a972-c9cce4439a9c', 'beginner', 6, 4, 40, array['lose_fat', 'general_health', 'improve_conditioning', 'type:cardio', 'type:strength', 'type:functional']::text[], array['dumbbell', 'bodyweight', 'bike', 'rower', 'band']::text[], 'plus', 'Steady cardio grows by 5 minutes every other week (30 → 40), intervals add a round a week (6 → 9), and the main lifts go from 3 to 4 sets in week 4 — add load when you reach 12 reps. Week 6 is lighter.', array['3–5 minutes easy cardio (walk, bike, rower or skipping)', 'World''s greatest stretch × 3 per side', 'Bodyweight squats × 10', 'Band pull-aparts or arm circles × 15', '2–3 ramp-up sets of your first lift, building toward working weight']::text[], array['3–5 minutes easy walking or cycling to bring heart rate down', 'Child''s pose — 60 seconds', 'Figure-four glute stretch — 30–45 seconds per side', 'Slow nasal breathing — 1–2 minutes']::text[], false, false, true, 'curated') on conflict (slug) do update set name = excluded.name, summary = excluded.summary, description = excluded.description, category_id = excluded.category_id, difficulty = excluded.difficulty, duration_weeks = excluded.duration_weeks, days_per_week = excluded.days_per_week, session_minutes = excluded.session_minutes, goals = excluded.goals, equipment = excluded.equipment, tier = excluded.tier, progression = excluded.progression, warmup = excluded.warmup, cooldown = excluded.cooldown, low_impact = excluded.low_impact, needs_specialist_review = excluded.needs_specialist_review, is_published = true;
insert into public.program_weeks (id, program_id, week_number, focus, is_deload) values ('80c70595-e1be-55e5-bf9a-15662cb27d20', '08b41fbb-65d7-5d6d-b0cd-b6554822306e', 1, 'Week 1: 30 min steady cardio, 6 intervals; strength 3 sets — add load when you hit 12 reps', false) on conflict (id) do update set focus = excluded.focus, is_deload = excluded.is_deload;
insert into public.program_days (id, week_id, day_number, name, focus, estimated_minutes, warmup, cooldown) values ('bd008393-6515-5919-8a09-564e26581700', '80c70595-e1be-55e5-bf9a-15662cb27d20', 1, 'Strength Circuit A', 'Full-body strength', 40, array['3–5 minutes easy cardio (walk, bike, rower or skipping)', 'World''s greatest stretch × 3 per side', 'Bodyweight squats × 10', 'Band pull-aparts or arm circles × 15', '2–3 ramp-up sets of your first lift, building toward working weight']::text[], array['3–5 minutes easy walking or cycling to bring heart rate down', 'Child''s pose — 60 seconds', 'Figure-four glute stretch — 30–45 seconds per side', 'Slow nasal breathing — 1–2 minutes']::text[]) on conflict (id) do update set name = excluded.name, focus = excluded.focus, estimated_minutes = excluded.estimated_minutes, warmup = excluded.warmup, cooldown = excluded.cooldown;
