insert into public.training_programs (id, slug, name, summary, description, category_id, difficulty, duration_weeks, days_per_week, session_minutes, goals, equipment, tier, progression, warmup, cooldown, low_impact, needs_specialist_review, is_published, source) values ('5afc13a3-89f9-5d69-acdf-e22f8dcd13ab', '10k-training', '10K Training: Build to 10 Kilometres', 'Ten weeks, four runs a week: mostly easy running, one quality session, a long run to 70 minutes, two cutback weeks and a taper.', 'For runners comfortable with 30–40 minutes of easy running. One weekly quality session moves from short repeats to threshold intervals to 10K-pace work; everything else is easy. Weeks 4 and 7 cut back, and week 10 tapers into a 10K race or time trial.', 'd4e79e61-b816-5c53-a64a-537abe13101d', 'intermediate', 10, 4, 50, array['improve_conditioning', 'general_health', 'type:cardio']::text[], array['bodyweight']::text[], 'plus', 'Quality moves from 6 × 60 s repeats to 3 × 8 min threshold to 4 × 10 min at 10K pace; the long run grows from 45 to 70 minutes. Weeks 4 and 7 cut back; week 10 tapers.', array['5 minutes brisk walk or very easy jog', 'Leg swings × 10 each leg', 'A-skips × 20 m and 2 relaxed strides']::text[], array['5 minutes easy walking', 'Calf stretch — 30 seconds per side', 'Standing quad stretch — 30 seconds per side']::text[], false, false, true, 'curated') on conflict (slug) do update set name = excluded.name, summary = excluded.summary, description = excluded.description, category_id = excluded.category_id, difficulty = excluded.difficulty, duration_weeks = excluded.duration_weeks, days_per_week = excluded.days_per_week, session_minutes = excluded.session_minutes, goals = excluded.goals, equipment = excluded.equipment, tier = excluded.tier, progression = excluded.progression, warmup = excluded.warmup, cooldown = excluded.cooldown, low_impact = excluded.low_impact, needs_specialist_review = excluded.needs_specialist_review, is_published = true;
