insert into public.training_programs (id, slug, name, summary, description, category_id, difficulty, duration_weeks, days_per_week, session_minutes, goals, equipment, tier, progression, warmup, cooldown, low_impact, needs_specialist_review, is_published, source) values ('0ef1d6e1-9fda-58a2-81a7-a7de19dc6c6c', 'calisthenics-foundations', 'Calisthenics Foundations', 'Three full-body bodyweight sessions a week: pull-ups, push-ups, dips, squats and core, built through progressions.', 'Bodyweight strength built the way calisthenics communities teach it: a short list of pulling, pushing, leg and core movements, each with a ladder of progressions (band-assisted → full pull-up, incline → full push-up, split squat → rear-foot-elevated). Pull and push are paired so you rest one while working the other. You need a pull-up bar and a resistance band; a sturdy table or low bar works for rows.', '9dd43e10-2cb8-514b-9368-7d6645f24325', 'beginner', 8, 3, 45, array['build_strength', 'build_muscle', 'general_health', 'type:strength', 'type:home']::text[], array['bodyweight', 'pull_up_bar', 'band', 'mat']::text[], 'pro', 'Double progression on every movement: when you reach the top of the rep range on all sets, move to the next progression and start again at the bottom of the range (band-assisted → negatives → full pull-ups; incline → floor → feet-elevated push-ups). Week 4 and week 8 are lighter.', array['3 minutes skipping or marching', 'Wrist circles and rocking on hands and knees × 10', 'Band pull-aparts × 15', 'Bodyweight squats × 10', 'Scapular pull-ups or dead-hang shrugs × 8']::text[], array['3–5 minutes easy walking or cycling to bring heart rate down', 'Child''s pose — 60 seconds', 'Figure-four glute stretch — 30–45 seconds per side', 'Slow nasal breathing — 1–2 minutes']::text[], false, false, true, 'curated') on conflict (slug) do update set name = excluded.name, summary = excluded.summary, description = excluded.description, category_id = excluded.category_id, difficulty = excluded.difficulty, duration_weeks = excluded.duration_weeks, days_per_week = excluded.days_per_week, session_minutes = excluded.session_minutes, goals = excluded.goals, equipment = excluded.equipment, tier = excluded.tier, progression = excluded.progression, warmup = excluded.warmup, cooldown = excluded.cooldown, low_impact = excluded.low_impact, needs_specialist_review = excluded.needs_specialist_review, is_published = true;
insert into public.program_weeks (id, program_id, week_number, focus, is_deload) values ('f6caa13b-a6e9-5c10-b4d7-9fa6148e5d1a', '0ef1d6e1-9fda-58a2-81a7-a7de19dc6c6c', 1, 'Block 1: own every rep in the range, about 3 reps in reserve', false) on conflict (id) do update set focus = excluded.focus, is_deload = excluded.is_deload;
