insert into public.training_programs (id, slug, name, summary, description, category_id, difficulty, duration_weeks, days_per_week, session_minutes, goals, equipment, tier, progression, warmup, cooldown, low_impact, needs_specialist_review, is_published, source) values ('bdf262da-e177-565a-9360-cc8ba9b791f0', 'dumbbell-home-strength', 'Dumbbell Home Strength', 'Three full-body sessions a week with a pair of adjustable dumbbells and a bench.', 'A complete strength plan for a home setup: squat, hinge, lunge, press, row and carry patterns with dumbbells only. Sets stay 1–3 reps short of failure, which builds muscle and strength with modest loads. No bench? Do floor presses and supported rows on a sturdy chair.', 'a218e28e-c9e8-59ad-afc5-39d0355f9746', 'beginner', 8, 3, 45, array['build_strength', 'build_muscle', 'general_health', 'lose_fat', 'type:home', 'type:strength']::text[], array['dumbbell', 'bench', 'bodyweight']::text[], 'plus', 'Double progression: work in the rep range until every set hits the top with 1–2 reps in reserve, then use the next dumbbell. When the heaviest dumbbell is too light, slow the lowering to 3 seconds or add a set. Week 8 is a deload.', array['3–5 minutes easy cardio (walk, bike, rower or skipping)', 'World''s greatest stretch × 3 per side', 'Bodyweight squats × 10', 'Band pull-aparts or arm circles × 15', '2–3 ramp-up sets of your first lift, building toward working weight']::text[], array['3–5 minutes easy walking or cycling to bring heart rate down', 'Child''s pose — 60 seconds', 'Figure-four glute stretch — 30–45 seconds per side', 'Slow nasal breathing — 1–2 minutes']::text[], false, false, true, 'curated') on conflict (slug) do update set name = excluded.name, summary = excluded.summary, description = excluded.description, category_id = excluded.category_id, difficulty = excluded.difficulty, duration_weeks = excluded.duration_weeks, days_per_week = excluded.days_per_week, session_minutes = excluded.session_minutes, goals = excluded.goals, equipment = excluded.equipment, tier = excluded.tier, progression = excluded.progression, warmup = excluded.warmup, cooldown = excluded.cooldown, low_impact = excluded.low_impact, needs_specialist_review = excluded.needs_specialist_review, is_published = true;
