insert into public.training_programs (id, slug, name, summary, description, category_id, difficulty, duration_weeks, days_per_week, session_minutes, goals, equipment, tier, progression, warmup, cooldown, low_impact, needs_specialist_review, is_published, source) values ('694a792b-e974-5d62-8454-660374283426', 'band-bodyweight-total-body', 'Bands & Bodyweight Total Body', 'Three 30–35-minute sessions a week with resistance bands and your bodyweight — travel- and apartment-friendly.', 'Resistance bands supply the pulling and isolation work that bodyweight alone can''t; push-ups, squats, lunges and bridges cover the rest. Bands get harder as they stretch, so control the return. A set of loop bands (light, medium, heavy) and a door anchor is enough.', 'a218e28e-c9e8-59ad-afc5-39d0355f9746', 'beginner', 6, 3, 35, array['general_health', 'build_strength', 'lose_fat', 'type:home', 'type:strength']::text[], array['band', 'bodyweight', 'mat']::text[], 'plus', 'Add reps until you reach the top of each range, then use a heavier band or a harder variation (incline → floor push-up, bodyweight → single-leg bridge). Weeks 4–5 add a set to most exercises; week 6 is lighter.', array['3 minutes marching or skipping', 'Band pass-throughs × 10', 'Bodyweight squats × 10', 'World''s greatest stretch × 2 per side']::text[], array['3–5 minutes easy walking or cycling to bring heart rate down', 'Child''s pose — 60 seconds', 'Figure-four glute stretch — 30–45 seconds per side', 'Slow nasal breathing — 1–2 minutes']::text[], false, false, true, 'curated') on conflict (slug) do update set name = excluded.name, summary = excluded.summary, description = excluded.description, category_id = excluded.category_id, difficulty = excluded.difficulty, duration_weeks = excluded.duration_weeks, days_per_week = excluded.days_per_week, session_minutes = excluded.session_minutes, goals = excluded.goals, equipment = excluded.equipment, tier = excluded.tier, progression = excluded.progression, warmup = excluded.warmup, cooldown = excluded.cooldown, low_impact = excluded.low_impact, needs_specialist_review = excluded.needs_specialist_review, is_published = true;
