insert into public.training_programs (id, slug, name, summary, description, category_id, difficulty, duration_weeks, days_per_week, session_minutes, goals, equipment, tier, progression, warmup, cooldown, low_impact, needs_specialist_review, is_published, source) values ('687c3f23-c212-5d93-bb5f-2ca0177f3ca4', 'kettlebell-circuit-intervals', 'Kettlebell & Bodyweight Circuits', 'Three interval-circuit sessions a week: every-minute-on-the-minute strength, timed work:rest rounds and a short finisher.', 'Functional conditioning without a full gym: kettlebell swings, goblet squats, push-ups, rows and carries arranged as timed circuits. EMOM blocks keep strength moves crisp; work:rest intervals (40:20, then 45:15) build work capacity. Stop a round early if form breaks — the clock serves the movement, not the other way round.', '30351ab3-3de1-597d-bb50-b0c1579a05b1', 'intermediate', 6, 3, 40, array['improve_conditioning', 'lose_fat', 'general_health', 'type:functional', 'type:cardio']::text[], array['kettlebell', 'dumbbell', 'bodyweight', 'jump_rope', 'mat']::text[], 'plus', 'Density: each week the timed rounds get an extra round or a shorter rest; strength moves keep their full rest. Use a heavier kettlebell when all swing sets feel easy. Week 6 is a lighter week.', array['5 minutes easy jump rope, bike or shadowboxing', 'Lateral shuffles × 20 seconds each way', 'World''s greatest stretch × 3 per side', '2 × 10-second build-up efforts at moderate intensity']::text[], array['3–5 minutes easy walking or cycling to bring heart rate down', 'Child''s pose — 60 seconds', 'Figure-four glute stretch — 30–45 seconds per side', 'Slow nasal breathing — 1–2 minutes']::text[], false, false, true, 'curated') on conflict (slug) do update set name = excluded.name, summary = excluded.summary, description = excluded.description, category_id = excluded.category_id, difficulty = excluded.difficulty, duration_weeks = excluded.duration_weeks, days_per_week = excluded.days_per_week, session_minutes = excluded.session_minutes, goals = excluded.goals, equipment = excluded.equipment, tier = excluded.tier, progression = excluded.progression, warmup = excluded.warmup, cooldown = excluded.cooldown, low_impact = excluded.low_impact, needs_specialist_review = excluded.needs_specialist_review, is_published = true;
