insert into public.training_programs (id, slug, name, summary, description, category_id, difficulty, duration_weeks, days_per_week, session_minutes, goals, equipment, tier, progression, warmup, cooldown, low_impact, needs_specialist_review, is_published, source) values ('ad2861fb-3014-513b-9c33-abe1b5708ca3', 'hybrid-strength-and-run', 'Hybrid: Strength & 5K–10K Running', 'Two full-body strength days and three runs a week, spaced so hard runs never land next to heavy leg days.', 'Concurrent training for people who want to stay strong and run well. Interference is smallest when strength and running stay moderate in volume and hard sessions are spread out, so the week runs Monday strength, Tuesday easy run, Thursday intervals, Friday strength (upper emphasis), Saturday long easy run — about 80% of running easy. Keep at least a day between hard intervals and heavy squats or deadlifts.', '05b1597f-81b1-57a4-8345-488339112291', 'intermediate', 8, 5, 45, array['improve_conditioning', 'build_strength', 'general_health', 'type:strength', 'type:cardio']::text[], array['barbell', 'rack', 'bench', 'dumbbell', 'pull_up_bar', 'bodyweight']::text[], 'plus', 'Strength: add a little weight when every set reaches its target at RPE 7–8. Running: easy and long runs grow about 10% a week, interval rounds rise from 4 to 6. Weeks 4 and 8 are lighter on both.', array['3–5 minutes easy cardio (walk, bike, rower or skipping)', 'World''s greatest stretch × 3 per side', 'Bodyweight squats × 10', 'Band pull-aparts or arm circles × 15', '2–3 ramp-up sets of your first lift, building toward working weight']::text[], array['3–5 minutes easy walking or cycling to bring heart rate down', 'Child''s pose — 60 seconds', 'Figure-four glute stretch — 30–45 seconds per side', 'Slow nasal breathing — 1–2 minutes']::text[], false, false, true, 'curated') on conflict (slug) do update set name = excluded.name, summary = excluded.summary, description = excluded.description, category_id = excluded.category_id, difficulty = excluded.difficulty, duration_weeks = excluded.duration_weeks, days_per_week = excluded.days_per_week, session_minutes = excluded.session_minutes, goals = excluded.goals, equipment = excluded.equipment, tier = excluded.tier, progression = excluded.progression, warmup = excluded.warmup, cooldown = excluded.cooldown, low_impact = excluded.low_impact, needs_specialist_review = excluded.needs_specialist_review, is_published = true;
