insert into public.training_programs (id, slug, name, summary, description, category_id, difficulty, duration_weeks, days_per_week, session_minutes, goals, equipment, tier, progression, warmup, cooldown, low_impact, needs_specialist_review, is_published, source) values ('a4c81bd0-23ba-5592-af64-6fc9136a42eb', 'seated-strength-mobility', 'Seated Strength & Mobility', 'Three chair-based sessions a week for strength, posture and mobility when standing exercise is hard.', 'For adults who need or prefer to exercise seated — after illness, with balance or joint limits, or as a first step back. Every exercise is done on a sturdy chair without wheels (sit-to-stands use the chair as a target). Move slowly, breathe out on the effort and stop if anything causes pain or dizziness. If you have a heart, lung, bone or joint condition, check with your healthcare provider before starting.', '5225ea79-fbe6-5abc-819f-3349cce2461e', 'beginner', 6, 3, 30, array['general_health', 'mobility', 'build_strength', 'type:low_impact', 'type:strength', 'type:mobility']::text[], array['bodyweight', 'dumbbell', 'band']::text[], 'pro', 'Weeks 1–3: add a rep or two each session. Weeks 4–5: add a set to most exercises, or a slightly heavier band or dumbbell. Week 6 is lighter. When sit-to-stands feel easy, cross your arms or slow the lowering.', array['Seated marching 1–2 minutes', 'Shoulder rolls × 10', 'Seated cat-cow × 8 breaths', 'Ankle circles × 10 each direction']::text[], array['Seated forward reach 30 seconds', 'Seated figure-four stretch 30 seconds per side', 'Slow breathing 1 minute']::text[], true, true, true, 'curated') on conflict (slug) do update set name = excluded.name, summary = excluded.summary, description = excluded.description, category_id = excluded.category_id, difficulty = excluded.difficulty, duration_weeks = excluded.duration_weeks, days_per_week = excluded.days_per_week, session_minutes = excluded.session_minutes, goals = excluded.goals, equipment = excluded.equipment, tier = excluded.tier, progression = excluded.progression, warmup = excluded.warmup, cooldown = excluded.cooldown, low_impact = excluded.low_impact, needs_specialist_review = excluded.needs_specialist_review, is_published = true;
