insert into public.training_programs (id, slug, name, summary, description, category_id, difficulty, duration_weeks, days_per_week, session_minutes, goals, equipment, tier, progression, warmup, cooldown, low_impact, needs_specialist_review, is_published, source) values ('558e2cad-cd02-5bad-81a1-b69c7db16fd8', 'beginner-strength-foundations-8-week', 'Beginner Strength Foundations', 'Eight weeks of three full-body barbell sessions: learn the squat, bench, deadlift, press, rows and chin-ups, then test a new 5-rep best.', 'Goal: get measurably stronger on the basic barbell lifts while learning to judge effort. Focus: squat and bench twice a week, deadlift and overhead press once, rows, pulldowns and chin-ups every session. Reps come down from 8 to 6 to 5 while the reps you keep in reserve shrink from about four to about two, so weight goes up steadily without grinding. Week 5 is a planned lighter week and week 8 tests a new 5-rep best on each lift with a rep or two still in the tank. For new lifters, or anyone returning after a long break, who wants a structured start that teaches effort control instead of adding a fixed amount every session.', '42a6d9d6-53e5-5755-8274-3a0b73c46fb9', 'beginner', 8, 3, 45, array['build_strength', 'general_health', 'type:strength']::text[], array['barbell', 'rack', 'bench', 'pull_up_bar', 'cable', 'mat']::text[], 'pro', 'Effort-driven linear progression. Each session, if every work set was completed with at least the target reps in reserve, add the smallest jump next time: about 2.5 kg / 5 lb on squats, 2.5–5 kg / 5–10 lb on deadlifts and 1–2.5 kg / 2.5–5 lb on bench, press and rows. If a set felt harder than the target, keep the weight. Missed reps: repeat the weight next session. Miss the same weight twice in a row: reset that lift about 10% lighter and build back up. When the reps drop (8 → 6 in week 3, 6 → 5 in week 6), start about 5% heavier than your last sets. Week 5 is a lighter week at about 90% of week 4''s weights; week 8 is a 5-rep test with 1–2 reps in reserve.', array['3–5 minutes easy cardio (walk, bike, rower or skipping)', 'World''s greatest stretch × 3 per side', 'Bodyweight squats × 10', 'Band pull-aparts or arm circles × 15', '2–3 ramp-up sets of your first lift, building toward working weight']::text[], array['3–5 minutes easy walking or cycling to bring heart rate down', 'Child''s pose — 60 seconds', 'Figure-four glute stretch — 30–45 seconds per side', 'Slow nasal breathing — 1–2 minutes']::text[], false, false, true, 'curated') on conflict (slug) do update set name = excluded.name, summary = excluded.summary, description = excluded.description, category_id = excluded.category_id, difficulty = excluded.difficulty, duration_weeks = excluded.duration_weeks, days_per_week = excluded.days_per_week, session_minutes = excluded.session_minutes, goals = excluded.goals, equipment = excluded.equipment, tier = excluded.tier, progression = excluded.progression, warmup = excluded.warmup, cooldown = excluded.cooldown, low_impact = excluded.low_impact, needs_specialist_review = excluded.needs_specialist_review, is_published = true;
insert into public.program_weeks (id, program_id, week_number, focus, is_deload) values ('3e51fdfd-46c2-5964-a1c1-32b4097ea4d6', '558e2cad-cd02-5bad-81a1-b69c7db16fd8', 1, 'Week 1 — learn the lifts: sets of 8 with about 4 reps in reserve; start light and find your working weights', false) on conflict (id) do update set focus = excluded.focus, is_deload = excluded.is_deload;
insert into public.program_days (id, week_id, day_number, name, focus, estimated_minutes, warmup, cooldown) values ('55a1319a-36f7-5d5c-8142-0e55fc806a03', '3e51fdfd-46c2-5964-a1c1-32b4097ea4d6', 1, 'Day A — Squat & Bench', 'Squat and bench press, rows', 45, array['3–5 minutes easy cardio (walk, bike, rower or skipping)', 'World''s greatest stretch × 3 per side', 'Bodyweight squats × 10', 'Band pull-aparts or arm circles × 15', '2–3 ramp-up sets of your first lift, building toward working weight']::text[], array['3–5 minutes easy walking or cycling to bring heart rate down', 'Child''s pose — 60 seconds', 'Figure-four glute stretch — 30–45 seconds per side', 'Slow nasal breathing — 1–2 minutes']::text[]) on conflict (id) do update set name = excluded.name, focus = excluded.focus, estimated_minutes = excluded.estimated_minutes, warmup = excluded.warmup, cooldown = excluded.cooldown;
insert into public.program_exercises (day_id, exercise_id, position, sets, reps, duration_seconds, rest_seconds, intensity, rpe, notes) values ('55a1319a-36f7-5d5c-8142-0e55fc806a03', '48e2051d-9493-5969-a85a-34c1d3d1d2ab', 0, 3, '8', null, 150, null, 6, 'Start with the empty bar and add weight each warm-up set until a set of 8 feels like 4 reps were left. That''s your working weight. Depth you can control, bar over mid-foot.');
