insert into public.program_exercises (day_id, exercise_id, position, sets, reps, duration_seconds, rest_seconds, intensity, rpe, notes) values ('07c42792-7f47-5b65-9ce6-dfda47e90d9e', '4d46cb36-e0a0-506e-a7bb-d9bfe7d31814', 1, 3, '8', null, 150, null, 6, 'Start with the empty bar and add weight each warm-up set until a set of 8 feels like 4 reps were left. That''s your working weight. Squeeze glutes and keep ribs down; press the bar back over mid-foot.');
