insert into public.program_exercises (day_id, exercise_id, position, sets, reps, duration_seconds, rest_seconds, intensity, rpe, notes) values ('5fc19791-975a-57f4-bdd1-c96c7950ef3d', '48e2051d-9493-5969-a85a-34c1d3d1d2ab', 0, 1, '5', null, 180, null, 8.5, 'Test: ramp up in 4–6 warm-up sets, then one set of 5 that leaves 1–2 good reps in the tank. A new 5-rep best that moves well is the goal — no grinders. Depth you can control, bar over mid-foot.');
