insert into public.training_programs (id, slug, name, summary, description, category_id, difficulty, duration_weeks, days_per_week, session_minutes, goals, equipment, tier, progression, warmup, cooldown, low_impact, needs_specialist_review, is_published, source) values ('95790170-801c-5fb2-8e2c-9612999cba09', 'power-and-athletic-strength-10-week', 'Power and Athletic Strength', 'Ten weeks, three days: jumps, throws and power cleans at full rest paired with squat, bench and trap-bar strength, with a deload and a test week.', 'Goal: produce force faster — jump farther, throw harder and get stronger at the same time. Focus: each session opens with a small dose of power work (box jumps, trap-bar jumps, broad jumps, medicine-ball throws, power cleans) done fresh with full rest, then strength lifts (back squat, bench press, trap-bar deadlift, pull-ups) and single-leg and trunk work. Power volume stays low on purpose — quality, not fatigue. Phase 1 (weeks 1–4) builds strength from sets of 6 to 4; week 5 deloads; phase 2 (weeks 6–9) goes heavier on the lifts and shifts power to doubles with maximal intent; week 10 tests broad jump, throws, a clean double and one top set per lift. For field and court athletes and lifters with at least six months of barbell experience who want to be more explosive. An optional fourth conditioning day is described in the instructions.', 'f708f087-cda3-534e-bff4-d71485e31190', 'intermediate', 10, 3, 45, array['athletic_performance', 'build_strength', 'type:athletic', 'type:strength']::text[], array['barbell', 'rack', 'bench', 'box', 'trap_bar', 'medicine_ball', 'pull_up_bar', 'dumbbell', 'mat']::text[], 'pro', 'Power work stays at 6–12 jumps or throws per exercise with 75–120 s between sets: it progresses by intent — a higher box, a heavier ball or trap bar, a farther target — not by fatigue, and drops from triples to doubles in phase 2. Stop any set when height, distance or speed drops. Strength lifts are chosen by reps in reserve: sets of 6 at RPE 7 in week 1 down to triples at RPE 8.5 in week 8; add load when every set lands at or below the target RPE. Power cleans build from technique triples (RPE 6) to heavy singles (RPE 8). Week 5 deloads, week 9 cuts volume before testing, and week 10 records best jumps, throws and a top set of 3 per lift.', array['5 minutes easy jump rope, bike or shadowboxing', 'Lateral shuffles × 20 seconds each way', 'World''s greatest stretch × 3 per side', '2 × 10-second build-up efforts at moderate intensity']::text[], array['3–5 minutes easy walking or cycling to bring heart rate down', 'Child''s pose — 60 seconds', 'Figure-four glute stretch — 30–45 seconds per side', 'Slow nasal breathing — 1–2 minutes']::text[], false, false, true, 'curated') on conflict (slug) do update set name = excluded.name, summary = excluded.summary, description = excluded.description, category_id = excluded.category_id, difficulty = excluded.difficulty, duration_weeks = excluded.duration_weeks, days_per_week = excluded.days_per_week, session_minutes = excluded.session_minutes, goals = excluded.goals, equipment = excluded.equipment, tier = excluded.tier, progression = excluded.progression, warmup = excluded.warmup, cooldown = excluded.cooldown, low_impact = excluded.low_impact, needs_specialist_review = excluded.needs_specialist_review, is_published = true;
insert into public.program_weeks (id, program_id, week_number, focus, is_deload) values ('5ef0f2f5-28bc-5495-a1be-0a4bc9953845', '95790170-801c-5fb2-8e2c-9612999cba09', 1, 'Phase 1, week 1 — learn the rhythm: 3 sets of 3 jumps and throws at full rest; lifts at sets of 6, about 3 reps in reserve', false) on conflict (id) do update set focus = excluded.focus, is_deload = excluded.is_deload;
insert into public.program_days (id, week_id, day_number, name, focus, estimated_minutes, warmup, cooldown) values ('658b100d-a47f-5292-b171-02a4587f8f44', '5ef0f2f5-28bc-5495-a1be-0a4bc9953845', 1, 'Day 1 — Lower Power & Squat', 'Box jumps and trap-bar jumps, then back squat and hamstrings', 40, array['5 minutes easy jump rope, bike or shadowboxing', 'Lateral shuffles × 20 seconds each way', 'World''s greatest stretch × 3 per side', '2 × 10-second build-up efforts at moderate intensity', 'Pogo hops × 10 and 2 practice jumps at half effort']::text[], array['3–5 minutes easy walking or cycling to bring heart rate down', 'Child''s pose — 60 seconds', 'Figure-four glute stretch — 30–45 seconds per side', 'Slow nasal breathing — 1–2 minutes']::text[]) on conflict (id) do update set name = excluded.name, focus = excluded.focus, estimated_minutes = excluded.estimated_minutes, warmup = excluded.warmup, cooldown = excluded.cooldown;
insert into public.program_exercises (day_id, exercise_id, position, sets, reps, duration_seconds, rest_seconds, intensity, rpe, notes) values ('658b100d-a47f-5292-b171-02a4587f8f44', '70d0d7da-4b27-5741-a362-e32f9f9c97b8', 0, 3, '3', null, 90, null, null, 'Every rep at full intent with a full reset; stop the set if speed or height drops. Step down; land softly in the same position you took off from.');
insert into public.program_exercises (day_id, exercise_id, position, sets, reps, duration_seconds, rest_seconds, intensity, rpe, notes) values ('658b100d-a47f-5292-b171-02a4587f8f44', 'fc34e9f2-fff3-5064-a2cc-d0a41fb2c3f7', 1, 3, '3', null, 120, null, null, 'Every rep at full intent with a full reset; stop the set if speed or height drops. Light load only: one you can jump with as high as a bodyweight jump minus a little. Land with soft knees.');
insert into public.program_exercises (day_id, exercise_id, position, sets, reps, duration_seconds, rest_seconds, intensity, rpe, notes) values ('658b100d-a47f-5292-b171-02a4587f8f44', '48e2051d-9493-5969-a85a-34c1d3d1d2ab', 2, 4, '6', null, 180, null, 7, 'Choose the weight from the target reps in reserve; move it fast. Beat last week''s load or bar speed, never by grinding.');
insert into public.program_exercises (day_id, exercise_id, position, sets, reps, duration_seconds, rest_seconds, intensity, rpe, notes) values ('658b100d-a47f-5292-b171-02a4587f8f44', '7694c265-91ed-5760-93d7-acb8e8aa051a', 3, 2, '4', null, 90, null, null, 'Lower as slowly as you can control, catch yourself with your hands, push back up.');
insert into public.program_exercises (day_id, exercise_id, position, sets, reps, duration_seconds, rest_seconds, intensity, rpe, notes) values ('658b100d-a47f-5292-b171-02a4587f8f44', '72b1c751-8acd-5be7-a221-09b81d1b83d8', 4, 2, null, 15, 45, null, null, 'Per side. Short-lever version (knee on the bench) to start.');
