insert into public.training_programs (id, slug, name, summary, description, category_id, difficulty, duration_weeks, days_per_week, session_minutes, goals, equipment, tier, progression, warmup, cooldown, low_impact, needs_specialist_review, is_published, source) values ('28e83960-2c21-5dc8-9015-ffd083066aae', 'push-pull-legs-12-week', 'Push/Pull/Legs', 'Push, pull and legs twice a week for 12 weeks: two six-week blocks that build volume and end in deloads, with a 3-day option.', 'Goal: muscle gain with high frequency. Each muscle is trained twice a week across six focused sessions with about 10–17 hard sets per major muscle in week 1, rising to about 14–21 by each block''s peak week. Block 2 rotates the main variations (incline-led push days, chin-ups, front squats and hack squats). For intermediates who can train most days; there is a 3-day option for busier weeks.', '8f19916a-c1e0-5027-887e-6f78ca07b045', 'intermediate', 12, 6, 45, array['build_muscle', 'type:hypertrophy']::text[], array['barbell', 'rack', 'bench', 'dumbbell', 'cable', 'machine', 'pull_up_bar']::text[], 'pro', 'Two six-week blocks. Block 1 holds sets for two weeks while effort rises, then adds a set to key exercises in weeks 3–4 and two in week 5; week 6 deloads. Block 2 starts a little harder, adds sets sooner and peaks in week 11; week 12 deloads. Double progression throughout.', array['3–5 minutes easy cardio (walk, bike, rower or skipping)', 'World''s greatest stretch × 3 per side', 'Bodyweight squats × 10', 'Band pull-aparts or arm circles × 15', '2–3 ramp-up sets of your first lift, building toward working weight']::text[], array['3–5 minutes easy walking or cycling to bring heart rate down', 'Child''s pose — 60 seconds', 'Figure-four glute stretch — 30–45 seconds per side', 'Slow nasal breathing — 1–2 minutes']::text[], false, false, true, 'curated') on conflict (slug) do update set name = excluded.name, summary = excluded.summary, description = excluded.description, category_id = excluded.category_id, difficulty = excluded.difficulty, duration_weeks = excluded.duration_weeks, days_per_week = excluded.days_per_week, session_minutes = excluded.session_minutes, goals = excluded.goals, equipment = excluded.equipment, tier = excluded.tier, progression = excluded.progression, warmup = excluded.warmup, cooldown = excluded.cooldown, low_impact = excluded.low_impact, needs_specialist_review = excluded.needs_specialist_review, is_published = true;
