insert into public.training_programs (id, slug, name, summary, description, category_id, difficulty, duration_weeks, days_per_week, session_minutes, goals, equipment, tier, progression, warmup, cooldown, low_impact, needs_specialist_review, is_published, source) values ('9c73e017-f51e-534a-80c1-28a07baa0ba9', 'upper-body-specialization', 'Upper Body Specialization', 'Eight weeks of three upper-body days and one leg maintenance day: chest, back and shoulders build to about 14–20 hard sets a week.', 'Goal: bring up the chest, back, shoulders and arms when the upper body lags behind the legs. Three upper sessions train each upper muscle two to three times a week, starting around 10–15 hard sets and building to about 14–20, while one lower session keeps legs at maintenance volume (about 7–8 sets) so you don''t lose what you''ve built. For intermediates; run it for one or two blocks, then return to a balanced program.', '8f19916a-c1e0-5027-887e-6f78ca07b045', 'intermediate', 8, 4, 50, array['build_muscle', 'type:hypertrophy']::text[], array['barbell', 'rack', 'bench', 'dumbbell', 'cable', 'machine', 'pull_up_bar']::text[], 'pro', 'Two four-week blocks. Upper-body key exercises gain one set in week 2 and two in week 3 as reps in reserve fall from about 3 to 1–2; block 2 starts a set higher and peaks at about 1 rep in reserve. Leg work stays at maintenance sets throughout. Weeks 4 and 8 deload.', array['3–5 minutes easy cardio (walk, bike, rower or skipping)', 'World''s greatest stretch × 3 per side', 'Bodyweight squats × 10', 'Band pull-aparts or arm circles × 15', '2–3 ramp-up sets of your first lift, building toward working weight']::text[], array['3–5 minutes easy walking or cycling to bring heart rate down', 'Child''s pose — 60 seconds', 'Figure-four glute stretch — 30–45 seconds per side', 'Slow nasal breathing — 1–2 minutes']::text[], false, false, true, 'curated') on conflict (slug) do update set name = excluded.name, summary = excluded.summary, description = excluded.description, category_id = excluded.category_id, difficulty = excluded.difficulty, duration_weeks = excluded.duration_weeks, days_per_week = excluded.days_per_week, session_minutes = excluded.session_minutes, goals = excluded.goals, equipment = excluded.equipment, tier = excluded.tier, progression = excluded.progression, warmup = excluded.warmup, cooldown = excluded.cooldown, low_impact = excluded.low_impact, needs_specialist_review = excluded.needs_specialist_review, is_published = true;
