insert into public.training_programs (id, slug, name, summary, description, category_id, difficulty, duration_weeks, days_per_week, session_minutes, goals, equipment, tier, progression, warmup, cooldown, low_impact, needs_specialist_review, is_published, source) values ('8a7a89e2-7cee-5988-bf37-727f670fc498', 'first-30-days-in-the-gym', 'First 30 Days in the Gym', 'A calm four-week introduction to a commercial gym: machines and dumbbells, two easy sets to start, technique before load.', 'For complete beginners who feel unsure where to start in a gym. Goal: learn how the machines, dumbbells and cardio equipment work, practise the basic squat, hinge, push and pull patterns, and build a three-day habit. Volume and effort rise very gradually — week 1 is two sets of each exercise at about RPE 6 (four reps left in the tank), week 4 is three slightly heavier sets at about RPE 7.5. Each session also tries one cardio machine at an easy pace. You''ll finish with a written record of your settings and starting weights, ready for a longer program such as Full Body Fitness Foundations.', 'd2ffdbb8-dde8-5744-86a5-50f499a01d50', 'beginner', 4, 3, 40, array['general_health', 'build_strength', 'build_muscle', 'type:strength']::text[], array['machine', 'dumbbell', 'bench', 'bodyweight', 'mat', 'bike', 'rower']::text[], 'pro', 'Week 1: two sets at RPE 6. Week 2: a third set on the first three exercises. Week 3: three sets of everything at RPE 7 — add the smallest weight step wherever all sets reached 12 reps. Week 4: sets of 8–10 with a little more weight at about RPE 7.5. Core holds grow by 5 seconds and the easy cardio by a minute or two each week (5 → 10 minutes).', array['5 minutes easy on a bike, treadmill or cross-trainer — try a different machine each session', 'Bodyweight squats × 10', 'Arm circles × 10 each direction', 'One light practice set of your first exercise × 10']::text[], array['2–3 minutes easy walking', 'Child''s pose — 45 seconds', 'Figure-four glute stretch — 30 seconds per side']::text[], false, false, true, 'curated') on conflict (slug) do update set name = excluded.name, summary = excluded.summary, description = excluded.description, category_id = excluded.category_id, difficulty = excluded.difficulty, duration_weeks = excluded.duration_weeks, days_per_week = excluded.days_per_week, session_minutes = excluded.session_minutes, goals = excluded.goals, equipment = excluded.equipment, tier = excluded.tier, progression = excluded.progression, warmup = excluded.warmup, cooldown = excluded.cooldown, low_impact = excluded.low_impact, needs_specialist_review = excluded.needs_specialist_review, is_published = true;
insert into public.program_weeks (id, program_id, week_number, focus, is_deload) values ('13a50fe0-401f-5aee-9d55-96d6ed44d9d0', '8a7a89e2-7cee-5988-bf37-727f670fc498', 1, 'Week 1 — learn the gym: two easy sets of each exercise at about RPE 6 (4 reps still in the tank); note every seat and pin setting', false) on conflict (id) do update set focus = excluded.focus, is_deload = excluded.is_deload;
insert into public.program_days (id, week_id, day_number, name, focus, estimated_minutes, warmup, cooldown) values ('a554b97d-0811-5660-9d42-254125d1ca0f', '13a50fe0-401f-5aee-9d55-96d6ed44d9d0', 1, 'Machines A', 'Leg press, chest press and row on fixed machines', 35, array['5 minutes easy on a bike, treadmill or cross-trainer — try a different machine each session', 'Bodyweight squats × 10', 'Arm circles × 10 each direction', 'One light practice set of your first exercise × 10']::text[], array['2–3 minutes easy walking', 'Child''s pose — 45 seconds', 'Figure-four glute stretch — 30 seconds per side']::text[]) on conflict (id) do update set name = excluded.name, focus = excluded.focus, estimated_minutes = excluded.estimated_minutes, warmup = excluded.warmup, cooldown = excluded.cooldown;
insert into public.program_exercises (day_id, exercise_id, position, sets, reps, duration_seconds, rest_seconds, intensity, rpe, notes) values ('a554b97d-0811-5660-9d42-254125d1ca0f', 'f0303216-82cb-5825-b13b-6069891e4291', 0, 2, '10-12', null, 90, null, 6, 'First time on the machine: ask a staff member to show you the seat and safety settings, and write the seat position down. Feet shoulder-width on the platform; stop each rep before your lower back lifts off the pad.');
insert into public.program_exercises (day_id, exercise_id, position, sets, reps, duration_seconds, rest_seconds, intensity, rpe, notes) values ('a554b97d-0811-5660-9d42-254125d1ca0f', '6e830b45-94be-5700-8d49-e7686d8a67cf', 1, 2, '10-12', null, 90, null, 6, 'Set the seat so the handles line up with mid-chest. Note the pin number you finish on.');
insert into public.program_exercises (day_id, exercise_id, position, sets, reps, duration_seconds, rest_seconds, intensity, rpe, notes) values ('a554b97d-0811-5660-9d42-254125d1ca0f', '5eab5397-0a6f-5e9d-a560-e44951754ee8', 2, 2, '10-12', null, 90, null, 6, 'Chest tall against the pad or upright on the bench; pull the handle to your lower ribs.');
insert into public.program_exercises (day_id, exercise_id, position, sets, reps, duration_seconds, rest_seconds, intensity, rpe, notes) values ('a554b97d-0811-5660-9d42-254125d1ca0f', 'f2f91154-45f0-52f1-8228-71f2ec6fbf2f', 3, 2, '10-12', null, 60, null, 6, 'Line the machine''s pivot up with your knee — the sticker on the frame shows where.');
insert into public.program_exercises (day_id, exercise_id, position, sets, reps, duration_seconds, rest_seconds, intensity, rpe, notes) values ('a554b97d-0811-5660-9d42-254125d1ca0f', '0776620a-5f8a-5281-af09-10ba8ed6fb7e', 4, 2, '6 per side', null, 45, null, null, 'On a mat. Lower back stays gently pressed into the floor; breathe out as the arm and leg reach.');
insert into public.program_exercises (day_id, exercise_id, position, sets, reps, duration_seconds, rest_seconds, intensity, rpe, notes) values ('a554b97d-0811-5660-9d42-254125d1ca0f', '814f80b6-2f9d-5078-96eb-f07d8ed23949', 5, 1, null, 300, 0, null, 4, 'Treadmill at a brisk walk you could still talk through. Learn the start, stop and emergency clip before you begin.');
insert into public.program_days (id, week_id, day_number, name, focus, estimated_minutes, warmup, cooldown) values ('339efe4c-0273-53fd-98e8-9064caeb8d7b', '13a50fe0-401f-5aee-9d55-96d6ed44d9d0', 2, 'Dumbbells A', 'Squat, press and row with dumbbells', 35, array['5 minutes easy on a bike, treadmill or cross-trainer — try a different machine each session', 'Bodyweight squats × 10', 'Arm circles × 10 each direction', 'One light practice set of your first exercise × 10']::text[], array['2–3 minutes easy walking', 'Child''s pose — 45 seconds', 'Figure-four glute stretch — 30 seconds per side']::text[]) on conflict (id) do update set name = excluded.name, focus = excluded.focus, estimated_minutes = excluded.estimated_minutes, warmup = excluded.warmup, cooldown = excluded.cooldown;
insert into public.program_exercises (day_id, exercise_id, position, sets, reps, duration_seconds, rest_seconds, intensity, rpe, notes) values ('339efe4c-0273-53fd-98e8-9064caeb8d7b', 'ee1fd8c7-c27d-505c-9ae9-8d214fb5f7dd', 0, 2, '10-12', null, 90, null, 6, 'Pick up the dumbbell from the rack with a flat back, hold it at your chest by one end and squat to a comfortable depth.');
insert into public.program_exercises (day_id, exercise_id, position, sets, reps, duration_seconds, rest_seconds, intensity, rpe, notes) values ('339efe4c-0273-53fd-98e8-9064caeb8d7b', '8f3a51d0-5d63-51c0-a0e5-e775434245a6', 1, 2, '10-12', null, 90, null, 6, 'Sit on the end of the bench with the dumbbells on your thighs, then lie back with them — the safest way to get into position.');
insert into public.program_exercises (day_id, exercise_id, position, sets, reps, duration_seconds, rest_seconds, intensity, rpe, notes) values ('339efe4c-0273-53fd-98e8-9064caeb8d7b', '062c10ca-2a45-5311-953d-c884fc0212b0', 2, 2, '10-12 per side', null, 75, null, 6, 'One hand and knee on the bench, back flat. Return the dumbbells to the rack when you''re done.');
insert into public.program_exercises (day_id, exercise_id, position, sets, reps, duration_seconds, rest_seconds, intensity, rpe, notes) values ('339efe4c-0273-53fd-98e8-9064caeb8d7b', 'c56b8193-b199-5189-976d-7a5131053cfd', 3, 2, '12-15', null, 60, null, 6, 'Bodyweight first; rest a dumbbell across your hips once 15 reps feel easy.');
insert into public.program_exercises (day_id, exercise_id, position, sets, reps, duration_seconds, rest_seconds, intensity, rpe, notes) values ('339efe4c-0273-53fd-98e8-9064caeb8d7b', '5fc3044f-cc7a-53a4-9a5a-20b6a148b84d', 4, 2, null, 20, 45, null, null, 'Forearms on a mat, body in one straight line. Knees down is fine.');
insert into public.program_exercises (day_id, exercise_id, position, sets, reps, duration_seconds, rest_seconds, intensity, rpe, notes) values ('339efe4c-0273-53fd-98e8-9064caeb8d7b', 'f826d072-40fc-58c6-96c7-6e471df49ded', 5, 1, null, 300, 0, null, 4, 'Steady easy ride — not intervals. Set the saddle at hip height when standing beside it.');
insert into public.program_days (id, week_id, day_number, name, focus, estimated_minutes, warmup, cooldown) values ('aff80691-096d-5c9b-b9a8-78fb7e45b8ed', '13a50fe0-401f-5aee-9d55-96d6ed44d9d0', 3, 'Mixed Basics', 'Pulldown, hip hinge and overhead press', 35, array['5 minutes easy on a bike, treadmill or cross-trainer — try a different machine each session', 'Bodyweight squats × 10', 'Arm circles × 10 each direction', 'One light practice set of your first exercise × 10']::text[], array['2–3 minutes easy walking', 'Child''s pose — 45 seconds', 'Figure-four glute stretch — 30 seconds per side']::text[]) on conflict (id) do update set name = excluded.name, focus = excluded.focus, estimated_minutes = excluded.estimated_minutes, warmup = excluded.warmup, cooldown = excluded.cooldown;
insert into public.program_exercises (day_id, exercise_id, position, sets, reps, duration_seconds, rest_seconds, intensity, rpe, notes) values ('aff80691-096d-5c9b-b9a8-78fb7e45b8ed', 'ad2a1bd2-4f4c-590a-b298-b5389dd9fa45', 0, 2, '10-12', null, 90, null, 6, 'Tuck your thighs under the pad. Pull the bar to your upper chest, elbows down toward your back pockets.');
insert into public.program_exercises (day_id, exercise_id, position, sets, reps, duration_seconds, rest_seconds, intensity, rpe, notes) values ('aff80691-096d-5c9b-b9a8-78fb7e45b8ed', '0e912efb-2839-5f97-b38e-6e57cd1acea7', 1, 2, '10-12', null, 90, null, 6, 'Dumbbells. Push your hips back like closing a car door with your bottom, back flat, dumbbells close to your legs; stop when you feel your hamstrings.');
insert into public.program_exercises (day_id, exercise_id, position, sets, reps, duration_seconds, rest_seconds, intensity, rpe, notes) values ('aff80691-096d-5c9b-b9a8-78fb7e45b8ed', 'bb7e2951-6956-5eed-8e39-f635f548faac', 2, 2, '10-12', null, 90, null, 6, 'Set the bench upright. Press up without arching your lower back.');
insert into public.program_exercises (day_id, exercise_id, position, sets, reps, duration_seconds, rest_seconds, intensity, rpe, notes) values ('aff80691-096d-5c9b-b9a8-78fb7e45b8ed', '2beab523-a662-5a3d-855b-488ec6d34911', 3, 2, '10-12', null, 60, null, 6, 'Line the machine''s pivot up with your knee and set the ankle pad just above your shoes.');
insert into public.program_exercises (day_id, exercise_id, position, sets, reps, duration_seconds, rest_seconds, intensity, rpe, notes) values ('aff80691-096d-5c9b-b9a8-78fb7e45b8ed', '16a7773c-217a-58af-805f-5242283617ce', 4, 2, '6 per side', null, 45, null, null, 'On hands and knees; reach opposite arm and leg long and pause for a breath.');
insert into public.program_exercises (day_id, exercise_id, position, sets, reps, duration_seconds, rest_seconds, intensity, rpe, notes) values ('aff80691-096d-5c9b-b9a8-78fb7e45b8ed', '3596814c-ae30-5e9b-a0f3-079d8687dd96', 5, 1, null, 300, 0, null, 4, 'Steady easy rowing: legs, then body, then arms — and back in reverse order. Damper around 3–5.');
