insert into public.training_programs (id, slug, name, summary, description, category_id, difficulty, duration_weeks, days_per_week, session_minutes, goals, equipment, tier, progression, warmup, cooldown, low_impact, needs_specialist_review, is_published, source) values ('d91ad266-bc7a-58d9-a199-48bd61a591d5', 'full-body-fitness-foundations', 'Full Body Fitness Foundations', 'Eight weeks of three full-body strength sessions, each ending with a short conditioning finisher — dumbbells, machines and bodyweight.', 'Goal: build all-round strength and fitness in one plan. Each session trains a squat or leg press, a hinge, a push and a pull (every major muscle twice a week, in line with ACSM guidance), then finishes with 4–7 minutes of bike, rower or bodyweight intervals. For beginners who know their way around a gym — or who have finished First 30 Days in the Gym — and want a structured next step. Effort rises from about RPE 6 to RPE 8, reps move from 10–12 to heavier 8–10, and week 8 is lighter before you move on.', 'd2ffdbb8-dde8-5744-86a5-50f499a01d50', 'beginner', 8, 3, 45, array['general_health', 'build_strength', 'improve_conditioning', 'lose_fat', 'type:strength', 'type:functional']::text[], array['dumbbell', 'bench', 'machine', 'bodyweight', 'mat', 'bike', 'rower']::text[], 'pro', 'Weeks 1–3: sets of 10–12, effort rising from RPE 6 to 7 and a third accessory set in week 3. Weeks 4–7: heavier sets of 8–10 on the main lifts, RPE 7 to 8, with a fourth set from week 6. Double progression throughout: when every set reaches the top of the range at the target effort, use the next weight up. Finishers grow from 4 × 20 s to 7 × 30 s; core holds lengthen each week. Week 8 is a lighter week.', array['3–5 minutes easy cardio (walk, bike, rower or skipping)', 'World''s greatest stretch × 3 per side', 'Bodyweight squats × 10', 'Band pull-aparts or arm circles × 15', '2–3 ramp-up sets of your first lift, building toward working weight']::text[], array['3–5 minutes easy walking or cycling to bring heart rate down', 'Child''s pose — 60 seconds', 'Figure-four glute stretch — 30–45 seconds per side', 'Slow nasal breathing — 1–2 minutes']::text[], false, false, true, 'curated') on conflict (slug) do update set name = excluded.name, summary = excluded.summary, description = excluded.description, category_id = excluded.category_id, difficulty = excluded.difficulty, duration_weeks = excluded.duration_weeks, days_per_week = excluded.days_per_week, session_minutes = excluded.session_minutes, goals = excluded.goals, equipment = excluded.equipment, tier = excluded.tier, progression = excluded.progression, warmup = excluded.warmup, cooldown = excluded.cooldown, low_impact = excluded.low_impact, needs_specialist_review = excluded.needs_specialist_review, is_published = true;
insert into public.program_weeks (id, program_id, week_number, focus, is_deload) values ('828b1cb2-f1fb-5c7b-a5b7-b53ea08acd22', 'd91ad266-bc7a-58d9-a199-48bd61a591d5', 1, 'Week 1 — sets of 10–12 at about RPE 6 (4 reps in reserve) to find your working weights; finisher 4 × 20 s', false) on conflict (id) do update set focus = excluded.focus, is_deload = excluded.is_deload;
