insert into public.training_programs (id, slug, name, summary, description, category_id, difficulty, duration_weeks, days_per_week, session_minutes, goals, equipment, tier, progression, warmup, cooldown, low_impact, needs_specialist_review, is_published, source) values ('6bc70813-d047-5647-9735-5528a45d8821', 'busy-schedule-30-minute-workouts', 'Busy Schedule: 30-Minute Workouts', 'Three dumbbell sessions a week that fit in 30 minutes including the warm-up — supersets and a short finisher circuit.', 'Goal: real full-body strength and fitness in the time you actually have. Every session — warm-up, two dumbbell supersets, a short finisher circuit and a minute of cool-down — fits in 30 minutes. Pairing exercises that don''t compete (a squat with a press, a hinge with a row) lets one muscle group rest while the other works, so you get more done without rushing your heaviest sets. For beginners and returning exercisers with a pair of adjustable dumbbells and a bench, at home or in a gym. Progress comes from heavier dumbbells and shorter rests between rounds, not longer sessions.', 'a218e28e-c9e8-59ad-afc5-39d0355f9746', 'beginner', 8, 3, 30, array['general_health', 'build_strength', 'lose_fat', 'build_muscle', 'type:strength', 'type:home']::text[], array['dumbbell', 'bench', 'bodyweight', 'mat']::text[], 'pro', 'Density within a fixed 30 minutes. Weeks 1–3: sets of 10–12 with rest between superset rounds falling from 60 s to 45 s and effort rising from RPE 7 to 8. Week 4 is lighter. Weeks 5–7: heavier dumbbells for 8–10 reps, rest again falling from 60 s to 45 s; finisher efforts lengthen from 30 s to 40 s. Week 8 is lighter. Use the next dumbbell when every round reaches the top of the range.', array['2 minutes marching, skipping or easy stairs', 'World''s greatest stretch × 2 per side', 'First superset: one light set of each × 8']::text[], array['1 minute slow breathing and a stretch of your choice']::text[], false, false, true, 'curated') on conflict (slug) do update set name = excluded.name, summary = excluded.summary, description = excluded.description, category_id = excluded.category_id, difficulty = excluded.difficulty, duration_weeks = excluded.duration_weeks, days_per_week = excluded.days_per_week, session_minutes = excluded.session_minutes, goals = excluded.goals, equipment = excluded.equipment, tier = excluded.tier, progression = excluded.progression, warmup = excluded.warmup, cooldown = excluded.cooldown, low_impact = excluded.low_impact, needs_specialist_review = excluded.needs_specialist_review, is_published = true;
