insert into public.training_programs (id, slug, name, summary, description, category_id, difficulty, duration_weeks, days_per_week, session_minutes, goals, equipment, tier, progression, warmup, cooldown, low_impact, needs_specialist_review, is_published, source) values ('380387bd-3f58-522d-9bfa-7a9db4c39681', 'active-aging-strength-and-balance', 'Active Aging Strength and Balance', 'Twelve weeks of low-impact strength with balance practice every session and sit-to-stand progressions from supported to loaded.', 'Goal: stronger legs, steadier balance and easier everyday tasks — getting out of a chair, climbing stairs, carrying shopping. For older adults and anyone returning to exercise who wants a gentle, progressive start. WHO guidelines suggest adults 65+ do balance and strength work on three or more days a week; every session here includes balance practice, and the sit-to-stand progresses from using your hands, to arms crossed, to holding a dumbbell with a brisk rise. Everything is low impact and done next to a sturdy chair or counter. Effort stays moderate (RPE 5–7.5) with a lighter week every fourth week. A 2-day option is in the instructions. If you have a heart, lung, bone or joint condition, or have fallen recently, check with your healthcare provider before starting.', '5225ea79-fbe6-5abc-819f-3349cce2461e', 'beginner', 12, 3, 35, array['general_health', 'build_strength', 'mobility', 'type:low_impact', 'type:strength']::text[], array['bodyweight', 'dumbbell', 'band']::text[], 'pro', 'Three four-week phases, each three building weeks and a lighter week. Phase 1: 2 → 3 sets of 10–12 at RPE 5–6 with supported variations. Phase 2: 3 sets of 8–12 at RPE 6–7 with harder variations (arms-crossed sit-to-stand, counter push-ups). Phase 3: 3 sets of 8–10 at RPE 6.5–7.5 with a dumbbell and a brisk rise. Balance holds grow from 2 × 15 s with a hand on a support to 3 × 35 s with little or no support; carries and the walk lengthen each week (walk 10 → 20 minutes).', array['3–5 minutes standing march or easy walk', 'Cat-cow × 8 slow breaths', 'Sit-to-stand × 5, slow and controlled', 'Arm circles × 10 each direction']::text[], array['Slow walk 2–3 minutes', 'Seated hamstring stretch — 30 seconds per side', 'Slow breathing — 1 minute']::text[], true, true, true, 'curated') on conflict (slug) do update set name = excluded.name, summary = excluded.summary, description = excluded.description, category_id = excluded.category_id, difficulty = excluded.difficulty, duration_weeks = excluded.duration_weeks, days_per_week = excluded.days_per_week, session_minutes = excluded.session_minutes, goals = excluded.goals, equipment = excluded.equipment, tier = excluded.tier, progression = excluded.progression, warmup = excluded.warmup, cooldown = excluded.cooldown, low_impact = excluded.low_impact, needs_specialist_review = excluded.needs_specialist_review, is_published = true;
insert into public.program_weeks (id, program_id, week_number, focus, is_deload) values ('9d188a94-a810-5853-8c07-a3537a7bb81e', '380387bd-3f58-522d-9bfa-7a9db4c39681', 1, 'Phase 1, week 1 — learn the movements: 2 easy sets of 10–12 (about RPE 5), a support always within reach', false) on conflict (id) do update set focus = excluded.focus, is_deload = excluded.is_deload;
