insert into public.program_exercises (day_id, exercise_id, position, sets, reps, duration_seconds, rest_seconds, intensity, rpe, notes) values ('24fe20f3-132a-538e-b6fb-20e1eaba2015', '2cac4506-3b8c-5aa1-b1de-540db9c7d187', 2, 2, '8-10', null, 75, null, 5.5, 'Band anchored in a door at chest height; squeeze the shoulder blades together. Lighter week: easier resistance, every rep comfortable.');
insert into public.program_exercises (day_id, exercise_id, position, sets, reps, duration_seconds, rest_seconds, intensity, rpe, notes) values ('24fe20f3-132a-538e-b6fb-20e1eaba2015', 'b0a8cfe4-00d8-50fb-91ac-76bd68272eb2', 3, 1, '12-15', null, 45, null, null, 'Hold a counter. Rise up slowly, pause, lower slowly. Lighter week: easier resistance, every rep comfortable.');
insert into public.program_exercises (day_id, exercise_id, position, sets, reps, duration_seconds, rest_seconds, intensity, rpe, notes) values ('24fe20f3-132a-538e-b6fb-20e1eaba2015', 'df7455a7-5c9e-51f7-8ec9-64ebc9b5333d', 4, 2, null, 35, 30, null, null, 'Per leg, next to a counter. Steady without hands? Turn your head slowly side to side, or try it on a cushion. Lighter week: easier resistance, every rep comfortable.');
