insert into public.program_days (id, week_id, day_number, name, focus, estimated_minutes, warmup, cooldown) values ('e4d55984-adec-5489-97e4-77c6e08b27b0', '796f1341-0163-5758-89dc-78bc382d2456', 3, 'Strength & Stamina C', 'Sit-to-stand power, press, row, balance and a walk', 45, array['3–5 minutes standing march or easy walk', 'Cat-cow × 8 slow breaths', 'Sit-to-stand × 5, slow and controlled', 'Arm circles × 10 each direction']::text[], array['Slow walk 2–3 minutes', 'Seated hamstring stretch — 30 seconds per side', 'Slow breathing — 1 minute']::text[]) on conflict (id) do update set name = excluded.name, focus = excluded.focus, estimated_minutes = excluded.estimated_minutes, warmup = excluded.warmup, cooldown = excluded.cooldown;
