insert into public.program_exercises (day_id, exercise_id, position, sets, reps, duration_seconds, rest_seconds, intensity, rpe, notes) values ('e4d55984-adec-5489-97e4-77c6e08b27b0', '814f80b6-2f9d-5078-96eb-f07d8ed23949', 4, 1, null, 1200, 0, null, 5, '20 minutes of walking, brisk enough to breathe a little harder but still talk. Lighter week: easier resistance, every rep comfortable.');
insert into public.training_programs (id, slug, name, summary, description, category_id, difficulty, duration_weeks, days_per_week, session_minutes, goals, equipment, tier, progression, warmup, cooldown, low_impact, needs_specialist_review, is_published, source) values ('5466ba07-93ea-5dc8-bf00-b47a4ace55ce', 'beginner-run-walk-5k-10-week', 'Beginner Run/Walk to 5K: 10 Weeks', 'Three run/walk sessions a week for ten weeks — a slower build than most couch-to-5K plans, finishing with 30 minutes of continuous easy running.', 'For complete beginners, heavier or returning runners, and anyone who found faster plans too steep. Week 1 alternates 60 seconds of easy running with 90 seconds of walking; the running bouts lengthen and the walk breaks shrink a little each week, so your weekly running time rises by no more than about 10–15% over the previous full week. Weeks 4 and 8 are lighter so your joints, tendons and bones can catch up with your fitness. Every run is easy and conversational; walking is part of the plan. The last session is 30 minutes without stopping — about 5 km for many new runners. A walking-only version of every session is built in for days when running isn''t right.', 'd4e79e61-b816-5c53-a64a-537abe13101d', 'beginner', 10, 3, 30, array['improve_conditioning', 'general_health', 'lose_fat', 'type:cardio']::text[], array['bodyweight']::text[], 'pro', 'Running bouts lengthen (60 s → 90 s → 2, 3, 4, 5 minutes → continuous) while walk breaks shorten. Weekly running time goes about 28 → 33 → 39 → 44 → 50 → 57 minutes, never more than about 15% above the previous full week. Weeks 4 and 8 step back by about 20–25%. Repeat any week until its last session feels comfortable.', array['5 minutes brisk walking', 'Leg swings × 10 each leg', 'Ankle circles × 10 each direction']::text[], array['5 minutes easy walking', 'Calf stretch — 30 seconds per side', 'Standing quad stretch — 30 seconds per side']::text[], false, false, true, 'curated') on conflict (slug) do update set name = excluded.name, summary = excluded.summary, description = excluded.description, category_id = excluded.category_id, difficulty = excluded.difficulty, duration_weeks = excluded.duration_weeks, days_per_week = excluded.days_per_week, session_minutes = excluded.session_minutes, goals = excluded.goals, equipment = excluded.equipment, tier = excluded.tier, progression = excluded.progression, warmup = excluded.warmup, cooldown = excluded.cooldown, low_impact = excluded.low_impact, needs_specialist_review = excluded.needs_specialist_review, is_published = true;
