insert into public.training_programs (id, slug, name, summary, description, category_id, difficulty, duration_weeks, days_per_week, session_minutes, goals, equipment, tier, progression, warmup, cooldown, low_impact, needs_specialist_review, is_published, source) values ('12ce6c57-c9b7-5c7d-b3b2-0678425e895d', 'conditioning-intervals-8-week', 'Conditioning & Intervals: Bike, Rower and Kettlebell', 'Three interval sessions a week — bike, kettlebell-and-bodyweight circuits and rower — with work:rest ratios that tighten over eight weeks.', 'For people who already train and want a bigger engine: better repeat-effort fitness, faster recovery between hard efforts and more work done in less time. Each week has a bike power session (short hard intervals, from 1:3 to 1:1 work:rest), a kettlebell and bodyweight circuit (from 20:40 to 40:20) and longer rower intervals (3–4 minutes at a hard, sustainable pace with shrinking rests). Weeks 4 and 8 are lighter. Effort is set by feel, so it works at any fitness level within the intermediate range; no bike or rower? An outdoor run or hill repeats can replace either.', '30351ab3-3de1-597d-bb50-b0c1579a05b1', 'intermediate', 8, 3, 35, array['improve_conditioning', 'lose_fat', 'general_health', 'type:cardio', 'type:functional']::text[], array['bike', 'rower', 'kettlebell', 'bodyweight']::text[], 'pro', 'Density: bike 8 × 30 s with 90 s easy → 10 × 45 s with 45 s easy; circuits 20:40 for 4 rounds → 40:20 for 5 rounds; rower 4 × 3 min with 2 min easy → 5 × 4 min with 90 s easy. Each week adds work or trims rest, never both on the same piece. Weeks 4 and 8 drop rounds and lengthen rests.', array['5 minutes easy jump rope, bike or shadowboxing', 'Lateral shuffles × 20 seconds each way', 'World''s greatest stretch × 3 per side', '2 × 10-second build-up efforts at moderate intensity']::text[], array['3–5 minutes easy walking or cycling to bring heart rate down', 'Child''s pose — 60 seconds', 'Figure-four glute stretch — 30–45 seconds per side', 'Slow nasal breathing — 1–2 minutes']::text[], false, false, true, 'curated') on conflict (slug) do update set name = excluded.name, summary = excluded.summary, description = excluded.description, category_id = excluded.category_id, difficulty = excluded.difficulty, duration_weeks = excluded.duration_weeks, days_per_week = excluded.days_per_week, session_minutes = excluded.session_minutes, goals = excluded.goals, equipment = excluded.equipment, tier = excluded.tier, progression = excluded.progression, warmup = excluded.warmup, cooldown = excluded.cooldown, low_impact = excluded.low_impact, needs_specialist_review = excluded.needs_specialist_review, is_published = true;
insert into public.program_weeks (id, program_id, week_number, focus, is_deload) values ('da9de93b-4001-53fd-b6ae-f06c96560cbb', '12ce6c57-c9b7-5c7d-b3b2-0678425e895d', 1, 'Week 1: bike 1:3, circuit 20:40, row 3 min on / 2 min off — more work or less rest than last week', false) on conflict (id) do update set focus = excluded.focus, is_deload = excluded.is_deload;
insert into public.program_days (id, week_id, day_number, name, focus, estimated_minutes, warmup, cooldown) values ('4497b5f9-c68a-5ba4-9c1d-317b85b8d2b3', 'da9de93b-4001-53fd-b6ae-f06c96560cbb', 1, 'Bike Power Intervals', '8 × 30 s hard, 90 s easy (work:rest 1:3)', 35, array['5 minutes easy jump rope, bike or shadowboxing', 'Lateral shuffles × 20 seconds each way', 'World''s greatest stretch × 3 per side', '2 × 10-second build-up efforts at moderate intensity']::text[], array['3–5 minutes easy walking or cycling to bring heart rate down', 'Child''s pose — 60 seconds', 'Figure-four glute stretch — 30–45 seconds per side', 'Slow nasal breathing — 1–2 minutes']::text[]) on conflict (id) do update set name = excluded.name, focus = excluded.focus, estimated_minutes = excluded.estimated_minutes, warmup = excluded.warmup, cooldown = excluded.cooldown;
