insert into public.program_days (id, week_id, day_number, name, focus, estimated_minutes, warmup, cooldown) values ('0f86b020-ef61-50d2-9f74-7b372f34d359', '5fab971a-ae87-5dde-9b09-ec9d7e415bd3', 3, 'Rower Intervals + Carries', '3 × 3 min hard, 150 s easy (work:rest 6:5)', 35, array['5 minutes easy jump rope, bike or shadowboxing', 'Lateral shuffles × 20 seconds each way', 'World''s greatest stretch × 3 per side', '2 × 10-second build-up efforts at moderate intensity']::text[], array['3–5 minutes easy walking or cycling to bring heart rate down', 'Child''s pose — 60 seconds', 'Figure-four glute stretch — 30–45 seconds per side', 'Slow nasal breathing — 1–2 minutes']::text[]) on conflict (id) do update set name = excluded.name, focus = excluded.focus, estimated_minutes = excluded.estimated_minutes, warmup = excluded.warmup, cooldown = excluded.cooldown;
insert into public.program_exercises (day_id, exercise_id, position, sets, reps, duration_seconds, rest_seconds, intensity, rpe, notes) values ('0f86b020-ef61-50d2-9f74-7b372f34d359', '3596814c-ae30-5e9b-a0f3-079d8687dd96', 0, 3, null, 180, 150, null, 6.5, '3 min at a hard pace you can hold for every rep (about 5K-run effort), 150 s easy paddling. Note your average split — aim to hold it as the rest shortens. Lighter week: steady, not all-out.');
