insert into public.training_programs (id, slug, name, summary, description, category_id, difficulty, duration_weeks, days_per_week, session_minutes, goals, equipment, tier, progression, warmup, cooldown, low_impact, needs_specialist_review, is_published, source) values ('a420e4dd-07e0-56ef-9d92-bad1df570800', 'full-body-mobility-6-week', 'Full-Body Mobility: 6-Week Routine', 'Five short mobility sessions a week (or four) for hips, spine, shoulders and ankles, with holds that grow every week.', 'For all levels: 15–25 minutes of mobility work you can do on its own or after training. Each session targets one region — hips and hamstrings, spine and shoulders, ankles and squat, a full-body flow and a long-hold session — and the time you spend in each position grows every week, because regular practice and longer total time under stretch are what improve range of motion. Move slowly and stay in a comfortable, pain-free range. This is general mobility training, not rehabilitation: if you have an injury or pain, follow your healthcare provider''s advice.', '5f664aca-35b8-56b3-941c-843e25abd264', 'beginner', 6, 5, 15, array['mobility', 'general_health', 'type:mobility', 'type:low_impact']::text[], array['mat', 'band', 'bodyweight']::text[], 'pro', 'Weeks 1–3: one hold per side growing from 30 to 50 seconds, and one slow set of each drill. Weeks 4–6: two holds per side (40 → 60 seconds) and two sets of each drill — total time per side goes from 30 to 120 seconds. The long-hold day builds from one 45-second to one 2-minute hold per side. Sessions grow from about 15 to about 25 minutes.', array['1–2 minutes of slow nasal breathing, lying or seated', 'Cat-cow × 6 slow breaths', 'Arm circles × 10 each direction']::text[], array['Lie on your back, knees bent — 1 minute of slow breathing']::text[], true, false, true, 'curated') on conflict (slug) do update set name = excluded.name, summary = excluded.summary, description = excluded.description, category_id = excluded.category_id, difficulty = excluded.difficulty, duration_weeks = excluded.duration_weeks, days_per_week = excluded.days_per_week, session_minutes = excluded.session_minutes, goals = excluded.goals, equipment = excluded.equipment, tier = excluded.tier, progression = excluded.progression, warmup = excluded.warmup, cooldown = excluded.cooldown, low_impact = excluded.low_impact, needs_specialist_review = excluded.needs_specialist_review, is_published = true;
insert into public.program_weeks (id, program_id, week_number, focus, is_deload) values ('a8e6bb75-6bcc-5d3e-a86c-8327335a3586', 'a420e4dd-07e0-56ef-9d92-bad1df570800', 1, 'Week 1: one 30-second hold per side and one slow set of each drill — learn the positions, stay pain-free', false) on conflict (id) do update set focus = excluded.focus, is_deload = excluded.is_deload;
