insert into public.program_days (id, week_id, day_number, name, focus, estimated_minutes, warmup, cooldown) values ('617f4bac-0c86-5e51-8473-2ef54f3903a6', '20ccd357-a917-5e53-b410-68a943508488', 5, 'Long Holds & Breathing', 'Longer, relaxed static holds', 25, array['1–2 minutes of slow nasal breathing, lying or seated', 'Cat-cow × 6 slow breaths', 'Arm circles × 10 each direction']::text[], array['Lie on your back, knees bent — 1 minute of slow breathing']::text[]) on conflict (id) do update set name = excluded.name, focus = excluded.focus, estimated_minutes = excluded.estimated_minutes, warmup = excluded.warmup, cooldown = excluded.cooldown;
insert into public.program_exercises (day_id, exercise_id, position, sets, reps, duration_seconds, rest_seconds, intensity, rpe, notes) values ('617f4bac-0c86-5e51-8473-2ef54f3903a6', '23f9503b-882b-5ac2-88c9-7542b301ba3c', 0, 2, null, 120, 10, null, null, 'One 120-second hold per side. Lying on your back; breathe out slowly and let the hip relax.');
