insert into public.program_exercises (day_id, exercise_id, position, sets, reps, duration_seconds, rest_seconds, intensity, rpe, notes) values ('617f4bac-0c86-5e51-8473-2ef54f3903a6', '40d84c3e-5194-5aaa-8ba0-5f74903b28ba', 2, 2, null, 120, 10, null, null, 'One 120-second hold per side. Band around the foot; long exhales.');
insert into public.program_exercises (day_id, exercise_id, position, sets, reps, duration_seconds, rest_seconds, intensity, rpe, notes) values ('617f4bac-0c86-5e51-8473-2ef54f3903a6', 'e14235bb-fe7b-5c34-acea-7d2fe278b788', 3, 1, null, 120, 0, null, null, 'Slow breathing: 4 seconds in, 6 seconds out.');
insert into public.training_programs (id, slug, name, summary, description, category_id, difficulty, duration_weeks, days_per_week, session_minutes, goals, equipment, tier, progression, warmup, cooldown, low_impact, needs_specialist_review, is_published, source) values ('778a0949-3668-5c7d-9365-eac79fe06ea6', 'core-strength-stability-8-week', 'Core Strength & Stability: 8 Weeks', 'Three sessions a week of anti-extension, anti-rotation and anti-lateral-flexion work, from planks and dead bugs to rollouts and Copenhagen planks.', 'For beginners to intermediates who want a strong, stable trunk for lifting, running and everyday life. The core''s main job is to resist unwanted movement, so each session trains one direction: resisting extension (dead bugs, planks, ab-wheel rollouts), rotation (Pallof presses, bird dogs, single-leg hinges, bear crawls) and side-bending (side planks, Copenhagen planks, suitcase carries). Phase 1 (weeks 1–3) teaches each brace and adds reps and seconds; phase 2 (weeks 5–7) moves to harder levers. Weeks 4 and 8 are lighter. Pairs well with any strength or running plan.', 'a218e28e-c9e8-59ad-afc5-39d0355f9746', 'beginner', 8, 3, 30, array['build_strength', 'general_health', 'athletic_performance', 'type:strength', 'type:home']::text[], array['bodyweight', 'mat', 'band', 'dumbbell', 'ab_wheel', 'bench']::text[], 'pro', 'Phase 1 (weeks 1–3): holds grow by 5–10 seconds and reps by 1–2 each week (plank 20 → 40 s, rollouts 5 → 8, side plank from the knees 20 → 30 s). Phase 2 (weeks 5–7): harder versions — long-lever dead bugs, hard-style planks, side planks from the feet, long-lever Copenhagen planks, single-leg bridges and loaded single-leg hinges — built up the same way. Weeks 4 and 8 drop to two sets of the easier versions.', array['2–3 minutes easy marching or cycling', 'Cat-cow × 6 slow breaths', 'Glute bridge × 10', 'Dead bug × 4 per side, slow']::text[], array['Child''s pose — 60 seconds', 'Figure-four stretch — 30 seconds per side']::text[], false, false, true, 'curated') on conflict (slug) do update set name = excluded.name, summary = excluded.summary, description = excluded.description, category_id = excluded.category_id, difficulty = excluded.difficulty, duration_weeks = excluded.duration_weeks, days_per_week = excluded.days_per_week, session_minutes = excluded.session_minutes, goals = excluded.goals, equipment = excluded.equipment, tier = excluded.tier, progression = excluded.progression, warmup = excluded.warmup, cooldown = excluded.cooldown, low_impact = excluded.low_impact, needs_specialist_review = excluded.needs_specialist_review, is_published = true;
