insert into public.training_programs (id, slug, name, summary, description, category_id, difficulty, duration_weeks, days_per_week, session_minutes, goals, equipment, tier, progression, warmup, cooldown, low_impact, needs_specialist_review, is_published, source) values ('5e740c69-bbab-5fc0-92e0-a5502700dad4', 'movement-quality-foundations', 'Movement Quality Foundations: Squat, Hinge, Lunge, Push, Pull, Carry', 'Three slow-tempo sessions a week that teach the six basic movement patterns with bodyweight first, then light dumbbells.', 'For true beginners, people returning after a long break, or lifters who want to clean up their technique. Every session practises the basic patterns — squat, hip hinge, lunge, push, pull and carry — at a slow 3-1-1 tempo so you feel each position. Weeks 1–2 use bodyweight only; weeks 3–5 add light dumbbells and a resistance band once each pattern looks and feels consistent; week 6 is lighter so you can check your form against week 1. It prepares you for any full-body strength program. Leave every set with plenty in reserve.', 'd2ffdbb8-dde8-5744-86a5-50f499a01d50', 'beginner', 6, 3, 30, array['general_health', 'build_strength', 'mobility', 'type:strength', 'type:low_impact']::text[], array['bodyweight', 'dumbbell', 'band', 'bench']::text[], 'pro', 'Week 1: two sets of 8 with bodyweight. Week 2: a third set. Week 3: light dumbbells on the squat, hinge and lunge. Week 4: sets of 10 and longer carries. Week 5: full push-ups and a little more load where every rep stayed clean (RPE 5 → 7 across the block). Week 6 is lighter.', array['3 minutes marching or easy walking', 'Cat-cow × 6', 'World''s greatest stretch × 2 per side', 'Bodyweight squats × 5, slow']::text[], array['2 minutes easy walking', 'Child''s pose — 60 seconds', 'Figure-four stretch — 30 seconds per side']::text[], true, false, true, 'curated') on conflict (slug) do update set name = excluded.name, summary = excluded.summary, description = excluded.description, category_id = excluded.category_id, difficulty = excluded.difficulty, duration_weeks = excluded.duration_weeks, days_per_week = excluded.days_per_week, session_minutes = excluded.session_minutes, goals = excluded.goals, equipment = excluded.equipment, tier = excluded.tier, progression = excluded.progression, warmup = excluded.warmup, cooldown = excluded.cooldown, low_impact = excluded.low_impact, needs_specialist_review = excluded.needs_specialist_review, is_published = true;
insert into public.program_weeks (id, program_id, week_number, focus, is_deload) values ('c21dba3f-a13a-581a-8e3a-de9f9d78a5f5', '5e740c69-bbab-5fc0-92e0-a5502700dad4', 1, 'Week 1: learn the six patterns with bodyweight, two sets, slow tempo', false) on conflict (id) do update set focus = excluded.focus, is_deload = excluded.is_deload;
