insert into public.training_programs (id, slug, name, summary, description, category_id, difficulty, duration_weeks, days_per_week, session_minutes, goals, equipment, tier, progression, warmup, cooldown, low_impact, needs_specialist_review, is_published, source) values ('7e2d86aa-8877-550c-bbfd-ad49b374a5dd', 'flexibility-recovery-routines', 'Flexibility & Recovery Routines', 'Four gentle sessions a week (five optional) of easy walking or cycling and relaxed stretching to help you feel looser and recover between workouts.', 'For anyone at any level who wants a calm, structured routine of gentle stretching and easy aerobic activity — alongside a training plan, on a lighter phase, or on its own. Two sessions pair 15–24 minutes of easy walking or cycling with lower-body stretches, one works the spine and shoulders, and one is long, relaxed holds with slow breathing. This is a general wellness routine, not rehabilitation or treatment: it is not designed for injuries, pain or medical conditions — if you have one, follow the plan from your healthcare provider or physiotherapist instead.', '93e126f2-1ee0-5555-97ae-5e7a8a4e10d2', 'beginner', 6, 4, 25, array['mobility', 'general_health', 'type:mobility', 'type:low_impact', 'type:cardio']::text[], array['bodyweight', 'mat', 'band']::text[], 'pro', 'Easy aerobic time grows from 15 to 24 minutes (about 10% a week), stretch holds from 30 to 60 seconds and long holds from 45 to 90 seconds. Effort stays easy throughout — the progression is time, not intensity.', array['2 minutes easy walking or marching', 'Shoulder rolls × 10', 'Gentle hip circles × 5 each direction']::text[], array['1–2 minutes of slow breathing: 4 seconds in, 6 seconds out']::text[], true, false, true, 'curated') on conflict (slug) do update set name = excluded.name, summary = excluded.summary, description = excluded.description, category_id = excluded.category_id, difficulty = excluded.difficulty, duration_weeks = excluded.duration_weeks, days_per_week = excluded.days_per_week, session_minutes = excluded.session_minutes, goals = excluded.goals, equipment = excluded.equipment, tier = excluded.tier, progression = excluded.progression, warmup = excluded.warmup, cooldown = excluded.cooldown, low_impact = excluded.low_impact, needs_specialist_review = excluded.needs_specialist_review, is_published = true;
